select t.id, 'ca', '[{"n":"1","title":"L’antiguitat a Catalunya"},{"n":"2","title":"La Catalunya romana"},{"n":"3","title":"El naixement de Catalunya"},{"n":"4","title":"La Catalunya feudal (s. xi -xii)"},{"n":"5","title":"L’expansió catalanoaragonesa (s. xiii -xiv)"},{"n":"6","title":"La crisi de la baixa edat mitjana (s. xiv i xv)"},{"n":"7","title":"Catalunya en la monarquia hispànica i la Guerra dels Segadors (s. xvi -xvii)"},{"n":"8","title":"La Guerra de Successió i l’Onze de Setembre"},{"n":"9","title":"Les transformacions del segle xviii"}]'::jsonb, '["El naixement de Catalunya se situa entre els segles segles ix i x.","Catalunya ha estat cruïlla de persones, pobles, cultures i religions que han contribuït a fixar la nostra cultura com ara la coneixem.","El substrat romà constitueix la base sobre la qual cristal·litzarà la cultura catalana.","Catalunya neix com a entitat política sobirana sota les mateixes circumstàncies que molts regnes medievals. En el nostre cas particular és conseqüència de la feblesa de la monarquia franca i de l’enfortiment dels comtats catalans sota el domini franc com a territori de frontera amb els sarraïns i que rebia el nom de Marca Hispànica.","L’expansió de la corona catalanoaragonesa es duu a terme en dues direccions: la Mediterrània i la peninsular. Com a conseqüència d’aquest fet compartim en els nostres dies una mateixa cultura i llengua amb València, les Illes Balears i la ciutat sarda de l’Alguer.","En el segle xiv neixen les principals institucions polítiques que han arribat fins als nostres dies, les Corts Catalanes, amb funcions legislatives, i la Diputació del General o Generalitat, que tenia encomanades tasques executives, així com el Consell de Cent, que era l’administració local de Barcelona. El Parlament de Catalunya i la Generalitat de Catalunya tal com els coneixem avui són hereus directes d’aquestes institucions medievals.","La decadència de Catalunya comença a la baixa edat mitjana com a conseqüència d’una crisi econòmica i demogràfica, de la crisi social i la política. Fruit d’aquesta crisi política es produeix una unió dinàstica amb Castella que desplaçarà el poder cap al regne veí.","La monarquia hispànica no suposa la pèrdua de la identitat política de Catalunya. Tanmateix, en aquest període es perden, entre d’altres, els territoris de la Catalunya Nord i de Sardenya com a conseqüència de les guerres europees.","La pèrdua de les llibertats col·lectives de Catalunya és conseqüència de la derrota militar de l’11 de setembre de 1714 davant de les tropes franceses i castellanes de Felip V en el que anomenem Guerra de Successió i que es produeix per la mort sense descendència del rei Carles II, i en què s’erigiren dos bàndols, els partidaris de l’arxiduc Carles i els de Felip d’Anjou.","La recuperació demogràfica, social i econòmica que impulsarà la reivindicació de la recuperació de les institucions catalanes es va produir al llarg del segle xviii com a conseqüència de les transformacions agràries i preindustrials."]'::jsonb, '["Amfiteatre","Anglicanisme","Calvinisme","Creixement vegetatiu","Estat feudal","Fòrum","Heretgia dels càtars","Iconografia","Indústria lítica","Inflació","Menestrals","Ocupació sarraïna","Prohoms","Termes","Usatges","Vassallatge"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"L''antiguitat a Catalunya","blocks":[{"text":"La història de Catalunya com a tal no comença fins a l''edat mitjana. L''historiador Vicens Vives va definir Catalunya amb dues paraules: «redós», on es formen cultures pròpies i autòctones, i «passadís», per on circulen pobles vinguts de fora que, en contacte amb els anteriors, donen a l''antiguitat catalana la seva especificitat.","refs":[{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"La història de Catalunya com a tal no comença pròpiament fins a l’edat mitjana"},{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"L’historiador Vicens Vives va definir Catalunya com a “redós” i “passadís”, “redós” on es configuraran cultures pròpies i autòctones i “passadís” per on circularan tota mena de pobles vinguts de fora amb la seva cultura"}]},{"text":"La indústria lítica del paleolític inferior demostra que hi havia grups humans caçadors i recol·lectors en diversos punts del territori. Dues restes que cal saber: la més antiga és l''home de Talteüll, al Rosselló, de fa uns 450.000 anys; i destaca també la mandíbula de Banyoles, de fa uns 70.000 anys. Després vénen el neolític, l''edat dels metalls, la colonització grega i la cultura ibèrica, que són les etapes de la història antiga catalana.","refs":[{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"La resta humana més antiga és l’home de Talteüll, al Rosselló, de fa uns 450.000 anys. I cal destacar la mandíbula de Banyoles, de fa uns 70.000 anys."},{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"El neolític, l’edat dels metalls, la colonització grega i la cultura ibèrica són etapes de la història antiga catalana."}]}]},{"n":"2","title":"La Catalunya romana","blocks":[{"text":"Els romans arriben a Catalunya en el context de les guerres púniques entre Roma i Cartago: el 218 aC Gneu Corneli Escipió desembarca a Empúries. Amb la guerra contra els cartaginesos, la submissió dels pobles peninsulars i l''organització del poder romà s''inicia la romanització. Per la seva situació mediterrània, el territori català es romanitza intensament: adopta les formes econòmiques, socials, polítiques i culturals llatines. L''economia era agrària (blat, vinya i olivera), amb un comerç florent orientat sobretot a Roma i un artesanat notable de ceràmica i teixits.","refs":[{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"Fou en el transcurs de les guerres púniques entre Roma i Cartago quan els romans van desembarcar a Catalunya: el 218 a. de C. Gneu Corneli Escipió posava peu a Empúries."},{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"Una civilització basada en una economia agrària de productes mediterranis (blat, vinya i olivera), dotada d’un comerç florent que, en una gran part, tenia com a destinatària la mateixa Roma, i d’un artesanat notable (ceràmica i teixits)."}]},{"text":"La ciutat era l''eix de l''organització romana: hi havia el govern i hi vivien els propietaris de les terres. La ciutat més important de la Catalunya romana fou Tarraco, amb fòrum, termes, amfiteatre, circ, aqüeductes i muralles a imitació de Roma. La Via Augusta comunicava amb la capital de l''imperi. La llatinització va introduir la llengua llatina, el dret i la religió romanes, i el contacte del llatí amb les llengües existents va fer néixer les llengües romàniques, entre les quals el català. El sistema econòmic i social es basava en l''esclau.","refs":[{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"La ciutat més important de la Catalunya romana fou Tarraco, on es reproduïa l’estructura urbanística típica de les ciutats romanes (fòrum, termes, amfiteatre, circ, aqüeductes, muralles...)"},{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"alguna de les quals, com la Via Augusta, comunicava amb la capital de l’imperi"},{"ref":"p. 12","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=12","quote":"A la llarga, el contacte del llatí amb les llengües existents va propiciar el naixement de les llengües romàniques, entre les quals hi ha el català. El sistema econòmic i social romà es basava en l’esclau"}]},{"text":"A partir del segle III dC, la crisi del sistema esclavista (s''atura l''expansió i els esclaus s''encareixen) transforma l''imperi: entren pobles bàrbars, els territoris es desvinculen de Roma i les ciutats entren en crisi. Tot plegat porta a la ruralització, a la conversió dels esclaus en colons i a una barreja d''elements romans i germànics, com els visigots.","refs":[{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"va portar, a partir del segle iii d. de C., cap a una gradual transformació de l’imperi"},{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"Tot plegat comportà una ruralització de la societat, una transformació dels esclaus en colons i l’adopció d’una estructura política resultat de la barreja d’elements romans i d’elements aportats pels pobles nouvinguts d’arrel germànica, com els visigots."}]},{"text":"Entre els segles V i VIII els visigots formen una monarquia peninsular amb capital a Toledo, molt romanitzada, rural i convertida al catolicisme al segle VI. El 711 entren a la Península bandes armades del nord d''Àfrica, que derroten els visigots; cap al 720 ja havien ocupat els territoris catalans. Segons la guia, l''arribada dels musulmans és la «partida de naixement» de Catalunya com a entitat política independent.","refs":[{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"Entre els segles v i viii, els visigots van conformar una entitat política peninsular monàrquica, amb Toledo com a capital"},{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"El 711, bandes armades del nord d’Àfrica entraren a la Península, derrotaren els visigots i, ràpidament, ocuparen el territori. Al voltant del 720 ja s’havia produït l’ocupació sarraïna dels territoris catalans."},{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"signifiquen la partida de naixement de Catalunya com a entitat política independent"}]}]},{"n":"3","title":"El naixement de Catalunya","blocks":[{"text":"El naixement de Catalunya se situa entre els segles IX i X. El seu antecedent polític immediat és la Marca Hispànica impulsada per Carlemany, frontera entre el regne franc i els dominis sarraïns (que Carles Martell havia vençut a Poitiers el 732). El fracàs davant Saragossa (778) va impedir portar la Marca fins a l''Ebre, però el lliurament de Girona (785) i la conquesta de Barcelona (801) van definir la Catalunya Vella: territoris pirinencs, les terres entre el Llobregat i el Cardener, el Segrià mitjà i la Conca de Tremp.","refs":[{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"El naixement de Catalunya se situa entre els segles ix i x. L’antecedent polític immediat a la seva formació el trobem en la creació de la Marca Hispànica que va impulsar Carlemany."},{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"El fracàs de la conquesta de Saragossa (778) va fer que no pogués estendre la Marca fins a la frontera natural de l’Ebre tal com desitjava. Amb tot, el lliurament a Carlemany de la ciutat de Girona (785) o la conquesta de Barcelona (801) van emmarcar un territori, que correspon a allò que és conegut com la Catalunya Vella"}]},{"text":"El territori es va dividir en comtats governats per comtes vinculats per vassallatge als reis francs, sense unitat entre ells. Eren nomenats pel rei franc, no eren hereditaris i exercien la sobirania (administració política, econòmica i judicial) en nom del rei. Guifré el Pilós, fundador del casal de Barcelona, va reunir diversos comtats i va repoblar les planes de la Catalunya central.","refs":[{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"Eren nomenats pel rei franc, no tenien caràcter hereditari i exercien la sobirania (administració política, econòmica i judicial) en nom del rei."},{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"Guifré el Pilós, fundador del casal de Barcelona, reuní diferents comtats i repoblà les planes interiors de la Catalunya central."}]},{"text":"Dos fenòmens fan de Catalunya una unitat política independent: la transmissió hereditària del poder comtal i la desvinculació final dels comtes respecte a la monarquia franca, cap al 988, amb el comte Borrell II. Hi intervenen la feblesa de la monarquia franca, que havia canviat de dinastia, l''enfortiment dels comtes i la primacia del casal de Barcelona.","refs":[{"ref":"p. 13","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=13","quote":"una desvinculació final dels comtes catalans respecte a la monarquia franca, cosa que es produí cap al 988 amb el comte Borrell II"},{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"feblesa d’una monarquia franca que havia canviat de dinastia, enfortiment dels comtes catalans, que ja passaven la seva autoritat política de pares a fills, i relació entre els diferents comtats catalans acceptant la primacia gradual del casal de Barcelona"}]}]},{"n":"4","title":"La Catalunya feudal (s. XI-XII)","blocks":[{"text":"Als segles XI i XII Catalunya es consolida com a estat feudal independent aglutinat per la casa de Barcelona. Amb la conquesta de la Catalunya Nova, al segle XII, la frontera arriba a Tortosa (1148) i a Lleida i Fraga (1149).","refs":[{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"Es comença una expansió que porta a la conquesta del que anomenem la Catalunya Nova durant el segle xii, que porta les fronteres de Catalunya fins a Tortosa el 1148 i a Lleida i Fraga el 1149."}]},{"text":"El 1137 Ramon Berenguer IV es casa amb Peronella d''Aragó, filla de Ramir el Monjo, i neix la Confederació Catalanoaragonesa. És una unió dinàstica i no una fusió: cada territori conserva institucions, lleis i tradicions i només comparteixen el monarca, el «comte rei». En canvi, es van perdre els drets sobre Occitània: l''heretgia càtara o albigesa va provocar una guerra del papa Innocenci III i el rei de França contra els catalans, i la batalla de Muret, on va morir Pere el Catòlic, va posar fi al domini catalanoaragonès en aquelles terres.","refs":[{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"El 1137, Ramon Berenguer IV es casa amb Peronella d’Aragó, filla de Ramir el Monjo, amb la qual cosa es forma la Confederació Catalanoaragonesa, una unió dinàstica, més que no pas una fusió entre Aragó i Catalunya, en la qual cada territori conserva les seves institucions, lleis i tradicions i només comparteixen el monarca, que es converteix en “comte rei”."},{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"La batalla de Muret, on va morir el mateix rei Pere el Catòlic, va significar la fi del domini catalanoaragonès sobre aquestes terres."}]},{"text":"La societat és plenament feudal: dos estaments privilegiats (noblesa i clergat) i una massa de pagesos lligats a la terra sota la jurisdicció dels senyors. Les relacions feudovassallàtiques, regulades pels usatges, jerarquitzaven els senyors. Tot en un marc de creixement econòmic, demogràfic i urbà.","refs":[{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"Estem davant d’una societat plenament feudal on hi ha dos estaments privilegiats, el nobiliari i l’eclesiàstic, i una massa de pagesos lligats a la terra i sota la jurisdicció dels senyors. Les relacions feudovassallàtiques marcaven la jerarquització entre els senyors, regulada pels usatges."}]}]},{"n":"5","title":"L''expansió catalanoaragonesa (s. XIII-XIV)","blocks":[{"text":"Jaume I el Conqueridor (1208-1276) inicia l''expansió en dues direccions: la Mediterrània i el sud peninsular. Conquereix Mallorca, Menorca i Eivissa entre 1229 i 1235 (terres repartides entre la noblesa catalana i el rei) i València entre 1232 i 1244. L''acord amb Castella, que també s''expandia cap al sud, atura l''avanç a la zona d''Alacant-Múrcia. Els seus descendents hi afegeixen Sardenya, Sicília, Nàpols, els ducats d''Atenes i Neopàtria i establiments comercials al nord d''Àfrica.","refs":[{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"Jaume I el Conqueridor (1208-1276) fou qui inicià l’expansió de la corona catalanoaragonesa en dues direccions: la Mediterrània i el sud peninsular. La conquesta de Mallorca, Menorca i Eivissa fou duta a terme entre 1229 i 1235"},{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"La conquesta de València, territori on el domini sarraí havia establert una pròspera agricultura, durà del 1232 al 1244"},{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"L’acord amb Castella va aturar l’expansió a la zona d’Alacant-Múrcia."},{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"Sardenya, Sicília, Nàpols, els ducats grecs d’Atenes i Neopàtria i les instal·lacions comercials del nord d’Àfrica"}]},{"text":"Entre els segles XIII i XV es consoliden les institucions. Les Corts Catalanes eren una assemblea amb representants dels tres estaments o braços: nobiliari, eclesiàstic i reial (representants de les ciutats). Legislaven, aprovaven impostos, assessoraven el monarca i negociaven privilegis a canvi de subsidis.","refs":[{"ref":"p. 14","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=14","quote":"les Corts Catalanes, assemblea política formada per representants dels tres estaments: el braç nobiliari, el braç eclesiàstic i el braç reial o representants de les ciutats. Les funcions de les Corts eren legislatives, aprovaven nous impostos, assessoraven el monarca i negociaven privilegis a canvi de subsidis."}]},{"text":"Al segle XIV neix la Diputació del General o Generalitat, representació permanent de les Corts formada per tres diputats (un per braç) i tres oïdors de comptes. Executava les decisions de les Corts, defensava constitucions i lleis i recaptava subsidis i impostos. Al govern de Barcelona destaca el Consell de Cent: cent prohoms que representaven la burgesia comercial, els mercaders i els menestrals, amb funció consultiva i de control sobre els cinc consellers que governaven la ciutat.","refs":[{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"Durant el segle xiv naixeria la Diputació del General o Generalitat, que era una representació de caràcter permanent de les Corts composta per tres diputats, un per cada braç, i tres oïdors de comptes. La seva tasca era la d’executar les decisions de les Corts, la defensa de les constitucions i lleis i la recaptació de subsidis i impostos."},{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"el Consell de Cent, assemblea de cent prohoms de la ciutat que representaven els estaments de Barcelona: la burgesia comercial, els mercaders i els menestrals. Aquests representants tenien la missió consultiva i de control sobre els cinc consellers que governaven la ciutat."}]}]},{"n":"6","title":"La crisi de la baixa edat mitjana (s. XIV i XV)","blocks":[{"text":"Als segles XIV i XV s''ajunten tres crisis: econòmica i de població, social i política. La població havia superat el que podia produir l''agricultura i qualsevol mala collita provocava crisis de subsistència. La pesta negra, a partir de 1348, va matar de mitjana un terç de la població (en alguns llocs, la meitat). El comerç mediterrani es va veure pertorbat pels turcs i per la competència de Gènova i Venècia; la pèrdua de centralitat de la Mediterrània explica que Portugal i Castella busquessin noves rutes cap a les Índies.","refs":[{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"Durant els segles xiv i xv veurem la conjunció de tres crisis: una crisi econòmica i de població, una crisi social i una crisi política."},{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"En aquest marc era normal que l’extensió de la pesta negra, a partir de 1348, fes estralls. La mitjana de mortaldat se situà en un terç de la població, tot i que en alguns llocs arribà a la meitat."},{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"El comerç per la Mediterrània va començar a ser pertorbat per la presència dels turcs i per la competència d’altres ciutats mercantils com Gènova o Venècia."}]},{"text":"La crisi social esclata sobretot al segle XV. A Barcelona s''enfronten la Busca i la Biga, grups urbans amb interessos econòmics oposats que volien controlar el govern de la ciutat; i hi ha pogroms i assalts als calls jueus. Al camp, la Guerra dels Remences enfronta pagesos (que volien alliberar-se de càrregues feudals) i senyors (que volien lligar-los més a la terra). Acaba amb la Sentència de Guadalupe (1486), impulsada per Ferran II, que va donar estabilitat als pagesos durant l''edat moderna.","refs":[{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"hi hagué enfrontaments entre la Busca i la Biga, grups socials urbans que tenien interessos econòmics contraposats i que volien controlar el poder de la ciutat"},{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"La Guerra dels Remences finalitzà amb la Sentència de Guadalupe (1486), auspiciada pel rei Ferran II, que regulava les relacions socials en el camp català durant l’edat moderna i que va donar estabilitat als camperols catalans."}]},{"text":"La crisi política arrenca amb la mort sense descendència de Martí l''Humà, últim rei de la casa de Barcelona, que obliga al Compromís de Casp (1412): s''elegeix Ferran d''Antequera, de família castellana. El seu nét, Ferran II, es casa amb Isabel de Castella; aquesta unió dinàstica acabarà fent que la corona d''Aragó perdi fins i tot la seva monarquia pròpia.","refs":[{"ref":"p. 15","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=15","quote":"La mort de Martí l’Humà sense descendència, l’últim rei de la casa de Barcelona, forçà el Compromís de Casp (1412), en què s’elegí Ferran d’Antequera, de família castellana, com a rei de la corona d’Aragó. El seu nét, Ferran II, fou qui es casà amb la reina Isabel de Castella."}]}]},{"n":"7","title":"Catalunya en la monarquia hispànica i la Guerra dels Segadors (s. XVI-XVII)","blocks":[{"text":"Dins la monarquia hispànica, el centre polític era Castella (on residien rei i cort); Catalunya conservava les seves institucions i el virrei hi representava el rei. És l''època que alguns autors anomenen «decadència». Una mostra n''és el bandolerisme: els bandolers dominaven boscos i mitja muntanya; el seu origen era sobretot la petita noblesa arruïnada per la crisi, tot i que també n''hi havia d''origen popular. Els més famosos van ser Joan Serrallonga i Perot Rocaguinarda. El fenomen desapareix amb la recuperació econòmica de final del segle XVII.","refs":[{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"Catalunya mantenia les seves institucions i el virrei era el representant del rei a casa nostra."},{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"L’origen dels bandolers l’hem de trobar en la petita noblesa arruïnada per la crisi, tot i que també hi havia bandolers d’origen popular. Alguns van gaudir d’una gran fama, com Joan Serrallonga o Perot Rocaguinarda."}]},{"text":"La Guerra dels Segadors (1640) té com a causes la Guerra dels Trenta Anys, que obligava a grans despeses, i les dificultats de la hisenda reial. El comte duc d''Olivares, en un escrit a Felip IV el 1625, defensava uniformitzar l''imperi i imposar les lleis castellanes, i va impulsar la Unió d''Armes, per la qual Catalunya havia d''aportar molts homes i diners a l''exèrcit. La guerra contra França va portar un gran exèrcit a Catalunya, que la població havia d''alimentar, amb abusos, i a més hi va haver males collites.","refs":[{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"El comte duc d’Olivares manifestà, en un escrit a Felip IV el 1625, que calia uniformitzar l’imperi i imposar les lleis castellanes"},{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"el comte duc va començar a imposar la Unió d’Armes, mitjançant la qual Catalunya havia d’aportar a l’exèrcit una gran quantitat d’homes i de diners"}]},{"text":"El 7 de juny de 1640 esclata a Barcelona la revolta dels segadors. Al principi no era patriòtica ni anticastellana: expressava el malestar popular. Les autoritats, amb Pau Claris al capdavant de la Generalitat, la van convertir en una confrontació contra la política del comte duc i en una guerra de separació. Es va demanar ajut a França i Lluís XIII va ser reconegut comte de Barcelona. Amb la Pau dels Pirineus (1659) Catalunya continua dins la monarquia hispànica, però França es queda el Rosselló, la Cerdanya, el Vallespir i el Conflent (la Catalunya Nord).","refs":[{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"concretament el 7 de juny de 1640. Aquesta revolta no tenia un caràcter patriòtic, ni anticastellà, sinó que expressava el malestar popular. Les autoritats de Catalunya, però, amb Pau Claris al davant de la Generalitat"},{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"Les autoritats catalanes van buscar l’ajut de França i el seu rei, Lluís XIII, fou reconegut com a comte de Barcelona."},{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"Finalment, amb la Pau dels Pirineus (1659), Catalunya segueix pertanyent a la monarquia hispànica i França es queda amb els comtats del Rosselló, la Cerdanya, el Vallespir i el Conflent."}]}]},{"n":"8","title":"La Guerra de Successió i l''Onze de Setembre","blocks":[{"text":"Carles II mor sense descendència el 1700 i el 1701 Felip V, el successor que havia nomenat, entra a Madrid. Anglaterra, Holanda, l''Imperi Austríac i després Portugal formen la Gran Aliança de la Haia, perquè Anglaterra no volia que una mateixa família regnés a França i a la monarquia hispànica. El 1702 comença la guerra i el 1703, a Viena, l''arxiduc Carles es proclama rei. Felip V havia jurat les constitucions a les Corts, però el 20 de juny de 1705 Catalunya signa amb Anglaterra el Pacte de Gènova: suport a l''arxiduc a canvi d''ajut militar i de la defensa de les constitucions catalanes.","refs":[{"ref":"p. 16","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=16","quote":"Carles II va morir sense descendència el 1700 i el 1701 Felip V, nomenat successor pel rei moribund, va entrar a Madrid."},{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"El 1702 començava la Guerra de Successió i el 1703, a Viena, l’arxiduc Carles es va proclamar rei de la monarquia hispànica."},{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"20 de juny de 1705 Catalunya va signar amb Anglaterra el Pacte de Gènova, mitjançant el qual donava suport a l’arxiduc Carles, a canvi d’ajut militar i el compromís de defensar les llibertats i constitucions catalanes."}]},{"text":"La guia resumeix en quatre les raons del suport català a l''arxiduc: la desconfiança cap a una monarquia de tradició centralista com la francesa; el sentiment antifrancès de la població, que venia de la Guerra dels Segadors; l''actitud repressiva del virrei de Felip V, Velasco; i l''admiració de certes capes econòmicament potents pel model econòmic i polític holandès (i també l''anglès). Amb aquest suport, la guerra internacional es converteix també en guerra civil; per als catalans l''arxiduc era Carles III.","refs":[{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"Tercera, l’actitud repressiva i desafortunada del virrei de Felip V, Velasco. Quarta, l’admiració que sentien certes capes econòmicament potents pel model econòmic i polític holandès"},{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"Amb el suport català a l’arxiduc, per a nosaltres Carles III, la guerra que havia començat a ser internacional es convertia en una guerra civil."}]},{"text":"Quan l''arxiduc hereta la corona imperial, els aliats ja no volen un sol rei per a la monarquia hispànica i l''Imperi, i negocien el tractat d''Utrecht (1713). Catalunya, sola, resisteix fins a l''Onze de Setembre de 1714, quan Barcelona cau en mans de les tropes felipistes i el conseller en cap Rafael Casanova és ferit. La repressió abolí les institucions catalanes; el Decret de Nova Planta (1716) va establir la centralització, la castellanització i l''absolutisme monàrquic, amb el cadastre, la construcció de la Ciutadella i l''empresonament i mort de molts austriacistes.","refs":[{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"tractat d’Utrecht el 1713. Catalunya restava sola i va decidir resistir. L’Onze de Setembre de 1714 la ciutat de Barcelona queia en mans de les tropes felipistes, mentre el conseller en cap de la ciutat, Rafael Casanova, era ferit."},{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"Decret de Nova Planta, de 1716, s’establiren la centralització, la castellanització i l’absolutisme monàrquic. Una repressió que comportà la imposició del cadastre, la construcció de la Ciutadella i l’empresonament i la mort de molts austriacistes."}]}]},{"n":"9","title":"Les transformacions del segle XVIII","blocks":[{"text":"Tot i haver perdut l''autogovern, al segle XVIII Catalunya viu un dinamisme econòmic que anuncia el capitalisme. Entre 1712 i 1787 la població es dobla: passa d''uns 470.000 a uns 900.000 habitants, per la reducció de les mortalitats catastròfiques i el creixement vegetatiu, fruit de les transformacions agràries. El litoral creix per sobre de la mitjana, l''interior creix i la muntanya s''alenteix; Barcelona arriba a final de segle a uns 100.000 habitants.","refs":[{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"En setanta anys, els que van de 1712 a 1787, Catalunya doblarà la seva població, que passarà d’uns 470.000 habitants a uns 900.000."},{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"un creixement per damunt de la mitjana a la zona del litoral, un creixement a l’interior i un alentiment a la muntanya"},{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"Barcelona arribaria al final de segle cap als 100.000 habitants"}]},{"text":"L''agricultura prospera per tres processos: extensió dels conreus, intensificació de les explotacions i especialització (per exemple, la vinya). El comerç es reactiva: mercat regional, comerç amb la resta de la Península i, sobretot, mercat colonial, especialment quan es liberalitza el comerç amb Amèrica des de qualsevol port, a l''últim terç de segle. S''exporten vi, aiguardent i teixits estampats i s''importen productes colonials.","refs":[{"ref":"p. 17","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=17","quote":"L’agricultura catalana va tenir una prosperitat rellevant que es basà en tres processos: l’extensió dels conreus, la intensificació de les explotacions i l’especialització agrícola"},{"ref":"p. 18","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=18","quote":"especialment quan es va liberalitzar el comerç amb Amèrica des de qualsevol port peninsular, a l’últim terç de segle. S’exportaven productes propis com el vi, l’aiguardent o els teixits estampats, mentre que s’importaven productes colonials."}]},{"text":"La demanda creixent de manufactures supera la capacitat dels gremis urbans i s''estén el treball a domicili: moltes cases de pagès treballen la llana. Cap a final de segle es popularitza el treball del cotó, que serà el motor de la naixent indústria catalana, amb la primera fàbrica d''indianes (teixits de cotó estampats).","refs":[{"ref":"p. 18","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=18","quote":"Moltes cases de pagès es dedicaren al treball de la llana"},{"ref":"p. 18","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=18","quote":"Cap al final de segle, es va començar a popularitzar el treball sobre el cotó, que a la llarga serà el motor de la naixent indústria catalana, quan veiem aparèixer la primera fàbrica d’indianes (teixits de cotó estampats)"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Naixement de Catalunya: segles IX-X; antecedent, la Marca Hispànica de Carlemany. Segons les idees força, neix com molts regnes medievals, per la feblesa de la monarquia franca i l''enfortiment dels comtats.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"En el nostre cas particular és conseqüència de la feblesa de la monarquia franca i de l’enfortiment dels comtats catalans sota el domini franc com a territori de frontera amb els sarraïns i que rebia el nom de Marca Hispànica."}]},{"text":"El substrat romà és la base sobre la qual cristal·litza la cultura catalana, i Catalunya ha estat cruïlla de pobles, cultures i religions.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"El substrat romà constitueix la base sobre la qual cristal·litzarà la cultura catalana."}]},{"text":"Per l''expansió en dues direccions compartim avui cultura i llengua amb València, les Illes Balears i l''Alguer.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"compartim en els nostres dies una mateixa cultura i llengua amb València, les Illes Balears i la ciutat sarda de l’Alguer"}]},{"text":"Institucions del segle XIV: Corts (funcions legislatives), Diputació del General o Generalitat (tasques executives) i Consell de Cent (administració local de Barcelona). El Parlament i la Generalitat actuals en són hereus directes.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"les Corts Catalanes, amb funcions legislatives, i la Diputació del General o Generalitat, que tenia encomanades tasques executives, així com el Consell de Cent, que era l’administració local de Barcelona"}]},{"text":"La decadència comença a la baixa edat mitjana i la unió dinàstica amb Castella desplaça el poder cap al regne veí.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"Fruit d’aquesta crisi política es produeix una unió dinàstica amb Castella que desplaçarà el poder cap al regne veí."}]},{"text":"Amb la monarquia hispànica Catalunya no perd la identitat política, però perd, entre d''altres, la Catalunya Nord i Sardenya per les guerres europees.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"La monarquia hispànica no suposa la pèrdua de la identitat política de Catalunya. Tanmateix, en aquest període es perden, entre d’altres, els territoris de la Catalunya Nord i de Sardenya com a conseqüència de les guerres europees."}]},{"text":"La pèrdua de les llibertats col·lectives és conseqüència de la derrota de l''11 de setembre de 1714 davant les tropes de Felip V; els dos bàndols eren els partidaris de l''arxiduc Carles i els de Felip d''Anjou.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"La pèrdua de les llibertats col·lectives de Catalunya és conseqüència de la derrota militar de l’11 de setembre de 1714"}]},{"text":"La recuperació demogràfica, social i econòmica del segle XVIII és conseqüència de les transformacions agràries i preindustrials.","refs":[{"ref":"p. 19","law":"Guia d''estudi, tema A.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=19","quote":"es va produir al llarg del segle xviii com a conseqüència de les transformacions agràries i preindustrials"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=11'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=11', 11, 19, 19, null
  from public.topics t where t.slug = 'mossos-a1-historia-1'
