insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema A.3, pp. 32-38', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=32', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-a3-historia-policia', 'A.3 Història de la policia a Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('mossos-esquadra') and t.slug = 'mossos-a3-historia-policia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Les forces de seguretat i la seva història"},{"n":"2","title":"L’origen dels Mossos d’Esquadra"},{"n":"3","title":"Transformacions policials durant el segle xix"},{"n":"4","title":"La policia durant les primeres dècades del segle xx"},{"n":"5","title":"La policia i la democràcia"}]'::jsonb, '["Una de les bases del manteniment de l’odre públic a Catalunya fou la defensa de la Pau i Treva.","La institucionalització del cos policial dels Mossos d’Esquadra va tenir lloc entre 1719 i 1721.","Els Mossos d’Esquadra es convertirien durant el segle xviii en un precedent de la policia moderna.","Durant el segle xix el Mossos continuarien la seva tasca, tot i la formació del cos policial unificat a tota Espanya de la Guàrdia Civil a partir de la meitat de segle.","El desenvolupament de les guàrdies urbanes va ser important a partir del segle xix amb el creixement urbanístic, i en destaca la formació de la Guàrdia Urbana de Barcelona el 1843.","A partir de l’abril de 1931, amb la República, les Esquadres no tan sols es van mantenir sinó que van adaptar-se al nou règim i van agafar un tarannà diferent del que havien tingut fins aquell moment. Van passar a ser identificades amb les institucions pròpies i amb el govern català, lleials als presidents de la Generalitat i vinculades al projecte populista republicà i catalanista d’aquells anys.","Durant la Guerra Civil, la policia es va veure immersa en les vicissituds històriques i va ser fidel al Govern de la Generalitat durant l’aixecament militar colpista.","El règim franquista fou un règim policial on es barrejaven els interessos del règim amb les tasques policials i militars i el partit únic era considerat un braç més de la policia.","Amb la restauració de la Generalitat i l’Estatut d’autonomia, els Mossos d’Esquadra esdevenen la policia de Catalunya, arrelada a l’imaginari col·lectiu, professionalment ben preparada i coincident amb els pressupòsits d’una societat avançada i democràtica."]'::jsonb, '["Cossos policials","Desplegament","Esquadres de Catalunya","Exèrcit popular","Fur militar","Guàrdia Civil","Guàrdia Urbana","Inquisició","Jurisdicció","Milícia Nacional","Mosso d’Esquadra","Ordre públic","Pau i Treva","Policia democràtica","Policia integral","Policia de Catalunya","Reial Audiència","Règim policial","Sistema de seguretat"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Les forces de seguretat i la seva història","blocks":[{"text":"La guia parteix d''una idea: cada sistema de seguretat pública té una policia concreta, amb unes funcions determinades, que és fruit de l''evolució històrica i de la realitat de cada moment. Per entendre una estructura policial cal conèixer l''organització econòmica, social i política de la societat, perquè la funció policial remet sempre al poder i a com aquest es relaciona amb la població. Per això la història de la policia és «la radiografia» de la història de les poblacions, de les seves vicissituds i tensions. La funció policial és, a més, una de les expressions més antigues de l''autoritat.","refs":[{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"Una estructura policial és impossible d’entendre si no es té en compte el marc d’organització econòmica, social i política d’una societat. En definitiva, la funció policial remet sempre al poder –en totes les seves formes– i a la manera com aquest poder es relaciona amb la seva societat."},{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"La història de la policia resulta, doncs, la radiografia de la història concreta de les poblacions, de les seves vicissituds i de les seves tensions."},{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"La funció policial, en les seves diverses formes, és una de les més antigues com a expressió de l’autoritat."}]},{"text":"Amb el feudalisme el poder es parcel·la i cada senyor té el seu propi sistema de seguretat. A la corona catalanoaragonesa es formen estructures armades per defensar els interessos de la monarquia, però la major part del país depenia de barons eclesiàstics i laics (i d''alguna ciutat), que eren responsables de l''ordre públic. A Catalunya no va existir mai un cos permanent de policia: l''ordre es mantenia més per la repressió que per la prevenció. Va ser fonamental la defensa de la Pau i Treva i la col·laboració de la població a través del sometent i del sagramental.","refs":[{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"El feudalisme, amb la consegüent parcel·lació dels poders, va comportar que cada un d’ells refermés el seu propi sistema de seguretat."},{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"A Catalunya no va existir mai un cos permanent de policia i el manteniment de l’ordre s’exercia a través de la repressió més que de la prevenció. Un fet fonamental fou la defensa de la Pau i Treva i la col·laboració de la població, a través del sometent i del sagramental."}]}]},{"n":"2","title":"L''origen dels Mossos d''Esquadra (1719-1723)","blocks":[{"text":"Fins fa uns anys hi havia la tradició que situava la creació dels Mossos el 1690 i donava tot el protagonisme als Veciana; avui l''origen és força conegut i ja no és motiu de polèmica, tot i que recerques en curs en perfilaran millor els detalls i el paper de Pere Anton Veciana. El cos actual de la policia de Catalunya té, doncs, un origen al segle XVIII.","refs":[{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"quan hi havia la tradició que suposava la seva creació el 1690 i donava tot el protagonisme als Veciana"},{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"recerques en curs ben segur que en perfilaran millor l’origen, les característiques en el moment de la seva formació i el paper de Pere Anton Veciana"}]},{"text":"El 1719, les tensions amb França obliguen a situar l''exèrcit a la frontera i cal una força que controli l''interior. El capità general i la Reial Audiència organitzen unes esquadres de paisans distribuïdes pels corregiments. Quan la tensió desapareix, el 1721, la majoria d''aquestes colles de veïns armats es desarmen, però es manté la de Valls, amb destacaments a Riudoms i Rodonyà, sota el comandament únic de Pere Anton Veciana. En aquest període s''institucionalitzen els Mossos d''Esquadra. El 1723 les esquadres es remodelen i s''amplien, i Pere Anton Veciana i Rabasa n''és nomenat comandant.","refs":[{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"El 1719 les tensions amb França van fer situar l’exèrcit a la frontera, per la qual cosa calia crear una força policial que controlés l’interior del territori. Per fer aquesta tasca, el capità general i la Reial Audiència van organitzar unes esquadres de paisans, distribuïdes pels corregiments."},{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"la de Valls, amb destacaments a Riudoms i Rodonyà, es va mantenir sota la comandància única de Pere Anton Veciana. En aquest període es van institucionalitzar els Mossos d’Esquadra. L’any 1723 es van remodelar i ampliar les esquadres i, aquest any, Pere Anton Veciana i Rabasa en fou nomenat el comandant."}]},{"text":"Compte amb les dates: les idees força diuen que la institucionalització va tenir lloc «entre 1719 i 1721», mentre que el desenvolupament del tema situa la institucionalització en el període que segueix el 1721 i la remodelació el 1723. Per a l''examen, si la pregunta remet a les idees força, la resposta és 1719-1721.","refs":[{"ref":"p. 38","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=38","quote":"La institucionalització del cos policial dels Mossos d’Esquadra va tenir lloc entre 1719 i 1721."}]}]},{"n":"3","title":"Els Mossos al segle XVIII: una policia precursora","blocks":[{"text":"En primera instància, els Mossos eren una força policial típicament reial i borbònica, que controlava l''ordre públic en un territori on quedaven austriacistes derrotats però armats i on la població tenia prohibit el sometent i portar armes. Durant tot el segle XVIII els va comandar la família Veciana, premiada per la seva fidelitat filipista.","refs":[{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"Els Mossos representarien, en primera instància, una força policial típicament reial i borbònica, controladora de l’ordre públic en un territori amb algun austriacista derrotat però armat que calia perseguir, i amb una població a la qual s’havia prohibit el sometent i la possibilitat de portar armes."},{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"Al llarg del segle xviii, els Mossos sempre van ser comandats per la família Veciana, a qui es premiava la fidelitat monàrquica filipista."}]},{"text":"Des dels anys quaranta del segle XVIII el cos es converteix en una policia preparada i efectiva, tota una innovació i un precedent de les policies modernes: creix pel territori i és la policia més avançada del moment. Per això, a la segona meitat del segle, el model es va exportar a altres zones de la monarquia.","refs":[{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"a partir dels anys quaranta del segle xviii, i transformant-se en un precedent de les policies modernes"},{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"Això va fer, fins i tot, que a la segona meitat de segle el model fora exportat a altres zones de la monarquia per a la seva implantació."}]}]},{"n":"4","title":"El segle XIX: l''Estat liberal i la Guàrdia Civil","blocks":[{"text":"Al segle XIX la nació i l''estat esdevenen els eixos del poder i l''estat liberal substitueix la monarquia absoluta, cosa que exigeix un nou aparell policial. El segle s''obre amb la Milícia Nacional, força revolucionària civil i local, dissolta quan s''abandonen els projectes liberals més progressistes. Qui vertebra l''Estat és el liberalisme conservador, que fa girar la seguretat entorn de tres conceptes: militarització, centralització i una concepció profundament conservadora de la societat. D''aquí neix, el 1844, la Guàrdia Civil, que porta l''Estat a tots els racons i esdevé l''eix troncal de la seguretat pública.","refs":[{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"amb la força revolucionària de la Milícia Nacional, profundament civil i local, que serà dissolta quan s’abandonin els projectes liberals més progressistes"},{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"tres conceptes: la militarització, la centralització i una concepció profundament conservadora de la societat. En aquests principis rau la fundació, el 1844, de la Guàrdia Civil, que va portar el nou Estat fins als últims racons de la Península i va esdevenir l’eix troncal de la seguretat pública."}]},{"text":"Els Mossos perviuen gairebé tot el segle com a forces auxiliars reconegudes pel nou sistema, perquè participaven del fur militar. El canvi és al comandament: des de 1835-1837 la família Veciana deixa de controlar el cos, que passa a mans d''oficials de l''exèrcit.","refs":[{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"es van convertir en unes forces auxiliars, reconegudes pel nou ordre i pel nou sistema policial gràcies al fet que participaven del fur militar"},{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"la família Veciana ja no va controlar més el cos i des de 1835-1837 es va posar en mans d’oficials provinents de l’exèrcit"}]}]},{"n":"5","title":"El segle XIX: policies municipals i restabliment dels Mossos","blocks":[{"text":"El creixement urbà fa aparèixer les primeres policies municipals, que amb els serenos i els alcaldes de barri formen la seguretat dels ajuntaments. La Constitució de 1812 ja encomanava als alcaldes vetllar per la pau i la seguretat dels veïns. Aquesta funció recull una tradició moderna (l''herència de la Milícia Nacional) i una d''antiga (l''autodefensa de les comunitats amb el sometent, la partida o la ronda). La Guàrdia Municipal de Barcelona es crea el 26 de novembre de 1843 i serà una de les més importants de Catalunya.","refs":[{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"van començar a aparèixer les primeres policies municipals que, juntament amb els serenos i els alcaldes de barri, completaven les estructures de seguretat dependents dels ajuntaments. La Constitució de 1812 ja havia consagrat als alcaldes la funció de vetllar per la pau i la seguretat dels veïns."},{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"el sometent, la partida o la ronda"},{"ref":"p. 34","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=34","quote":"La Guàrdia Municipal de la ciutat de Barcelona, per exemple, va ser creada el 26 de novembre de 1843"}]},{"text":"El Sexenni revolucionari havia dissolt els Mossos. Amb la Restauració, des de 1875 es planteja recuperar-los i a partir de 1880 es reorganitzen definitivament. Mal vistos per les classes populars urbanes, tenien fama entre la pagesia i el suport de Capitania i d''una part de la burgesia; eren útils per restablir l''ordre després de l''última Guerra Carlina. La Diputació Provincial de Barcelona els restitueix el 1877 i n''aprova el Reglament el 1880. Actuen com a auxiliar rural de la Guàrdia Civil i defensen la propietat al camp; les altres diputacions només mantenen la Guàrdia Civil.","refs":[{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"Un cop liquidada l’experiència del Sexenni revolucionari, que havia dissolt el cos dels Mossos d’Esquadra"},{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"És en aquest context que la Diputació Provincial de Barcelona restituí els Mossos d’Esquadra el 1877 i n’aprovà el Reglament el 1880. Continuava el seu paper d’auxiliar rural de la Guàrdia Civil"},{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"La resta de diputacions provincials, menys poblades i amb una seguretat pública menys conflictiva, van optar per continuar només amb la Guàrdia Civil."}]}]},{"n":"6","title":"Les primeres dècades del segle XX (1898-1923)","blocks":[{"text":"Després de 1898, la Lliga volia, segons les Bases de Manresa (1892), una seguretat basada en el sometent i una força permanent sota el poder regional. El fur militar dels Mossos, reinstaurat el 1892, els posava en una situació compromesa davant l''actitud de l''exèrcit (assalt al Cu-Cut! i La Veu de Catalunya, 1905). La Lliga, a la Diputació i a la Mancomunitat (1914), va tenir una posició ambivalent: no els va incloure en els plans regionals perquè eren exclusius de Barcelona, però els va defensar; eren repartits en una cinquantena de poblacions de la província.","refs":[{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"un sistema de seguretat basat en el sometent i amb una força policial permanent sota les ordres del poder regional. El fur militar dels Mossos, reinstaurat el 1892"},{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"no van ser mai tinguts en compte en els plans de reorganització regional, pel fet de ser exclusius de Barcelona"},{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"repartides en una cinquantena de poblacions de la província de Barcelona"}]},{"text":"Entre 1905 i 1908, la Llei i el Reglament de la policia governativa inicien la professionalització de la policia civil de l''Estat amb dos cossos: el de Vigilancia, civil, d''investigació i policia judicial, i el de Seguridad, uniformat i d''organització militar, per a la via pública. La reforma crea definitivament la Dirección General de Seguridad, l''ingrés per concurs oposició i escoles de formació.","refs":[{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"Entre 1905 i 1908, amb l’aparició de la Llei i del Reglament de la policia governativa"},{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"el de Vigilancia, absolutament civil i dedicat a funcions d’investigació i de policia judicial, i el de Seguridad, uniformat i amb organització militar, que faria el servei a les vies públiques"},{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"la creació definitiva de la Dirección General de Seguridad, l’ingrés en els cossos policials mitjançant concursos oposició o la creació d’escoles de formació"}]},{"text":"A la Setmana Tràgica (1909) la repressió la fa sobretot la Guàrdia Civil, amb el sometent i els Mossos. Els republicans en demanen la dissolució i el setembre de 1917 la Diputació aprova l''extinció gradual del cos amortitzant les vacants. Però el pistolerisme (des de 1919) revitalitza els Mossos per controlar la perifèria de les ciutats.","refs":[{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"el setembre d’aquest any la Diputació aprovava l’extinció gradual del cos amb l’amortització de les places que anaven quedant vacants"},{"ref":"p. 35","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=35","quote":"La necessitat d’una força policial que controlés la perifèria de les ciutats davant de l’actuació de pistolers va tornar a revitalitzar les funcions d’aquest cos."}]}]},{"n":"7","title":"La dictadura de Primo de Rivera i la reorganització de 1930","blocks":[{"text":"La dictadura (1923) veu els Mossos com un cos propi. Pagats per la Diputació però sota Capitania i el governador civil, custodien els terrenys de l''Exposició Universal i, amb el comandant Oller, fan tasca repressiva al servei de Martínez Anido, ministre de la Governació. Per això, caigut Primo de Rivera, el Decret del 14 d''agost de 1930 dissol els Mossos de Barcelona i els reorganitza vinculats exclusivament a la Diputació, cosa que redueix la dependència militar i del govern civil.","refs":[{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"Els Mossos, amb el comandant Oller com a cap, foren utilitzats per a la tasca policial repressiva de la dictadura i de Martínez Anido, ministre de la Governació durant aquells anys."},{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"El Decret del 14 d’agost de 1930 dissolia el cos dels Mossos d’Esquadra de Barcelona i el tornava a reorganitzar sota uns nous paràmetres."},{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"es va aconseguir que el cos armat es vinculés exclusivament a la Diputació"}]}]},{"n":"8","title":"La República i la Guerra Civil","blocks":[{"text":"Amb la República (abril de 1931) les Esquadres s''identifiquen amb les institucions autonòmiques i el govern català, lleials als presidents de la Generalitat. El 14 d''abril de 1931 el capità Frederic Escofet es posa a les ordres de Macià, i Pérez Farràs, comandant d''artilleria, és nomenat comandant dels Mossos. El 14 d''octubre de 1932 un decret de Macià estén els Mossos a tot Catalunya; amb l''Estatut, tots els cossos depenen del Comissariat d''Ordre Públic.","refs":[{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"El 14 d’abril de 1931, el capità Frederic Escofet, caporal del destacament de la Garriga, es va posar a les ordres del president Macià"},{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"Pérez Farràs, comandant d’artilleria, va ser nomenat comandant dels Mossos"},{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"El 14 d’octubre de 1932, el president Macià signava un decret mitjançant el qual s’estenia el cos policial dels Mossos a tot Catalunya. Al mateix temps, i a partir de l’Estatut, tots els cossos policials van passar a dependre del Comissariat d’Ordre Públic"}]},{"text":"Després dels fets d''Octubre de 1934 les Esquadres són desarmades per haver atacat l''exèrcit, però tornen a ser operatives amb un nou comandant. Amb el Front d''Esquerres (febrer de 1936) arriba l''amnistia, també per als seus comandaments, i Companys torna a Barcelona escortat per motoristes de la Guàrdia Urbana i dels Mossos. A la Guerra Civil la policia es posa al costat de la Generalitat contra els colpistes, amb tensions amb les patrulles de control i els fets de maig de 1937.","refs":[{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"Després dels fets d’Octubre, les Esquadres, en un primer moment, van ser desarmades pel fet d’haver atacat l’exèrcit"},{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"La tornada a Barcelona del president Companys, escortat per motoristes de la Guàrdia Urbana i dels Mossos"},{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"D’entrada, van posar-se al costat del Govern de la Generalitat i en contra de les forces colpistes."}]}]},{"n":"9","title":"El franquisme: un règim policial","blocks":[{"text":"El franquisme és un veritable règim policial: barreja els interessos del règim amb les tasques policials i militars i considera el partit únic un braç més de la policia. Hi ha depuracions a la Guàrdia Civil i la policia, i se suspenen cossos com els Mossos. Fins al 1952 no es restitueixen, integrats a l''exèrcit en fur, insígnies i dependència, com a guàrdia de la Diputació de Barcelona, presidida pel marquès de Castell-Florite. La policia, inclosa la local, era un instrument del nou ordre i sovint s''hi premiava l''afecció al règim.","refs":[{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"Es van produir depuracions dins la Guàrdia Civil i la policia i la suspensió d’alguns cossos policials, entre ells, els Mossos d’Esquadra. S’hauria d’esperar fins a l’any 1952 perquè els Mossos, integrats en l’exèrcit espanyol en fur, insígnies i dependència, fossin restituïts com una guàrdia de la Diputació de Barcelona presidida, en aquells moments, pel marquès de Castell-Florite."}]}]},{"n":"10","title":"La policia i la democràcia: el model de 1978","blocks":[{"text":"Després de 1975, la Transició, fruit de l''acord entre el rupturisme de l''oposició i el reformisme del règim anterior, porta Constitució, llibertats i Estatut. La Constitució de 1978 estableix un model policial pluralista amb tres nivells: la policia de l''Administració central de l''Estat, les policies de les comunitats autònomes que la prevegin en el seu estatut i les policies locals. La reflexió sobre la nova policia havia de transformar els aparells de la dictadura, garantir l''eficàcia i redefinir la seguretat d''acord amb la nova estructura de l''Estat. A les policies locals el canvi comença amb els primers ajuntaments democràtics de 1979.","refs":[{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"la Constitució espanyola de 1978 va establir un model pluralista en aquesta matèria, a través de tres nivells: la policia de l’Administració central de l’Estat, les policies de les comunitats autònomes l’estatut de les quals en preveiés la creació i les policies locals dependents del poder municipal"},{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"que s’havien de transformar els aparells policials de la dictadura, que calia garantir, amb la transformació, l’eficàcia policial"},{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"van iniciar-se a partir dels primers ajuntaments democràtics de 1979"}]}]},{"n":"11","title":"La Policia de la Generalitat i el desplegament","blocks":[{"text":"La Generalitat restaurada estén els Mossos a partir del nucli de la Diputació de Barcelona. La guia el presenta com un cos creat al set-cents, amb nom històric, la policia més antiga d''Europa i alhora nova, imatge d''una Catalunya autònoma. El 1983 el Parlament aprova la llei que crea la Policia de la Generalitat, amb els Mossos com a nucli inicial. L''Escola de Policia de Catalunya inaugura la seu a Mollet del Vallès el 1985; des de 1991 hi formen també les policies locals, i avui és l''Institut de Seguretat Pública de Catalunya.","refs":[{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"resultava ser la més antiga d’Europa"},{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"El 1983 el Parlament de Catalunya aprovava una llei mitjançant la qual es creava la Policia de la Generalitat, el nucli inicial de la qual fou el cos dels Mossos."},{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"l’Escola de Policia de Catalunya, que inauguraria la seva seu a Mollet del Vallès el 1985. A partir de 1991 també s’hi formarien els membres de les policies locals"},{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"avui Institut de Seguretat Pública de Catalunya"}]},{"text":"El desplegament comença el novembre de 1994, en substitució dels cossos de l''Estat: primer a Osona, després al Ripollès i la Selva. Entre 1997 i 1998 la Generalitat assumeix les competències executives de trànsit. El novembre de 2008 culmina el desplegament amb l''arribada a les Terres de l''Ebre i el Camp de Tarragona.","refs":[{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"A partir de novembre de 1994 es va iniciar el desplegament dels Mossos d’Esquadra en el territori català, en substitució de les forces i els cossos de seguretat de l’Estat. El primer emplaçament seria la comarca d’Osona, seguida del Ripollès i la Selva."},{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"Entre 1997 i 1998 la Generalitat tindria les competències executives en matèria de trànsit i circulació de vehicles de motor. El novembre de 2008 va significar la culminació del procés de desplegament, amb l’arribada del cos a les Terres de l’Ebre i el Camp de Tarragona."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Edat mitjana: cap cos permanent de policia; ordre per repressió; Pau i Treva, sometent i sagramental.","refs":[{"ref":"p. 38","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=38","quote":"Una de les bases del manteniment de l’odre públic a Catalunya fou la defensa de la Pau i Treva."}]},{"text":"1719: esquadres de paisans organitzades pel capità general i la Reial Audiència; 1721: es manté la de Valls; 1723: Pere Anton Veciana i Rabasa, comandant.","refs":[{"ref":"p. 33","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=33","quote":"el capità general i la Reial Audiència van organitzar unes esquadres de paisans"}]},{"text":"Al segle XVIII els Mossos són un precedent de la policia moderna.","refs":[{"ref":"p. 38","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=38","quote":"Els Mossos d’Esquadra es convertirien durant el segle xviii en un precedent de la policia moderna."}]},{"text":"Guàrdia Civil: 1844. Guàrdia Municipal (o Urbana) de Barcelona: 1843. Restitució dels Mossos per la Diputació: 1877; Reglament: 1880.","refs":[{"ref":"p. 38","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=38","quote":"en destaca la formació de la Guàrdia Urbana de Barcelona el 1843"}]},{"text":"Decret de 14 d''agost de 1930: dissolució i reorganització; decret de Macià de 14 d''octubre de 1932: extensió a tot Catalunya.","refs":[{"ref":"p. 36","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=36","quote":"s’estenia el cos policial dels Mossos a tot Catalunya"}]},{"text":"Durant la Guerra Civil la policia va ser fidel al Govern de la Generalitat; el franquisme, un règim policial; restitució dels Mossos el 1952.","refs":[{"ref":"p. 38","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=38","quote":"Durant la Guerra Civil, la policia es va veure immersa en les vicissituds històriques i va ser fidel al Govern de la Generalitat durant l’aixecament militar colpista."}]},{"text":"Policia de la Generalitat: llei de 1983; Escola a Mollet: 1985; policies locals hi formen des de 1991.","refs":[{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"A partir de 1991 també s’hi formarien els membres de les policies locals"}]},{"text":"Desplegament: Osona (novembre de 1994) → Terres de l''Ebre i Camp de Tarragona (novembre de 2008).","refs":[{"ref":"p. 37","law":"Guia d''estudi, tema A.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=37","quote":"El primer emplaçament seria la comarca d’Osona"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=32'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=32', 32, 38, 38, null
