insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema A.5, pp. 57-66', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=57', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-a5-marc-geografic', 'A.5 Marc geogràfic de Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('mossos-esquadra') and t.slug = 'mossos-a5-marc-geografic' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Situació i divisió administrativa"},{"n":"2","title":"El relleu"},{"n":"2.1","title":"El Pirineu"},{"n":"2.2","title":"La Depressió Central"},{"n":"2.3","title":"El Sistema Mediterrani"},{"n":"2.4","title":"La Serralada Transversal"},{"n":"2.5","title":"Les planes litorals i la costa"},{"n":"3","title":"Els climes a Catalunya"},{"n":"3.1","title":"Les temperatures"},{"n":"3.2","title":"Les precipitacions"},{"n":"4","title":"La xarxa hidrogràfica"},{"n":"5","title":"La vegetació"},{"n":"6","title":"La població"},{"n":"6.1","title":"Evolució de la població"},{"n":"6.2","title":"Distribució de la població"}]'::jsonb, '["Administrativament, Catalunya s’organitza en vuit vegueries, 42 comarques i 947 municipis.","Catalunya no configura cap unitat fisiogràfica determinada i es caracteritza per una gran diversitat paisatgística. A partir de la interacció de factors físics, socials, econòmics i culturals, s’ha anat conformant una important varietat comarcal.","Catalunya està formada per tres grans unitats de relleu, que són els Pirineus, la Depressió Central i el Sistema Mediterrani. El litoral català, per la seva banda, està constituït per planes litorals, costes i alguns deltes.","A Catalunya, el clima és de tipus mediterrani temperat. La complexitat orogràfica de Catalunya i la proximitat a la mar Mediterrània fan que tinguin rellevància factors com el relleu i la continentalitat, que donen lloc a altres varietats climàtiques.","Els rius catalans presenten règims fluvials molt diferents i irregulars, fet que provoca l’existència de diferents xarxes hidrogràfiques.","La variada orografia i el clima fan que a Catalunya hi trobem una gran diversitat de paisatges vegetals. La vegetació potencial a Catalunya pertany a tres grans regions biogeogràfiques: la regió mediterrània, la regió eurosiberiana i la regió boreoalpina.","La població de Catalunya ha tingut tres grans períodes de creixement en els darrers 100 anys. L’últim ha estat protagonitzat per persones procedents de l’estranger, cosa que ha provocat una heterogeneïtzació de la societat catalana.","La distribució de la població a Catalunya és molt irregular, amb una concentració del 64% a la RMB."]'::jsonb, '["Altiplà","Altitud","Anticicló","Àrea Metropolitana de Barcelona","Boscos caducifolis","Comarca","Conques d’erosió","Continentalitat","Densitat de població","Esperança de vida","Fluxos de mobilitat","Índex de fecunditat","Ombra pluviomètrica","Onada immigratòria","Orografia","Planes deltaiques","Planes tectòniques","Règim pluvial","Règim pluvionival","Regió Metropolitana de Barcelona","Relleu en costa","Unitat fisiogràfica","Valls fluvials","Vegetació potencial","Vegueria","Xarxa fluvial"]'::jsonb, '[{"text":"Esmena oficial (setembre 2026): Catalunya té 42 comarques més l’Aran com a entitat territorial singular (p. 56 i punt 1 de la p. 64), 947 municipis i 8 vegueries.","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf"}]'::jsonb, '[{"n":"1","title":"Situació de Catalunya","blocks":[{"text":"Catalunya ocupa 32.108 km² a l''extrem nord-est de la península Ibèrica, dins de la regió mediterrània. Els seus límits naturals són els Pirineus al nord, la mar Mediterrània al sud i a l''est, i la depressió de l''Ebre a l''oest. Pel que fa als límits polítics, toca amb França i Andorra al nord, amb Aragó a l''oest i amb el País Valencià al sud.","refs":[{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"Catalunya, amb una extensió de 32.108 km2, es troba situada a l’extrem nord-est de la península Ibèrica, en la regió mediterrània, delimitada al nord per la serralada dels Pirineus, al sud i est per la mar Mediterrània i a l’oest per la depressió de l’Ebre."},{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"Catalunya limita al nord amb França i Andorra; a l’oest, amb Aragó, i al sud, amb el País Valencià."}]},{"text":"Una idea força: Catalunya no forma cap unitat fisiogràfica determinada. El seu tret definidor és la gran diversitat paisatgística, amb una orografia irregular en què s''alternen planes i muntanyes. La combinació de factors físics, socials, econòmics i culturals ha anat creant una important varietat comarcal.","refs":[{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"Catalunya no configura cap unitat fisiogràfica determinada i es caracteritza per una gran diversitat paisatgística, amb una irregular orografia, caracteritzada per una alternança de planes i muntanyes. A partir de la interacció de factors físics, socials, econòmics i culturals, s’ha anat conformant una important varietat comarcal."}]}]},{"n":"2","title":"Divisió administrativa: províncies, comarques, municipis i vegueries","blocks":[{"text":"El territori es divideix en quatre províncies (Barcelona, Tarragona, Lleida i Girona) i en comarques, que es divideixen en municipis: 947 l''any 2019. El municipi és la unitat administrativa bàsica, on resideix l''autoritat local. Compte amb les comarques: el text del tema en diu 43, però les idees força en diuen 42. L''esmena oficial de setembre de 2026 ho aclareix: 42 comarques més l''Aran com a entitat territorial singular, 947 municipis i 8 vegueries.","refs":[{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"El seu territori està dividit en quatre províncies, Barcelona, Tarragona, Lleida i Girona, i en 43 comarques. Les comarques es divideixen en municipis, fins a un total de 947 l’any 2019. El municipi és la unitat administrativa bàsica, on resideix l’autoritat local."},{"ref":"Idea força 1, p. 66","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=66","quote":"Administrativament, Catalunya s’organitza en vuit vegueries, 42 comarques i 947 municipis."},{"ref":"","law":"Esmenes a la Guia d''estudi (setembre 2026)","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf","quote":"Catalunya té 42 comarques més l’Aran com a entitat territorial singular (p. 56 i punt 1 de la p. 64), 947 municipis i 8 vegueries."}]},{"text":"La Llei de vegueries la va aprovar el Parlament el 27 de juliol de 2010, seguint les directrius de l''Estatut de 2006. La vegueria és una unitat administrativa entre l''escala comarcal i l''autonòmica, pensada per substituir les diputacions provincials. La llei en fixava set, i a començaments de 2017 es van ampliar a vuit. Només hi ha fixades les capitals que coincideixen amb les províncies: Barcelona, Lleida, Tarragona i Girona.","refs":[{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"Les vegueries són una unitat administrativa que s’ha de situar entre l’escala comarcal i l’autonòmica, i substituir les diputacions provincials. La Llei, aprovada el 27 de juliol, seguint les directrius marcades a l’Estatut de 2006, fixava en set el nombre definitiu de vegueries, ampliat a vuit a començaments de 2017."},{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"únicament estan fixades les que coincideixen amb les províncies: Barcelona, Lleida, Tarragona i Girona."}]},{"text":"Les vuit vegueries són Alt Pirineu, Barcelona, Catalunya Central, Girona, Lleida, Camp de Tarragona, Terres de l''Ebre i Penedès. L''Aran, entitat territorial singular que es relaciona bilateralment amb el Govern de la Generalitat, forma part de l''Alt Pirineu. L''Anoia queda partida: vuit municipis van a la Catalunya Central i la resta, al Penedès.","refs":[{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"l’Aran constitueix una entitat territorial singular dins de Catalunya, es relaciona de manera bilateral amb els òrgans de govern de la Generalitat, i forma part de la vegueria de l’Alt Pirineu."},{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"Penedès, que comprèn els municipis de les comarques de l’Alt Penedès, el Baix Penedès, el Garraf i bona part de l’Anoia (excepte vuit municipis, que restaran a la vegueria central)."}]}]},{"n":"3","title":"El relleu: grans unitats i el Pirineu","blocks":[{"text":"El relleu català té tres grans unitats: els Pirineus, la Depressió Central i el Sistema Mediterrani, que conflueixen a l''extrem nord-est, a la Serralada Transversal. El litoral alterna planes litorals, costes abruptes i alguns deltes.","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"Catalunya està formada per tres grans unitats de relleu, que són els Pirineus, la Depressió Central i el Sistema Mediterrani. Aquestes tres unitats conflueixen en l’extrem nord-est, on es troba la Serralada Transversal."}]},{"text":"El Pirineu fa més de 400 km, del golf de Biscaia a la Mediterrània; la part catalana en té uns 250, de la Vall d''Aran al cap de Creus. Les seves valls fluvials van de nord a sud i obren pas cap a la Depressió Central. L''excepció és la Cerdanya, plana d''origen tectònic orientada d''est a oest, per on passa el curs alt del Segre. Entre valls es passa per ports i collades (la Bonaigua, el Cantó, Toses). Té dues subunitats: el Pirineu axial i el Prepirineu.","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"El Pirineu és una serralada de grans dimensions que s’estén al llarg de més de 400 km, des del golf de Biscaia a la mar Mediterrània. La part catalana té uns 250 km de longitud"},{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"L’excepció n’és la Cerdanya, plana d’origen tectònic, orientada d’est a oest i per on circula el curs alt del Segre."},{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"En general, el Pirineu es pot dividir en dues subunitats: el Pirineu axial i el Prepirineu."}]},{"text":"El Pirineu axial és el sector més alt, amb cims punxeguts, valls profundes i estanys glacials del quaternari; les altituds baixen d''oest a est. A la Vall d''Aran i el Pallars hi ha cims de més de 3.000 m, com la Pica d''Estats (3.143 m), el punt més alt de Catalunya. A la Cerdanya i el Ripollès no s''arriba als 3.000 m (Puigmal, 2.913 m; Tossa Plana de Lles, 2.916 m).","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"Alguns cims superen els 3.000 metres, com la Pica d’Estats (3.143 m), que és el punt més elevat de Catalunya. Al sector de la Cerdanya i el Ripollès les formes se suavitzen i no arriben als 3.000 metres (Puigmal, 2.913 m; Tossa Plana de Lles, 2.916 m)."}]},{"text":"El Prepirineu, més baix, s''estén al sud de l''axial i és més ample entre la Noguera Ribagorçana i el Segre, on hi ha la Conca de Tremp i els Montsecs. Entre el Segre i el Llobregat hi destaquen la serra del Cadí (2.648 m), amb el Pedraforca (2.497 m), i la serra del Moixeró (2.276 m).","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"El Prepirineu és una subunitat de menor alçada que s’estén al sud del Pirineu axial i presenta la seva màxima amplada entre la Noguera Ribagorçana i el Segre."},{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"la serra del Cadí (2.648 m), amb el massís del Pedraforca (2.497 m), i la serra del Moixeró (2.276 m)"}]}]},{"n":"4","title":"La Depressió Central","blocks":[{"text":"La Depressió Central ocupa bona part del país entre el Pirineu i el Sistema Mediterrani i està oberta cap a ponent, cap a la depressió de l''Ebre, de la qual forma part. S''inclina lleugerament cap a ponent; les cotes més altes (uns 1.000 m) són al nord-est, tocant a la Serralada Transversal.","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"Està oberta cap a ponent, cap a la depressió de l’Ebre, de la qual forma part. La Depressió Central està lleugerament inclinada cap a ponent i les seves altituds més importants, al voltant dels 1.000 m, es troben en el sector nord-est, en contacte amb la Serralada Transversal."}]},{"text":"Al centre i a l''est hi ha altiplans (Lluçanès, Moianès i Segarra) i conques d''erosió: la plana de Vic, el pla de Bages, la conca d''Òdena i la conca de Barberà, excavades pels rius Ter i Congost, Cardener i Llobregat, i Anoia i Francolí. A l''oest hi ha planes sedimentàries, com les d''Urgell i de Lleida.","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"Destaquen els altiplans del Lluçanès, del Moianès i el de la Segarra. Entre aquests relleus, hi trobem la plana de Vic, el pla de Bages, la conca d’Òdena i la conca de Barberà, que són conques d’erosió"}]}]},{"n":"5","title":"El Sistema Mediterrani i la Serralada Transversal","blocks":[{"text":"El Sistema Mediterrani és paral·lel a la costa i té tres subunitats: la Serralada Prelitoral i la Litoral, separades per la Depressió Prelitoral. A la Prelitoral hi ha les Guilleries, el Montseny, Sant Llorenç del Munt, Montserrat, Prades, el Montsant i els ports de Besseit; el Turó de l''Home, al Montseny (1.706 m), és el punt culminant del Sistema Mediterrani.","refs":[{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"està constituït per tres subunitats de relleu: la Serralada Prelitoral i la Serralada Litoral, separades per la Depressió Prelitoral."},{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"el Montseny, amb el cim del Turó de l’Home (1.706 m) com a punt culminant del Sistema Mediterrani"}]},{"text":"La Serralada Litoral, de l''Empordà al Garraf, és més baixa (Gavarres, Montnegre, Corredor, Collserola, Garraf). La Depressió Prelitoral, fruit de l''enfonsament de part de l''antic massís, comprèn les planes del Penedès, el Vallès, la Selva i el Gironès.","refs":[{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"La Serralada Litoral s’estén des de l’Empordà fins al Garraf i ofereix menors altituds."},{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"Comprèn les planes del Penedès, el Vallès, la Selva i el Gironès."}]},{"text":"A la Serralada Transversal conflueixen les tres grans unitats. La caracteritza l''activitat volcànica del pla d''Olot: cons com Santa Margarida i el Croscat i colades com la massa basàltica de Castellfollit de la Roca. Hi destaca la serra de Puigsacalm (1.515 m).","refs":[{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"es caracteritza per l’activitat volcànica localitzada al pla d’Olot i el seu entorn, amb cons volcànics com els de Santa Margarida i el Croscat, i corrents de lava com la massa basàltica de Castellfollit de la Roca."}]}]},{"n":"6","title":"Les planes litorals i la costa","blocks":[{"text":"La costa fa uns 515 km, de Portbou al riu de la Sénia (límit amb el País Valencià). És sobretot suau i sorrenca, excepte on les serres toquen al mar: el cap de Creus, la Costa Brava i les costes de Garraf. Les planes litorals principals són la de l''Empordà, amb aiguamolls, i el delta de l''Ebre, de 320 km². També són planes deltaiques les de la Tordera, el Besòs, el Llobregat i el Francolí.","refs":[{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"El litoral català (uns 515 km de costa) s’estén des de Portbou fins al riu de la Sénia (límit amb el País Valencià)."},{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"el delta de l’Ebre, amb una extensió de 320 km2. Altres planes deltaiques són les formades per les desembocadures de la Tordera, el Besòs, el Llobregat i el Francolí."}]}]},{"n":"7","title":"Els climes a Catalunya","blocks":[{"text":"El clima és mediterrani temperat: un hivern fred i un estiu càlid, estables, i una primavera i una tardor més inestables i plujoses. El relleu i la continentalitat creen altres varietats: mediterrani litoral, de tendència continental, de muntanya baixa i mitjana i de muntanya alta. A més, hi ha clima atlàntic a la Vall d''Aran i climes alpí i subalpí a partir dels 1.500 m al Pirineu.","refs":[{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"A Catalunya, el clima és de tipus mediterrani temperat i es caracteritza per una estació freda, l’hivern, i una de càlida, l’estiu."},{"ref":"p. 61","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=61","quote":"factors com el relleu i la continentalitat tinguin influència en el règim termomètric i en el règim de precipitacions"},{"ref":"p. 61","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=61","quote":"A aquests climes, cal afegir-hi el clima atlàntic que trobem a la Vall d’Aran, i els climes alpí i subalpí que es donen a partir dels 1.500 m en sectors del Pirineu."}]},{"text":"Els climes es reparteixen segons dos factors: la distància al mar (continentalitat) i l''altitud. Com més lluny del mar i més amunt, menys mediterrani. La latitud hi pesa poc: el nord és més fred per les muntanyes, no per la distància a l''Equador.","refs":[{"ref":"p. 61","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=61","quote":"Els diferents climes es troben distribuïts a Catalunya segons dos grans factors geogràfics: d’una banda la distància al mar (continentalitat) i de l’altra, l’altitud."}]}]},{"n":"8","title":"Les temperatures i les precipitacions","blocks":[{"text":"Les temperatures mitjanes anuals van dels 17,1 °C de Tortosa (50 m) als 3 °C de l''Estany Gento (més de 2.000 m). La temperatura es mesura amb el termòmetre, en graus Celsius, i calen com a mínim 10 anys de registres diaris per tenir una mitjana anual representativa.","refs":[{"ref":"p. 61","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=61","quote":"les temperatures mitjanes anuals varien entre els 17,1ºC de Tortosa, situada a 50 m d’altitud, i els 3ºC d’Estany Gento"},{"ref":"p. 61","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=61","quote":"fan falta un mínim de 10 anys de registres tèrmics diaris per tal de poder obtenir una mitjana anual representativa"}]},{"text":"La inversió tèrmica és el no acompliment del gradient tèrmic (normalment es perden 0,6 graus cada 100 m). Passa en dies d''hivern amb anticicló en planes com la de Vic: l''aire fred i la boira s''acumulen al fons i hi fa més fred que als relleus propers. L''amplitud tèrmica (diferència entre màxima i mínima) creix com més lluny del mar.","refs":[{"ref":"p. 61","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=61","quote":"inversió tèrmica (és a dir, el no acompliment del gradient tèrmic, és a dir, com més altitud menys temperatura, en una relació mitjana de 0,6 graus per cada 100 metres d’ascens vertical)"},{"ref":"p. 61","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=61","quote":"Així, com més lluny del mar, més amplitud tèrmica"}]},{"text":"La precipitació es mesura amb el pluviòmetre (mm o litres per m²) i calen com a mínim 30 anys de registres diaris perquè les dades siguin vàlides. Plou més a la muntanya, prop de la costa i a la Vall d''Aran, i menys a les planes de ponent, per l''ombra pluviomètrica. La pluja es concentra a la primavera i la tardor, sovint en tempestes de gota freda; a l''agost la Molina rep 123 mm i Lleida, 24 mm. La gota freda fa de la pluja un dels principals riscos climàtics (inundacions i riuades).","refs":[{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"Cal un mínim de 30 anys de registres diaris per tal que les dades siguin vàlides."},{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"La precipitació mitjana mensual del mes d’agost a la Molina és de 123 mm (1.267 mm anuals), mentre que a Lleida és de 24 mm (326 mm anuals)."},{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"La irregularitat de les precipitacions i especialment el fenomen de la gota freda converteixen les precipitacions en un dels principals riscos climàtics a Catalunya."}]}]},{"n":"9","title":"La xarxa hidrogràfica","blocks":[{"text":"Tots els rius catalans són mediterranis excepte la Garona, que neix a la Vall d''Aran i va a l''Atlàntic. Els mediterranis formen tres grups: els afluents catalans de l''Ebre (el Segre i els seus afluents: Noguera Ribagorçana, Noguera Pallaresa i Valira); els que neixen al Pirineu i van directament al mar (Muga, Fluvià, Ter i Llobregat), i els que neixen al Sistema Mediterrani (Tordera, Besòs, Foix, Gaià, Francolí i Sénia). Hi ha, doncs, quatre xarxes: atlàntica, Pirineus-Ebre, Pirineus-Mediterrània i mediterrània.","refs":[{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"Els rius de Catalunya pertanyen al vessant mediterrani, excepte la Garona, amb la capçalera a la Vall d’Aran, que pertany al vessant atlàntic."},{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"els afluents catalans de l’Ebre, amb el Segre i els seus afluents (la Noguera Ribagorçana, la Noguera Pallaresa i la Valira)"},{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"xarxa atlàntica, xarxa Pirineus-Ebre, xarxa Pirineus-Mediterrània i xarxa mediterrània"}]},{"text":"Els règims fluvials són diferents i irregulars. Els rius del Pirineu occidental reben molta neu a l''hivern, que els manté el cabal fins ben entrat l''estiu: règim pluvionival, més regular. Els del Pirineu oriental i del Sistema Mediterrani depenen només de la pluja (règim pluvial): menys cabal, molt irregular, i alguns s''assequen en sequera.","refs":[{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"les capçaleres dels rius que neixen al Pirineu occidental tenen importants aportacions en forma de neu durant l’hivern, la qual cosa garanteix el cabal fins ben avançat l’estiu (règim pluvionival). Aquests rius tenen una major regularitat dels seus cabals."},{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"els rius que neixen al Pirineu oriental i al Sistema Mediterrani depenen en exclusiva de les pluges per mantenir regular el seu cabal (règim pluvial)"}]}]},{"n":"10","title":"La vegetació","blocks":[{"text":"La vegetació actual sovint no coincideix amb la potencial (la que hi hauria espontàniament segons clima i litologia): predominen matollars i pinedes en antics conreus abandonats. La vegetació potencial pertany a tres regions: mediterrània, eurosiberiana i boreoalpina.","refs":[{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"La vegetació potencial a Catalunya pertany a tres grans regions biogeogràfiques: mediterrània, eurosiberiana i boreoalpina."}]},{"text":"La mediterrània té alzinars (alzina i carrasca) i màquies; a les zones més seques, brolles. L''eurosiberiana, humida i ombrívola, és el domini dels boscos caducifolis (rouredes i fagedes) i del pi roig. La boreoalpina, de clima fred, té pi negre i avetoses entre 1.600 i 2.300 m i prats alpins fins als 2.500-2.800 m.","refs":[{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"Les comunitats vegetals pròpies de la regió mediterrània són els alzinars i les màquies."},{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"És el domini dels boscos caducifolis (rouredes i fagedes) i els boscos de pi roig."},{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"presenta boscos de pi negre i avetoses entre els 1.600 i els 2.300 m, i prats alpins fins als 2.500 i 2.800 m"}]}]},{"n":"11","title":"La població: evolució","blocks":[{"text":"El 1857 Catalunya tenia 1.652.611 habitants. La industrialització va portar immigració de la resta d''Espanya i migracions de la muntanya cap a la costa. A la postguerra, el fet cabdal va ser la intensa immigració d''altres zones de l''Estat, afavorida pel desenvolupament econòmic català: 3,2 milions el 1950 i 5,9 el 1980. Va arribar sobretot al Barcelonès, el Baix Llobregat, el Vallès Occidental i el Tarragonès.","refs":[{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"el fet demogràfic cabdal a Catalunya va ser la intensa immigració procedent d’altres zones de l’Estat i afavorida pel desenvolupament econòmic a Catalunya."},{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"3,2 milions el 1950, 3,8 milions el 1960, 5,1 milions el 1970 i 5,9 milions el 1980"}]},{"text":"Des del final dels anys vuitanta arriba una tercera onada, del nord d''Àfrica, Llatinoamèrica i l''est d''Europa, que fa créixer la població, recupera la natalitat i frena en part l''envelliment; amb la crisi del 2007 s''estanca. Idea força: tres grans períodes de creixement en cent anys, l''últim amb persones de l''estranger.","refs":[{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"Des del final dels anys vuitanta té lloc una nova immigració, procedent principalment de països del nord d’Àfrica, de Llatinoamèrica i de l’est d’Europa."},{"ref":"Idea força 7, p. 66","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=66","quote":"La població de Catalunya ha tingut tres grans períodes de creixement en els darrers 100 anys."}]},{"text":"El 2021 hi havia 7.763.362 habitants. La població envelleix: els menors de 15 anys han passat del 25,6% al 14,7% (2022) i els majors de 65, del 10,2% (1975) al 19,2% (2022). L''índex de fecunditat és d''1,23, per sota de la taxa de substitució. L''esperança de vida en néixer és de 82,4 anys (Idescat, 2020).","refs":[{"ref":"p. 63","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=63","quote":"La població de Catalunya l’any 2021 era de 7.763.362 habitants"},{"ref":"p. 64","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=64","quote":"L’índex de fecunditat continua baix, inferior a la taxa de substitució amb un 1,23"},{"ref":"p. 64","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=64","quote":"L’esperança de vida continua sent de les més altes del món amb 82,4 anys en néixer"}]}]},{"n":"12","title":"La distribució de la població","blocks":[{"text":"La densitat és de 241 hab/km², però el repartiment és molt desigual. A la taula del 2021, l''àmbit Metropolità té 4.931.245 habitants (64%) en 2.464 km², i l''Alt Pirineu i Aran, l''1%, amb 12,9 hab/km². Compte: el text dona un 65% per a l''àmbit metropolità, però la taula i la idea força diuen 64%, la xifra que cal recordar.","refs":[{"ref":"p. 64","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=64","quote":"Catalunya 7.763.362 32.108 241 100% Metropolità 4.931.245 2.464 2001 64%"},{"ref":"Idea força 8, p. 66","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=66","quote":"La distribució de la població a Catalunya és molt irregular, amb una concentració del 64% a la RMB."}]},{"text":"La població es concentra al litoral, on hi ha les ciutats i la indústria, pel pes històric del mar i el comerç marítim. L''interior, aïllat per serralades i la manca de grans vies, està poc poblat: Lleida, Vic, Manresa o Igualada són «illes de població enmig d''un desert poblacional». Les vegueries de Barcelona, Penedès i Camp de Tarragona apleguen tres quartes parts de la població, i les Terres de l''Ebre o l''Alt Pirineu i Aran no arriben al 3%.","refs":[{"ref":"p. 64","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=64","quote":"Lleida fonamentalment, però també Vic, Manresa, Berga, Balaguer, Igualada o Mollerussa són illes de població enmig d’un desert poblacional."},{"ref":"p. 65","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=65","quote":"les vegueries barcelonina, penedesenca i del Camp de Tarragona apleguen tres quartes parts de la població de Catalunya. Mentre que les Terres de l’Ebre o l’Alt Pirineu i Aran, a penes arriben al 3%."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"32.108 km²; vuit vegueries, 42 comarques (més l''Aran) i 947 municipis. Unitat bàsica: el municipi.","refs":[{"ref":"Idea força 1, p. 66","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=66","quote":"Administrativament, Catalunya s’organitza en vuit vegueries, 42 comarques i 947 municipis."}]},{"text":"Llei de vegueries: 27 de juliol de 2010; set vegueries, vuit des de 2017. L''Aran és a l''Alt Pirineu.","refs":[{"ref":"p. 58","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=58","quote":"fixava en set el nombre definitiu de vegueries, ampliat a vuit a començaments de 2017"}]},{"text":"Pica d''Estats (3.143 m), punt més alt; Turó de l''Home (1.706 m), cim del Sistema Mediterrani.","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"la Pica d’Estats (3.143 m), que és el punt més elevat de Catalunya"}]},{"text":"La Depressió Central s''obre a ponent; la Serralada Transversal té els volcans d''Olot.","refs":[{"ref":"p. 59","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=59","quote":"Està oberta cap a ponent, cap a la depressió de l’Ebre"}]},{"text":"Costa d''uns 515 km; delta de l''Ebre, 320 km².","refs":[{"ref":"p. 60","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=60","quote":"El litoral català (uns 515 km de costa)"}]},{"text":"Clima atlàntic a la Vall d''Aran; registres mínims de 10 anys (temperatura) i 30 (precipitació).","refs":[{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"Cal un mínim de 30 anys de registres diaris per tal que les dades siguin vàlides."}]},{"text":"Rius: Garona atlàntica; quatre xarxes; pluvionival regular, pluvial irregular.","refs":[{"ref":"p. 62","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=62","quote":"existeixen un total de quatres xarxes diferents"}]},{"text":"Població 2021: 7.763.362 habitants; 64% a la RMB; densitat de 241 hab/km².","refs":[{"ref":"p. 64","law":"Guia d''estudi, tema A.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=64","quote":"Tot i tenir una densitat de població de 241 hab/km2"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=57'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=57', 57, 66, 66, null
  from public.topics t where t.slug = 'mossos-a5-marc-geografic'
