insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La migració a Catalunya i fluxos migratoris"},{"n":"1.1","title":"Les migracions contemporànies"},{"n":"1.2","title":"La immigració a Espanya i Catalunya"},{"n":"1.3","title":"La dinàmica migratòria i l’evolució de la població catalana"},{"n":"2","title":"Les polítiques públiques en matèria d’immigració"},{"n":"2.1","title":"Política migratòria comunitària"},{"n":"2.2","title":"Política migratòria d’Espanya i Catalunya"},{"n":"3","title":"Models d’integració i marcs de convivència en la societat multicultural"},{"n":"4","title":"Les polítiques públiques en matèria d’igualtat d’oportunitats"},{"n":"5","title":"Els serveis socials a Catalunya"},{"n":"5.1","title":"L’Estat del benestar i la provisió de serveis"},{"n":"5.2","title":"Els serveis socials"}]'::jsonb, '["Durant les últimes dècades s’han consolidat noves pautes migratòries internacionals que han contribuït a generalitzar els moviments migratoris de manera important. Podem destacar tres dimensions en què es percep aquest caràcter del fenomen migratori: el creixement constant del volum de persones migrants, l’ampliació de les xarxes i cadenes migratòries, i la diversificació dels tipus migratoris.","L’Estat espanyol s’ha convertit, durant les últimes quatre dècades, en un important centre de recepció d’immigració.","Catalunya es troba inserida en el context de globalització i intensificació dels fluxos que caracteritza les migracions internacionals de les últimes dècades del segle xx i principis del segle xxi.","La dècada dels vuitanta es va caracteritzar per una acceleració de la immigració, de manera que el nombre d’estrangers a Catalunya gairebé va duplicar-se, guanyant pes relatiu en el conjunt de la societat catalana.","La immigració estrangera a Catalunya es nodreix d’un doble flux: d’una banda, l’arribada d’europeus, i de l’altra, una creixent immigració de països extracomunitaris.","A l’hora de definir les pautes de convivència amb què es definiran les estratègies i polítiques socials en societats que reben fluxos migratoris, les ciències socials diferencien tres grans models: assimilació, melting pot –gresol cultural– i pluralisme cultural.","La ràpida acceleració dels fluxos, la seva afectació múltiple i el seu interès en relació amb el món laboral han donat lloc al desenvolupament d’una normativa que regula aquesta immigració des d’un punt de vista legal. Aquest marc legal ve determinat pel fet de pertànyer a la UE i a més de la competència de l’Estat, hi hem d’afegir les iniciatives preses per la Generalitat i els ajuntaments en diferents àmbits.","L’estat de benestar es defineix com el conjunt de polítiques l’objectiu de les quals és millorar les condicions de vida de la ciutadania i assegurar la igualtat d’oportunitats. Es fonamenta en transferències socials, serveis, i intervencions.","L’estat social i democràtic de dret consagra el principi d’igualtat i no-discriminació, entre d’altres, per raó de sexe, i el configura com un dret subjectiu a tenir un tracte igual, però l’existència del reconeixement d’aquest dret no significa que en la realitat, en la vida quotidiana, no es donin situacions que de fet són discriminatòries.","Les polítiques públiques són aquelles decisions adoptades pels òrgans de govern, ja sigui mitjançant normes, disposicions, estratègies, plans d’actuació o actes, i que tenen per objecte determinar les actuacions que el govern planifica o executa en relació amb una matèria concreta.","Les polítiques d’igualtat d’oportunitats consisteixen en la determinació i adopció de mesures per part de les institucions públiques amb l’objectiu de pal·liar i resoldre les situacions de desigualtat social entre homes i dones.","A Catalunya, les polítiques a favor de la igualtat d’oportunitats entre homes i dones es desenvolupen a través de plans plurianuals que s’elaboren, planifiquen i executen de manera conjunta entre diferents departaments de la Generalitat de Catalunya.","Des de la seva creació el 1989, l’Institut Català de les Dones té el repte de dissenyar estratègies de transversalitat que garanteixin que totes les polítiques incorporin la perspectiva de gènere i de les dones especialment per afavorir la conciliació de la vida familiar i professional de les dones i dels homes i erradicar la violència contra les dones.","El sistema català de serveis socials constitueix un recurs a l’abast de tota la ciutadania i té com a destinatàries totes les persones que necessiten informació, valoració, diagnòstic, orientació, suport, intervenció i assessorament individual, familiar o comunitari per fer front i prevenir situacions de necessitat personal bàsica, de manca de cohesió social o familiar o de desigualtat."]'::jsonb, '["Acollida","Aculturació","Asil","Assimilació","Cadena migratòria","Canvi social","Ciutadania","Cohesió social","Conciliació","Desplaçats","Desigualtat social","Diversitat sociocultural","Emigració","Entrada clandestina","Estrangeria","Estrangers de “tercers països”","Exclusió social","Gènere","Globalització","Gresol cultural","Igualtat d’oportunitats","Immigració extracomunitària","Immigració permanent o de llarga durada","Llibertat de circulació","Marcs de convivència","Migracions","Minories ètniques o culturals","Models d’integració","Multidimensional","Nacionalitat per residència","Població autòctona","Polítiques públiques","Protecció internacional","Pluralisme cultural","Refugi","Regularització","Serveis socials","Tipologies migratòries","Transferències socials","Violència masclista"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Les migracions contemporànies","blocks":[{"text":"La diversitat social i cultural és cada vegada més un valor compartit. Avui són les migracions les que concentren el debat sobre la diversitat cultural. Segons les Nacions Unides, el 2024 hi havia 304 milions de persones vivint fora del seu territori d''origen, més del 3,7% de la població mundial, per factors d''expulsió del país d''origen i d''atracció dels altres. L''ACNUR comptava, a finals de 2024, 123,2 milions de persones desplaçades forçosament per la guerra i la violència.","refs":[{"ref":"p. 68","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=68","quote":"Segons les Nacions Unides, l’any 2024 hi havia 304 milions de persones que vivien fora del seu territori d’origen"},{"ref":"p. 68","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=68","quote":"Una realitat que afecta més del 3,7% de la població mundial, les causes de la qual es deuen tant a factors d’expulsió dels mateixos països com a factors d’atracció de la resta. Segons l’ACNUR, a finals de 2024 hi havia 123,2 milions de persones desplaçades forçosament al món"}]},{"text":"Aquest augment s''explica sobretot per la proliferació i la durada dels conflictes armats (Síria, Ucraïna, Sudan), la violència, la persecució i la vulneració dels drets humans, als quals se sumen la inestabilitat institucional, les desigualtats econòmiques i, cada cop més, la crisi climàtica. El context és la globalització: el moviment creixent de capitals, mercaderies i persones en un món molt interdependent.","refs":[{"ref":"p. 68","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=68","quote":"Aquest augment sostingut en els darrers anys s’explica principalment per la proliferació i la durada dels conflictes armats —com els de Síria, Ucraïna o Sudan—"},{"ref":"p. 68","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=68","quote":"Una de les característiques més acusades del món actual és el creixent moviment internacional de capitals, de mercaderies i també, és clar, de persones, en un context de gran interdependència entre diferents societats. És allò que hem anomenat globalització"}]},{"text":"El senyal d''identitat de les migracions actuals és el seu caràcter global, que es percep en tres dimensions (idea força): a) el creixement o almenys manteniment constant del volum de migrants, que en fa un fenomen permanent; b) l''ampliació de les xarxes i cadenes migratòries, és a dir, les relacions entre individus, famílies i grups que fan de pont entre origen i destinació (dominen les xarxes sud-nord i transoceàniques i creix la migració est-oest); i c) la diversificació dels tipus migratoris (refugiats, personal qualificat, reagrupació familiar, migracions femenines, canvi climàtic…), tot i que predomina el motiu econòmic. El resultat és la formació de minories ètniques o culturals i més diversitat sociocultural.","refs":[{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"podem dir que el senyal d’identitat de les actuals migracions és el seu caràcter global"},{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"b) L’ampliació de les xarxes i cadenes migratòries –és a dir, del conjunt de relacions entre individus, famílies i grups que serveixen de pont entre els llocs de partida i els llocs de destinació."},{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"si bé en general dominen les xarxes sud-nord i les transoceàniques. Més recentment, destaca també la migració est-oest."},{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"El resultat de tot aquest entramat de moviments, voluntaris o forçats, així com el seu creixement constant, ha estat la formació de minories ètniques o culturals en el si dels països receptors"}]}]},{"n":"2","title":"La immigració a Espanya: estabilitat i nacionalitat","blocks":[{"text":"Espanya s''ha incorporat a les tendències globals de mobilitat, però gran part dels estrangers hi porten molt de temps: segons el padró i el Ministeri d''Inclusió, Seguretat Social i Migracions (2025), uns vuit de cada deu tenen residència de llarga durada o permanent, i cal sumar-hi els que ja tenen la nacionalitat (prop del 15-20%). És una població cada vegada més estabilitzada i integrada.","refs":[{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"aproximadament vuit de cada deu estrangers disposen de residència de llarga durada o permanent, als quals cal sumar-hi els que ja han obtingut la nacionalitat espanyola, que representen prop del 15%–20% dels estrangers residents."}]},{"text":"La nacionalitat per residència, que s''obté acumulant anys d''estada legal, és la via principal de naturalització. El termini normal és de 10 anys; 5 per als refugiats, i 2 per als iberoamericans, filipins, equatoguineans, portuguesos i persones d''origen sefardí. Les concessions van passar de 6.751 (1995) a 261.295 (2013) i 114.207 (2015).","refs":[{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"El termini normal són 10 anys, tot i que per a alguns col·lectius són menys: 5 anys per als refugiats i 2 anys per als iberoamericans, filipins, equatoguineans, portuguesos i persones d’origen sefardí."},{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"El 1995, per exemple, van ser 6.751 les persones que van obtenir la nacionalitat; el 2013, ja n’eren 261.295 i el 2015, en varen ser 114.207."}]},{"text":"Espanya també ha tornat a ser país d''emigració (98.934 emigrants el 2015 i 145.841 el 2023), sense deixar de ser-ho d''immigració. El 2015 el saldo migratori estranger va ser positiu per primera vegada des del 2010. Els estrangers residents regularitzats eren 5.801.946 el juny de 2020 (12,25% de la població) i 6.911.971 el gener de 2025 (un 14%).","refs":[{"ref":"p. 70","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=70","quote":"El saldo migratori estranger el 2015 fou positiu per primera vegada des del 2010"},{"ref":"p. 70","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=70","quote":"pel que fa al gener de 2025, el nombre d’estrangers residents a Espanya era de 6.911.971 persones en situació regularitzada, que representava aproximadament un 14% del total de la població."}]}]},{"n":"3","title":"Per què Espanya i Catalunya es van convertir en receptores i com ha canviat la immigració","blocks":[{"text":"Espanya i Catalunya es van convertir en receptores d''immigració internacional en poc temps, bàsicament entre 1998 i 2008, per dos factors: a) el ràpid creixement econòmic dels anys noranta i començament del segle XXI, amb mercats de treball molt diferenciats, i b) una realitat demogràfica en ràpid envelliment i amb desequilibris greus en l''estructura d''edats.","refs":[{"ref":"p. 70","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=70","quote":"bàsicament al llarg del decenni 1998-2008, en receptors d’immigració internacional s’explica, entre altres raons, per dos factors: a) El ràpid creixement econòmic experimentat al llarg de la dècada dels noranta del segle xx i els primers anys del segle xxi, juntament amb l’existència d’uns mercats de treball molt diferenciats. b) La realitat demogràfica espanyola i catalana, immersa en un ràpid procés d’envelliment"}]},{"text":"Els canvis recents es resumeixen en quatre trets: a) ha guanyat pes la immigració extracomunitària (INE 2024: un 35% d''estrangers de la UE i un 65% de fora); b) és molt heterogènia, amb més de 180 nacionalitats; per continents, Amèrica és el primer (més de tres milions), i les nacionalitats més nombroses són Romania, el Marroc i Colòmbia; c) hi ha dues tipologies: una d''econòmica i laboral, cap a feines poc qualificades, i una altra de països desenvolupats (jubilats, estudiants, alta qualificació); i d) tendeix a ser permanent o de llarga durada, d''assentament.","refs":[{"ref":"p. 70","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=70","quote":"aproximadament un 35% dels estrangers residents a Espanya són ciutadans de la Unió Europea, mentre que prop d’un 65% procedeixen de països extracomunitaris."},{"ref":"p. 70","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=70","quote":"Pel que fa a les nacionalitats més nombroses, destaquen Romania, el Marroc i Colòmbia."},{"ref":"p. 71","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=71","quote":"d) Una tendència cap a una immigració permanent o de llarga durada."}]},{"text":"La distribució per comunitats no és homogènia: Catalunya, la Comunitat de Madrid i la Comunitat Valenciana acullen prop del 60% dels estrangers residents. Segons l''INE (2024-2025), Catalunya té un saldo migratori intern lleugerament negatiu, d''unes 1.500 persones.","refs":[{"ref":"p. 71","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=71","quote":"Actualment, les tres regions amb més concentració de població estrangera són Catalunya, la Comunitat de Madrid i la Comunitat Valenciana, que acullen prop del 60% dels estrangers residents a Espanya."},{"ref":"p. 71","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=71","quote":"Catalunya presenta un saldo migratori lleugerament negatiu, d’unes 1.500 persones en el període més recent"}]}]},{"n":"4","title":"La dinàmica migratòria i la població catalana","blocks":[{"text":"Les migracions són l''element més important de la trajectòria demogràfica catalana del segle XX, i expliquen que Catalunya sigui la segona comunitat més poblada. La tercera gran onada immigratòria dels darrers cent anys ha acabat amb aproximadament un terç de catalans nascuts fora de Catalunya, com en les dues anteriors, i sense canviar la distribució relativa de la població. Fins al final dels setanta, l''aportació clau va venir d''altres regions espanyoles (prop de tres milions de persones entre 1901 i 1980); avui un 18% dels habitants han nascut en altres comunitats.","refs":[{"ref":"p. 71","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=71","quote":"S’ha conclòs la tercera gran onada immigratòria dels darrers 100 anys amb un resultat d’aproximadament un terç de catalans nascuts fora de Catalunya, com ja va passar en les dues onades anteriors."},{"ref":"p. 71","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=71","quote":"Algunes estimacions indiquen que entre els anys 1901 i 1980 el flux d’immigrants podria haver assolit una xifra propera als tres milions de persones. Avui, aproximadament un 18% del total d’habitants de Catalunya són persones nascudes en altres regions o comunitats espanyoles."}]},{"text":"Als noranta pren protagonisme la immigració estrangera. Va créixer molt entre el 2000 i el 2010, després es va moderar i des del 2023 torna a créixer: segons la taula de l''Idescat, el 2000 els estrangers eren el 2,90% i el 2025 són 1.522.819 sobre 8.154.627 habitants, el 18,7%. Es nodreix d''un doble flux: europeus comunitaris (un 24,3% dels estrangers) i una immigració extracomunitària creixent, sobretot d''Àfrica i Llatinoamèrica.","refs":[{"ref":"p. 72","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=72","quote":"2025 8.154.627 1.522.819 18,7%"},{"ref":"p. 72","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=72","quote":"1) d’una banda, l’arribada d’europeus comunitaris (un 24,3% sobre el total dels estrangers) i, 2) de l’altra, una creixent immigració de països extracomunitaris, que procedeix principalment d’Àfrica i de Llatinoamèrica"}]},{"text":"El 2021 convivien a Catalunya gairebé 200 nacionalitats. El col·lectiu més nombrós és el marroquí (més del 19%), seguit del romanès, l''italià i el xinès; després, el pakistanès, l''hondureny, el colombià i el francès. Per continents (2025), Amèrica és el primer (32,8%), seguit d''Europa (29,9%), Àfrica (23,2%) i Àsia i Oceania (14,1%).","refs":[{"ref":"p. 73","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=73","quote":"El col·lectiu més nombrós és el marroquí, que representa més del 19% de tots els estrangers. El segueixen el romanès, l’italià i el xinès."},{"ref":"p. 73","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=73","quote":"Europa 454.624 29,9% Àfrica 353.807 23,2% Amèrica 499.146 32,8%"}]},{"text":"Els estrangers són majoritàriament en edat laboral (25-49 anys) i molts treballen en feines de baixa qualificació, vulnerables en temps de crisi: el risc de pobresa va superar el 40% a partir del 2011, davant del 15% dels espanyols. Avui la seva taxa d''atur és del 14,1%, més del doble que la dels espanyols (6,5%), amb una taxa global del 8,2%; el col·lectiu africà és el més vulnerable. Territorialment segueixen les pautes generals: Barcelona ciutat té uns 430.000 estrangers (el 25% dels seus habitants i prop del 30% dels de Catalunya) i l''àmbit metropolità en concentra el 65%. Hi destaquen municipis petits com Castelló d''Empúries (prop del 45%) i Guissona (més del 50%).","refs":[{"ref":"p. 74","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=74","quote":"Actualment, la taxa d’atur de la població estrangera se situa al voltant del 14,1%, més del doble que la de la població espanyola (6,5%), mentre que la taxa d’atur global a Catalunya és del 8,2%."},{"ref":"p. 74","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=74","quote":"La ciutat de Barcelona es manté com el principal nucli receptor, amb aproximadament 430.000 residents estrangers"},{"ref":"p. 74","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=74","quote":"És el cas de Castelló d’Empúries, amb prop del 45% de població estrangera, o Guissona, que es manté com un dels casos més destacats, amb percentatges que superen el 50%."}]}]},{"n":"5","title":"Política migratòria comunitària","blocks":[{"text":"Com que Espanya és membre de la UE, el marc europeu condiciona la política d''immigració. A gairebé tots els països de la UE el control de fluxos s''ha fet més restrictiu per als «estrangers de tercers països», i hi intervenen cada cop més nivells supraestatals. L''estrangeria es divideix en dues categories: comunitària i no comunitària. Amb el Tractat d''Amsterdam, en vigor el 1999, el ciutadà comunitari pot desplaçar-se, assentar-se i treballar lliurement a qualsevol país de la UE, amb drets laborals, socials i polítics (vot i candidatura a les eleccions europees i locals).","refs":[{"ref":"p. 75","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=75","quote":"Amb l’entrada en vigor, el 1999, del Tractat d’Amsterdam, el ciutadà comunitari pot desplaçar-se, assentar-se i treballar lliurement a qualsevol part dels països de la UE"}]},{"text":"Els no comunitaris tenen drets i possibilitats d''assentament més limitats; les restriccions d''entrada (que poden afavorir l''entrada clandestina) i la rigidesa dels requisits de residència i treball generen situacions d''irregularitat. El 2009 l''Eurocambra va aprovar el Pacte europeu sobre immigració i asil, que vol limitar la immigració a les necessitats del mercat laboral. Recorda la diferència: les directives s''han de transposar al dret intern; els reglaments són obligatoris i directament aplicables.","refs":[{"ref":"p. 75","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=75","quote":"El 2009 la Eurocàmara va aprovar el Pacte europeu sobre immigració i asil, el qual busca limitar la immigració a les necessitats del mercat laboral."},{"ref":"p. 75","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=75","quote":"El cas dels reglaments, però, és diferent, ja que aquests tenen abast general, són obligatoris i directament aplicables a tots els estats membres."}]},{"text":"La Directiva 2011/95/UE especifica els motius per concedir protecció internacional i defineix qui és refugiat. Vol que els estats apliquin criteris comuns per identificar qui necessita protecció i garantir un mínim de prestacions: informació, unitat familiar, permisos de residència i documents de viatge, educació, ocupació, prestacions socials i mèdiques i habitatge.","refs":[{"ref":"p. 75","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=75","quote":"La Directiva 2011/95/UE, que especifica els motius que donen lloc a la concessió de protecció internacional, defineix qui és refugiat i el contingut d’aquest estatut de protecció."}]}]},{"n":"6","title":"Política migratòria d''Espanya i de Catalunya","blocks":[{"text":"El marc legal és competència de l''Estat, però la Generalitat i els ajuntaments hi sumen iniciatives en educació, sanitat o protecció de menors. Des del 1985, la política estatal ha volgut orientar els fluxos segons les demandes del mercat de treball. La norma clau és la Llei orgànica 8/2000, sobre drets i llibertats dels estrangers a Espanya i la seva integració social, una llei marc la quarta reforma de la qual va entrar en vigor el desembre de 2009. El mateix 2009 es va aprovar la Llei 12/2009, de 30 d''octubre, reguladora del dret d''asil i de la protecció subsidiària.","refs":[{"ref":"p. 76","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=76","quote":"Entre les principals mesures que conformen la política migratòria espanyola, cal assenyalar la Llei orgànica 8/2000, sobre drets i llibertats dels estrangers a Espanya i la seva integració social. El desembre de 2009 va entrar en vigor la quarta reforma d’aquesta Llei d’estrangeria. Es tracta d’una llei marc"},{"ref":"p. 76","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=76","quote":"També el 2009 a l’Estat espanyol s’aprova la Llei 12/2009, de 30 d’octubre, reguladora del dret d’asil i de la protecció subsidiària."}]},{"text":"El reglament de la llei es va aprovar el 2011 (Reial decret 557/2011) i avui el substitueix el Reial decret 1155/2024, de 19 de novembre, en vigor des del 2025, que regula entrada, residència, treball i reagrupació familiar. Compte: la guia l''anomena «Reglament de la Llei orgànica 4/2000», però abans parla de la LO 8/2000 sense explicar-ne la relació. Les polítiques d''integració es mesuren amb indicadors de la Declaració de Saragossa (2010): ocupació, educació, drets de ciutadania i benestar material.","refs":[{"ref":"p. 76","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=76","quote":"El marc reglamentari vigent queda actualment establert amb l’aprovació del Reial decret 1155/2024, de 19 de novembre, pel qual s’aprova el Reglament de la Llei orgànica 4/2000, en vigor des de l’any 2025."},{"ref":"p. 76","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=76","quote":"es mesuren a partir d’indicadors acordats per la Unió Europea (UE) en la Declaració de Saragossa (Conferència Ministerial Europea sobre Integració, 2010) i pivoten sobre l’ocupació, l’educació, els drets de ciutadania i el nivell de benestar material."}]},{"text":"A Catalunya, el primer Pla interdepartamental d''immigració és del 1993; el segueix el Pla de ciutadania i immigració 2005-2008. El 2008 s''aprova el Pacte nacional per a la immigració i es crea la Taula de Ciutadania i Immigració, òrgan de consulta i participació de les polítiques del fet migratori. El 2010 arriba la Llei 10/2010, de 7 de maig, d''acollida de les persones immigrades i de les retornades a Catalunya, i el 2014 el Decret 150/2014, de 18 de novembre, dels serveis d''acollida. El Pla de ciutadania i de les migracions 2017-2020 va ser l''últim amb aquest format.","refs":[{"ref":"p. 76","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=76","quote":"A Catalunya, el 1993 es va aprovar el primer Pla interdepartamental d’immigració"},{"ref":"p. 76","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=76","quote":"El 2008 s’aprova el Pacte nacional per a la immigració i es crea La Taula de Ciutadania i Immigració, que és un òrgan de consulta i participació per a les polítiques de gestió del fet migratori que promou la Generalitat de Catalunya. El 2010 s’aprova la Llei 10/2010, de 7 de maig, d’acollida de les persones immigrades i de les retornades a Catalunya, i el 2014 el Decret 150/2014, de 18 de novembre, dels serveis d’acollida."}]}]},{"n":"7","title":"Models d''integració i marcs de convivència","blocks":[{"text":"Tota societat ha de fixar un model de convivència amb els immigrants. Les ciències socials en distingeixen tres. L''assimilació: l''immigrant adopta la cultura majoritària i així és admès com un membre més; es creu que l''aculturació redueix el prejudici, i l''admissió es condiciona a la «capacitat d''assimilació». El melting pot o gresol cultural: nadius i immigrants creen junts una nova cultura, fruit de la fusió dels elements culturals. El pluralisme cultural: ningú no vol perdre la seva identitat, i tots s''adhereixen a uns principis comuns de convivència mantenint les peculiaritats de cada col·lectiu, generalment en l''esfera privada.","refs":[{"ref":"p. 77","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=77","quote":"Han sorgit tres models en el panorama de les ciències socials i en les pràctiques polítiques: l’assimilació, el melting pot i el pluralisme cultural."},{"ref":"p. 77","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=77","quote":"aquest model d’integració implica tots els membres de la societat (nadius i immigrants) en la creació d’una nova cultura general, com a resultat de la fusió dels diversos elements culturals i les diferents identitats."},{"ref":"p. 77","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=77","quote":"l’adaptació es produirà mitjançant l’adhesió per part de tots a uns principis comuns de convivència, però mantenint en certs nivells les peculiaritats de cada col·lectiu, generalment limitades a l’esfera privada"}]},{"text":"Les crítiques: l''assimilació i fins i tot el melting pot es rebutgen perquè contravenen el dret dels grups a mantenir la seva identitat; el pluralisme cultural es critica pel risc de fragmentació social i de coexistència separada entre grups.","refs":[{"ref":"p. 77","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=77","quote":"Quant al pluralisme cultural, es critica pels seus riscos de fragmentació social, que pot donar lloc a una coexistència social separada entre els diversos grups."}]}]},{"n":"8","title":"Igualtat d''oportunitats: conceptes i marc legal","blocks":[{"text":"Les polítiques públiques són decisions dels òrgans de govern (normes, disposicions, estratègies, plans o actes) que determinen les actuacions sobre una matèria. Les d''igualtat d''oportunitats entre dones i homes busquen pal·liar i resoldre les desigualtats en tots els àmbits de la vida. Per a l''OIT són una qüestió de justícia social, de desenvolupament econòmic i de drets humans.","refs":[{"ref":"p. 77","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=77","quote":"Les polítiques públiques són aquelles decisions adoptades pels òrgans de govern, ja sigui mitjançant normes, disposicions, estratègies, plans d’actuació o actes"},{"ref":"p. 77","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=77","quote":"Les polítiques d’igualtat d’oportunitats entre dones i homes consisteixen en la determinació i adopció de mesures per part de les institucions públiques amb l’objectiu de pal·liar i resoldre les situacions de desigualtat entre homes i dones"}]},{"text":"A l''Estat, la Llei 39/1999, de 5 de novembre, va promoure la conciliació familiar i laboral; però la regulació específica contra tota discriminació per raó de sexe arriba amb la Llei 3/2007, de 22 de març, per a la igualtat efectiva entre dones i homes. A Catalunya, l''article 41 de l''Estatut obliga els poders públics a incorporar la perspectiva de gènere a les polítiques públiques i a garantir que les dones no siguin discriminades per embaràs o maternitat.","refs":[{"ref":"p. 78","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=78","quote":"Però no és fins a l’entrada en vigor de la Llei 3/2007, de 22 de març, per a la igualtat efectiva entre dones i homes, en què es fa una regulació específica per abordar i combatre totes les manifestacions encara subsistents de discriminació"},{"ref":"p. 78","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=78","quote":"L’article 41 de l’EAC estableix l’obligació que tenen els poders públics d’incorporar la perspectiva de gènere en les diferents polítiques públiques"}]},{"text":"Lleis catalanes clau: la Llei 8/2006, de 5 de juliol, de conciliació del personal de les administracions públiques catalanes (el Reial decret llei 6/2019 fixa després 16 setmanes de descans per a l''altre progenitor); la Llei 5/2008, del 24 d''abril, del dret de les dones a eradicar la violència masclista; i la Llei 17/2015, de 21 de juliol, d''igualtat efectiva de dones i homes, la primera llei d''igualtat catalana, aprovada pel Parlament el 8 de juliol de 2015.","refs":[{"ref":"p. 78","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=78","quote":"tenen dret a un període de descans de 16 setmanes"},{"ref":"p. 78","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=78","quote":"Posteriorment s’aprova la Llei 5/2008, del 24 d’abril, del dret de les dones a eradicar la violència masclista"},{"ref":"p. 78","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=78","quote":"El 8 de juliol de 2015 el Parlament de Catalunya va aprovar la primera llei d’igualtat de dones i homes catalana, la Llei 17/2015, de 21 de juliol"}]}]},{"n":"9","title":"Igualtat d''oportunitats: institucions i plans de la Generalitat","blocks":[{"text":"Les polítiques d''igualtat del Govern s''articulen en plans plurianuals elaborats i executats conjuntament per diversos departaments. L''Institut Català de les Dones, creat el 1989, té el repte de dissenyar estratègies de transversalitat perquè totes les polítiques incorporin la perspectiva de gènere. El I Pla d''actuació per a la igualtat d''oportunitats de les dones va abastar el període 1989-1992.","refs":[{"ref":"p. 79","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=79","quote":"Des de la seva creació el 1989 l’Institut Català de les Dones té el repte de dissenyar estratègies de transversalitat que garanteixin que totes les polítiques incorporin la perspectiva de gènere i de les dones."},{"ref":"p. 79","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=79","quote":"El I Pla d’actuació del Govern de la Generalitat de Catalunya per a la igualtat d’oportunitats per a les dones va comprendre el període 1989-1992"}]},{"text":"Cronologia posterior: des del 2005, abordatge integral de la violència contra les dones; Pla estratègic de polítiques de dones 2012-2015; Pla estratègic de polítiques d''igualtat de gènere 2019-2022; el 2021, creació del Departament d''Igualtat i Feminismes (Decret 249/2021, de 22 de juny); i el 2023, Pla d''igualtat de gènere de l''Administració de la Generalitat 2023-2027, amb agents d''igualtat i mesures contra la bretxa salarial, el sostre de vidre i la violència sexual a la feina. La guia no esmenta canvis posteriors en l''estructura departamental.","refs":[{"ref":"p. 79","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=79","quote":"L’any 2021, el Govern de la Generalitat crea el Departament d’Igualtat i Feminismes i en fixa l’estructura mitjançant el Decret 249/2021, de 22 de juny"},{"ref":"p. 79","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=79","quote":"L’any 2023, el Govern aprova el Pla d’igualtat de gènere de l’Administració de la Generalitat de Catalunya 2023-2027 que incorpora agents d’igualtat i mesures contra la bretxa salarial, el sostre de vidre i la violència sexual en l’àmbit laboral."}]}]},{"n":"10","title":"L''Estat del benestar i els serveis socials","blocks":[{"text":"L''Estat del benestar és el conjunt de polítiques que volen millorar les condicions de vida de la ciutadania i assegurar la igualtat d''oportunitats; l''Estat proveeix serveis a tota la població. Té quatre dimensions: a) transferències socials (pensions, subsidi d''atur); b) serveis (educació, sanitat i ajuda a les famílies); c) intervencions normatives per protegir el treballador, el consumidor i el medi ambient, i d) intervencions per estimular i garantir l''ocupació.","refs":[{"ref":"p. 80","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=80","quote":"S’entén per Estat del benestar el conjunt de polítiques l’objectiu de les quals és millorar les condicions de vida de la ciutadania i assegurar la igualtat d’oportunitats."},{"ref":"p. 80","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=80","quote":"a) Les transferències socials, com són les pensions o el subsidi d’atur. b) Els serveis, els més importants dels quals són l’educació, la sanitat i els serveis d’ajuda a les famílies."}]},{"text":"El sistema català de serveis socials és a l''abast de tota la ciutadania i s''adreça a qui necessiti informació, valoració, diagnòstic, orientació, suport o assessorament per prevenir o afrontar situacions de necessitat bàsica, manca de cohesió o desigualtat. L''integren serveis públics i privats. El regula la Llei 12/2007, de serveis socials. La xarxa té dos nivells: l''atenció primària, la més propera (treballadors socials, educadors i treballadors familiars, amb atenció polivalent), i els serveis especialitzats, complementaris, per a grups concrets (gent gran, persones amb discapacitat, drogodependents, infants).","refs":[{"ref":"p. 80","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=80","quote":"Catalunya compta amb la Llei 12/2007, de serveis socials"},{"ref":"p. 80","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=80","quote":"La xarxa bàsica de serveis socials constaria, així, de dos nivells bàsics d’actuació. El primer estaria format per l’atenció primària, que seria la resposta més propera a la ciutadania"},{"ref":"p. 80","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=80","quote":"El segon nivell el conformarien els serveis de caire especialitzat."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"304 milions de migrants al món (ONU, 2024) i 123,2 milions de desplaçats forçosos (ACNUR).","refs":[{"ref":"p. 68","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=68","quote":"Segons les Nacions Unides, l’any 2024 hi havia 304 milions de persones"}]},{"text":"Tres dimensions del caràcter global: volum constant, ampliació de xarxes i cadenes, diversificació de tipus.","refs":[{"ref":"Idea força 1, p. 81","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=81","quote":"el creixement constant del volum de persones migrants, l’ampliació de les xarxes i cadenes migratòries, i la diversificació dels tipus migratoris."}]},{"text":"Nacionalitat per residència: 10 anys (5 refugiats, 2 iberoamericans i altres).","refs":[{"ref":"p. 69","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=69","quote":"El termini normal són 10 anys"}]},{"text":"Catalunya 2025: 18,7% d''estrangers; el marroquí és el col·lectiu més nombrós (2021).","refs":[{"ref":"p. 73","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=73","quote":"El col·lectiu més nombrós és el marroquí"}]},{"text":"Tractat d''Amsterdam (1999): lliure circulació; Directiva 2011/95/UE: protecció internacional i refugi.","refs":[{"ref":"p. 75","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=75","quote":"La Directiva 2011/95/UE, que especifica els motius que donen lloc a la concessió de protecció internacional"}]},{"text":"Lleis: LO 8/2000 (estrangeria), Llei 12/2009 (asil), Llei 10/2010 (acollida), Llei 12/2007 (serveis socials).","refs":[{"ref":"p. 76","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=76","quote":"El 2010 s’aprova la Llei 10/2010, de 7 de maig, d’acollida de les persones immigrades i de les retornades a Catalunya"}]},{"text":"Models: assimilació, melting pot (gresol) i pluralisme cultural (risc de fragmentació).","refs":[{"ref":"Idea força 6, p. 81","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=81","quote":"les ciències socials diferencien tres grans models: assimilació, melting pot –gresol cultural– i pluralisme cultural."}]},{"text":"Igualtat: art. 41 EAC; Llei 3/2007; Llei 5/2008 (violència masclista); Llei 17/2015; Institut Català de les Dones (1989).","refs":[{"ref":"Idea força 13, p. 82","law":"Guia d''estudi, tema A.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=82","quote":"Des de la seva creació el 1989, l’Institut Català de les Dones"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=67'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=67', 67, 82, 81, null
  from public.topics t where t.slug = 'mossos-a6-entorn-social'
