   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema A.7, pp. 83-93', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=83', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-a7-tic', 'A.7 Les tecnologies de la informació en el segle XXI') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('mossos-esquadra') and t.slug = 'mossos-a7-tic' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La societat del coneixement i les tecnologies de la informació. Internet i la Internet de les coses (IoT)"},{"n":"2","title":"Efectes de les tecnologies de la informació i la comunicació (TIC)"},{"n":"3","title":"Seguretat de la informació"},{"n":"4","title":"L’administració electrònica. Signatura electrònica"},{"n":"5","title":"Comunicació i control públic: espais de seguretat i alarmes socials"},{"n":"6","title":"La intel·ligència artificial (IA) i l’automatització de processos"}]'::jsonb, '["La societat postindustrial de la segona meitat del segle xx dona pas a la societat informatitzada, la cibersocietat, que es caracteritza per considerar la informació com la principal riquesa i font d’organització.","El que caracteritza la societat de la informació és que, gràcies a les TIC, la transmissió d’aquesta informació arriba a un nombre enorme d’usuaris, amb una rapidesa i immediatesa impensables fins fa ben poc, i amb un volum tan gran que allò difícil és, justament, processar en l’àmbit personal la gran quantitat d’informació que es rep diàriament.","La Internet de les coses esdevé un nou paradigma en relació amb la xarxa d’Internet, ja que fa créixer de manera exponencial el volum de dispositius interconnectats juntament amb noves formes d’amenaces.","La seguretat de la informació ha de ser un element bàsic a l’hora de gestionar les organitzacions. Així, cal enfocar-la com un objectiu global de caràcter intern.","Cada vegada és més important la qualitat de la informació i el coneixement rebuts que la quantitat. Les persones han d’aprendre a valorar i seleccionar la informació abans de processar-la. Internet és una immensa xarxa de computadores estesa per tot el planeta i que permet, a qualsevol usuari, conèixer arxius d’informació i de dades, amb so i imatges animades o estàtiques, gràfics, etc., a partir d’adreces electròniques o bé mitjançant programari que permet navegar a la recerca d’informació de tota mena des de qualsevol punt del món.","L’administració electrònica és un model de relació entre els ciutadans i l’Administració que aspira a millorar la prestació dels serveis als ciutadans, les empreses i les entitats, i a augmentar la productivitat d’aquests serveis i la participació ciutadana mitjançant l’ús de les tecnologies de la informació i la comunicació.","Gràcies a la signatura electrònica és possible garantir conceptes clau com l’autenticitat, la integritat i el no repudi en el si de les comunicacions electròniques.","Un dels perills més patents que avui dia pot comportar Internet és la seva manca de regulació, però, sobretot, que la innovació també es doni en noves formes de delictes contra els drets de les persones.","La IA representa una evolució de les tecnologies de la informació que permet l’automatització de processos i la presa de decisions assistida a partir de l’anàlisi massiva de dades, fet que obre noves oportunitats però també nous reptes en matèria de seguretat, control i garantia dels drets fonamentals."]'::jsonb, '["Automatització","Administració electrònica","Avenç tecnològic","Cibercultura","Cibersocietat","Comerç electrònic","Dades confidencials","Globalització","Hipermèdia","Hipertext","Informàtica","Innovació tecnològica","Interactivitat","Internet de les coses","Multimèdia","Obsolescència","Realitat virtual","Robotització","Sector de serveis, terciari","Sector industrial, secundari","Seguretat de la informació","Signatura electrònica","Sistemes de comunicació","Societat postindustrial","Tècnica","Tecnologies de la informació i la comunicació","Transaccions","Universitat oberta"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La societat del coneixement: origen i característiques","blocks":[{"text":"La humanitat ha evolucionat al ritme de les innovacions tecnològiques, i avui som a l''era de la informació. La gran diferència respecte d''altres conquestes tecnològiques és el protagonisme dels ciutadans: la informació i el coneixement, que abans eren un privilegi d''una minoria, ara són a l''abast de tothom a un cost relativament baix, i es transmeten amb més capacitat, disponibilitat i immediatesa. D''aquí neix la societat de la informació, també anomenada societat del coneixement, fruit de l''espectacular desenvolupament de les tecnologies de la informació i la comunicació (TIC).","refs":[{"ref":"p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"Abans, la informació i el coneixement, el poder, eren un privilegi al qual podia accedir només una minoria; ara, són a l’abast de tots els ciutadans de forma relativament poc costosa."},{"ref":"p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"Tot aquest conjunt de factors han fet que sorgeixi una nova societat, la societat de la informació, també anomenada societat del coneixement."}]},{"text":"L''acte de naixement de la societat del coneixement té data: el 1981, quan Microsoft desenvolupa el sistema operatiu MS-DOS i IBM presenta el primer ordinador personal (PC). El 1984 el Macintosh d''Apple, amb interfície gràfica de finestres i ratolí (incorporats després a Windows), estén l''ús de l''ordinador a tots els àmbits i usuaris. Aquests són els fets cabdals que marquen l''inici de l''era de la informàtica.","refs":[{"ref":"p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"l’acte de naixement de la societat del coneixement o de la informació té una data concreta: l’any 1981. Aquest any Microsoft desenvolupa el sistema operatiu MS-DOS i IBM presenta el primer ordinador personal, el PC (personal computer)."},{"ref":"p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"L’aparició del Macintosh d’Apple el 1984, amb una interfície gràfica de finestres i del ratolí (mouse), incorporat després als sistemes Windows"}]},{"text":"La societat postindustrial de la segona meitat del segle XX dona pas a la societat informatitzada o cibersocietat, que considera la informació la principal riquesa i font d''organització (idea força 1). Conseqüència: la major part de la població activa ja no és al sector secundari (indústria), sinó al terciari (serveis), cada vegada més lligat a la informàtica, i a la indústria la mà d''obra és substituïda per la robotització i l''automatització.","refs":[{"ref":"Idea força 1, p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"La societat postindustrial de la segona meitat del segle xx dona pas a la societat informatitzada, la cibersocietat, que es caracteritza per considerar la informació com la principal riquesa i font d’organització."},{"ref":"p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"La mà a la indústria és substituïda per la robotització i l’automatització dels processos productius."}]}]},{"n":"2","title":"Els sis conceptes de la cibersocietat i Internet","blocks":[{"text":"Com que les TIC abasten tots els sectors productius i d''oci, la cibersocietat s''organitza al voltant de sis conceptes: a) multimèdia, la integració de so, imatge i text; b) hipermèdia, la integració de multimèdia i hipertext (text organitzat de forma no seqüencial); c) realitat virtual, que trasllada les persones a una realitat diferent; d) grans xarxes d''ordinadors, rèplica dels sistemes de comunicació entre grups; e) Internet, l''«autopista de la informació», i f) telefonia mòbil, que des de mitjans dels noranta s''ha difós com cap altre dispositiu i ha convergit amb Internet en una única xarxa mundial.","refs":[{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"a) Multimèdia: la informàtica permet integrar so, imatge i text. b) Hipermèdia: integració de multimèdia i hipertext, que és un text organitzat de forma no seqüencial."},{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"e) Internet: també anomenada autopista de la informació."}]},{"text":"Les tecnologies de la informació són una manera d''elaborar, processar, emmagatzemar i transmetre informació entre persones. El que es transmet són bàsicament dades, que aporten informació però poc coneixement. Cal distingir transport (els sistemes de telecomunicacions) i contingut (els missatges: converses, lleure, cultura, telecompra).","refs":[{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"En realitat, el que es transmet són bàsicament dades, que aporten informació, però poc coneixement."},{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"el transport s’efectua mitjançant els sistemes de telecomunicacions; el contingut són els missatges que s’envien per aquests sistemes"}]},{"text":"Internet és una immensa xarxa de computadores estesa per tot el planeta que permet a qualsevol usuari accedir a informació, dades, so, imatges i gràfics a partir d''adreces electròniques o navegant des de qualsevol punt del món. Una conseqüència clau és el diari electrònic, possible gràcies a l''hipertext, que enllaça documents (la paraula subratllada en blau). La societat interactiva és sinònim de societat interconnectada.","refs":[{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"Actualment, Internet és una immensa xarxa de computadores estesa per tot el planeta"},{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"El diari electrònic és una de les conseqüències més importants d’aquest món"},{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"La societat interactiva és sinònim de la societat interconnectada"}]}]},{"n":"3","title":"La Internet de les coses (IoT): safety i security","blocks":[{"text":"Als canvis des dels anys vuitanta s''hi afegeix la Internet de les coses (IoT, Internet of things), el màxim exponent de la interconnexió de dispositius per Internet, amb funcions com la videovigilància, la domòtica o l''automoció. Segons la idea força 3, és un nou paradigma perquè fa créixer exponencialment el volum de dispositius interconnectats i, alhora, les noves formes d''amenaces.","refs":[{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"La IoT representa el màxim exponent de la interconnexió de dispositius a través d’Internet, els quals poden estar orientats a múltiples funcions, com ara videovigilància, domòtica, automoció, etc."},{"ref":"Idea força 3, p. 92","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=92","quote":"La Internet de les coses esdevé un nou paradigma en relació amb la xarxa d’Internet, ja que fa créixer de manera exponencial el volum de dispositius interconnectats juntament amb noves formes d’amenaces."}]},{"text":"Els països llatins fan servir una sola paraula, seguretat, mentre que el món anglosaxó en té dues: safety, per a la seguretat ambiental, els riscos laborals, etc., i security, per a la seguretat física i lògica orientada al control d''accessos i la prevenció d''intrusions. La IoT potser obligarà a ajuntar-ho tot en una sola paraula. Exemple: un edifici té inspeccions d''entitats col·laboradores de l''Administració (ECA) per a ascensors o instal·lacions elèctriques (safety) i controls de la policia administrativa sobre videovigilància o accessos (security); en els edificis intel·ligents (smart buildings) un sistema central, sovint remot, ho controla tot.","refs":[{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"el món anglosaxó sempre ha mantingut dos conceptes ben clars i diferenciats, atès que els separa en safety, per als assumptes relacionats amb la seguretat ambiental, riscos laborals, etc., i security, per a allò relacionat amb la seguretat física i lògica en un sentit més orientat al control d’accessos, prevenció d’intrusions, etc."},{"ref":"p. 86","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=86","quote":"els edificis intel·ligents (smart buildings), on un sistema de control central pren possessió final de tots els elements de seguretat (safety i security) d’un emplaçament"}]},{"text":"El risc: un detector de fum pot funcionar perfectament, però avisa el panell central a través d''una interfície de xarxa, i cal garantir que aquesta comunicació és segura. Estudis recents ja han demostrat que és possible comprometre la seguretat d''aquests dispositius.","refs":[{"ref":"p. 86","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=86","quote":"Malauradament, estudis recents ja han demostrat que és possible comprometre la seguretat d’aquests dispositius."}]}]},{"n":"4","title":"Efectes de les TIC en el treball i l''economia","blocks":[{"text":"El tret propi de la societat de la informació és que la transmissió arriba a un nombre enorme d''usuaris, amb una rapidesa impensable i un volum tan gran que el difícil és processar tota la informació que es rep (idea força 2). Les TIC afecten tots els àmbits (treball, lleure, cultura, economia, relació amb l''Administració) i el coneixement esdevé la primera font de productivitat.","refs":[{"ref":"p. 86","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=86","quote":"En la nova societat del coneixement, el coneixement és, precisament, la primera font de productivitat."},{"ref":"p. 86","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=86","quote":"El que caracteritza la societat de la informació és que, gràcies a les TIC, aquesta transmissió arriba a un nombre enorme d’usuaris"}]},{"text":"El pas de la societat postindustrial a la del coneixement desplaça la força de treball del secundari al terciari, com la Revolució Industrial la va desplaçar de produir aliments a produir manufactures. Característiques del canvi: a) agricultura i ramaderia esdevenen minoritàries; b) disminueix l''ocupació industrial tradicional; c) augmenten i es diversifiquen les feines executives, professionals i tècniques; d) creix l''ocupació d''alta formació i qualificació, i e) augmenten els treballadors terciaris (oficinistes i venedors) a la base del sistema productiu.","refs":[{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"c) Augmenten i es diversifiquen les feines de caràcter executiu, professional i tècnic. d) Incrementa l’ocupació de més alta formació i qualificació."}]},{"text":"Com la mecanització industrial, ara també es tornen rutinaris processos del terciari; per això calen formació contínua i reciclatge, perquè les professions queden obsoletes molt més de pressa. Les relacions econòmiques passen en temps real: comerç electrònic, mercats globals, pagaments amb targeta i telecompra.","refs":[{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"fa necessària la formació contínua i el reciclatge periòdic dels treballadors"},{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"Les relacions econòmiques de la nova societat es produeixen en temps real."}]}]},{"n":"5","title":"Efectes de les TIC en la cultura, la llar, l''Administració i el coneixement","blocks":[{"text":"En la cultura, el concepte clau és la multimèdia i el resultat és la cibercultura: una nova concepció de la cultura i de la societat on el que es transmet té tanta importància com el mitjà tecnològic que ho fa possible. A la llar s''estableix una relació directa i individual persona-màquina a través de la pantalla, que provoca ciberdependència: desapareix el valor de l''esforç per aconseguir un objectiu i la noció del temps com a acumulació d''experiència. També es difumina la frontera entre feina i casa (correu i trucades de feina a casa).","refs":[{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"el resultat final és la cibercultura, que és una nova concepció de la cultura i de la societat, on el que es transmet té tanta importància com el mitjà tecnològic que fa possible aquesta transmissió."},{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"Això provoca, de retruc, un important efecte de ciberdependència: desapareix el concepte del valor de l’esforç per aconseguir un objectiu o la noció del temps com a acumulació d’experiència"}]},{"text":"La relació entre Administració i administrats també canvia: apareix l''Administració oberta, que vol adaptar els serveis a les necessitats dels ciutadans, oferir serveis integrats, simplificar tràmits, fer transaccions electròniques i donar servei 24 hores, set dies a la setmana (pagar impostos o l''IRPF per Internet). En formació creixen l''e-learning i la universitat oberta.","refs":[{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"Sorgeixen conceptes com l’Administració oberta"},{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"En l’àmbit de la formació, cada vegada té més rellevància la formació a distància, l’e-learning, i el concepte d’universitat oberta."}]},{"text":"Com que la informació ja no és escassa, hi ha un conflicte entre l''excés d''informació i el que el cervell pot processar. Per això és més important la qualitat de la informació i el coneixement rebuts que la quantitat, i cal aprendre a valorar-la i seleccionar-la (idea força 5). A més, la velocitat escurça el cicle vital dels coneixements, que per primera vegada a la història és més curt que la vida de les persones.","refs":[{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"Per tant, cada vegada és més important la qualitat de la informació i el coneixement rebuts que la quantitat. Les persones han d’aprendre a valorar i seleccionar la informació abans de processar-la."},{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"ara aquest cicle vital dels coneixements s’ha fet molt més curt que la vida de les persones"}]}]},{"n":"6","title":"Seguretat de la informació","blocks":[{"text":"Les amenaces tecnològiques avancen tan de pressa que moltes organitzacions no poden fer-hi front. Cal distingir dos conceptes que semblen iguals però no ho són. La seguretat informàtica s''associa als aspectes tècnics i operacionals. La seguretat de la informació es basa en els aspectes estratègics: gestió de riscos i amenaces, anàlisi d''escenaris i bones pràctiques, amb l''objectiu d''assegurar la confidencialitat, la integritat i la disponibilitat en l''ús de la informació.","refs":[{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"La seguretat informàtica s’ha d’associar a aquells aspectes tècnics i operacionals de la seguretat, mentre que la seguretat de la informació es basa en els aspectes estratègics"},{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"amb l’objectiu d’assegurar la confidencialitat, integritat i disponibilitat en l’ús de la informació."}]},{"text":"Les estratègies de protecció han de seguir tres principis: la seguretat ha de ser un objectiu global; s''ha de dissenyar com una part de l''organització, i el marc legal s''ha de considerar des de l''inici com una part del disseny de les polítiques. Els mecanismes habituals (tallafocs, antivirus) no són suficients per si sols: calen polítiques àmplies, més enllà de la tecnologia, i la conscienciació dels usuaris. Idea força 4: la seguretat de la informació és un objectiu global de caràcter intern.","refs":[{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"La seguretat ha de ser un objectiu global."},{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"El marc legal s’ha de considerar, des de l’inici, com una part més del disseny de les polítiques de seguretat."},{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"és evident que els mecanismes de seguretat habituals (tallafocs, antivirus, etc.) no són suficients per si mateixos per a la protecció de la informació."}]}]},{"n":"7","title":"L''administració electrònica","blocks":[{"text":"L''administració electrònica vol millorar la transparència, l''eficàcia i la qualitat del sector públic amb l''ús de les TIC en les relacions entre el sector públic, ciutadans, empreses i organitzacions. Aspira a millorar la prestació dels serveis i a augmentar-ne la productivitat i la participació ciutadana (idea força 6).","refs":[{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"L’administració electrònica té com a objectiu millorar la transparència, l’eficàcia i la qualitat del sector públic mitjançant l’ús de les TIC"},{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"L’administració electrònica aspira a la millora en la prestació dels serveis als ciutadans, les empreses i les entitats, i a augmentar la productivitat d’aquests serveis i la participació ciutadana"}]},{"text":"A Catalunya es va començar a apostar per un model d''administració electrònica l''any 1997. Des d''aleshores s''ha consolidat mitjançant la cooperació entre les administracions públiques catalanes, buscant solucions comunes tant en la relació amb els ciutadans com en la gestió interna.","refs":[{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"A Catalunya es va començar a apostar pel desenvolupament d’un model d’administració electrònica l’any 1997"},{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"a través de la cooperació entre les diferents administracions públiques catalanes"}]}]},{"n":"8","title":"La signatura electrònica","blocks":[{"text":"En l''administració electrònica i les comunicacions per Internet són clau les relacions de confiança, que protegeixen la privacitat i creen un espai de seguretat on les comunicacions siguin viables: aquesta és la principal motivació de la signatura electrònica.","refs":[{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"Aquesta és la principal motivació de la signatura electrònica."}]},{"text":"La signatura electrònica permet enviar missatges complint tres propietats: autenticitat (el receptor està segur de la identitat del remitent), integritat (certesa que el missatge no s''ha modificat durant la transmissió) i no repudi (l''emissor no pot negar que l''ha enviat, per exemple al·legant que ho ha fet una tercera persona). Són imprescindibles per a activitats delicades com les votacions electròniques.","refs":[{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"Autenticitat: la signatura d’un missatge per l’emissor permet que el receptor estigui segur de la identitat del remitent."},{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"Integritat: certesa que el missatge no s’ha modificat durant la transmissió."},{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"No repudi: l’emissor d’un missatge no pot repudiar o negar que l’ha enviat"},{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"Si volem fer activitats tan delicades com, per exemple, participar en unes votacions electròniques, és imprescindible garantir les tres propietats abans esmentades."}]}]},{"n":"9","title":"Comunicació i control públic: regulació d''Internet","blocks":[{"text":"Un dels perills més evidents d''Internet és la manca de regulació (idea força 8), i sobretot que la innovació arribi també a noves formes de delictes contra els drets de les persones. Internet és un canal insegur, perquè la informació és accessible en qualsevol punt intermedi. Per enviar dades confidencials, la solució adoptada és el protocol SSL (Secure Sockets Layer).","refs":[{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"Un dels perills més patents que avui dia pot comportar Internet és la seva manca de regulació."},{"ref":"p. 89","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=89","quote":"En el cas d’Internet, la solució adoptada es basa en la utilització del protocol SSL (Secure Sockets Layer)."}]},{"text":"Davant la pèrdua de capacitat de control de l''Estat en un món globalitzat, cal una normativa consensuada internacionalment. Però és difícil: la tecnologia ha crescut amb una ètica transgressora, la propietat intel·lectual està en debat i la pirateria ha assolit proporcions monumentals, perquè els infractors, emparats per l''anonimat, no perceben el perjudici. Els poders públics han de legislar sense vulnerar la inviolabilitat de les comunicacions ni el dret a la intimitat.","refs":[{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"es fa necessària la demanda consensuada a escala internacional d’una sèrie de normatives per garantir l’operativitat i el funcionament de la xarxa."},{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"La pirateria de productes culturals, d’oci i de programari ha assolit proporcions monumentals"}]}]},{"n":"10","title":"Protecció de dades i alarmes de disseny","blocks":[{"text":"La Constitució protegeix la intimitat i l''honor. D''aquí va sorgir la Llei orgànica 5/1992 (LORTAD), que aplica l''article 18.4 CE sobre la limitació de l''ús de la informàtica per garantir l''honor i la intimitat personal i familiar, i es va crear l''Agència de Protecció de Dades (APD). Aquesta legislació s''ha actualitzat amb la Llei orgànica 15/1999, de 13 de desembre (avui derogada, llevat d''alguns preceptes), el seu reglament (Reial decret 1720/2007, de 21 de desembre) i la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, que és la vigent. La guia no esmenta el Reglament general europeu de protecció de dades.","refs":[{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"sorgí la Llei orgànica 5/1992, de regulació i tractament automàtic de les dades (LORTAD), que aplica l’article 18.4 de la CE, sobre la limitació de l’ús de la informàtica per garantir l’honor i la intimitat personal i familiar dels ciutadans"},{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"es va constituir l’Agència de Protecció de Dades (APD)"},{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"La Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals."}]},{"text":"Les TIC (mòbil, correu, xarxes socials) han barrejat el que és públic i el que és privat. Neix un nou debat sobre els límits de la seguretat pública en l''esfera privada i sobre com protegir la vida domèstica dels nous perills: són les anomenades alarmes de disseny.","refs":[{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"Hi ha un conflicte de separació entre l’esfera pública i la privada."},{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"S’originen unes noves alarmes, que podríem definir com a alarmes de disseny."}]}]},{"n":"11","title":"La intel·ligència artificial i l''automatització de processos","blocks":[{"text":"La intel·ligència artificial (IA) és el conjunt de tecnologies i sistemes informàtics que permeten a les màquines simular capacitats pròpies de la intel·ligència humana, com l''entrenament, l''anàlisi de dades, el reconeixement de patrons o la presa de decisions automatitzades. Està lligada a les TIC, Internet i la IoT: el gran volum de dades dels dispositius connectats i l''augment de la capacitat de càlcul i emmagatzematge la fan cada vegada més autònoma, i és clau en la robotització i l''automatització de processos.","refs":[{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"Aquest terme fa referència al conjunt de tecnologies i sistemes informàtics que permeten a les màquines simular determinades capacitats pròpies de la intel·ligència humana, com ara l’entrenament, l’anàlisi de dades, el reconeixement de patrons o la presa de decisions automatitzades."},{"ref":"p. 91","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=91","quote":"la IA esdevé un element clau en la robotització i l’automatització de processos productius, de serveis i de gestió"}]},{"text":"S''aplica a serveis digitals, anàlisi de grans volums d''informació, mobilitat, control d''accessos, videovigilància, gestió d''alarmes o decisió assistida. En seguretat i control públic obre oportunitats i riscos: com amb la IoT, cal garantir la seguretat de la informació, la integritat de les dades i la protecció davant accessos no autoritzats. Planteja reptes de supervisió humana, de responsabilitat sobre les decisions automatitzades i de respecte als drets fonamentals (privacitat, no-discriminació, control en espais públics). La guia no cita cap norma específica sobre IA.","refs":[{"ref":"p. 91","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=91","quote":"l’ús de sistemes basats en IA introdueix reptes rellevants pel que fa a la supervisió humana, la responsabilitat sobre les decisions adoptades de manera automatitzada i el respecte als drets fonamentals"},{"ref":"p. 91","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=91","quote":"fa imprescindible garantir la seguretat de la informació, la integritat de les dades i la protecció davant d’accessos no autoritzats o de manipulacions malicioses."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"1981: MS-DOS de Microsoft i primer PC d''IBM, naixement de la societat del coneixement. 1984: Macintosh.","refs":[{"ref":"p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"té una data concreta: l’any 1981"}]},{"text":"Cibersocietat: la informació és la principal riquesa i font d''organització.","refs":[{"ref":"p. 84","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=84","quote":"considerar la informació com la principal riquesa i font d’organització"}]},{"text":"Hipermèdia = multimèdia + hipertext; multimèdia = so, imatge i text.","refs":[{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"Hipermèdia: integració de multimèdia i hipertext"}]},{"text":"Safety: seguretat ambiental i riscos laborals; security: control d''accessos i intrusions.","refs":[{"ref":"p. 85","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=85","quote":"safety, per als assumptes relacionats amb la seguretat ambiental, riscos laborals, etc."}]},{"text":"Ciberdependència: desapareix el valor de l''esforç. Cibercultura: el que es transmet val tant com el mitjà.","refs":[{"ref":"p. 87","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=87","quote":"important efecte de ciberdependència"}]},{"text":"Seguretat informàtica = tècnica i operacional; seguretat de la informació = estratègica (confidencialitat, integritat, disponibilitat).","refs":[{"ref":"p. 88","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=88","quote":"La seguretat informàtica s’ha d’associar a aquells aspectes tècnics i operacionals de la seguretat"}]},{"text":"Administració electrònica a Catalunya des del 1997. Signatura electrònica: autenticitat, integritat i no repudi.","refs":[{"ref":"Idea força 7, p. 92","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=92","quote":"Gràcies a la signatura electrònica és possible garantir conceptes clau com l’autenticitat, la integritat i el no repudi en el si de les comunicacions electròniques."}]},{"text":"Dades confidencials a Internet: protocol SSL. LORTAD (LO 5/1992) aplica l''art. 18.4 CE; vigent, LO 3/2018.","refs":[{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"aplica l’article 18.4 de la CE"}]},{"text":"Conflicte públic-privat: alarmes de disseny.","refs":[{"ref":"p. 90","law":"Guia d''estudi, tema A.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=90","quote":"alarmes de disseny"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=83'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=83', 83, 93, 92, null
