insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema B.1, pp. 94-106', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=94', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
