insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Antecedents històrics i naturalesa jurídica"},{"n":"1.1","title":"Antecedents històrics"},{"n":"1.2","title":"Naturalesa jurídica"},{"n":"2","title":"Contingut i estructura"},{"n":"2.1","title":"Contingut"},{"n":"2.2","title":"Estructura"},{"n":"3","title":"Els drets, els deures i els principis rectors"},{"n":"4","title":"Les competències de la Generalitat de Catalunya"},{"n":"4.1","title":"Tipologia"},{"n":"4.2","title":"Principis i criteris"},{"n":"4.3","title":"Les matèries de les competències"},{"n":"5","title":"La competència en matèria de seguretat pública establerta a l’Estatut d’autonomia de Catalunya"}]'::jsonb, '["L’Estatut d’autonomia de Catalunya és la norma institucional bàsica de la Comunitat Autònoma de Catalunya.","La Generalitat és el sistema institucional en què s’organitza l’autogovern de Catalunya. Els poders de la Generalitat emanen del poble de Catalunya i s’exerceixen d’acord amb el que estableixen l’EAC i la Constitució.","El català és la llengua d’ús normal i preferent de les administracions públiques.","L’EAC incorpora un catàleg de drets, deures i principis rectors que informa la condició política de ciutadania.","La regulació que fa l’EAC de les competències de la Generalitat pretén garantir i ampliar el nivell competencial autonòmic.","L’EAC preveu els mecanismes perquè la Generalitat participi com a tal en les institucions i en la fixació de polítiques de l’Estat, disposi de mecanismes àgils de col·laboració i cooperació amb les comunitats autònomes, sigui present i faci sentir la seva veu davant les institucions europees i impulsi la projecció exterior, i promogui el interessos de Catalunya, tot respectant les competències estatals.","La Generalitat té el comandament de la Policia de la Generalitat - Mossos d’Esquadra i la coordinació de l’actuació de les policies locals.","La Policia de la Generalitat - Mossos d’Esquadra exerceix les funcions en els àmbits de la seguretat pública i l’ordre públic, la policia administrativa, i la policia judicial i la investigació criminal."]'::jsonb, '["Bloc de constitucionalitat","Competències compartides","Competències exclusives","Competències executives","Convenis de col·laboració","Estatut d’autonomia","Policia de la Generalitat - Mossos d’Esquadra","Policies locals","Seguretat pública","Sistema institucional"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Antecedents: de l''Estatut de 1979 a la proposta de reforma","blocks":[{"text":"Amb la Constitució de 1978 (CE), Catalunya va accedir a l''autonomia per la via de l''article 151.2 CE, amb l''Estatut d''autonomia de 1979, aprovat per la Llei orgànica 4/1979, de 18 de desembre, que va regir l''autogovern català durant més de 25 anys.","refs":[{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"En el marc de la Constitució espanyola de 1978 (CE), Catalunya accedia a l’autonomia pel procediment establert al seu article 151.2, mitjançant l’aprovació de l’Estatut d’autonomia de 1979 (Llei orgànica 4/1979, de 18 de desembre). Aquesta norma ha regit l’autogovern català durant més de 25 anys."}]},{"text":"El procés de reforma va començar el 9 de febrer de 2004, després de les eleccions del novembre de 2003, en què quatre dels cinc partits parlamentaris proposaven canviar l''Estatut. La primera fase, al Parlament, va tenir tres passos: una ponència conjunta de tots els grups (a partir de documentació de l''Institut d''Estudis Autonòmics), la tramitació a la Comissió d''Organització i Administració de la Generalitat i l''aprovació pel Ple el 30 de setembre de 2005, amb 120 vots a favor i 15 en contra.","refs":[{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"Després de les eleccions autonòmiques del novembre de 2003, en les quals quatre dels cinc partits parlamentaris presentaven propostes de canvi del marc estatutari, el 9 de febrer de 2004 s’iniciava el procés de reforma de l’Estatut."},{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"primer, per una ponència conjunta amb representants de tots els grups parlamentaris, a partir de la documentació prèvia elaborada per l’Institut d’Estudis Autonòmics; segonament, va ser tramitada dins la Comissió d’Organització i Administració de la Generalitat, i, finalment, el text de la proposta fou aprovat pel Ple del Parlament el 30 de setembre de 2005 (amb 120 vots a favor i 15 en contra)."}]},{"text":"Entre la comissió i el Ple hi va haver el Dictamen núm. 269 del Consell Consultiu (5 de setembre de 2005) sobre la constitucionalitat de la proposta. Les trobades de líders polítics a Miravet van ajudar a impulsar el procés.","refs":[{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"Entre les dues darreres etapes hi hagué el Dictamen núm. 269 del Consell Consultiu (5 de setembre de 2005), que va pronunciar-se sobre la constitucionalitat de la proposta. També cal esmentar les trobades de líders polítics catalans (Miravet), que van contribuir a impulsar el procés."}]}]},{"n":"2","title":"La tramitació a les Corts, el referèndum i la Sentència 31/2010","blocks":[{"text":"La segona fase es va fer a les Corts Generals: presa en consideració pel Ple del Congrés, esmenes i discussió a la Comissió Conjunta Paritària (Comissió Constitucional del Congrés i una delegació del Parlament), on es va formalitzar l''acord (Dictamen de 21 de març de 2006). El Ple del Congrés el va aprovar el 30 de març de 2006 i el Senat, el 10 de maig de 2006, sense modificacions.","refs":[{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"presa en consideració pel Ple del Congrés dels Diputats; presentació d’esmenes; discussió dins la Comissió Conjunta Paritària, integrada per la Comissió Constitucional del Congrés i una delegació del Parlament de Catalunya, en què es va formalitzar l’acord sobre el text (Dictamen de 21 de març de 2006)"},{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"aprovació pel Ple del Congrés (30 de març de 2006), i tramitació del text pel Senat, que l’aprovà el 10 de maig de 2006, sense introduir-hi modificacions."}]},{"text":"El procés es va tancar amb el referèndum del 18 de juny de 2006, amb resultat positiu. La reforma, aprovada per la Llei orgànica 6/2006, de 19 de juliol, va entrar en vigor el 9 d''agost de 2006.","refs":[{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"El procés va finalitzar amb el referèndum del dia 18 de juny de 2006, en què s’obtingué un resultat positiu. Després de la seva promulgació i publicació oficial, la reforma de l’Estatut d’autonomia de Catalunya (EAC), aprovada per la Llei orgànica 6/2006, de 19 de juliol, va entrar en vigor el dia 9 d’agost de 2006."}]},{"text":"La Sentència del Tribunal Constitucional 31/2010, de 28 de juny, va declarar inconstitucionals alguns articles de l''EAC; destaquen els referits a la llengua catalana, el Consell de Garanties Estatutàries, el Síndic de Greuges, el Consell de Justícia de Catalunya, les competències sobre l''Administració de justícia, la participació en els tributs estatals i les finances dels governs locals.","refs":[{"ref":"apartat 1.1, p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"El Tribunal Constitucional, en la Sentència 31/2010, de 28 de juny, va declarar inconstitucionals alguns articles de l’EAC, entre els quals destaquen els referits a la llengua catalana, el Consell de Garanties Estatutàries, el Síndic de Greuges, el Consell de Justícia de Catalunya, les competències sobre l’Administració de justícia, la participació en els tributs estatals i les finances dels governs locals."}]}]},{"n":"3","title":"Naturalesa jurídica: norma institucional bàsica i llei orgànica","blocks":[{"text":"El títol VIII de la CE no fixa directament el model territorial, sinó principis i regles per passar d''un Estat unitari a un de políticament descentralitzat. La base és el principi dispositiu: els territoris (nacionalitats i regions, article 2 CE) decideixen si exerceixen el dret a l''autonomia i com. La CE remet la creació de les comunitats als estatuts, que tenen així una funció constitucional.","refs":[{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"Aquesta transformació es basa en el principi dispositiu, d’acord amb el qual són els mateixos territoris interessats, identificats com a nacionalitats i regions (article 2 CE), els que decideixen exercir el dret a l’autonomia"},{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"La norma estatutària assumeix així una funció constitucional, atès que és un complement indispensable de la Constitució per a la determinació de l’estructura territorial de l’Estat."}]},{"text":"L''EAC té una doble naturalesa jurídica. D''una banda, és la llei primera i fonamental de l''ordenament català, la norma institucional bàsica de la Comunitat (article 147.1 CE), amb un paper semblant al d''una constitució sense tenir-ne formalment el caràcter. Fixa els tipus de normes catalanes (llei, decret legislatiu, decret llei i reglaments), condiciona la validesa de les altres normes autonòmiques i té eficàcia derogatòria immediata.","refs":[{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"l’EAC té una doble naturalesa jurídica: d’una banda, és la llei primera i fonamental de l’ordenament jurídic català i, de l’altra, és una llei orgànica estatal. En el primer sentit, l’Estatut d’autonomia es caracteritza per ser la norma institucional bàsica de la Comunitat Autònoma de Catalunya (article 147.1 CE)."},{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"l’EAC estableix els tipus de normes que l’integren (llei, decret legislatiu, decret llei i reglaments)"}]},{"text":"De l''altra, és una norma estatal: una llei orgànica aprovada per les Corts Generals, que al Congrés exigeix majoria absoluta. Té un procediment especial d''aprovació i reforma perquè és de caràcter paccionat: necessita la concurrència de dues voluntats, l''autonòmica i l''estatal.","refs":[{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"és també una norma estatal, que revesteix la forma de llei orgànica aprovada per les Corts Generals (amb l’exigència d’una majoria absoluta de la cambra en el cas del Congrés dels Diputats)."},{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"L’EAC és una norma de caràcter paccionat, ja que tant la seva aprovació com la seva reforma exigeixen la concurrència de dues voluntats, l’autonòmica i l’estatal."}]},{"text":"L''Estatut de 1979 es va elaborar pel procediment de l''article 152.1 CE, amb negociació entre les Corts Generals i l''assemblea proponent (senadors i diputats del territori). L''Estatut regula la seva pròpia reforma, però la CE ja imposa un referèndum preceptiu i vinculant (article 152.2 CE).","refs":[{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"l’elaboració de l’EAC de 1979 va seguir el procediment de l’article 152.1 CE, que reforça el caràcter bilateral mitjançant l’exigència d’una negociació entre les Corts Generals i els representants de l’assemblea proponent"},{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"si bé ja fixa un referèndum preceptiu i vinculant de la població de la comunitat autònoma (article 152.2 CE)."}]}]},{"n":"4","title":"Posició a l''ordenament: bloc de la constitucionalitat i rigidesa","blocks":[{"text":"L''EAC està subordinat a la Constitució, però supraordenat a la resta de normes, estatals i autonòmiques, per la funció constitucional que fa (no per jerarquia ni competència). Primer motiu: forma part del bloc de la constitucionalitat i, després de la Constitució, és la principal norma que delimita competències entre l''Estat i la Comunitat; per això és paràmetre de constitucionalitat de les lleis estatals i autonòmiques.","refs":[{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"L’EAC ocupa una posició especial en l’ordenament jurídic, ja que està subordinat a la Constitució però està supraordenat a la resta de normes de l’ordenament, tant estatals com autonòmiques."},{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"la integració en l’anomenat bloc de la constitucionalitat converteix l’Estatut en la principal norma que, a més de la mateixa Constitució, intervé en la delimitació de les competències entre l’Estat i la comunitat autònoma. D’aquesta manera, actua com a paràmetre de constitucionalitat de les lleis estatals i autonòmiques"}]},{"text":"Segon motiu: la rigidesa. L''EAC té força passiva o resistència davant d''altres normes, perquè només es pot reformar pels seus procediments (article 152.2 CE): és indisponible unilateralment per al legislador estatal i per a l''autonòmic.","refs":[{"ref":"apartat 1.2, p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"l’EAC presenti una força passiva o resistència enfront d’altres normes, ja que només pot ser reformat pels procediments específics que s’hi preveuen (article 152.2 CE). Per tant, és indisponible unilateralment tant per al legislador estatal com per al legislador autonòmic."}]}]},{"n":"5","title":"Contingut de l''Estatut: necessari, remès i ampliat","blocks":[{"text":"L''article 147.2 CE fixa el contingut mínim o obligatori dels estatuts (reserva estatutària): la denominació que s''ajusti a la identitat històrica (article 1 EAC); la delimitació del territori (article 9); la denominació, organització i seu de les institucions (títol II), i les competències i les bases per al traspàs de serveis (títol IV).","refs":[{"ref":"apartat 2.1, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"L’article 147.2 CE estableix un contingut mínim o obligatori de tots els estatuts. Aquest precepte estableix una reserva estatutària"},{"ref":"apartat 2.1, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"a) La denominació de la comunitat autònoma que s’ajusti millor a la seva identitat històrica (article 1 EAC). b) La delimitació del territori de la comunitat autònoma (article 9 EAC). c) La denominació, l’organització i la seu de les institucions autònomes pròpies (títol II EAC). d) Les competències assumides dins del marc establert per la Constitució i les bases per al traspàs dels serveis corresponents (títol IV EAC)."}]},{"text":"La reserva no impedeix que altres normes completin l''Estatut. L''Estatut de 1979 deixava el detall institucional a la Llei 3/1982, de 23 de març, del Parlament, el president i el Consell Executiu. I la Comunitat pot rebre noves competències per les lleis de l''article 150 CE: llei marc i llei orgànica de transferència o delegació.","refs":[{"ref":"apartat 2.1, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"l’Estatut de 1979 deixava un espai per a una regulació de detall per la Llei 3/1982, de 23 de març, del Parlament, el president i el Consell Executiu (enllaçant amb la tradició de l’anomenat Estatut interior de 1933)."},{"ref":"apartat 2.1, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"la comunitat autònoma pot rebre noves competències en virtut de les lleis estatals de l’article 150 CE (llei marc i llei orgànica de transferència o delegació)."}]},{"text":"La CE remet als estatuts altres matèries: l''oficialitat de la llengua pròpia (art. 3.2 CE i 6 EAC), les banderes i ensenyes (art. 4.2 CE i 8 EAC), la designació dels senadors autonòmics (art. 69.5 CE i 61 EAC) o els convenis amb altres comunitats (art. 145.2 CE). Els estatuts n''inclouen d''altres (hisenda, fonts del dret, ens locals), i és plenament legítim que l''EAC inclogui un catàleg de drets i deures.","refs":[{"ref":"apartat 2.1, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"Altres matèries específiques que la CE remet als estatuts són: la declaració d’oficialitat de la llengua oficial pròpia (art. 3.2 CE i 6 EAC), el reconeixement de banderes i ensenyes pròpies (art. 4.2 CE i 8 EAC), el procediment de designació dels senadors de representació autonòmica (art. 69.5 CE i 61 EAC) o la celebració de convenis amb altres comunitats autònomes (art. 145.2 CE)"},{"ref":"apartat 2.1, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"cal considerar plenament legítima la inclusió a l’EAC d’un catàleg de drets i deures dels ciutadans, atès que responen al significat de norma institucional bàsica i es vinculen amb les competències de la Generalitat."}]}]},{"n":"6","title":"Estructura: preàmbul i principis generals de l''articulat","blocks":[{"text":"L''EAC de 2006 s''ordena en preàmbul, títols, capítols i, en alguns casos, seccions. Té una part dogmàtica (principis generals, drets i deures, principis rectors) i una part orgànica (institucions, competències, relacions institucionals, finançament i reforma).","refs":[{"ref":"apartat 2.2, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"A banda del preàmbul, l’articulat s’ordena en títols, capítols i –només pel que fa a alguns capítols– seccions."},{"ref":"apartat 2.2, p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"es pot distingir una part dogmàtica (principis generals, drets i deures dels ciutadans i principis rectors) i una part orgànica (institucions, competències, relacions institucionals i finançament, a més del procediment de reforma)."}]},{"text":"El preàmbul recull les motivacions de l''Estatut: no té valor normatiu, però serveix per interpretar-lo. Invoca el passat històric i el dret inalienable a l''autogovern, i diu que el Parlament ha definit Catalunya com a nació de manera àmpliament majoritària i que la CE reconeix la realitat nacional de Catalunya com a nacionalitat.","refs":[{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"Recull el conjunt de motivacions que fonamenten la regulació estatutària. No té valor normatiu, però és un element important per a la interpretació del text."},{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"“El Parlament de Catalunya, recollint el sentiment i la voluntat de la ciutadania de Catalunya, ha definit Catalunya com a nació d’una manera àmpliament majoritària. La Constitució espanyola, en l’article segon, reconeix la realitat nacional de Catalunya com a nacionalitat”."}]},{"text":"L''articulat defineix Catalunya com a nacionalitat constituïda en comunitat autònoma i invoca els drets històrics del poble català (articles 1 i 5). La Generalitat és el sistema institucional de l''autogovern: Parlament, Presidència i Govern; els òrgans de rellevància estatutària (Síndic de Greuges i Consell de Garanties Estatutàries), i els ens locals (municipis, vegueries i comarques). Barcelona és la capital i la seu permanent del Parlament, la Presidència i el Govern (articles 2 i 10).","refs":[{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"Catalunya és definida com a nacionalitat, que exerceix el seu autogovern constituïda en comunitat autònoma, d’acord amb la Constitució i amb l’Estatut."},{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"Integren aquest sistema, a més de les institucions polítiques bàsiques (Parlament, Presidència i Govern), els òrgans de rellevància estatutària (Síndic de Greuges, Consell de Garanties Estatutàries) i els ens locals (municipis, vegueries i comarques). S’estableix la capitalitat de Barcelona, que és la seu permanent del Parlament, la Presidència i el Govern (articles 2 i 10 EAC)."}]},{"text":"El territori correspon als límits geogràfics i administratius actuals de la Generalitat. Són catalans els ciutadans espanyols amb veïnatge administratiu a Catalunya i els espanyols residents a l''estranger que l''hi han tingut darrerament i ho sol·licitin (articles 7, 9 i 14).","refs":[{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"la condició política de catalans o ciutadans de Catalunya es reconeix als ciutadans espanyols que tenen veïnatge administratiu a Catalunya, així com als espanyols residents a l’estranger que han tingut darrerament aquest veïnatge i ho sol·licitin (articles 7, 9 i 14 EAC)."}]},{"text":"El català és la llengua pròpia; català i castellà són oficials. El català és la llengua d''ús normal i preferent de les administracions i dels mitjans públics, i la normalment emprada en l''ensenyament. El deure de conèixer les dues llengües equipara jurídicament el català amb el castellà de l''article 3.1 CE (article 6). Símbols nacionals: bandera quadribarrada, Diada de l''Onze de Setembre i himne «Els segadors» (article 8). L''aranès és llengua pròpia de l''Aran i oficial a Catalunya (article 11).","refs":[{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"El català és la llengua d’ús normal i preferent de les administracions públiques i els mitjans de comunicació públics de Catalunya i la llengua normalment emprada en l’ensenyament."},{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"L’establiment del darrer deure permet l’equiparació jurídica del català respecte del que estableix l’article 3.1 CE per al castellà (article 6 EAC)."},{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"Els símbols nacionals de Catalunya són la bandera tradicional quadribarrada, la Diada de l’Onze de Setembre i l’himne “Els segadors” (article 8 EAC)."},{"ref":"apartat 2.2, p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"L’aranès, denominació que rep la llengua occitana a l’Aran, es declara llengua pròpia d’aquest territori i oficial a Catalunya, d’acord amb l’Estatut i les lleis (article 11 EAC)."}]}]},{"n":"7","title":"Estructura: títols i disposicions","blocks":[{"text":"Els set títols: I, drets, deures i principis rectors (articles 15-54); II, institucions (55-94); III, poder judicial a Catalunya (95-109); IV, competències (110-173); V, relacions institucionals (174-200); VI, finançament (201-221), i VII, reforma de l''Estatut (222 i 223).","refs":[{"ref":"apartat 2.2, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"Títol primer: “Dels drets, deures i principis rectors” (articles del 15 al 54)"},{"ref":"apartat 2.2, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"Títol segon: “De les institucions” (articles del 55 al 94)"},{"ref":"apartat 2.2, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"Títol tercer: “Del poder judicial a Catalunya” (articles del 95 al 109)"},{"ref":"apartat 2.2, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"Títol quart: “De les competències” (articles del 110 al 173)"},{"ref":"apartat 2.2, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"Títol cinquè: “De les relacions institucionals de la Generalitat” (articles del 174 al 200) […] Títol sisè: “Del finançament de la Generalitat” (articles del 201 al 221) Títol setè: “De la reforma de l’Estatut” (articles 222 i 223)"}]},{"text":"Al final hi ha quinze disposicions addicionals, dues transitòries, una derogatòria i quatre finals.","refs":[{"ref":"apartat 2.2, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"3. Disposicions: quinze disposicions addicionals, dues disposicions transitòries, una disposició derogatòria i quatre disposicions finals."}]}]},{"n":"8","title":"Els drets, els deures i els principis rectors","blocks":[{"text":"La gran novetat de 2006 és el catàleg de drets, que no afecta el règim general dels drets fonamentals del títol I de la CE. La ciutadania de Catalunya és titular dels drets i deures de l''Estatut, la Constitució, la Unió Europea, la Declaració Universal dels Drets Humans, el Conveni europeu de drets humans i els tractats subscrits per Espanya (articles 4 i 15).","refs":[{"ref":"apartat 3, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"Convé precisar que la declaració estatutària de drets no afecta el règim general dels drets fonamentals previst en el títol I de la CE i en les lleis orgàniques que els despleguen."},{"ref":"apartat 3, p. 101","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=101","quote":"la ciutadania de Catalunya és titular dels drets i deures reconeguts per l’Estatut, la Constitució, la Unió Europea, la Declaració Universal dels Drets Humans, el Conveni europeu per a la protecció dels drets humans i els altres tractats en aquesta matèria subscrits per Espanya."}]},{"text":"El reconeixement estatutari de drets no atribueix competències a la Generalitat ni modifica la distribució de competències amb l''Estat. Els drets dels capítols I, II i III són bàsicament drets subjectius, en els àmbits civil i social, polític i administratiu, i lingüístic.","refs":[{"ref":"apartat 3, p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"El reconeixement estatutari de drets i deures no atribueix directament competències a la Generalitat, ni implica cap modificació del sistema de distribució de competències amb l’Estat."},{"ref":"apartat 3, p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"Els drets reconeguts en els capítols I, II i III del títol primer de l’EAC es configuren bàsicament com a drets subjectius"}]},{"text":"Els drets vinculen tots els poders públics de Catalunya i, segons el dret, els particulars. El Parlament ha d''aprovar per llei la Carta dels drets i deures de la ciutadania i hi ha un recurs específic davant el Tribunal Superior de Justícia de Catalunya (capítol IV). Els principis rectors (capítol V) orienten les polítiques públiques i són exigibles davant la jurisdicció d''acord amb les normes que els despleguen.","refs":[{"ref":"apartat 3, p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"Es preveu que el Parlament ha d’aprovar per llei la Carta dels drets i deures de la ciutadania de Catalunya, i es reserven la regulació essencial i el desplegament directe dels drets a la llei. Finalment, es preveu una garantia jurisdiccional específica, per mitjà d’un recurs davant el Tribunal Superior de Justícia de Catalunya (capítol IV)."},{"ref":"apartat 3, p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"les garanties dels principis rectors són inicialment més reduïdes: a més d’informar la legislació positiva, la pràctica judicial i l’actuació dels poders públics, s’estableix que són exigibles davant la jurisdicció d’acord amb les normes que els despleguen."}]}]},{"n":"9","title":"Les competències: tipologia","blocks":[{"text":"El títol IV vol garantir i ampliar el nivell competencial, respectant les competències exclusives de l''Estat (article 149.1 CE). Hi ha tres tipus de competències (articles 110 a 112). Les exclusives donen a la Generalitat, de manera íntegra, la potestat legislativa, la reglamentària i la funció executiva. La clàusula «respectant el que estableixi l''Estat...» limita l''exercici, però no la titularitat.","refs":[{"ref":"apartat 4, p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"(l’article 149.1 CE fixa les competències exclusives de l’Estat)"},{"ref":"apartat 4.1, p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"a) Les competències exclusives atribueixen de manera íntegra la potestat legislativa, la potestat reglamentària i la funció executiva, de manera que correspon únicament a la Generalitat l’exercici d’aquestes potestats en els àmbits de competència exclusiva."},{"ref":"apartat 4.1, p. 103","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=103","quote":"Cal precisar que aquesta fórmula fixa un límit en l’exercici de la competència per part de la Generalitat, però no afecta la seva titularitat."}]},{"text":"Les compartides donen les tres potestats en el marc de les bases que fixi l''Estat; les bases no poden ser regles detallades ni fixar-se per reglament o acte administratiu. Les executives donen la potestat reglamentària per executar la normativa estatal i la funció executiva; la novetat és que inclouen reglaments executius materials (ad extra), no només organitzatius (ad intra).","refs":[{"ref":"apartat 4.1, p. 103","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=103","quote":"b) Les competències compartides atribueixen a la Generalitat la potestat legislativa, la potestat reglamentària i la funció executiva, en el marc de les bases que fixi l’Estat. Amb això s’indica que, en l’aspecte material, les bases no poden ser regles concretes o detallades i, en l’aspecte formal, no poden fixar-se per mitjà de reglaments o actes administratius."},{"ref":"apartat 4.1, p. 103","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=103","quote":"la principal novetat és el reconeixement a la Generalitat de la potestat de dictar reglaments executius de caràcter material (ad extra), mentre que abans es limitava als reglaments organitzatius (ad intra)."}]}]},{"n":"10","title":"Principis i criteris competencials i les matèries","blocks":[{"text":"En foment (subvencions), l''Estat pot destinar recursos a qualsevol àmbit, però sense alterar la distribució de competències. La Generalitat participa en competències estatals amb informes previs preceptius (energia, infraestructures del transport) o amb acord previ (inversions estatals en béns i equipaments culturals).","refs":[{"ref":"apartat 4.2, p. 103","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=103","quote":"aquest té la possibilitat de destinar recursos propis a qualsevol àmbit o activitat, però sense alterar el sistema de distribució de competències que hi regeix."},{"ref":"apartat 4.2, p. 103","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=103","quote":"en què es preveu l’emissió preceptiva d’informes previs (per exemple, en matèria d’energia o infraestructures del transport) o bé l’acord previ dels dos ens (així, en matèria d’inversions de l’Estat a Catalunya en béns i equipaments culturals)."}]},{"text":"El dret de la Unió Europea no altera la distribució de competències. Si l''objecte d''una competència supera Catalunya, la Generalitat actua sobre la part del seu territori i, si no es pot fraccionar, hi ha col·laboració entre comunitats i, subsidiàriament, coordinació per l''Estat.","refs":[{"ref":"apartat 4.2, p. 103","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=103","quote":"es precisa que la presència de la normativa de la Unió Europea no altera la distribució de competències"},{"ref":"apartat 4.2, p. 104","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=104","quote":"quan l’objecte no es pot fraccionar, la previsió d’instruments de col·laboració entre les comunitats autònomes afectades i, subsidiàriament, la coordinació per l’Estat d’aquestes comunitats."}]},{"text":"Les matèries s''enumeren per ordre alfabètic als articles 116 a 173, precedides de la clàusula «en tot cas», que indica que la llista no és tancada. Són exclusives, per exemple, l''agricultura, la indústria, l''ordenació administrativa del comerç i els transports terrestres íntegrament per Catalunya. No es defineix el tipus de competència en la promoció de l''activitat econòmica o l''ordenació farmacèutica.","refs":[{"ref":"apartat 4.3, p. 104","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=104","quote":"A més, en cada article, la llista de submatèries és precedida de la clàusula “en tot cas”, indicativa que l’enumeració no és tancada o exhaustiva"},{"ref":"apartat 4.3, p. 104","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=104","quote":"A mode d’exemple, es pot esmentar el règim d’exclusivitat que preval en matèries com ara l’agricultura, la indústria, l’ordenació administrativa del comerç o els transports terrestres que transcorrin íntegrament per Catalunya"},{"ref":"apartat 4.3, p. 104","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=104","quote":"(per exemple, en la promoció de l’activitat econòmica, l’ordenació farmacèutica o algunes submatèries d’immigració)"}]}]},{"n":"11","title":"La competència en seguretat pública (article 164 EAC)","blocks":[{"text":"L''article 164 EAC atribueix a la Generalitat, d''acord amb la legislació estatal: la planificació i regulació del sistema de seguretat pública i l''ordenació de les policies locals; la creació i organització dels Mossos d''Esquadra, i el control i la vigilància del trànsit. A més, en el marc de la legislació estatal: les funcions governatives sobre reunió i manifestació, i el compliment de les normes de conservació de la natura, el medi ambient i els recursos hidrològics.","refs":[{"ref":"apartat 5, p. 104","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=104","quote":"a) La planificació i la regulació del sistema de seguretat pública de Catalunya i l’ordenació de les policies locals. b) La creació i l’organització de la Policia de la Generalitat - Mossos d’Esquadra. c) El control i la vigilància del trànsit."},{"ref":"apartat 5, p. 104","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=104","quote":"a) Les funcions governatives sobre l’exercici dels drets de reunió i manifestació. b) El compliment de les disposicions per a la conservació de la natura, del medi ambient i dels recursos hidrològics."}]},{"text":"La Generalitat té el comandament suprem dels Mossos i coordina les policies locals. La Junta de Seguretat és paritària Generalitat-Estat i la presideix el president o presidenta de la Generalitat. Els Mossos actuen a tot Catalunya en seguretat pública i ordre públic, policia administrativa, i policia judicial i investigació criminal (crim organitzat i terrorisme inclosos).","refs":[{"ref":"apartat 5, p. 104","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=104","quote":"La Generalitat té el comandament suprem de la Policia de la Generalitat - Mossos d’Esquadra i la coordinació de l’actuació de les policies locals."},{"ref":"apartat 5, p. 105","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=105","quote":"La Junta de Seguretat és un òrgan de composició paritària entre la Generalitat i l’Estat i és presidida pel/per la president/a de la Generalitat."},{"ref":"apartat 5, p. 105","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=105","quote":"a) La seguretat pública i l’ordre públic. b) La policia administrativa, que inclou la que deriva de la normativa estatal. c) La policia judicial i la investigació criminal, que inclou les diverses formes de crim organitzat i terrorisme, en els termes que estableixin les lleis."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Estatut de 1979: Llei orgànica 4/1979, de 18 de desembre, per la via de l''article 151.2 CE.","refs":[{"ref":"p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"Llei orgànica 4/1979, de 18 de desembre"}]},{"text":"Reforma: Ple del Parlament, 30 de setembre de 2005 (120 a favor, 15 en contra); Senat, 10 de maig de 2006 sense canvis; referèndum, 18 de juny de 2006.","refs":[{"ref":"p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"fou aprovat pel Ple del Parlament el 30 de setembre de 2005 (amb 120 vots a favor i 15 en contra)"}]},{"text":"EAC vigent: Llei orgànica 6/2006, de 19 de juliol, en vigor el 9 d''agost de 2006; retallat per la STC 31/2010, de 28 de juny.","refs":[{"ref":"p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"aprovada per la Llei orgànica 6/2006, de 19 de juliol, va entrar en vigor el dia 9 d’agost de 2006"}]},{"text":"Dictamen núm. 269 del Consell Consultiu (5 de setembre de 2005) sobre la constitucionalitat de la proposta.","refs":[{"ref":"p. 97","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=97","quote":"Dictamen núm. 269 del Consell Consultiu (5 de setembre de 2005)"}]},{"text":"Norma institucional bàsica (art. 147.1 CE) i llei orgànica estatal (majoria absoluta del Congrés): doble naturalesa i caràcter paccionat.","refs":[{"ref":"p. 98","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=98","quote":"és la llei primera i fonamental de l’ordenament jurídic català i, de l’altra, és una llei orgànica estatal"}]},{"text":"Contingut obligatori dels estatuts: article 147.2 CE (denominació, territori, institucions i competències).","refs":[{"ref":"p. 99","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=99","quote":"L’article 147.2 CE estableix un contingut mínim o obligatori de tots els estatuts."}]},{"text":"El preàmbul no té valor normatiu, però serveix per interpretar.","refs":[{"ref":"p. 100","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=100","quote":"No té valor normatiu, però és un element important per a la interpretació del text."}]},{"text":"Competències: títol IV (articles 110-173); exclusives, compartides (bases de l''Estat) i executives.","refs":[{"ref":"p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"Les competències de la Generalitat són de tres tipus"}]},{"text":"Garantia jurisdiccional dels drets estatutaris: recurs davant el Tribunal Superior de Justícia de Catalunya.","refs":[{"ref":"p. 102","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=102","quote":"per mitjà d’un recurs davant el Tribunal Superior de Justícia de Catalunya (capítol IV)"}]},{"text":"Article 164 EAC: trànsit, Mossos i policies locals; Junta de Seguretat paritària, presidida pel president de la Generalitat.","refs":[{"ref":"p. 105","law":"Guia d''estudi, tema B.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=105","quote":"La Junta de Seguretat és un òrgan de composició paritària entre la Generalitat i l’Estat"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=94'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=94', 94, 106, 106, null
