insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Generalitat de Catalunya"},{"n":"2","title":"El Parlament de Catalunya"},{"n":"3","title":"La Presidència de la Generalitat de Catalunya"},{"n":"4","title":"El Govern i l’Administració de la Generalitat de Catalunya"},{"n":"5","title":"Altres institucions estatutàries"},{"n":"5.1","title":"El Consell de Garanties Estatutàries"},{"n":"5.2","title":"El Síndic de Greuges"},{"n":"5.3","title":"La Sindicatura de Comptes"},{"n":"5.4","title":"El Consell de l’Audiovisual de Catalunya"}]'::jsonb, '["La Generalitat és la institució en què s’organitza políticament l’autogovern de Catalunya, que comprèn bàsicament el Parlament, la Presidència de la Generalitat i el Govern.","El Parlament de Catalunya és l’assemblea representativa i legislativa de Catalunya i, com a tal, aprova els pressupostos i impulsa i controla l’acció política del Govern.","Per assegurar la independència i la llibertat del Parlament davant la resta de poders públics, els diputats gaudeixen de tres prerrogatives (garanties per al bon exercici de la seva funció): la inviolabilitat, la immunitat i el fur; i no estan sotmesos a mandat imperatiu.","L’EAC assigna al Parlament quatre grans funcions: la funció representativa, la legislativa, la funció de creació i control del Govern, i la funció de participació en l’activitat dels òrgans centrals de l’Estat.","El poder executiu de la Generalitat correspon a dues institucions bàsiques estretament relacionades, que són la Presidència de la Generalitat i el Govern, que és l’òrgan que dirigeix l’acció política i l’Administració de la Generalitat i és titular de la funció executiva i de la potestat reglamentària.","El/la president/a de la Generalitat ha de ser elegit pel Parlament de Catalunya entre els seus membres, per majoria absoluta en primera votació, o per majoria simple al cap de 48 hores.","La Presidència de la Generalitat té atribuïda una triple vessant: és el cap del Govern, el president de la Comunitat Autònoma de Catalunya i el representant ordinari de l’Estat a Catalunya.","Anomenem institucions de rellevància estatutària les que preveu l’EAC. Són institucions catalanes de rellevància estatutària el Consell de Garanties Estatutàries, el Síndic de Greuges, la Sindicatura de Comptes i el Consell de l’Audiovisual de Catalunya."]'::jsonb, '["Assemblea representativa","Autonomia reglamentària","Compareixença","Consellers","Delicte flagrant","Demarcació electoral","Dictamen","Diputat","Drets fonamentals","Enjudiciar","Ens públic","Examen d’incompatibilitats","Història secular","Inculpació","Majoria parlamentària","Majoria simple","Moció de censura","Negligència","Òrgan de fiscalització","Òrgan rector col·legiat","Òrgan unipersonal","Organisme consultiu","Ple","Portaveu","Potestat reglamentària","Preceptiu","Prerrogatives","Processament","Qüestió de confiança","Recurs d’inconstitucionalitat","Règim parlamentari","Responsabilitat penal","Sistema institucional","Sistema parlamentari","Sobirania popular","Sufragi universal","Vinculant"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La Generalitat de Catalunya: el sistema institucional","blocks":[{"text":"La Generalitat és el sistema institucional en què s''organitza políticament l''autogovern de Catalunya. El nom evoca un òrgan medieval politicoadministratiu i financer, la Diputació del General, que representava els interessos de les Corts Catalanes (precedent remot del Parlament) davant el rei quan no estaven reunides. Avui, com durant la Segona República, la Generalitat comprèn bàsicament el Parlament, la Presidència i el Govern. Només inclou les institucions autonòmiques d''àmbit català: en queden fora els òrgans que depenen de l''Estat central i els que deriven de l''autonomia local.","refs":[{"ref":"apartat 1, p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"el nom de Generalitat evoca un òrgan medieval de caràcter politicoadministratiu i financer, denominat també Diputació del General, que representava els interessos de les Corts Catalanes (precedent remot del Parlament)"},{"ref":"apartat 1, p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"Actualment, la Generalitat, com va succeir també durant la Segona República espanyola, és el complex institucional de Catalunya, que comprèn bàsicament el Parlament, la Presidència de la Generalitat i el Govern."},{"ref":"apartat 1, p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"resten fora d’aquesta denominació aquelles institucions i òrgans públics presents a Catalunya que depenen de l’Estat central, o bé les altres que deriven de l’autonomia local reconeguda per la CE o per l’EAC."}]},{"text":"D''acord amb l''article 152.1 CE, el president i el Govern són responsables políticament davant el Parlament: és el patró clàssic del règim parlamentari, basat en un nexe permanent de confiança entre Parlament i Govern. Aquest vincle s''expressa en la investidura del president i es verifica després amb mecanismes de control: la moció de censura (iniciativa del Parlament) i la qüestió de confiança (iniciativa del Govern). Com a contrapès, el Govern pot dissoldre l''assemblea i convocar eleccions, una apel·lació directa als electors.","refs":[{"ref":"apartat 1, p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"L’EAC, d’acord amb el que preveia la CE (article 152.1), estableix que el president o presidenta de la Generalitat i el Govern són responsables políticament davant el Parlament"},{"ref":"apartat 1, p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"(la moció de censura, a iniciativa del Parlament, i la qüestió de confiança, a iniciativa del Govern)"}]}]},{"n":"2","title":"Relacions entre el Parlament i el Govern","blocks":[{"text":"Aquestes relacions es regulen al capítol IV del títol II de l''EAC i a la Llei 13/2008, del 5 de novembre, de la presidència de la Generalitat i del Govern. El sistema afavoreix l''estabilitat del Govern: la moció de censura és constructiva i només s''aprova si la vota la majoria absoluta dels diputats, mentre que la qüestió de confiança s''entén atorgada si el president obté la majoria simple dels vots emesos. No s''exclouen els governs minoritaris, i el president pot dissoldre anticipadament el Parlament.","refs":[{"ref":"apartat 1, p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"Les relacions entre el Parlament i el Govern es regulen a partir del que estableixen el capítol IV del títol II de l’EAC i la Llei 13/2008, del 5 de novembre, de la presidència de la Generalitat i del Govern."},{"ref":"apartat 1, p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"(caràcter constructiu de la moció de censura, que només es considera aprovada si la voten afirmativament la majoria absoluta dels diputats, i de la qüestió de confiança que s’entén atorgada si el president o presidenta de la Generalitat obté la majoria simple dels vots emesos)"}]}]},{"n":"3","title":"El Parlament: composició, autonomia i seu","blocks":[{"text":"El Parlament és l''assemblea representativa i legislativa de Catalunya: aprova els pressupostos i impulsa i controla l''acció política del Govern. És unicameral i té entre 100 i 150 diputats, elegits per quatre anys per sufragi universal, lliure, igual, directe i secret. Actualment en té 135: 85 per Barcelona, 18 per Tarragona, 17 per Girona i 15 per Lleida; la xifra es pot modificar per la Llei electoral de Catalunya.","refs":[{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"El Parlament de Catalunya és l’assemblea representativa i legislativa de Catalunya i, com a tal, aprova els pressupostos i impulsa i controla l’acció política del Govern."},{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"la componen un mínim de cent diputats i un màxim de cent cinquanta, elegits per a un termini de quatre anys per mitjà de sufragi universal, lliure, igual, directe i secret"},{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"En l’actualitat la cambra parlamentària està integrada per 135 diputats dels quals 18 són elegits per la circumscripció de Tarragona, 17 per la de Girona, 15 per la de Lleida i 85 per la de Barcelona."}]},{"text":"L''article 58 EAC reconeix l''autonomia parlamentària: organitzativa, financera, administrativa i disciplinària. El Parlament dicta el seu reglament, fixa el seu pressupost i actua autònomament en personal i contractació. La seu és a Barcelona, al Parc de la Ciutadella, però pot fer sessions en altres indrets de Catalunya. El Reglament del Parlament es va aprovar el 22 de desembre de 2005.","refs":[{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"L’article 58 de l’EAC reconeix el principi d’autonomia parlamentària, que inclou l’autonomia organitzativa, financera, administrativa i disciplinària."},{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"El Parlament té la seva seu a Barcelona (al Parc de la Ciutadella), però pot fer sessions a altres indrets de Catalunya. El Reglament del Parlament de Catalunya va ser aprovat el 22 de desembre de 2005."}]}]},{"n":"4","title":"La legislatura i la condició de diputat","blocks":[{"text":"La legislatura s''acaba en complir-se quatre anys de les eleccions. L''article 66 EAC preveu dos finiments anticipats: la manca d''investidura i la dissolució anticipada que decideix discrecionalment el president (article 10.c de la Llei 13/2008). Si passen dos mesos des de la primera votació d''investidura sense que cap candidat obtingui la confiança, el Parlament queda dissolt automàticament i es convoquen eleccions.","refs":[{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"si transcorren dos mesos –a comptar des de la primera votació– i cap candidat no ha obtingut la confiança del Parlament, aquest serà dissolt automàticament i es convocaran noves eleccions."},{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"El segon supòsit és la dissolució anticipada del Parlament decidida discrecionalment pel president de la Generalitat, en els termes que estableix l’article 10.c de la Llei 13/2008."}]},{"text":"Per ser diputat cal ser major de divuit anys, tenir la condició política de català (article 7 EAC) i complir la llei electoral i el reglament: prometre o jurar acatar la CE i l''EAC i declarar professió i càrrecs públics per a l''examen d''incompatibilitats. La llei electoral ha d''establir criteris de paritat entre homes i dones a les llistes.","refs":[{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"Per ser elegit diputat del Parlament cal ser ciutadà major de divuit anys, gaudir de la condició política de català d’acord amb l’article 7 de l’EAC"},{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"la llei electoral de Catalunya ha d’establir criteris de paritat entre homes i dones per a l’elaboració de les llistes electorals."}]}]},{"n":"5","title":"Les prerrogatives dels diputats","blocks":[{"text":"Per garantir la independència del Parlament, els diputats no estan sotmesos a mandat imperatiu i tenen tres prerrogatives: inviolabilitat, immunitat i fur. La inviolabilitat protegeix la lliure formació de la voluntat de la cambra: no se''ls pot exigir responsabilitat per les opinions, manifestacions o vots emesos en actes parlamentaris (o en actes exteriors que en siguin reproducció literal).","refs":[{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"els diputats no estan sotmesos a mandat imperatiu i gaudeixen de tres prerrogatives (garanties per al bon exercici de la seva funció): la inviolabilitat, la immunitat i el fur."},{"ref":"apartat 2, p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"La inviolabilitat té com a objectiu garantir la lliure formació de la voluntat del Parlament"}]},{"text":"La immunitat els protegeix de restriccions de llibertat per motius polítics: durant el mandat no poden ser detinguts pels actes delictius comesos a Catalunya, excepte en cas de delicte flagrant. Pel fur especial, la inculpació, presó, processament i judici per delictes comesos a Catalunya corresponen al Tribunal Superior de Justícia de Catalunya; fora de Catalunya, a la Sala Penal del Tribunal Suprem.","refs":[{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"durant llur mandat, els diputats no poden ser detinguts pels actes delictius comesos en el territori de Catalunya, excepte en el cas de delicte flagrant."},{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"és competent per determinar-ne la inculpació, la presó, el processament i el judici el Tribunal Superior de Justícia de Catalunya. Fora del territori de Catalunya, la responsabilitat penal és exigible en els mateixos termes davant la Sala Penal del Tribunal Suprem."}]}]},{"n":"6","title":"Organització i funcionament del Parlament","blocks":[{"text":"Segons l''article 59 EAC, el Parlament té un president o presidenta (òrgan unipersonal que representa la cambra) i una Mesa, l''òrgan rector col·legiat, formada pel president, dos vicepresidents i quatre secretaris. La Diputació Permanent, presidida pel president del Parlament, té vint-i-tres membres en proporció als grups i garanteix la continuïtat dels treballs entre períodes de sessions o quan el Parlament ha estat dissolt o ha acabat el mandat.","refs":[{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"una mesa (òrgan rector col·legiat del Parlament, integrat pel president, dos vicepresidents i quatre secretaris, que és el centre decisori pel que fa al govern institucional del Parlament)"},{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"El Parlament té una diputació permanent, presidida pel president o presidenta del Parlament, i formada per vint-i-tres membres en proporció a la representació de cada grup parlamentari"}]},{"text":"Tots els diputats s''han d''integrar en grups parlamentaris; cada partit o coalició en forma un, amb un mínim de cinc diputats, llevat del grup mixt. La Junta de Portaveus, amb els portaveus de cada grup, acorda amb el president l''ordre del dia. El Parlament funciona en Ple o en comissions, i té dos períodes ordinaris de sessions: del 16 d''agost al 31 de desembre i del 15 de gener al 31 de juliol.","refs":[{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"cada partit o coalició només pot formar un grup parlamentari, que ha de tenir un mínim de cinc diputats, amb l’excepció del grup mixt"},{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"la Junta de Portaveus, integrada pels portaveus designats per cada grup, que té, entre altres funcions, la d’acordar amb el president o presidenta de la cambra l’ordre del dia de les sessions"},{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"El Parlament es reuneix anualment en dos períodes ordinaris de sessions, del 16 d’agost al 31 de desembre i del 15 de gener al 31 de juliol."}]},{"text":"Les sessions extraordinàries, fora dels períodes, les convoca el president del Parlament per acord de la Diputació Permanent, a proposta de tres grups parlamentaris o de la quarta part dels diputats, o a petició de grups o membres que representin la majoria absoluta. També a petició del president de la Generalitat.","refs":[{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"són convocades pel president o presidenta del Parlament, per acord de la Diputació Permanent, a proposta de tres grups parlamentaris o de la quarta part dels diputats, o bé a petició de grups parlamentaris o de membres que en representin la majoria absoluta."}]}]},{"n":"7","title":"Les funcions del Parlament","blocks":[{"text":"L''EAC assigna al Parlament quatre grans funcions: representativa, legislativa, de creació i control del Govern, i de participació en l''activitat dels òrgans centrals de l''Estat. Per l''article 55, el Parlament representa el poble de Catalunya; d''aquesta funció deriva la legitimitat de tot el sistema democràtic representatiu. Per això pot exigir responsabilitat al president i al Govern, i les seves lleis només les pot controlar el Tribunal Constitucional, no els jutges ordinaris.","refs":[{"ref":"apartat 2, p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"L’EAC assigna al Parlament quatre grans funcions: la funció representativa, la legislativa, la funció de creació i control del Govern, i la funció de participació en l’activitat dels òrgans centrals de l’Estat."},{"ref":"apartat 2, p. 111","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=111","quote":"representa el poble de Catalunya i d’aquesta funció deriva la legitimitat de tot el sistema democràtic representatiu."},{"ref":"apartat 2, p. 111","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=111","quote":"les lleis– només puguin ser controlades pel Tribunal Constitucional i no pels òrgans jurisdiccionals que integren el poder judicial."}]},{"text":"Funció electiva: el Parlament elegeix el Síndic de Greuges, proposa dues terceres parts del Consell de Garanties Estatutàries, els set síndics de la Sindicatura de Comptes i membres d''ens com el CAC. Funció legislativa: les lleis es publiquen al DOGC, tenen efectes a Catalunya i són jeràrquicament iguals a les de les Corts. Inclou els pressupostos (iniciativa reservada al Govern) i les lleis de desplegament bàsic de l''Estatut, que requereixen majoria absoluta del Ple.","refs":[{"ref":"apartat 2, p. 111","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=111","quote":"el Parlament elegeix el Síndic de Greuges, proposa el nomenament de dues terceres parts dels membres del Consell de Garanties Estatutàries, els set síndics que integren la Sindicatura de Comptes"},{"ref":"apartat 2, p. 111","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=111","quote":"les lleis de desplegament bàsic de l’Estatut, que són aquelles que regulen directament certes matèries rellevants de l’autogovern de Catalunya i que requereixen el vot favorable de la majoria absoluta del Ple del Parlament."}]},{"text":"El Parlament elegeix el president de la Generalitat entre els seus membres (article 67.2 EAC), impulsa l''acció política i controla el Govern amb mecanismes ordinaris (debats generals, interpel·lacions, preguntes, compareixences) i extraordinaris (moció de censura i qüestió de confiança). Davant l''Estat, designa els senadors autonòmics (actualment vuit, segons la guia), pot demanar transferència o delegació de competències, presentar una proposició de llei al Congrés (amb una comissió de màxim tres diputats) i interposar recursos d''inconstitucionalitat o conflictes de competències.","refs":[{"ref":"apartat 2, p. 111","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=111","quote":"l’EAC (article 67.2) estableix que el president o presidenta de la Generalitat ha de ser elegit pel Parlament entre els seus membres."},{"ref":"apartat 2, p. 111","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=111","quote":"designar els senadors autonòmics que corresponen a Catalunya (actualment vuit)"},{"ref":"apartat 2, p. 111","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=111","quote":"nomenant una comissió de màxim tres diputats per defensar aquesta iniciativa legislativa, i interposar davant el Tribunal Constitucional un recurs d’inconstitucionalitat o un conflicte de competències."}]}]},{"n":"8","title":"La Presidència de la Generalitat","blocks":[{"text":"El poder executiu correspon a dues institucions: el president o presidenta i el Govern. El president té la més alta representació de la Generalitat i l''elegeix el Parlament entre els seus membres, per majoria absoluta en primera votació o per majoria simple al cap de 48 hores; després és nomenat pel rei i nomena el Govern. La guia diu que el desplegament legal és fonamentalment a les lleis 3/1982 i 13/1989 (tot i que, en altres punts, cita la Llei 13/2008 de la presidència i del Govern).","refs":[{"ref":"apartat 3, p. 112","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=112","quote":"La regulació estatutària és breu i el desplegament legal es troba, fonamentalment, a les lleis 3/1982 i 13/1989."},{"ref":"apartat 3, p. 112","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=112","quote":"Ha de ser elegit pel Parlament de Catalunya entre els seus membres, per majoria absoluta en primera votació, o per majoria simple al cap de 48 hores."}]},{"text":"Té una triple vessant: cap del Govern, president de la Comunitat Autònoma i representant ordinari de l''Estat a Catalunya. Com a cap del Govern estableix les directrius de l''acció de govern, nomena i separa els consellers (i pot nomenar un vicepresident), convoca i presideix les reunions del Govern i coordina el programa legislatiu. Com a representant suprem, manté les relacions amb les institucions de l''Estat, signa convenis amb altres comunitats, convoca eleccions i nomena alts càrrecs.","refs":[{"ref":"apartat 3, p. 112","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=112","quote":"El president o presidenta de la Generalitat té atribuïda una triple vessant: és el cap del Govern, el president de la Comunitat Autònoma de Catalunya i el representant ordinari de l’Estat a Catalunya."},{"ref":"apartat 3, p. 112","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=112","quote":"b) nomenar i separar els consellers, i la facultat de nomenar un vicepresident o vicepresidenta; c) convocar i presidir les reunions del Govern"},{"ref":"apartat 3, p. 112","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=112","quote":"c) convocar eleccions al Parlament de Catalunya"}]},{"text":"Com a representant ordinari de l''Estat (les comunitats autònomes també són Estat), promulga en nom del rei les lleis, els decrets llei i els decrets legislatius i n''ordena la publicació, publica els nomenaments dels càrrecs estatals a Catalunya i demana la col·laboració de les autoritats de l''Estat. El càrrec és incompatible amb qualsevol altra activitat; a diferència dels consellers, el president ha de ser diputat quan és elegit. Una llei pot limitar els mandats.","refs":[{"ref":"apartat 3, p. 112","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=112","quote":"a) promulgar, en nom del rei, les lleis, els decrets llei, i els decrets legislatius de Catalunya i ordenar-ne la publicació"},{"ref":"apartat 3, p. 113","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=113","quote":"els consellers no han de tenir necessàriament la condició de diputat i el president sí que ho ha de ser en el moment de ser elegit."}]}]},{"n":"9","title":"El Govern","blocks":[{"text":"L''article 68 EAC defineix el Govern com l''òrgan superior col·legiat que dirigeix l''acció política i l''Administració i exerceix la funció executiva i la potestat reglamentària. El formen el president, el vicepresident o conseller primer (si n''hi ha) i els consellers, i cessa quan cessa el president. Per decret, el president pot nomenar i separar un conseller primer, i n''informa el Parlament (article 69). Segons la guia, el Decret 421/2006 crea el Departament de la Vicepresidència i preveu que el conseller de la Vicepresidència substitueixi el president.","refs":[{"ref":"apartat 4, p. 113","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=113","quote":"L’article 68 de l’EAC defineix el Govern com l’òrgan superior col·legiat que dirigeix l’acció política i l’Administració de la Generalitat i exerceix la funció executiva i la potestat reglamentària"},{"ref":"apartat 4, p. 113","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=113","quote":"El Govern es compon del president o presidenta de la Generalitat, el vicepresident o vicepresidenta o conseller primer o consellera primera, si s’escau, i els consellers, i cessa quan ho fa el president o presidenta de la Generalitat."},{"ref":"apartat 4, p. 113","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=113","quote":"Actualment el Decret 421/2006, de 28 de novembre"}]},{"text":"President i consellers tenen immunitat i fur especial (article 70), com els diputats. El Govern té iniciativa legislativa, pot dictar decrets legislatius amb delegació prèvia del Parlament (article 63) i, en cas de necessitat extraordinària i urgent, decrets llei (article 64). Les seves normes entren en vigor amb la publicació al DOGC. Hi ha responsabilitat solidària davant el Parlament (article 74). El Govern és òrgan de direcció política i administrativa.","refs":[{"ref":"apartat 4, p. 113","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=113","quote":"gaudeixen de dues prerrogatives: la immunitat i el fur especial, en els mateixos termes que hem vist per als diputats del Parlament."},{"ref":"apartat 4, p. 113","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=113","quote":"en virtut de l’article 64 pot dictar, en cas de necessitat extraordinària i urgent, disposicions legislatives provisionals sota la forma de decret llei."}]}]},{"n":"10","title":"L''Administració de la Generalitat i els òrgans consultius","blocks":[{"text":"L''Administració (article 71) exerceix les funcions executives, serveix amb objectivitat els interessos generals i actua amb submissió plena a la llei i al dret. S''estructura en departaments i actua amb coordinació, transversalitat i transparència, i al territori segons la desconcentració i la descentralització. Els òrgans consultius del Govern (article 72) són la Comissió Jurídica Assessora, l''alt òrgan consultiu, i el Consell de Treball, Econòmic i Social, en matèries socioeconòmiques, laborals i ocupacionals.","refs":[{"ref":"apartat 4, p. 114","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=114","quote":"Serveix amb objectivitat els interessos generals i actua amb submissió plena a les lleis i al dret."},{"ref":"apartat 4, p. 114","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=114","quote":"la Comissió Jurídica Assessora, que és l’alt òrgan consultiu del Govern, i el Consell de Treball, Econòmic i Social, òrgan d’assessorament en matèries socioeconòmiques, laborals i ocupacionals."}]}]},{"n":"11","title":"Consell de Garanties Estatutàries i Síndic de Greuges","blocks":[{"text":"Les institucions de rellevància estatutària són el Consell de Garanties Estatutàries (article 76), el Síndic de Greuges (78), la Sindicatura de Comptes (80) i el CAC (82). Les seves lleis són de desplegament bàsic (majoria absoluta). El Consell de Garanties dictamina sobre l''adequació a l''EAC i a la CE de projectes i proposicions de llei, decrets llei i decrets legislatius, i preceptivament abans de recursos d''inconstitucionalitat. Els seus membres, juristes, els nomena el president: dues terceres parts a proposta del Parlament per tres cinquenes parts i un terç a proposta del Govern.","refs":[{"ref":"apartat 5, p. 114","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=114","quote":"són institucions catalanes de rellevància estatutària el Consell de Garanties Estatutàries (article 76), el Síndic de Greuges (article 78), la Sindicatura de Comptes (article 80) i el Consell de l’Audiovisual de Catalunya (article 82)."},{"ref":"apartat 5.1, p. 115","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=115","quote":"dues terceres parts dels quals a proposta del Parlament, per majoria de tres cinquenes parts dels diputats, i una tercera part a proposta del Govern."}]},{"text":"El Síndic de Greuges protegeix els drets fonamentals i les llibertats públiques i supervisa l''activitat de l''Administració de la Generalitat i dels organismes que en depenen, de les empreses que gestionen serveis públics i de l''Administració local. L''elegeix el Parlament per tres cinquenes parts per sis anys, sense reelecció. No pot investigar queixes pendents de resolució judicial ni anul·lar actes: fa recomanacions i suggeriments, i presenta un informe anual al Parlament.","refs":[{"ref":"apartat 5.2, p. 115","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=115","quote":"Supervisa l’activitat de l’Administració de la Generalitat, la dels organismes públics o privats vinculats o que en depenen"},{"ref":"apartat 5.2, p. 115","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=115","quote":"El mandat del síndic o síndica de greuges és de sis anys des de la data en què és elegit pel Parlament, i no pot ser reelegit."},{"ref":"apartat 5.2, p. 115","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=115","quote":"en cap cas no pot modificar o anul·lar actes o resolucions administratives."}]}]},{"n":"12","title":"Sindicatura de Comptes i Consell de l''Audiovisual de Catalunya","blocks":[{"text":"La Sindicatura de Comptes és l''òrgan de fiscalització extern dels comptes i la gestió econòmica de la Generalitat, dels ens locals i del sector públic de Catalunya (article 80.1). Depèn orgànicament del Parlament però actua amb total independència, i presenta una memòria anual. El Ple té set síndics designats pel Parlament per tres cinquenes parts, per sis anys.","refs":[{"ref":"apartat 5.3, p. 115","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=115","quote":"És l’òrgan de fiscalització extern dels comptes, de la gestió econòmica i del control d’eficiència de la Generalitat, dels ens locals i de la resta del sector públic de Catalunya"},{"ref":"apartat 5.3, p. 116","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=116","quote":"El Ple de la Sindicatura de Comptes està integrat per set síndics designats pel Parlament per majoria de tres cinquenes parts i nomenats per un període de sis anys."}]},{"text":"El CAC és l''autoritat reguladora independent de la comunicació audiovisual pública i privada. Defensa la llibertat d''expressió, el pluralisme i la neutralitat informativa, i té potestat reglamentària (instruccions generals vinculants), sancionadora i inspectora.","refs":[{"ref":"apartat 5.4, p. 116","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=116","quote":"És l’autoritat reguladora independent en l’àmbit de la comunicació audiovisual pública i privada"},{"ref":"apartat 5.4, p. 116","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=116","quote":"potestat reglamentària, per la qual pot aprovar instruccions generals que són vinculants per als prestadors de serveis de comunicació audiovisual"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Parlament: entre 100 i 150 diputats; ara 135 (Barcelona 85, Tarragona 18, Girona 17, Lleida 15).","refs":[{"ref":"p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"integrada per 135 diputats"}]},{"text":"Moció de censura: majoria absoluta; qüestió de confiança: majoria simple dels vots emesos.","refs":[{"ref":"p. 108","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=108","quote":"obté la majoria simple dels vots emesos"}]},{"text":"Investidura: majoria absoluta, o simple al cap de 48 hores; dos mesos sense president = dissolució automàtica.","refs":[{"ref":"p. 112","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=112","quote":"per majoria absoluta en primera votació, o per majoria simple al cap de 48 hores"}]},{"text":"Mesa: president, dos vicepresidents i quatre secretaris; Diputació Permanent: 23 membres; grup: mínim cinc diputats.","refs":[{"ref":"p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"formada per vint-i-tres membres"}]},{"text":"Períodes de sessions: 16 d''agost-31 de desembre i 15 de gener-31 de juliol.","refs":[{"ref":"p. 110","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=110","quote":"del 16 d’agost al 31 de desembre i del 15 de gener al 31 de juliol"}]},{"text":"Diputats: inviolabilitat, immunitat (detenció només en flagrant) i fur (TSJC; fora de Catalunya, Sala Penal del TS).","refs":[{"ref":"p. 109","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=109","quote":"la inviolabilitat, la immunitat i el fur"}]},{"text":"Síndic de Greuges: tres cinquenes parts, sis anys, no reelegible.","refs":[{"ref":"p. 115","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=115","quote":"majoria de tres cinquenes parts dels seus membres"}]},{"text":"Sindicatura de Comptes: set síndics, sis anys; CGE: 2/3 a proposta del Parlament i 1/3 del Govern.","refs":[{"ref":"p. 116","law":"Guia d''estudi, tema B.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=116","quote":"set síndics designats pel Parlament"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=107'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=107', 107, 117, 117, null
