insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"L’ordenament jurídic"},{"n":"1.1","title":"Noció i característiques de l’ordenament jurídic espanyol"},{"n":"1.2","title":"Les regles de relació entre normes i entre ordenaments"},{"n":"1.3","title":"Les fonts"},{"n":"2","title":"La Constitució espanyola"},{"n":"2.1","title":"La Constitució com a norma suprema"},{"n":"2.2","title":"Contingut i estructura de la Constitució espanyola"},{"n":"3","title":"La llei"},{"n":"3.1","title":"El concepte de llei"},{"n":"3.2","title":"El procediment legislatiu ordinari"},{"n":"3.3","title":"Tipus de llei"},{"n":"4","title":"Les normes amb rang de llei"},{"n":"4.1","title":"El decret llei"},{"n":"4.2","title":"El decret legislatiu"},{"n":"5","title":"El reglament"},{"n":"5.1","title":"Concepte i posició en l’ordenament jurídic"},{"n":"5.2","title":"Classes de reglaments"},{"n":"5.3","title":"El control dels reglaments"},{"n":"6","title":"Els tractats internacionals"},{"n":"6.1","title":"Concepte"},{"n":"6.2","title":"La recepció interna dels tractats internacionals"},{"n":"6.3","title":"La posició dels tractats en el sistema de fonts"}]'::jsonb, '["L’ordenament jurídic espanyol està encapçalat per la Constitució. La Constitució és la norma que regula la producció de les altres normes jurídiques, obre la cadena de validesa i serveix de criteri interpretatiu de la resta de les normes jurídiques.","Les característiques de l’ordenament jurídic espanyol són: unitat, coherència, plenitud, dinamisme i pluralitat.","Un ordenament jurídic és un sistema tancat que pot estar format per diverses subestructures. Les seves relacions estan regides pel principi de competència entre ordenaments.","La Constitució espanyola (CE) és la norma suprema de l’ordenament jurídic, de la qual deriva la validesa de tota la resta de normes. És la norma jeràrquicament superior de l’ordenament jurídic espanyol perquè es diu que emana del poble, mitjançant els seus representants polítics, en exercici de la seva sobirania (poder constituent).","La llei és la norma jurídica aprovada pel Parlament (Corts Generals i assemblees legislatives de les comunitats autònomes) amb aquest caràcter i denominació que, en expressió del poder legislatiu i d’acord amb el procediment establert, regula les matèries no reservades per la CE a altres fonts del dret.","La llei és la norma de rang immediatament inferior a la Constitució i, per tant, no pot ser contrària a les disposicions de la norma fonamental; però, en la mesura que està elaborada pels representants del poble, se li concedeix un rang superior al de la resta de normes aprovades per altres òrgans de l’Estat.","A més de la llei ordinària, la CE preveu l’existència de diferents tipus o especialitats de lleis, en funció: del tràmit o procediment per aprovar-les (llei orgànica, llei de pressupostos, lleis de comissió i de lectura única); de la matèria que han de regular (llei orgànica, llei de pressupostos, llei de transferència o delegació, llei d’harmonització i llei marc), o de l’òrgan parlamentari que les aprovi (llei estatal o llei autonòmica).","Són lleis orgàniques: les que afecten el desenvolupament dels drets fonamentals o les llibertats públiques, les que aprovin els estatuts d’autonomia i les que afecten altres matèries no enumerades expressament per l’article 81 però previstes al llarg de l’articulat de la CE. Per tant, la distinció entre llei ordinària i llei orgànica es basa en la matèria que regulen i en el procediment d’aprovació (i de modificació i derogació, segons l’article 81 de la CE).","La CE atribueix al Govern la capacitat de dictar normes diferents dels reglaments, a les quals concedeix el mateix rang, força i valor que les lleis: el decret llei i el decret legislatiu. En qualsevol dels dos casos, però, la CE exigeix la intervenció de les Corts Generals en algun moment del procediment.","El Govern pot dictar reglaments, que són disposicions normatives de caràcter general subordinades a la llei.","Un tractat internacional és aquell acord escrit entre un o més estats pel qual les parts signants adquireixen determinats drets i obligacions, l’incompliment dels quals dona lloc a responsabilitat internacional davant les altres parts."]'::jsonb, '["Cadena de validesa","Clàusula de prevalença","Clàusula de supletorietat","Constitucionalitat","Delegació legislativa","Derogació","Derogació tàcita","Disposició addicional","Disposició derogatòria","Disposició final","Disposició transitòria","Disposicions legislatives provisionals","Disposicions normatives provisionals","Dret intern","Esmena","Estructura jeràrquica piramidal","Immutabilitat","Iniciativa legislativa","Llacunes normatives","Llei ordinària/ Llei orgànica","Norma suprema","Poder constituent","Principi de competència","Projecte de llei","Proposició de llei","Rang jeràrquic","Ratificació","Recurs","Reserva de llei","Supremacia"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"L''ordenament jurídic: noció i característiques","blocks":[{"text":"El dret no és una simple suma de normes: les normes d''un estat s''interrelacionen i formen un sistema ordenat anomenat ordenament jurídic. L''ordenament espanyol està encapçalat per la Constitució, que regula com s''han de produir les altres normes, és el paràmetre de validesa de tot l''ordenament i serveix de criteri per interpretar la resta de normes.","refs":[{"ref":"apartat 1.1, p. 119","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=119","quote":"El dret no és una simple suma de normes jurídiques, sinó un conjunt de normes ordenades per unes regles determinades."},{"ref":"apartat 1.1, p. 119","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=119","quote":"L’ordenament jurídic espanyol està encapçalat per la Constitució, que és la norma que regula la producció de les altres normes jurídiques positives"}]},{"text":"La guia hi atribueix cinc característiques. Unitat: cada element té una posició dins l''estructura, de manera que hi pot haver canvis interns sense perdre la unitat. Coherència: l''ordenament té regles per resoldre les contradiccions entre normes. Plenitud: ha de ser complet, sempre hi ha d''haver una norma aplicable a cada supòsit de fet i regles per resoldre les llacunes. Dinamisme: les normes no són immutables i es poden modificar (reforma, derogació, modificació) o adaptar sense canviar-ne el text (interpretació i mutació). Pluralitat: hi ha diversos centres de producció de normes, tenint en compte l''Estat de les autonomies i la Unió Europea.","refs":[{"ref":"apartat 1.1, p. 119","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=119","quote":"Coherència: l’ordenament jurídic es dota d’unes regles per resoldre contradiccions normatives. Plenitud: l’ordenament jurídic ha de ser complet; sempre hi ha d’haver una norma aplicable per a cada supòsit de fet."},{"ref":"apartat 1.1, p. 119","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=119","quote":"Dinamisme: les normes jurídiques no són immutables"},{"ref":"apartat 1.1, p. 119","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=119","quote":"Pluralitat: les expressions normatives són el reflex d’una pluralitat de centres de producció jurídica"}]}]},{"n":"2","title":"Les regles de relació entre normes i entre ordenaments","blocks":[{"text":"Per saber quina norma és vàlida i aplicable quan dues entren en conflicte, s''apliquen quatre principis. Jerarquia: les normes formen una piràmide segons el seu rang, i la de rang superior preval sobre la inferior; a dalt hi ha la Constitució, i per sota la llei i el reglament. Temporalitat: la norma posterior deroga l''anterior, però només entre normes del mateix rang; la derogació pot ser expressa (la norma nova diu quines normes modifica) o tàcita (quan es desprèn una contradicció amb l''antiga).","refs":[{"ref":"apartat 1.2, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"la norma de rang superior preval en la seva aplicació sobre la de rang inferior."},{"ref":"apartat 1.2, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"Aquest és un principi que només pot ser aplicat entre normes del mateix rang, i comporta la derogació de les normes. La derogació pot ser expressa (quan la norma nova diu exactament aquelles normes que està modificant) o tàcita (quan de la nova norma es desprèn l’existència d’una contradicció amb l’antiga)."}]},{"text":"Especialitat: la norma especial i concreta s''aplica preferentment sobre la general i abstracta. Competència: una norma només és vàlida si l''ha aprovada l''òrgan competent pel procediment que fixa una norma superior.","refs":[{"ref":"apartat 1.2, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"Principi d’especialitat: s’estableix una preferència en l’aplicació d’aquella norma especial i concreta sobre la general i abstracta."},{"ref":"apartat 1.2, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"perquè una norma sigui vàlida dins l’ordenament jurídic ha d’haver estat aprovada per l’òrgan competent i d’acord amb el procediment establert en una norma de rang superior."}]},{"text":"Un ordenament és un sistema tancat que pot tenir subestructures, com els ordenaments estatal i autonòmics; les seves relacions es regeixen pel principi de competència entre ordenaments. L''article 149.3 CE preveu dues regles: la clàusula de supletorietat (si una comunitat no exerceix les seves competències normatives, s''aplica supletòriament el dret estatal per evitar llacunes) i la clàusula de prevalença (en conflicte, la norma estatal preval si la comunitat no té competència exclusiva sobre la matèria).","refs":[{"ref":"apartat 1.2, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"Un ordenament jurídic és un sistema tancat que pot estar format per diverses subestructures. Les seves relacions estan regides pel principi de competència entre ordenaments."},{"ref":"apartat 1.2, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"a) La clàusula de supletorietat del dret estatal: en el cas que una comunitat autònoma no faci ús de les seves competències normatives, s’ha d’aplicar supletòriament el dret estatal perquè no es produeixin llacunes normatives."},{"ref":"apartat 1.2, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"les normes estatals prevalen sobre les de les comunitats autònomes en cas de conflicte, si aquestes darreres no tenen atribuïda la competència exclusiva sobre aquella determinada matèria."}]}]},{"n":"3","title":"Les fonts del dret administratiu","blocks":[{"text":"El dret administratiu és la part de l''ordenament que afecta l''Administració pública. Les seves fonts són, amb matisos, les de la resta del dret, i la guia les classifica seguint el Codi civil. Fonts directes primàries: la Constitució, la llei i les normes amb rang de llei, i el reglament. Fonts directes subsidiàries: el costum i els principis generals del dret. Fonts indirectes: els tractats internacionals, la jurisprudència contenciosa administrativa del Tribunal Suprem i la doctrina científica.","refs":[{"ref":"apartat 1.3, p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"Fonts directes primàries: La Constitució La llei i les disposicions normatives amb rang de llei El reglament Fonts directes subsidiàries: El costum Els principis generals del dret"},{"ref":"apartat 1.3, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"Fonts indirectes: Els tractats internacionals La jurisprudència contenciosa administrativa del Tribunal Suprem La doctrina científica"}]},{"text":"L''ordenament s''estructura segons el principi de jerarquia normativa, recollit a l''article 9.3 del títol preliminar de la CE: cap norma no pot contradir una de categoria superior. La Constitució és al cim, garantida pel control de constitucionalitat que fa el Tribunal Constitucional sobre les normes amb rang de llei. Per sota hi ha les lleis, obra d''òrgans representatius (Corts Generals i parlaments autonòmics), i l''últim graó l''ocupen els reglaments, la forma normativa més característica del dret administratiu.","refs":[{"ref":"apartat 1.3, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"L’ordenament jurídic positiu s’estructura d’acord amb el principi de jerarquia normativa, que la Constitució recull a l’article 9.3 del títol preliminar."},{"ref":"apartat 1.3, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"El darrer graó de l’ordenament jurídic positiu l’ocupen els reglaments, la forma normativa més característica del dret administratiu."}]}]},{"n":"4","title":"La Constitució com a norma suprema","blocks":[{"text":"La CE és la norma suprema, de la qual deriva la validesa de totes les altres. És superior perquè la van elaborar els representants del poble en exercici de la seva sobirania (poder constituent). Els poders constituïts i les normes que aproven hi queden subjectes (article 9.1 CE). Només es pot reformar pels procediments que ella mateixa preveu, cosa que en garanteix la supremacia i l''estabilitat.","refs":[{"ref":"apartat 2.1, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"La Constitució espanyola (en endavant, CE) és la norma suprema de tot l’ordenament jurídic, de la qual deriva la validesa de tota la resta de normes."},{"ref":"apartat 2.1, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"perquè va ser elaborada pels representants polítics del poble, en exercici de la seva sobirania (poder constituent)."}]},{"text":"S''imposa a tots els poders públics i ciutadans i té força activa i passiva davant les altres normes. Té legalitat formal suprema (és immune a altres normes pel seu procediment especial de reforma) i material (determina les fonts del dret i totes les normes han de ser conformes amb ella, cosa garantida pel control de constitucionalitat de les lleis).","refs":[{"ref":"apartat 2.1, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"Com a norma jurídica suprema s’imposa a tots els poders públics i ciutadans, gaudeix de força activa i passiva davant de totes les altres normes i atorga unitat a l’ordenament jurídic."}]},{"text":"La CE es va referendar el 6 de desembre de 1978. Segons la guia (edició de juny de 2026), només s''ha reformat dues vegades: el 1992, per permetre el sufragi passiu dels ciutadans comunitaris residents a Espanya en les eleccions municipals, i el 2011, quan es va modificar l''article 135 per l''estabilitat pressupostària arran de la crisi econòmica. Atenció: la guia no esmenta cap altra reforma posterior; per a l''examen, val la seva versió.","refs":[{"ref":"apartat 2.1, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"la CE va ser referendada el 6 de desembre de 1978"},{"ref":"apartat 2.1, p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"Únicament en dues ocasions, l’any 1992, per permetre el sufragi passiu en les eleccions municipals als ciutadans comunitaris residents a Espanya, i l’any 2011, en què es va modificar l’article 135"}]},{"text":"La CE regula cinc grans continguts: els valors superiors (llibertat, justícia, igualtat i pluralisme polític) de l''Estat social i democràtic de dret; els drets fonamentals i les llibertats públiques; l''organització dels poders (monarquia parlamentària); l''organització territorial (Estat de les autonomies), i la reforma constitucional.","refs":[{"ref":"apartat 2.2, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"(la llibertat, la justícia, la igualtat i el pluralisme polític, com a valors de l’Estat social i democràtic de dret)"}]}]},{"n":"5","title":"L''estructura de la Constitució","blocks":[{"text":"La CE té un preàmbul solemne, que reflecteix el seu fonament democràtic i els seus objectius; una part articulada de 169 articles agrupats en 11 títols (amb capítols i seccions), i una part final. El títol preliminar conté els principis: forma d''Estat i de govern, sobirania, organització territorial, llengües oficials, bandera, partits, sindicats i Forces Armades. El títol I reconeix els drets fonamentals i les llibertats públiques i en fixa les garanties.","refs":[{"ref":"apartat 2.2, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"b) Una part articulada (169 articles): s’agrupa en 11 títols, que se subdivideixen en capítols, i aquests, en seccions."},{"ref":"apartat 2.2, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"El títol I reconeix els drets fonamentals i les llibertats públiques, i estableix els mecanismes per a la seva garantia."}]},{"text":"La part orgànica va dels títols II al IX, excepte el VII, que es dedica a economia i finances: Corona (II), Corts Generals (III), Govern i Administració (IV), relacions Govern-Corts (V), poder judicial (VI), organització territorial (VIII) i Tribunal Constitucional (IX). El títol X regula la reforma constitucional. La part final té quatre disposicions addicionals, nou transitòries, una derogatòria i una final, que fixa l''entrada en vigor el mateix dia de la publicació oficial.","refs":[{"ref":"apartat 2.2, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"Els títols II al IX (excepte el VII, dedicat a economia i finances) despleguen l’anomenada part orgànica de la CE"},{"ref":"apartat 2.2, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"El darrer títol preveu els diferents procediments de reforma constitucional."},{"ref":"apartat 2.2, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"c) La part final: conté quatre disposicions addicionals; nou disposicions transitòries"},{"ref":"apartat 2.2, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"una disposició derogatòria, i una disposició final, que estableix l’entrada en vigor de la CE el mateix dia de la seva publicació oficial."}]}]},{"n":"6","title":"La llei: concepte, reserva de llei, rang i valor","blocks":[{"text":"La llei és la norma que elaboren amb aquest nom els òrgans amb potestat legislativa (Corts Generals i parlaments autonòmics) pel procediment establert, i regula les matèries no reservades a altres fonts. Cap matèria queda fora de la llei; en canvi, la CE reserva certes matèries a la llei (reserva de llei) i impedeix que el Govern les reguli directament. El supòsit més clar és l''article 53.1, sobre els drets fonamentals.","refs":[{"ref":"apartat 3.1, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"La llei és la disposició que elaboren amb aquest nom els òrgans dotats de potestat legislativa (Corts Generals i assemblees legislatives de les comunitats autònomes) d’acord amb el procediment establert, i que regula les matèries no reservades per la CE a altres fonts del dret."},{"ref":"apartat 3.1, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"L’article 53.1 és el supòsit més clar de reserva de llei que estableix la CE, en relació amb la regulació dels drets fonamentals."}]},{"text":"La llei és inferior a la CE (principi de constitucionalitat), però, com que la fan els representants del poble, té un rang superior a les normes d''altres òrgans. El rang de llei li dona força de llei: activa (pot modificar o derogar normes inferiors i normes anteriors del mateix rang) i passiva (les normes inferiors no la poden modificar ni derogar). El valor de llei vol dir que la seva validesa només es controla davant el Tribunal Constitucional, pel recurs i la qüestió d''inconstitucionalitat.","refs":[{"ref":"apartat 3.1, p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"li concedeix la força de llei, que pot ser activa (pot modificar o derogar normes de rang inferior i normes anteriors del mateix rang) i passiva (és immune a les altres normes de rang inferior, que no poden modificar-la ni derogar-la)."},{"ref":"apartat 3.1, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"validesa és controlable mitjançant processos de constitucionalitat (el recurs i la qüestió d’inconstitucionalitat) davant el Tribunal Constitucional."}]}]},{"n":"7","title":"El procediment legislatiu ordinari","blocks":[{"text":"La llei ordinària l''aproven les Corts Generals pel procediment comú, en tres fases. Iniciativa (article 87 CE): el Govern presenta projectes de llei; el Congrés, el Senat, els parlaments autonòmics i els ciutadans (iniciativa legislativa popular) presenten proposicions de llei. Elaboració: els diputats presenten i defensen esmenes en ponència, comissió i ple; el text comença al Congrés i passa al Senat, que el pot vetar o esmenar. Aprovació: la decisió final és del Congrés per majoria simple; després el text va al rei per a la sanció, la promulgació i la publicació al BOE.","refs":[{"ref":"apartat 3.2, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"el Govern, mitjançant la presentació d’un projecte de llei, i el Congrés, el Senat, els parlaments autonòmics i els ciutadans (mitjançant la iniciativa legislativa popular), tots ells a través de la presentació d’una proposició de llei."},{"ref":"apartat 3.2, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"S’inicia al Congrés i posteriorment es tramet al Senat, que té la possibilitat de vetar o esmenar el text."},{"ref":"apartat 3.2, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"L’aprovació final de la llei correspon al Congrés mitjançant la majoria simple de vots a favor."}]}]},{"n":"8","title":"Tipus de llei i la llei orgànica","blocks":[{"text":"Hi ha especialitats de llei segons el procediment (orgànica, de pressupostos, de comissió i de lectura única), la matèria (orgànica, de pressupostos, de transferència o delegació, d''harmonització i marc) o l''òrgan que l''aprova (estatal o autonòmica). Segons l''article 81 CE, són lleis orgàniques les que desenvolupen els drets fonamentals i les llibertats públiques, les que aproven els estatuts d''autonomia i les d''altres matèries previstes al llarg de la CE.","refs":[{"ref":"apartat 3.3, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"a) el tràmit o procediment per aprovar-la (llei orgànica, llei de pressupostos, lleis de comissió i de lectura única)"},{"ref":"apartat 3.3, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"a) les que afecten el desenvolupament dels drets fonamentals o les llibertats públiques; b) les que aprovin els estatuts d’autonomia"}]},{"text":"Aprovar, modificar o derogar una llei orgànica exigeix majoria absoluta del Congrés (la meitat més un dels membres) en una votació final sobre el conjunt (article 81.2 CE). Entre llei orgànica i ordinària no hi ha jerarquia: la relació es regeix pel principi de competència (procedimental).","refs":[{"ref":"apartat 3.3, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"exigeix la majoria absoluta del Congrés (la meitat més un dels seus membres) en una votació final del conjunt del projecte (article 81.2 de la CE)"},{"ref":"apartat 3.3, p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"Per tant, les relacions entre ambdues lleis es regeixen pel principi de competència i no de jerarquia."}]}]},{"n":"9","title":"Les normes amb rang de llei: decret llei i decret legislatiu","blocks":[{"text":"Les Corts tenen en exclusiva la potestat legislativa, però la CE permet al Govern dictar dues normes amb el mateix rang, força i valor que la llei: el decret llei i el decret legislatiu, sempre amb intervenció de les Corts. El decret llei (article 86.1) es dicta en casos de necessitat extraordinària i urgent i és provisional. No pot afectar les institucions bàsiques de l''Estat, els drets, deures i llibertats dels ciutadans, el règim de les comunitats autònomes ni el dret electoral general. El Govern de la Generalitat també en pot dictar.","refs":[{"ref":"apartat 4, p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"la CE atribueix al Govern la capacitat de dictar normes diferents dels reglaments, a les quals concedeix el mateix rang, força i valor que les lleis: el decret llei i el decret legislatiu."},{"ref":"apartat 4.1, p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"l’ordenament de les institucions bàsiques de l’Estat; els drets, els deures i les llibertats dels ciutadans; el règim de les comunitats autònomes, i el dret electoral general."}]},{"text":"El decret llei té una vigència limitada a 30 dies des de la promulgació; en aquest termini el Congrés l''ha de convalidar o derogar, i si en vol canviar el contingut el pot tramitar com a projecte de llei per urgència. El decret legislatiu (articles 82 i 85) neix d''una delegació expressa de les Corts per a una matèria concreta i amb termini, i no es pot delegar res reservat a llei orgànica. Per a un text articulat, la delegació es fa per llei de bases; per a un text refós, per llei ordinària.","refs":[{"ref":"apartat 4.1, p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"són disposicions normatives provisionals limitades a 30 dies"},{"ref":"apartat 4.1, p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"el Congrés dels Diputats ha d’estudiar-los i decidir si els convalida o si, per contra, els deroga."},{"ref":"apartat 4.2, p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"a) Si el Parlament encarrega al Govern l’elaboració d’un text articulat, la delegació s’ha de fer mitjançant una llei de bases."},{"ref":"apartat 4.2, p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"la delegació s’ha de fer mitjançant l’aprovació d’una llei ordinària."}]}]},{"n":"10","title":"El reglament: concepte, classes i control","blocks":[{"text":"El reglament és una disposició escrita que dicta l''Administració en virtut d''una competència pròpia. L''article 97 CE atribueix la potestat reglamentària al Govern, i els estatuts la donen als governs autonòmics. És inferior a la llei, i a dins hi ha jerarquia segons l''òrgan: segons l''article 24.2 de la Llei 50/1997, del Govern, primer els reials decrets del president o del Consell de Ministres i després les ordres ministerials.","refs":[{"ref":"apartat 5.1, p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"El reglament és una disposició escrita que dicta l’Administració pública en virtut d’una competència pròpia."},{"ref":"apartat 5.1, p. 125","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=125","quote":"disposicions normatives, aprovades per reial decret del president del Govern o del Consell de Ministres, i disposicions aprovades per ordre ministerial."}]},{"text":"Pel contingut, els reglaments són jurídics (afecten drets dels ciutadans) o organitzatius (normes internes). Per la relació amb la llei, són executius (despleguen una llei) o independents. A diferència de l''acte administratiu, que només aplica normes, el reglament innova l''ordenament amb voluntat de perdurar. Els tribunals ordinaris controlen la potestat reglamentària (article 106.1 CE): si un reglament és il·legal l''han d''inaplicar (article 6 LOPJ) i en poden declarar la nul·litat.","refs":[{"ref":"apartat 5.2, p. 125","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=125","quote":"el reglament innova l’ordenament jurídic amb voluntat de perdurabilitat, mentre que els actes administratius no modifiquen les normes vigents, sinó que simplement les apliquen."},{"ref":"apartat 5.3, p. 125","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=125","quote":"Si jutges i tribunals entenen que un reglament és il·legal en virtut del principi de jerarquia normativa, han d’inaplicar-lo (article 6 de la Llei orgànica del poder judicial)."}]}]},{"n":"11","title":"Els tractats internacionals","blocks":[{"text":"Un tractat és un acord escrit entre estats que crea drets i obligacions; incomplir-lo genera responsabilitat internacional. Es conclou en tres fases: negociació (Govern), adopció i autenticació del text amb la signatura, amb autorització prèvia del Consell de Ministres, i manifestació del consentiment, normalment per ratificació, amb el cap de l''Estat i, de vegades, les Corts (article 94 CE).","refs":[{"ref":"apartat 6.1, p. 125","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=125","quote":"Un tractat internacional és aquell acord escrit entre un o més estats pel qual les parts signants adquireixen determinats drets i obligacions"},{"ref":"apartat 6.2, p. 126","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=126","quote":"La forma més solemne de prestar-lo és mitjançant la ratificació."}]},{"text":"Un cop ratificat, el tractat s''incorpora automàticament al dret intern. Té força passiva davant la llei: només es pot derogar o modificar com diu el mateix tractat o el dret internacional (article 96.1 CE), i això li dona una posició superior a les lleis. Però la CE manté la supremacia fins i tot sobre els tractats (article 95 CE).","refs":[{"ref":"apartat 6.3, p. 126","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=126","quote":"Aquesta rigidesa els confereix una posició jeràrquicament superior a les lleis. En canvi, l’ordenament jurídic espanyol garanteix la supremacia de la CE, fins i tot per sobre dels tractats internacionals que s’hi incorporin (article 95 de la CE)."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Característiques de l''ordenament: unitat, coherència, plenitud, dinamisme i pluralitat.","refs":[{"ref":"p. 127","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=127","quote":"unitat, coherència, plenitud, dinamisme i pluralitat"}]},{"text":"Principi de jerarquia normativa: article 9.3 CE.","refs":[{"ref":"p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"que la Constitució recull a l’article 9.3 del títol preliminar"}]},{"text":"Temporalitat: només entre normes del mateix rang.","refs":[{"ref":"p. 120","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=120","quote":"només pot ser aplicat entre normes del mateix rang"}]},{"text":"CE referendada el 6 de desembre de 1978; 169 articles i 11 títols; títol VII, economia i finances.","refs":[{"ref":"p. 121","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=121","quote":"la CE va ser referendada el 6 de desembre de 1978"}]},{"text":"Reserva de llei per als drets fonamentals: article 53.1 CE.","refs":[{"ref":"p. 122","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=122","quote":"L’article 53.1 és el supòsit més clar de reserva de llei"}]},{"text":"Llei ordinària: aprovació final del Congrés per majoria simple. Llei orgànica: majoria absoluta (article 81.2).","refs":[{"ref":"p. 123","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=123","quote":"correspon al Congrés mitjançant la majoria simple de vots a favor"}]},{"text":"Decret llei: necessitat extraordinària i urgent; convalidació en 30 dies.","refs":[{"ref":"p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"En casos de necessitat extraordinària i urgent, el Govern pot dictar disposicions legislatives provisionals"}]},{"text":"Text articulat: llei de bases; text refós: llei ordinària.","refs":[{"ref":"p. 124","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=124","quote":"la delegació s’ha de fer mitjançant una llei de bases"}]},{"text":"Tractats: per sobre de les lleis, per sota de la CE.","refs":[{"ref":"p. 126","law":"Guia d''estudi, tema B.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=126","quote":"garanteix la supremacia de la CE"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=118'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=118', 118, 128, 127, null
  from public.topics t where t.slug = 'mossos-b3-ordenament-juridic'
