insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema B.4, pp. 129-141', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=129', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-b4-drets', 'B.4 Els drets humans i els drets constitucionals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('mossos-esquadra') and t.slug = 'mossos-b4-drets' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Les declaracions de drets humans"},{"n":"2","title":"Els drets fonamentals i les llibertats públiques"},{"n":"2.1","title":"Drets personals o de llibertat"},{"n":"2.2","title":"Drets de participació o polítics"},{"n":"2.3","title":"Drets econòmics i socials"},{"n":"3","title":"La titularitat dels drets constitucionals"},{"n":"3.1","title":"Nacionals"},{"n":"3.2","title":"Estrangers"},{"n":"4","title":"Els drets constitucionals relacionats amb el procés penal"},{"n":"4.1","title":"Dret a la llibertat (article 17 de la Constitució espanyola)"},{"n":"4.2","title":"Dret a la inviolabilitat del domicili (article 18.2 de la Constitució espanyola)"},{"n":"4.3","title":"Dret al secret de les comunicacions (article 18.3 de la Constitució espanyola)"},{"n":"4.4","title":"Dret a la tutela judicial efectiva (article 24.2 de la Constitució espanyola)"},{"n":"4.5","title":"Mesures de protecció integral sobre la violència sexual"},{"n":"5","title":"Les garanties normatives"},{"n":"5.1","title":"La vinculació de tots els poders públics als drets i les llibertats"},{"n":"5.2","title":"El principi de reserva de llei"},{"n":"5.3","title":"La rigidesa de la Constitució espanyola"},{"n":"6","title":"Les garanties institucionals: el Defensor del Poble"},{"n":"6.1","title":"Nomenament"},{"n":"6.2","title":"Funcions"},{"n":"7","title":"Les garanties jurisdiccionals"},{"n":"7.1","title":"El recurs d’empara ordinari"},{"n":"7.2","title":"El recurs d’empara constitucional"},{"n":"7.3","title":"El procediment de tutela dels drets que preveu el Conveni europeu de drets humans"},{"n":"8","title":"La suspensió dels drets constitucionals"},{"n":"8.1","title":"La suspensió general dels drets"},{"n":"8.2","title":"La suspensió individual dels drets"}]'::jsonb, '["La CE estableix que les normes relatives als drets fonamentals i a les llibertats s’han d’interpretar de conformitat amb la Declaració Universal dels Drets Humans i els tractats i acords internacionals sobre aquestes matèries.","Els drets constitucionals previstos a la CE poden classificar-se en: drets personals, drets de participació, drets econòmics i socials.","Els drets que han de ser respectats per garantir que els processos penals es desenvolupen d’acord amb la CE són els següents: dret a la llibertat, dret a la inviolabilitat del domicili, dret al secret de les comunicacions, dret a la tutela judicial efectiva.","Les garanties per a la protecció dels drets es classifiquen en tres grups: normatives (la vinculació de tots els poders públics als drets i les llibertats, el principi de reserva de llei i la rigidesa de la Constitució espanyola), institucionals (el Defensor del Poble) i jurisdiccionals (el recurs d’empara ordinari, el recurs d’empara constitucional i el procediment de tutela dels drets previst al Conveni europeu de drets humans).","La CE preveu que, en determinades situacions, és possible suspendre l’exercici d’alguns dels drets reconeguts. Aquesta possible suspensió ha de ser interpretada sempre de manera restrictiva atès que només es justifica en un estat democràtic per a la defensa dels drets constitucionals quan determinades accions limiten o impedeixen de fet el seu exercici, o posen en perill l’ordenament de la comunitat estatal."]'::jsonb, '["Actuar d’ofici o a instància de part","Assistència lletrada","Comparèixer","Comunitat política","Constitucionalista","Contenciós administratiu","Convicció","Dogmàtic","Dret natural","Drets constitucionals","Efectivitat","Escorcolls","Esfera privada de la ciutadania","Estat d’excepció","Estat de dret","Estat de setge","Estat social","Garanties normatives","Inalienable","Insurrecció","Internacionalització","Jurisprudència","Normatives civils","Pluralisme polític","Poder públic","Principi de preferència i sumarietat","Proves invàlides","Recurs subsidiari","Resolució desestimatòria","Resolució estimatòria","Suspensió general o individual","Titulars dels drets","Tutela ordinària dels drets","Voluntat estatal"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Les declaracions de drets humans","blocks":[{"text":"Reconèixer i garantir els drets de les persones és imprescindible perquè hi hagi Estat de dret; la CE de 1978 hi dedica el títol I. Amb el constitucionalisme s''afirma que les persones tenen drets naturals, innats, anteriors a l''Estat i inalienables. Els precedents són documents anglesos del segle XVII, com la Petition of Rights de 1628. Al segle XVIII, a les colònies britàniques d''Amèrica, destaca la Declaració de drets de Virgínia de 1776, i a França, la Declaració dels drets de l''home i del ciutadà de 1789. Eren textos preconstitucionals que només declaraven els drets i obligaven els poders públics a respectar-los.","refs":[{"ref":"apartat 1, p. 130","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=130","quote":"cal destacar com a precedents de les declaracions de drets alguns documents anglesos del segle xvii, com ara la Petition of Rights de 1628."},{"ref":"apartat 1, p. 130","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=130","quote":"es van aprovar cartes de drets, la més important de les quals és la Declaració de drets de Virgínia de 1776. Pel que fa a Europa, es va aprovar a França la Declaració dels drets de l’home i del ciutadà de 1789."}]},{"text":"Després els drets es van incorporar a les constitucions com a part dogmàtica, però fins a la Segona Guerra Mundial només tenien efectes interns. Les greus vulneracions dels estats totalitaris (feixisme, nazisme, estalinisme) van portar a internacionalitzar-los: Declaració Universal dels Drets Humans (1948), Conveni europeu de drets humans i de les llibertats fonamentals (1950), els dos pactes internacionals de 1966 (drets civils i polítics; drets econòmics, socials i culturals) i la Carta dels drets fonamentals de la Unió Europea (2000).","refs":[{"ref":"apartat 1, p. 130","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=130","quote":"Els exemples més significatius d’aquesta internacionalització són la Declaració Universal dels Drets Humans de 1948, el Conveni europeu de drets humans i de les llibertats fonamentals de 1950, el Pacte internacional de drets civils i polítics de 1966 i el Pacte internacional de drets econòmics, socials i culturals de 1966"},{"ref":"apartat 1, p. 130","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=130","quote":"la Carta dels drets fonamentals de la Unió Europea de 2000."}]},{"text":"L''article 10.2 CE obliga a interpretar els drets fonamentals d''acord amb la Declaració Universal i els tractats ratificats per Espanya. Per això el Tribunal Constitucional reconeix efectes interns a aquestes declaracions i valor a la jurisprudència dels seus òrgans, sobretot del Tribunal Europeu de Drets Humans.","refs":[{"ref":"apartat 1, p. 130","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=130","quote":"a l’article 10.2, estableix que les normes relatives als drets fonamentals i a les llibertats que la CE reconeix s’han d’interpretar de conformitat amb la Declaració Universal dels Drets Humans i els tractats i acords internacionals sobre aquestes matèries ratificats per l’Estat espanyol."}]}]},{"n":"2","title":"Els drets fonamentals i la seva classificació","blocks":[{"text":"Els drets fonamentals són la positivació dels drets humans: drets subjectius amb garanties jurídiques. El títol I de la CE en recull una llista àmplia, però els drets fonamentals en sentit estricte són els de la secció primera del capítol II, articles 15 a 29. La guia els classifica en tres grups: personals o de llibertat, de participació o polítics, i econòmics i socials.","refs":[{"ref":"apartat 2, p. 131","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=131","quote":"Els drets fonamentals i les llibertats públiques estan previstos als articles 15 a 29 de la CE."},{"ref":"apartat 2, p. 131","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=131","quote":"distingeix entre drets personals o de llibertat, drets de participació o polítics i drets econòmics i socials."}]},{"text":"Els drets personals o de llibertat creen un àmbit on l''Estat no pot intervenir; no necessiten llei per exercir-se, sinó per protegir-los, i vinculen directament les administracions. Es relacionen amb l''Estat de dret. Són la vida i la integritat física i moral (art. 15), la llibertat ideològica i religiosa (16), la llibertat i la seguretat (17), l''honor, la intimitat i la pròpia imatge, la inviolabilitat del domicili i el secret de les comunicacions (18), i la residència i la circulació (19).","refs":[{"ref":"apartat 2.1, p. 131","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=131","quote":"Són aquells drets que es caracteritzen perquè consagren un àmbit de llibertat en favor de l’individu en què l’Estat no pot intervenir."},{"ref":"apartat 2.1, p. 131","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=131","quote":"El reconeixement d’aquests drets es relaciona amb l’Estat de dret"}]},{"text":"Els drets de participació o polítics permeten participar en la formació de la voluntat estatal i es relacionen amb l''Estat democràtic: expressió, informació i càtedra (art. 20), reunió i manifestació (21), associació (22), sufragi actiu i passiu i petició (29). Els econòmics i socials exigeixen intervenció activa dels poders públics i es relacionen amb l''Estat social: educació (27), vaga i sindicació (28), propietat (33), treball (35) i negociació col·lectiva (37).","refs":[{"ref":"apartat 2.2, p. 131","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=131","quote":"El reconeixement d’aquests drets es relaciona amb l’Estat democràtic, en què es garanteix el pluralisme polític i la participació de la ciutadania en els afers públics"},{"ref":"apartat 2.3, p. 132","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=132","quote":"Entre aquests drets es troben el dret a l’educació (art. 27), el dret al treball (art. 35), el dret a la vaga i el dret de sindicació (art. 28) el dret a la negociació col·lectiva (art. 37) i el dret a la propietat (art. 33)."}]}]},{"n":"3","title":"La titularitat dels drets: nacionals i estrangers","blocks":[{"text":"La CE no diu expressament qui és titular dels drets; els criteris els ha fixat el Tribunal Constitucional. Els espanyols en són titulars, tot i que alguns drets tenen requisits (el sufragi, només per als majors d''edat). L''article 13 CE diu que els estrangers gaudeixen de les llibertats del títol I en els termes dels tractats i la llei, i que només els espanyols tenen els drets de l''article 23 (sufragi i accés a càrrecs públics), llevat del sufragi municipal per reciprocitat.","refs":[{"ref":"apartat 3, p. 132","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=132","quote":"ha estat el Tribunal Constitucional el que ha establert els criteris principals en relació amb la titularitat dels drets"},{"ref":"apartat 3.2, p. 132","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=132","quote":"L’apartat 2 preveu que només els espanyols són titulars dels drets reconeguts a l’article 23 (dret de sufragi i d’accés a les funcions i als càrrecs públics)"}]},{"text":"Durant molt temps es va seguir la STC 107/1984, que admetia la desigualtat de tracte; la STC 263/2007, de 7 de novembre, la va reformular i va posar com a límit la dignitat de la persona. Amb la Llei orgànica 4/2000, de drets i llibertats dels estrangers (reformada per les LO 8/2000 i 2/2009), hi ha tres grups. Iguals per a tothom: vida, integritat, tutela judicial efectiva, llibertat. Amb condicions legals: reunió i manifestació, associació, vaga i educació (el TC reconeix un contingut mínim de reunió fins i tot a qui no és resident legal). Només nacionals: sufragi i accés a càrrecs públics, tot i que els estrangers residents poden votar a les municipals (article 6 LO 4/2000).","refs":[{"ref":"apartat 3.2, p. 132","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=132","quote":"aquesta posició es va reformular a partir de la STC 263/2007, de 7 de novembre, que imposa com a límit a tenir en compte pel legislador el de la dignitat de la persona."},{"ref":"apartat 3.2, p. 132","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=132","quote":"Exemples: dret a la vida, a la integritat física i moral, dret a la tutela judicial efectiva, dret a la llibertat."},{"ref":"apartat 3.2, p. 132","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=132","quote":"Per exemple, els reconeix el dret de reunió i manifestació i el dret d’associació."},{"ref":"apartat 3.2, p. 133","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=133","quote":"Drets dels quals només són titulars els nacionals. Seria el cas del dret de sufragi i d’accés a funcions i càrrecs públics."}]}]},{"n":"4","title":"Drets en el procés penal: llibertat (article 17 CE)","blocks":[{"text":"El dret a la llibertat permet organitzar la pròpia vida sense ingerències, llevat que una llei ho autoritzi; ningú no en pot ser privat sense causa legal i de manera proporcional. Garanties: les causes de privació han de ser en una llei orgànica; la detenció dura el temps estrictament necessari i com a màxim 72 hores, i llavors cal alliberar la persona o posar-la a disposició judicial; el detingut té dret a ser informat dels seus drets i dels motius, a no declarar i a l''assistència lletrada. L''habeas corpus és un procediment senzill i àgil perquè el jutge decideixi si una detenció és il·legal.","refs":[{"ref":"apartat 4.1, p. 133","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=133","quote":"La detenció no pot durar més que el temps estrictament necessari per fer les indagacions per aclarir els fets i, en qualsevol cas, com a màxim 72 hores."},{"ref":"apartat 4.1, p. 133","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=133","quote":"c) Drets de la persona detinguda: a ser informada dels seus drets i de les raons de la detenció, no obligació de declarar i dret a l’assistència lletrada."},{"ref":"apartat 4.1, p. 133","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=133","quote":"És un procediment senzill i àgil que té per finalitat que el jutge es pronunciï sobre si hi ha o no una situació de detenció il·legal."}]}]},{"n":"5","title":"Inviolabilitat del domicili i secret de les comunicacions","blocks":[{"text":"El domicili és inviolable (article 18.2). Només s''hi pot entrar en tres casos: consentiment del morador (exprés o evident per la conducta); delicte flagrant, quan hi ha percepció directa del delicte i urgència de la intervenció policial (les presumpcions no basten), i autorització judicial (escorcoll, detenció de qui hi és o execució de resolucions). Les proves obtingudes vulnerant aquest dret són invàlides.","refs":[{"ref":"apartat 4.2, p. 133","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=133","quote":"b) En supòsits de delicte flagrant. Quan hi ha evidència de la comissió del delicte, entesa l’evidència com a percepció directa, i ha de ser urgent la intervenció de la policia. No són suficients les presumpcions sobre la comissió del delicte."},{"ref":"apartat 4.2, p. 133","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=133","quote":"Les proves que s’obtinguin vulnerant aquest dret són invàlides i no poden ser utilitzades en el procés."}]},{"text":"El secret de les comunicacions (article 18.3), especialment postals, telegràfiques i telefòniques, inclou la comunicació i la identitat dels interlocutors. La intercepció només es pot autoritzar per resolució judicial motivada i proporcional, necessària per investigar delictes; no n''hi ha prou amb sospites ni amb una petició policial sense justificar. Les proves il·lícites tampoc no són vàlides.","refs":[{"ref":"apartat 4.3, p. 134","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=134","quote":"El contingut del secret de les comunicacions inclou tant la mateixa comunicació com la identitat dels interlocutors."},{"ref":"apartat 4.3, p. 134","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=134","quote":"La resolució judicial ha de ser motivada i proporcional, i no són suficients per adoptar-la les simples sospites o la sol·licitud policial d’intervenció que no argumenta la seva necessitat."}]}]},{"n":"6","title":"La tutela judicial efectiva i la llibertat sexual","blocks":[{"text":"La tutela judicial efectiva (article 24.2) dona garanties per defensar drets davant els jutges. Les generals són: lliure accés als tribunals; jutge ordinari predeterminat per la llei; defensa i assistència lletrada (advocat d''ofici si no hi ha mitjans); procés contradictori i amb igualtat, sense indefensió; mitjans de prova pertinents; procés sense dilacions indegudes; resolució motivada; recurs, si la llei el preveu, i execució de la decisió.","refs":[{"ref":"apartat 4.4, p. 134","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=134","quote":"b) Dret al jutge ordinari predeterminat per la llei"},{"ref":"apartat 4.4, p. 134","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=134","quote":"h) Dret a recórrer la decisió: aquest dret no implica que en tots els processos hi hagi la possibilitat de recórrer la decisió judicial"}]},{"text":"En el procés penal s''hi afegeixen tres garanties específiques: dret a ser informat de l''acusació; dret a no declarar contra si mateix i a no confessar-se culpable (l''acusat pot callar i no col·laborar), i presumpció d''innocència (l''acusació ha de provar la culpabilitat). La guia remet a la Llei orgànica 10/2022, de 6 de setembre, de garantia de la llibertat sexual, per a les mesures de protecció integral contra la violència sexual, i indica els títols preliminar, II (prevenció i detecció) i V (actuació de les forces i cossos de seguretat), però no en desenvolupa el contingut.","refs":[{"ref":"apartat 4.4, p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"b) Dret a no declarar contra si mateix i a no confessar-se culpable: l’acusat té dret a guardar silenci i a no col·laborar en la investigació."},{"ref":"apartat 4.5, p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"La Llei orgànica 10/2022, de 6 de setembre, de garantia de la llibertat sexual recull les mesures de protecció integral sobre la violència sexual."},{"ref":"apartat 4.5, p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"– II. Prevenció i detecció – V. Actuació de les forces i cossos de seguretat"}]}]},{"n":"7","title":"Les garanties normatives","blocks":[{"text":"Les garanties dels drets són de tres tipus: normatives, institucionals i jurisdiccionals. Les normatives són tres. Primera, la vinculació: l''article 53.1 CE diu que els drets del capítol II del títol I vinculen tots els poders públics, cosa que mostra el seu valor normatiu immediat, sense necessitat de llei. Segona, la reserva de llei: l''exercici dels drets només es pot regular per llei, i per als dels articles 15 a 29, només per llei orgànica; el legislador ha de respectar-ne el contingut essencial.","refs":[{"ref":"apartat 5.1, p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"L’article 53.1 de la CE estableix que els drets i les llibertats reconeguts en el capítol segon del títol I vinculen tots els poders públics."},{"ref":"apartat 5.2, p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"En relació amb els drets reconeguts a la secció primera del capítol II (articles 15 a 29), la llei que els pot regular només pot ser una llei orgànica."},{"ref":"apartat 5.2, p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"ha de respectar-ne el contingut essencial"}]},{"text":"Tercera, la rigidesa: els drets dels articles 15 a 29 només es poden reformar per l''article 168 CE, que exigeix dos terços de cada cambra, dissolució, noves eleccions, ratificació per les noves cambres, aprovació per dos terços i referèndum. Aquesta dificultat és una garantia.","refs":[{"ref":"apartat 5.3, p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"Els drets reconeguts als articles 15 a 29 de la CE només poden ser reformats seguint el procediment previst a l’article 168 del text constitucional."}]}]},{"n":"8","title":"La garantia institucional: el Defensor del Poble","blocks":[{"text":"L''article 54 CE crea el Defensor del Poble, alt comissionat de les Corts Generals per defensar els drets del títol I, regulat per la Llei orgànica 3/1981, de 6 d''abril; a Catalunya l''equivalent és el Síndic de Greuges. L''escullen les Corts per cinc anys entre espanyols majors d''edat amb ple ús dels drets civils i polítics, per tres cinquenes parts del Congrés, ratificades pel Senat amb la mateixa majoria.","refs":[{"ref":"apartat 6, p. 136","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=136","quote":"La figura del Defensor del Poble es troba regulada a la Llei orgànica 3/1981, de 6 d’abril."},{"ref":"apartat 6.1, p. 136","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=136","quote":"El Defensor del Poble és escollit, per un període de cinc anys, per les Corts Generals"},{"ref":"apartat 6.1, p. 136","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=136","quote":"L’elecció es fa per la majoria de tres cinquenes parts al Congrés, i s’ha de ratificar per aquesta mateixa majoria al Senat."}]},{"text":"Actua d''ofici o a instància de qualsevol persona amb interès legítim, i els poders públics l''han d''auxiliar amb caràcter preferent i urgent. Supervisa l''Administració, suggereix modificar normes, pot interposar recursos d''inconstitucionalitat i d''empara, fa recomanacions i advertències, exerceix l''acció de responsabilitat, comunica possibles delictes al Ministeri Fiscal i presenta un informe anual a les Corts.","refs":[{"ref":"apartat 6.2, p. 136","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=136","quote":"c) Interposar recursos d’inconstitucionalitat i recursos d’empara davant el Tribunal Constitucional."},{"ref":"apartat 6.2, p. 136","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=136","quote":"f) Elevar un informe anual de la seva gestió a les Corts Generals."}]}]},{"n":"9","title":"Garanties jurisdiccionals: l''empara ordinària","blocks":[{"text":"Les garanties jurisdiccionals actuen un cop vulnerat el dret per reparar-lo: empara ordinària, empara constitucional i recurs al Tribunal Europeu de Drets Humans. L''article 53.2 CE permet demanar la tutela dels drets de l''article 14 i de la secció primera davant els tribunals ordinaris per un procediment preferent i sumari, però el legislador no l''ha regulat. La Llei 62/1978 va ser vigent fins al 28 d''abril de 2003, i ara hi ha procediments propis a cada ordre jurisdiccional.","refs":[{"ref":"apartat 7.1, p. 137","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=137","quote":"davant els tribunals ordinaris per un procediment basat en els principis de preferència i sumarietat."},{"ref":"apartat 7.1, p. 137","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=137","quote":"però el legislador no ha regulat encara aquest procediment."},{"ref":"apartat 7.1, p. 137","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=137","quote":"La llei actualment no està en vigor, ja que va estar vigent fins el 28 d’abril de 2003."}]},{"text":"En el contenciós administratiu (articles 114 a 122 LJCA) hi ha tramitació preferent; si l''autoritat prohibeix o vol modificar una reunió, els promotors poden recórrer en 48 hores i el jutge decideix en 4 dies. En el civil (articles 249 i 250 LEC), es protegeixen l''honor, la intimitat i la pròpia imatge i l''acció de rectificació. En el laboral (articles 177 a 184 LRJS), la llibertat sindical, amb tramitació urgent i preferent.","refs":[{"ref":"apartat 7.1, p. 137","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=137","quote":"els promotors de la reunió poden interposar un recurs contenciós administratiu en el termini de 48 hores des de la notificació de la resolució i el jutge ha de decidir en 4 dies"},{"ref":"apartat 7.1, p. 137","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=137","quote":"Garantia jurisdiccional laboral (articles 177 a 184 de la Llei reguladora de la jurisdicció social)."}]}]},{"n":"10","title":"L''empara constitucional i el Tribunal Europeu de Drets Humans","blocks":[{"text":"L''empara davant el Tribunal Constitucional protegeix els mateixos drets més l''objecció de consciència (article 30.2). El seu objecte és la tutela dels drets davant vulneracions dels poders públics (article 41.2 LOTC). És subsidiari: cal esgotar la via ordinària, excepte contra el poder legislatiu. Hi estan legitimats qui tingui interès legítim, el Defensor del Poble i el Ministeri Fiscal. Terminis: actes legislatius sense valor de llei, tres mesos; òrgans executius, vint dies; òrgans judicials, trenta dies (havent invocat el dret i intentat la reparació, fins i tot amb l''incident de nul·litat).","refs":[{"ref":"apartat 7.2, p. 137","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=137","quote":"L’objecte de l’empara constitucional és la tutela dels drets davant de qualsevol vulneració realitzada pels poders públics."},{"ref":"apartat 7.2, p. 138","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=138","quote":"Legitimats per interposar el recurs d’empara constitucional són les persones naturals o jurídiques que invoquin un interès legítim, el Defensor del Poble i el Ministeri Fiscal."},{"ref":"apartat 7.2, p. 138","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=138","quote":"El recurs ha d’interposar-se en el termini de tres mesos des que la decisió dels òrgans legislatius és ferma."},{"ref":"apartat 7.2, p. 138","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=138","quote":"L’empara s’ha d’interposar en el termini dels vint dies següents a la notificació de la resolució dictada en el procés judicial previ."},{"ref":"apartat 7.2, p. 138","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=138","quote":"L’empara s’ha d’interposar en el termini de trenta dies següents a la notificació de la resolució dictada en el procés judicial."}]},{"text":"Si s''admet, el resolen les sales del TC; es pot suspendre l''acte si l''execució faria perdre la finalitat de l''empara. La sentència estimatòria pot reconèixer el dret, anul·lar l''acte i restablir-ne l''exercici. Davant el TEDH (títol II del Conveni, articles 19 a 51) s''hi va un cop esgotada la via interna, en sis mesos; es busca primer un acord amistós confidencial, i la sentència de sala es pot recórrer excepcionalment davant la gran sala en tres mesos.","refs":[{"ref":"apartat 7.2, p. 138","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=138","quote":"Si s’admet el recurs, la competència per conèixer-lo correspon a les sales del Tribunal Constitucional."},{"ref":"apartat 7.3, p. 139","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=139","quote":"Hi ha un termini de sis mesos des de la data de la decisió judicial interna ferma."},{"ref":"apartat 7.3, p. 139","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=139","quote":"La sentència de la sala es pot recórrer en supòsits excepcionals davant la gran sala en el termini de tres mesos."}]}]},{"n":"11","title":"La suspensió dels drets constitucionals","blocks":[{"text":"La suspensió s''interpreta sempre de manera restrictiva. L''article 116 CE preveu els estats d''alarma, excepció i setge (Llei orgànica 4/1981, d''1 de juny). En l''alarma no se suspenen drets, només se''n restringeix l''exercici; l''article 55.1 permet la suspensió en l''excepció i el setge. L''estat d''excepció el declara el Govern per decret del Consell de Ministres, amb autorització prèvia del Congrés, per 30 dies prorrogables per 30 més. S''hi poden suspendre: la llibertat (detenció fins a 10 dies, comunicada al jutge en 24 hores), el domicili, les comunicacions, la circulació i residència, l''expressió (mai amb censura prèvia), la reunió i manifestació, i la vaga i el conflicte col·lectiu.","refs":[{"ref":"apartat 8.1, p. 139","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=139","quote":"Durant l’estat d’alarma no es pot suspendre l’exercici dels drets, només es produeixen determinades restriccions en el seu exercici."},{"ref":"apartat 8.1, p. 139","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=139","quote":"Aquest estat el declara el Govern, mitjançant decret acordat en Consell de Ministres, prèvia autorització del Congrés dels Diputats, per un termini màxim de 30 dies, prorrogables per un termini igual, amb els mateixos requisits."},{"ref":"apartat 8.1, p. 139","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=139","quote":"Es pot detenir una persona, si hi ha sospites fonamentades que provocarà alteracions de l’ordre públic, durant un termini màxim de 10 dies. S’ha de comunicar la detenció al jutge en el termini de 24 hores."}]},{"text":"L''estat de setge, davant una insurrecció o un acte de força contra la sobirania, la integritat territorial o l''ordenament constitucional, el declara la majoria absoluta del Congrés a proposta del Govern; a més, s''hi poden suspendre les garanties del detingut (informació i assistència lletrada). La suspensió individual (article 55.2) afecta detinguts per bandes armades o terrorisme: la detenció es pot allargar fins a cinc dies amb autorització judicial abans de les 72 hores; es pot entrar al domicili sense autorització judicial, comunicant-ho al jutge, i el jutge pot acordar l''observació de comunicacions per tres mesos prorrogables per tres més.","refs":[{"ref":"apartat 8.1, p. 140","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=140","quote":"Aquest estat el declara la majoria absoluta del Congrés dels Diputats, a proposició del Govern."},{"ref":"apartat 8.2, p. 140","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=140","quote":"el termini màxim de detenció es pot prorrogar fins a cinc dies prèvia autorització judicial atorgada abans del termini de 72 hores."},{"ref":"apartat 8.2, p. 140","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=140","quote":"el jutge pot acordar, per un termini de tres mesos, prorrogable per tres més, l’observació postal, telegràfica o telefònica"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Virgínia 1776, França 1789, DUDH 1948, Conveni europeu 1950, pactes 1966, Carta de la UE 2000.","refs":[{"ref":"p. 130","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=130","quote":"la Declaració de drets de Virgínia de 1776"}]},{"text":"Drets fonamentals en sentit estricte: articles 15 a 29 CE; es regulen per llei orgànica.","refs":[{"ref":"p. 135","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=135","quote":"la llei que els pot regular només pot ser una llei orgànica"}]},{"text":"Classificació: personals (Estat de dret), de participació (Estat democràtic) i econòmics i socials (Estat social).","refs":[{"ref":"p. 131","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=131","quote":"El reconeixement d’aquests drets es relaciona amb l’Estat social"}]},{"text":"Estrangers: la STC 263/2007 posa la dignitat com a límit.","refs":[{"ref":"p. 132","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=132","quote":"STC 263/2007, de 7 de novembre"}]},{"text":"Detenció: màxim 72 hores; terrorisme, fins a cinc dies; estat d''excepció, fins a 10 dies.","refs":[{"ref":"p. 133","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=133","quote":"com a màxim 72 hores"}]},{"text":"Defensor del Poble: cinc anys, tres cinquenes parts del Congrés i ratificació del Senat.","refs":[{"ref":"p. 136","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=136","quote":"per un període de cinc anys"}]},{"text":"Reunió prohibida: recurs en 48 hores, decisió en 4 dies.","refs":[{"ref":"p. 137","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=137","quote":"el jutge ha de decidir en 4 dies"}]},{"text":"Empara constitucional: legislatiu tres mesos, executiu vint dies, judicial trenta dies; TEDH, sis mesos.","refs":[{"ref":"p. 139","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=139","quote":"Hi ha un termini de sis mesos"}]},{"text":"Estat d''excepció: Govern amb autorització del Congrés, 30+30 dies. Estat de setge: majoria absoluta del Congrés.","refs":[{"ref":"p. 139","law":"Guia d''estudi, tema B.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=139","quote":"prorrogables per un termini igual"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=129'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=129', 129, 141, 141, null
