insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Les Corts Generals"},{"n":"1.1","title":"Funcions"},{"n":"1.2","title":"L’autonomia de les cambres"},{"n":"1.3","title":"Composició del Congrés i del Senat"},{"n":"2","title":"El Govern"},{"n":"2.1","title":"Funcions"},{"n":"2.2","title":"Composició"},{"n":"2.3","title":"Nomenament i cessament dels membres del Govern"},{"n":"3","title":"La Corona"},{"n":"3.1","title":"Les funcions del rei"},{"n":"3.2","title":"L’estatut jurídic del rei"},{"n":"4","title":"Altres institucions de l’Estat"},{"n":"4.1","title":"El Tribunal de Comptes"},{"n":"4.2","title":"El Consell d’Estat"}]'::jsonb, '["Entenem per òrgans constitucionals aquells que són essencials per a l’existència del mateix Estat, de manera que la seva desaparició o transformació implica un canvi en l’estructura de l’Estat. En aquesta categoria s’inclouen: la Corona, les Corts Generals i el Govern.","Les Corts Generals són la suprema institució representativa del poble espanyol i tenen una estructura bicameral formada pel Congrés dels Diputats i el Senat.","La CE dota les Corts Generals d’una autonomia orgànica i funcional que es concreta en: autonomia reglamentària, autonomia de govern intern, autonomia administrativa i autonomia pressupostària.","El Congrés dels Diputats representa l’Estat atenent criteris de població. El nombre total de diputats es distribueix assignant a cada circumscripció un mínim inicial de dos diputats i la resta es distribueix en proporció a la població mitjançant una fórmula electoral.","El Senat és la cambra de representació territorial. La CE estableix dos mecanismes per a l’elecció dels senadors, però la seva composició no té un nombre fix, sinó que varia en funció de la població.","La CE preveu una sèrie de garanties perquè els membres de les Corts Generals puguin dur a terme les seves funcions d’una forma lliure i independent: la inviolabilitat i la immunitat.","El Govern és la institució encarregada de la direcció de la política interior i exterior de l’Estat. És un òrgan col·legiat, que actua sota la direcció del president o presidenta del Govern i a través del Consell de Ministres.","El Govern adopta una organització basada en el principi de jerarquia, ja que l’exercici del càrrec de ministre depèn directament de la decisió del seu president o presidenta i de la relació de confiança que hi hagi entre ells.","La forma política de govern de l’Estat espanyol és la monarquia parlamentària. La seva característica més important és que la configuració de la figura del cap de l’Estat es concreta en la institució de la Corona, de la qual el rei és el titular. La titularitat de la Corona és vitalícia i la seva successió es fa atenent criteris de transmissió hereditària. La inviolabilitat i la irresponsabilitat completen les característiques de la monarquia.","Els òrgans constitucionals de l’Estat compten amb l’ajuda d’uns òrgans d’assessorament tècnic que els auxilien en les seves tasques principals. D’entre els òrgans auxiliars cal destacar el Tribunal de Comptes i el Consell d’Estat."]'::jsonb, '["Aforament","Circumscripció electoral","Consell de Ministres","Contrasignats","Estructura bicameral","Fiscalitzar","Funció consultiva","Institució representativa","Investidura","Llistes electorals tancades i bloquejades","Majoria absoluta","Majoria simple","Monarquia parlamentària","Ordenament jurídic","Òrgan col·legiat","Òrgans constitucionals","Òrgans rectors","Preceptiu","Referendats","Responsabilitat solidària","Successió","Suplicatori","Transmissió hereditària","Vitalícia"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Els òrgans constitucionals i les Corts Generals","blocks":[{"text":"El tema comença distingint els òrgans constitucionals, que són els essencials per a l''existència mateixa de l''Estat: si desapareixen o es transformen, canvia l''estructura de l''Estat. Segons la guia, n''hi ha tres: la Corona, les Corts Generals i el Govern. Cal no confondre''ls amb els òrgans auxiliars (Tribunal de Comptes i Consell d''Estat), que s''estudien al final del tema.","refs":[{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"Entenem per òrgans constitucionals aquells que són essencials per a l’existència del mateix Estat, de manera que la seva desaparició o transformació implica un canvi en l’estructura de l’Estat. En aquesta categoria s’inclouen: la Corona, les Corts Generals i el Govern."}]},{"text":"Les Corts Generals són la suprema institució representativa del poble espanyol. Tenen una estructura bicameral, és a dir, dues cambres: el Congrés dels Diputats, que representa l''Estat atenent criteris de població, i el Senat, que representa els diferents territoris de l''Estat. Aquesta distinció (població / territori) és una pregunta clàssica d''examen.","refs":[{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"Les Corts Generals són la suprema institució representativa del poble espanyol i tenen una estructura bicameral formada pel Congrés dels Diputats, que representa l’Estat atenent criteris de població, i el Senat, que representa els diferents territoris de l’Estat espanyol."}]}]},{"n":"2","title":"Funcions de les Corts Generals","blocks":[{"text":"La guia enumera cinc funcions. La primera és la potestat legislativa: com que representen el poble, la Constitució (CE) els reserva en exclusiva la capacitat de fer lleis, que obliguen tothom (òrgans estatals, governamentals, judicials i ciutadania); l''únic límit és la supremacia de la CE.","refs":[{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"a) Potestat legislativa: en la mesura que les Corts Generals representen el poble espanyol, la CE els reserva, en exclusiva, la capacitat de fer lleis."},{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"L’únic límit a la seva actuació el tenen en la supremacia de la CE."}]},{"text":"La segona és l''aprovació del pressupost: la iniciativa correspon al Govern, però l''aprovació s''ha de fer per una llei singular i anual de les Corts. La tercera és atorgar la confiança al Govern, que la necessita per poder fer la seva gestió política.","refs":[{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"b) Aprovació del pressupost: la iniciativa legislativa en matèria pressupostària correspon al Govern, però la seva aprovació s’ha de fer mitjançant una llei singular i de caràcter anual de les Corts Generals."},{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"c) Atorgar la confiança al Govern: en la mesura que les Corts Generals representen la voluntat del poble, el Govern necessita de la seva confiança per poder dur a terme la seva gestió política."}]},{"text":"Cal distingir bé les dues últimes funcions pels seus instruments. El control de l''acció de govern, un cop concedida la confiança, es fa amb preguntes, interpel·lacions i comissions d''investigació. L''impuls de l''acció del Govern, en canvi, orienta el rumb governamental amb proposicions no de llei, resolucions i mocions.","refs":[{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"d) Control de l’acció de govern: un cop concedida la confiança, les Corts Generals retenen la capacitat de control de l’acció política governamental diària, mitjançant les preguntes, les interpel·lacions i la creació de comissions d’investigació."},{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"e) Impuls de l’acció del Govern: orienten el rumb de l’acció governamental mitjançant l’adopció de proposicions no de llei, resolucions i mocions dirigides al Govern."}]}]},{"n":"3","title":"L''autonomia de les cambres","blocks":[{"text":"Perquè les Corts treballin amb absoluta independència dels altres poders, sobretot de l''executiu, la CE els dona una autonomia orgànica i funcional que es concreta en quatre manifestacions. L''autonomia reglamentària vol dir que cada cambra aprova el seu propi reglament d''organització i funcionament. L''autonomia de govern intern vol dir que els òrgans rectors (presidents del Congrés i del Senat i les meses) els elegeixen els membres de cada cambra, sense interferències externes.","refs":[{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"a) Autonomia reglamentària: ambdues cambres poden aprovar els seus respectius reglaments d’organització i funcionament intern."},{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"b) Autonomia de govern intern: els seus òrgans rectors (els presidents del Congrés i del Senat i les meses respectives) són elegits pels membres de cada cambra, sense interferències externes."}]},{"text":"L''autonomia administrativa significa que el personal de les Corts no forma part de l''Administració pública (que depèn del Govern), sinó que té un estatut propi. L''autonomia pressupostària permet a les cambres aprovar el seu pressupost, que s''integra en els pressupostos generals de l''Estat, i gaudir d''autonomia en la despesa.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"c) Autonomia administrativa: el personal al servei de les Corts Generals no forma part de l’Administració pública, que se situa sota la dependència i la direcció del Govern, sinó que té el seu propi estatut personal."},{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"d) Autonomia pressupostària: les cambres aproven autònomament el seu pressupost respectiu (que s’ha d’integrar en els pressupostos generals de l’Estat) i gaudeixen d’autonomia en la despesa."}]}]},{"n":"4","title":"Composició del Congrés dels Diputats","blocks":[{"text":"El Congrés té 350 diputats, xifra fixada a l''article 172 de la Llei orgànica 5/1985, de 19 de juny, del règim electoral general (LOREG). La circumscripció electoral és la província. Cada circumscripció rep un mínim inicial de dos diputats i la resta es reparteix en proporció a la població amb una fórmula electoral, la Llei d''Hondt. Ceuta i Melilla tenen un diputat cadascuna.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"està format per tres-cents cinquanta diputats, tal com s’estableix a l’article 172 de la Llei orgànica 5/1985, de 19 de juny, del règim electoral general."},{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"la circumscripció electoral és la província i el nombre total de diputats es distribueix assignant a cada circumscripció un mínim inicial de dos diputats. La resta de diputats es distribueix en proporció a la població mitjançant una fórmula electoral (la Llei d’Hondt). Quant a les poblacions de Ceuta i Melilla, estan representades cadascuna per un diputat."}]},{"text":"Es vota amb llistes tancades i bloquejades: l''elector no pot afegir ni treure noms ni canviar-ne l''ordre. Els escons de cada candidatura es reparteixen en proporció als vots obtinguts a la circumscripció. El mandat dura una legislatura, quatre anys, tret que hi hagi una dissolució anticipada.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"El sufragi es fa mitjançant llistes electorals tancades i bloquejades de candidats, i el nombre de representants electes que correspon a cada candidatura es distribueix en proporció al nombre total de vots aconseguits en cada circumscripció."},{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"El període de representació és per tot el temps de durada d’una legislatura, és a dir, quatre anys, excepte que amb anterioritat es produeixi una dissolució anticipada de les cambres."}]}]},{"n":"5","title":"Composició del Senat","blocks":[{"text":"El Senat és la cambra de representació territorial. A diferència del Congrés, no té un nombre fix de membres: varia segons la població, perquè la CE preveu dos mecanismes d''elecció, l''elecció directa i la designació autonòmica (articles 165 i 166 LOREG). Per elecció directa, cada circumscripció provincial elegeix quatre senadors; Gran Canària, Mallorca i Tenerife, tres; Eivissa-Formentera, Menorca, Fuerteventura, Gomera, Hierro, Lanzarote i La Palma, un; i Ceuta i Melilla, dos cadascuna.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"El Senat és la cambra de representació territorial. La CE estableix dos mecanismes per a l’elecció dels senadors, però la seva composició no té un nombre fix, sinó que varia en funció de la població."},{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"1. En cada circumscripció provincial s’elegeixen quatre senadors. 2. En cada circumscripció insular s’elegeix el nombre següent de senadors: tres a Gran Canària, Mallorca i Tenerife, un a Eivissa-Formentera, Menorca, Fuerteventura, Gomera, Hierro, Lanzarote i La Palma. 3. Les poblacions de Ceuta i Melilla elegeixen cadascuna dos senadors."}]},{"text":"A més, cada comunitat autònoma designa un senador i un altre per cada milió d''habitants. La designació la fa l''assemblea legislativa de la comunitat (a Catalunya, el Parlament) segons el seu estatut, amb representació proporcional, i el nombre es calcula amb el cens de població de dret vigent a les últimes eleccions generals al Senat.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"4. Les comunitats autònomes designen a més un Senador i un altre més per cada milió d’habitants del seu territori respectiu. La designació correspon a l’assemblea legislativa de la comunitat autònoma"},{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"el nombre concret de senadors que correspongui a cada comunitat autònoma es determina prenent com a referència el cens de població de dret vigent en el moment de celebrar-se les últimes eleccions generals al Senat."}]},{"text":"En l''elecció directa, l''elector pot votar un màxim de tres candidats a les circumscripcions provincials; dos a Gran Canària, Mallorca, Tenerife, Ceuta i Melilla; i un a la resta d''illes. Surten elegits els candidats més votats fins a cobrir els senadors de la circumscripció. Si un senador elegit directament mor, queda incapacitat o renuncia, el substitueix el seu suplent. El mandat també és de quatre anys o fins a la dissolució de la cambra.","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"a) Els electors poden donar el seu vot a un màxim de tres candidats en les circumscripcions provincials, dos a Gran Canària, Mallorca, Tenerife, Ceuta i Melilla, i un a la resta de circumscripcions insulars."},{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"En cas de mort, incapacitat o renúncia d’un senador elegit directament, la vacant es cobrirà pel seu suplent"},{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"El mandat dels senadors acaba, com en el Congrés, transcorreguts quatre anys des de la seva elecció, o el dia de la dissolució de la cambra."}]}]},{"n":"6","title":"Garanties dels parlamentaris: inviolabilitat i immunitat","blocks":[{"text":"Perquè diputats i senadors exerceixin lliurement, la CE els dona dues garanties. La inviolabilitat impedeix jutjar-los per les opinions i els vots emesos en l''exercici de les seves funcions. La immunitat fa que només puguin ser detinguts en cas de delicte flagrant i que no puguin ser inculpats ni processats sense autorització prèvia de la seva cambra, que es concedeix mitjançant el suplicatori.","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"la inviolabilitat (els parlamentaris no poden ser jutjats per les opinions i vots realitzats en l’exercici de les seves funcions) i la immunitat (els diputats i senadors només poden ser detinguts en cas de delicte flagrant i no poden ser inculpats ni processats sense l’autorització prèvia de la seva cambra respectiva, mitjançant la concessió del suplicatori)."}]}]},{"n":"7","title":"El Govern: funcions i composició","blocks":[{"text":"El Govern dirigeix la política interior i exterior de l''Estat i, per fer-ho, disposa d''una Administració civil i militar. També exerceix la funció executiva (complir i fer complir les lleis), i per això té la potestat reglamentària.","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"El Govern és la institució encarregada de la direcció de la política interior i exterior de l’Estat. Per fer-ho, està dotada d’una Administració civil i militar."},{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"el Govern exerceix la funció executiva, que consisteix a complir i fer complir les lleis, per a la qual se li encomana l’exercici de la potestat reglamentària."}]},{"text":"El formen el president o presidenta, en posició preeminent; els vicepresidents, només si el president ho considera oportú; els ministres, designats pel president i al capdavant de les àrees de l''Administració; i els altres membres que fixi la llei, tot i que la Llei 50/1997, del Govern, no n''hi ha inclòs cap més. És un òrgan col·legiat que actua sota la direcció del president i a través del Consell de Ministres.","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"els vicepresidents, en el cas que el president o presidenta ho consideri oportú, que l’auxilien en la seva tasca de direcció"},{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"la Llei 50/1997, del Govern, ha optat per no incloure cap altre càrrec dins el que s’entén estrictament per Govern"},{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"El Govern és, doncs, un òrgan col·legiat, que actua sota la direcció del president o presidenta del Govern i a través del Consell de Ministres."}]},{"text":"La responsabilitat té tres nivells: tots els membres responen de la seva gestió davant el Congrés dels Diputats; cadascun respon individualment de la seva gestió política davant el president; i de la responsabilitat criminal, davant els tribunals.","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"Tots els membres del Govern responen de la seva gestió davant el Congrés dels Diputats i, a més, cadascun respon de forma individual per la seva gestió política, davant el president o presidenta del Govern, i de la seva responsabilitat criminal, davant els tribunals de justícia."}]}]},{"n":"8","title":"Estatut, nomenament i cessament dels membres del Govern","blocks":[{"text":"Els membres del Govern tenen dedicació exclusiva: no poden exercir altres funcions representatives que el mandat parlamentari, ni cap altra funció pública aliena al càrrec, ni activitats professionals o mercantils. No tenen immunitat ni inviolabilitat, llevat que també siguin diputats o senadors, però sí aforament: la seva responsabilitat penal només la pot exigir el Tribunal Suprem.","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"se’ls exigeix una dedicació exclusiva. No gaudeixen d’immunitat ni d’inviolabilitat excepte que, a més de la condició de membre del Govern, tinguin també la de diputat o senador. En canvi, sí que gaudeixen d’aforament: la seva responsabilitat penal només pot ser exigida pel Tribunal Suprem."}]},{"text":"El nomenament té dues fases: primer, el Congrés inviste el president; després, aquest forma el Govern i designa els membres, que nomena el rei com a ministres. Com que el càrrec de ministre depèn de la decisió del president i de la confiança mútua, el Govern s''organitza segons el principi de jerarquia.","refs":[{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"El nomenament del Govern consta de dues fases: la investidura del president o presidenta del Govern pel Congrés dels Diputats; i un cop aquest ha estat investit, procedeix a la formació del Govern i a la designació dels seus membres, que seran nomenats pel rei i tindran el càrrec de ministres."},{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"el Govern adopta una organització basada en el principi de jerarquia"}]},{"text":"Els membres poden ser cessats en qualsevol moment pel rei a proposta del president. Pel principi de responsabilitat solidària, el Govern cessa en bloc en tres casos: després d''unes eleccions, per pèrdua de la confiança parlamentària i per dimissió o mort del president. En tots tres casos el Govern cessant continua en funcions fins que pren possessió el nou.","refs":[{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"els membres del Govern poden ser cessats, en qualsevol moment, pel rei a proposta del president del Govern."},{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"d’acord amb el principi de responsabilitat solidària, el Govern cessa conjuntament en tres casos concrets: després d’unes eleccions, en els casos de pèrdua de confiança parlamentària i per dimissió o mort del president del Govern. En tots aquests casos, el Govern cessant continua en funcions fins a la presa de possessió del nou govern."}]}]},{"n":"9","title":"La Corona i les funcions del rei","blocks":[{"text":"La forma política de l''Estat espanyol és la monarquia parlamentària. El cap de l''Estat és la Corona, de la qual el rei és titular; la titularitat és vitalícia i se succeeix per transmissió hereditària. Per fer-ho compatible amb el principi democràtic, la CE no deixa que el rei participi en la direcció política i el separa expressament dels poders legislatiu, judicial i, sobretot, executiu: el rei representa la unitat de l''Estat i les Corts, el poble espanyol.","refs":[{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"La forma política de govern de l’Estat espanyol és la monarquia parlamentària."},{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"La titularitat de la Corona té unes característiques especials: és vitalícia i la seva successió es fa atenent criteris de transmissió hereditària."},{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"D’aquesta manera, el rei representa la unitat de l’Estat i les Corts Generals representen el poble espanyol."}]},{"text":"Les funcions del rei són sobretot simbòliques o representatives. La guia en destaca vuit: convocar i dissoldre les Corts i convocar eleccions; proposar candidat a president del Govern; sancionar i promulgar les lleis; expedir els decrets aprovats pel Consell de Ministres; nomenar i remoure els membres del Govern a proposta del president; declarar que la justícia s''administra en el seu nom; l''alt patronatge de les reials acadèmies; i el comandament suprem de les forces armades.","refs":[{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"a) convocar i dissoldre les Corts Generals i convocar eleccions; b) proposar candidat a president o presidenta del Govern; c) sancionar i promulgar les lleis; d) expedir els decrets aprovats pel Consell de Ministres;"},{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"e) nomenar i remoure els membres del Govern a proposta del president o presidenta; f) declarar que la justícia s’administra en el seu nom; g) representar l’alt patronatge de les reials acadèmies, i h) tenir el comandament suprem de les forces armades."}]},{"text":"Aquestes funcions són actes deguts: el rei no es pot negar a fer-les. La seva intervenció és imprescindible quan la CE l''exigeix, però simbòlica, perquè el contingut de l''acte ja l''han decidit els òrgans de direcció política i el rei no el pot modificar.","refs":[{"ref":"p. 146","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=146","quote":"aquestes funcions són considerades des del punt de vista constitucional com a actes deguts, és a dir, actes que el rei no pot negar-se a fer."}]}]},{"n":"10","title":"L''estatut jurídic del rei i el referendament","blocks":[{"text":"A més del mandat vitalici i la successió hereditària, l''estatut del rei es completa amb la inviolabilitat i la irresponsabilitat. La inviolabilitat vol dir que no pot ser jutjat d''acord amb les lleis penals ni està subjecte a la coerció legítima de l''Estat. La irresponsabilitat vol dir que no respon dels seus actes, polítics o personals, que no estan sotmesos a control constitucional ni jurisdiccional. Això no exclou la responsabilitat patrimonial en dret privat, però s''ha d''adreçar contra la Casa del Rei i el seu cap, no contra la persona del rei.","refs":[{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"La inviolabilitat comporta que el rei no pot ser jutjat d’acord amb les lleis penals. El rei no està subjecte a la coerció legítima de l’Estat."},{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"La irresponsabilitat significa que el rei no respon pels actes que fa, ja siguin polítics o exclusivament personals."},{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"cal actuar contra la Casa del Rei i el seu cap, però no pas contra la persona del rei."}]},{"text":"Com que de tot acte polític se''n deriva responsabilitat i el rei no en té, els seus actes han de ser contrasignats per una altra persona per ser vàlids: és el referendament, que transmet la responsabilitat a qui contrasigna. Normalment referenden el president del Govern o els ministres competents. Excepcionalment, la proposta reial de candidat a president i la dissolució automàtica de les Corts quan no s''ha pogut completar la investidura els referenda el president o presidenta del Congrés.","refs":[{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"Aquesta figura, anomenada referendament, comporta la transmissió de la responsabilitat dels actes del rei a la persona que contrasigna. Els actes del rei són referendats pel president o presidenta del Govern o els ministres competents."},{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"Excepcionalment, la proposta reial de candidat a president o presidenta del Govern i la dissolució automàtica de les Corts Generals (en aquells casos en què no s’hagi pogut completar el procediment d’investidura del president o presidenta del Govern) han de ser referendats pel president o presidenta del Congrés dels Diputats."}]}]},{"n":"11","title":"Òrgans auxiliars: el Tribunal de Comptes i el Consell d''Estat","blocks":[{"text":"Els òrgans constitucionals tenen l''ajuda d''òrgans d''assessorament tècnic; la guia en destaca dos. El Tribunal de Comptes fiscalitza els comptes i la gestió econòmica de l''Estat i del sector públic: examina el compte general de l''Estat i, com a òrgan auxiliar del Parlament, envia un informe anual a les Corts. També té una funció jurisdiccional: determinar la responsabilitat comptable dels qui utilitzen fons i cabals públics.","refs":[{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"El Tribunal de Comptes és l’òrgan encarregat de fiscalitzar els comptes i la gestió econòmica de l’Estat i del sector públic en general. Examina el compte general de l’Estat i, com a òrgan auxiliar del Parlament, remet un informe anual a les Corts Generals."},{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"fa una funció jurisdiccional consistent a determinar la responsabilitat comptable en què incorren aquells que tenen al seu càrrec la utilització de fons i cabals públics."}]},{"text":"El Consell d''Estat és l''òrgan consultiu suprem del Govern (article 107 CE), amb autonomia orgànica i funcional. Emet dictàmens sobre qualsevol assumpte que li demanin el Govern, els seus membres o els presidents de les comunitats autònomes. El seu dictamen és preceptiu en els projectes de decrets legislatius i en els avantprojectes de llei que executin tractats internacionals, entre altres casos de la Llei orgànica 3/1980, de 22 d''abril. En la seva funció vetlla pel respecte a la CE i a l''ordenament jurídic.","refs":[{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"És l’òrgan consultiu suprem del Govern (article 107 de la CE). Gaudeix d’autonomia orgànica i funcional i emet dictàmens sobre qualsevol assumpte que li sol·licitin el Govern, els seus membres o els presidents de les comunitats autònomes."},{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"La seva actuació és preceptiva sobre els projectes de decrets legislatius i els avantprojectes de llei que hagin de dictar-se en execució de tractats internacionals"},{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"(Llei orgànica 3/1980, de 22 d’abril, del Consell d’Estat)"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Òrgans constitucionals: Corona, Corts Generals i Govern. Òrgans auxiliars: Tribunal de Comptes i Consell d''Estat.","refs":[{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"D’entre els òrgans auxiliars cal destacar el Tribunal de Comptes i el Consell d’Estat."}]},{"text":"Congrés = criteris de població; Senat = representació territorial.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"El Congrés dels Diputats representa l’Estat atenent criteris de població"}]},{"text":"Congrés: 350 diputats (art. 172 LOREG), mínim inicial de dos per província, Llei d''Hondt, un diputat per Ceuta i un per Melilla.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"assignant a cada circumscripció un mínim inicial de dos diputats"}]},{"text":"Senat: quatre senadors per província (es voten fins a tres), dos per Ceuta i dos per Melilla, i un per comunitat autònoma més un per cada milió d''habitants.","refs":[{"ref":"p. 144","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=144","quote":"En cada circumscripció provincial s’elegeixen quatre senadors."}]},{"text":"Control del Govern: preguntes, interpel·lacions i comissions d''investigació; impuls: proposicions no de llei, resolucions i mocions.","refs":[{"ref":"p. 143","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=143","quote":"mitjançant les preguntes, les interpel·lacions i la creació de comissions d’investigació."}]},{"text":"Suplicatori: autorització de la cambra per inculpar o processar un parlamentari (immunitat).","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"mitjançant la concessió del suplicatori"}]},{"text":"Membres del Govern: aforats davant el Tribunal Suprem; cessament conjunt després d''eleccions, per pèrdua de confiança o per dimissió o mort del president.","refs":[{"ref":"p. 145","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=145","quote":"la seva responsabilitat penal només pot ser exigida pel Tribunal Suprem."}]},{"text":"Les funcions del rei són actes deguts i els seus actes s''han de referendar; la proposta de candidat a president la referenda el president del Congrés.","refs":[{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"han de ser referendats pel president o presidenta del Congrés dels Diputats."}]},{"text":"El Consell d''Estat és l''òrgan consultiu suprem del Govern (art. 107 CE); el Tribunal de Comptes determina la responsabilitat comptable.","refs":[{"ref":"p. 147","law":"Guia d''estudi, tema B.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=147","quote":"És l’òrgan consultiu suprem del Govern (article 107 de la CE)."}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=142'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=142', 142, 149, 148, null
  from public.topics t where t.slug = 'mossos-b5-institucions-estat'
