insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Poder judicial i potestat jurisdiccional"},{"n":"1.1","title":"Principis configuradors del poder judicial"},{"n":"1.2","title":"Estatut dels jutges i magistrats"},{"n":"1.3","title":"Estructura del poder judicial"},{"n":"1.4","title":"El Tribunal Superior de Justícia de Catalunya"},{"n":"2","title":"El Consell General del Poder Judicial"},{"n":"2.1","title":"Composició del Consell General del Poder Judicial"},{"n":"2.2","title":"Funcions (article 560 de la Llei orgànica 4/2013, de 28 de juny, de reforma del Consell General del Poder Judicial)"},{"n":"3","title":"El Ministeri Fiscal"},{"n":"4","title":"El Tribunal Constitucional"},{"n":"4.1","title":"Composició del Tribunal Constitucional"},{"n":"4.2","title":"Competències del Tribunal Constitucional"}]'::jsonb, '["El poder judicial és un dels poders de l’Estat, independent dels altres poders (executiu i legislatiu), que té l’atribució de resoldre els conflictes en què hagi d’aplicar-se el dret i que es compon de jutges i magistrats.","Per poder exercir les seves funcions jurisdiccionals, el poder judicial té el suport de l’Administració de justícia. L’Administració de justícia no és poder judicial, sinó que comprèn el conjunt de mitjans personals i materials destinats a l’organització de les activitats relacionades amb la justícia, amb la finalitat de garantir el compliment de les funcions del poder judicial.","Els principis que configuren el poder judicial són: l’exclusivitat i la unitat jurisdiccional.","Els jutges i magistrats formen un cos únic i el seu estatut, que es regula a la Llei orgànica del poder judicial (LOPJ), es regeix pels principis següents: independència, inamovibilitat, imparcialitat, incompatibilitat i responsabilitat.","L’estructura del poder judicial es determina bàsicament per dos criteris: un de material, que obeeix a un principi d’especialització (civil, penal, contenciós administratiu i social), i un altre de territorial.","Les competències del Tribunal Superior de Justícia de Catalunya en relació amb el dret autonòmic se centren bàsicament a ser l’última instància jurisdiccional de tots els processos judicials iniciats a Catalunya, sens perjudici de la facultat reconeguda al Tribunal Suprem per unificació de doctrina. És també el màxim intèrpret del dret de Catalunya.","El Consell General del Poder Judicial (CGPJ) és l’òrgan de govern del poder judicial i té atribuïdes expressament les funcions relatives a nomenaments, ascensos, inspecció i règim disciplinari de jutges i magistrats.","El Ministeri Fiscal no forma part del poder judicial, però les seves funcions estan directament relacionades amb la funció jurisdiccional. És un òrgan únic a tot l’Estat. Exerceix les seves funcions mitjançant òrgans propis d’acord amb els principis d’unitat d’actuació, dependència jeràrquica i subjecció a la legalitat i imparcialitat.","El Fiscal General de l’Estat és nomenat pel rei a proposta del Govern, després d’haver escoltat el CGPJ, entre juristes de reconeguda competència.","El TC es crea amb l’objectiu principal d’establir un òrgan que vigili el respecte a la CE i depuri l’ordenament de les lleis i normes amb rang de llei que vulnerin la norma constitucional."]'::jsonb, '["Associació professional","Atribució","Autonomia local","Estatut jurídic","Funció jurisdiccional","Juristes","Jutge","Magistrat","Normes impugnades","Posicions doctrinals","Potestat jurisdiccional","Prevaricació","Qüestió d’inconstitucionalitat","Recurs d’inconstitucionalitat","Recursos de cassació","Recusació","Responsabilitat disciplinària"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Poder judicial i potestat jurisdiccional","blocks":[{"text":"El poder judicial es regula a la Constitució (CE) i a la Llei orgànica 6/1985, d''1 de juliol, del poder judicial (LOPJ). És un poder de l''Estat independent de l''executiu i del legislatiu, únic a tot el territori i format per jutges i magistrats.","refs":[{"ref":"p. 151","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=151","quote":"El poder judicial es regula a la CE i a la Llei orgànica 6/1985, d’1 de juliol, del poder judicial. És un poder de l’Estat, independent dels altres poders (executiu i legislatiu), únic a tot el territori nacional, i que es compon de jutges i magistrats."}]},{"text":"La seva missió és la potestat jurisdiccional: aplicar el dret per resoldre conflictes i fer complir el que s''ha decidit si no es compleix voluntàriament. Aquesta potestat correspon a tots i cadascun dels jutges i magistrats, que l''exerceixen de manera independent.","refs":[{"ref":"p. 151","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=151","quote":"El poder judicial té encomanada la potestat jurisdiccional, que consisteix a aplicar el dret per resoldre conflictes i a fer complir allò que s’ha decidit si no es compleix voluntàriament."}]},{"text":"Cal no confondre poder judicial i Administració de justícia. L''Administració de justícia no és poder judicial: és el conjunt de mitjans personals i materials que organitzen les activitats relacionades amb la justícia per garantir que el poder judicial pugui complir les seves funcions.","refs":[{"ref":"p. 151","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=151","quote":"L’Administració de justícia no és poder judicial, sinó que comprèn el conjunt de mitjans personals i materials destinats a l’organització de les activitats relacionades amb la justícia, amb la finalitat de garantir el compliment de les funcions del poder judicial."}]}]},{"n":"2","title":"Principis configuradors: exclusivitat i unitat jurisdiccional","blocks":[{"text":"Dos principis configuren el poder judicial. Per l''exclusivitat, només els jutjats i tribunals poden exercir la potestat jurisdiccional, i aquests només poden exercir aquesta potestat i les funcions que la llei els atribueixi expressament en garantia de drets. Hi ha excepcions previstes a la CE per a matèries concretes, com el Tribunal Constitucional.","refs":[{"ref":"p. 151","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=151","quote":"La potestat jurisdiccional només pot ser exercida pels òrgans que integren el poder judicial (jutjats i tribunals), i aquests només poden exercir la potestat jurisdiccional i les altres funcions que expressament els siguin atribuïdes per llei, en garantia de qualsevol dret."},{"ref":"p. 151","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=151","quote":"altres òrgans exerceixin la potestat jurisdiccional (per exemple, el Tribunal Constitucional)."}]},{"text":"Per la unitat jurisdiccional, el poder judicial és únic a tot l''Estat: a diferència del legislatiu i l''executiu, no hi ha òrgans judicials autonòmics i òrgans judicials centrals. Tampoc no hi pot haver jurisdiccions especials ni tribunals no determinats prèviament per la llei; tots els òrgans formen una organització única amb un mateix règim jurídic.","refs":[{"ref":"p. 151","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=151","quote":"El poder judicial és únic a tot el territori estatal, i no hi ha, com succeeix amb el poder legislatiu i el poder executiu, òrgans judicials de les comunitats autònomes i òrgans judicials de l’Estat central. No hi pot haver jurisdiccions especials, ni es poden crear tribunals que no es trobin prèviament determinats per la llei."}]}]},{"n":"3","title":"Estatut dels jutges i magistrats: la independència","blocks":[{"text":"Jutges i magistrats formen un cos únic. El seu estatut, regulat a la LOPJ, es regeix per cinc principis: independència, inamovibilitat, imparcialitat, incompatibilitat i responsabilitat.","refs":[{"ref":"p. 151","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=151","quote":"Els jutges i magistrats formen un cos únic i el seu estatut, que es regula a la Llei orgànica del poder judicial (LOPJ), es regeix pels principis següents: independència, inamovibilitat, imparcialitat, incompatibilitat i responsabilitat."}]},{"text":"La independència té dues vessants. L''externa vol dir que el poder judicial és independent dels altres poders, sobretot de l''executiu; per això la competència sobre l''estatut dels jutges, que abans tenia l''executiu, s''ha atribuït al Consell General del Poder Judicial. La interna vol dir que els jutges decideixen d''acord amb el dret sense rebre cap ordre, instrucció o suggeriment, i que les seves decisions només es poden revisar per mitjà dels recursos legals.","refs":[{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"s’ha d’entendre l’atribució al Consell General del Poder Judicial de la competència relativa a l’estatut jurídic dels jutges i magistrats, que havia estat una funció atribuïda anteriorment al poder executiu."},{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"els jutges i magistrats adopten les seves decisions d’acord amb el dret, sense que puguin rebre cap ordre, instrucció o suggeriment relatiu als fets sotmesos al seu judici. Les seves decisions només poden ser revisades mitjançant els recursos previstos legalment."}]},{"text":"Independència no és llibertat absoluta: segons l''article 117.1 CE, els jutges estan sotmesos únicament a l''imperi de la llei. Per això la decisió judicial ha de ser la conclusió d''un raonament jurídic motivat que aplica les normes al cas concret.","refs":[{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"tal com disposa l’article 117.1 de la CE, els jutges i magistrats actuen sotmesos únicament a l’imperi de la llei."}]}]},{"n":"4","title":"Inamovibilitat, imparcialitat, incompatibilitat i responsabilitat","blocks":[{"text":"Per la inamovibilitat, els jutges només poden ser separats, suspesos, traslladats o jubilats per causes legals (ascensos, faltes, incapacitat, renúncia, pèrdua de la nacionalitat, condemna penal). Així s''evita que els apartin per motius no professionals i es protegeix la seva independència.","refs":[{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"Els jutges i magistrats només poden ser separats, suspesos, traslladats o jubilats per les causes establertes per la llei (ascensos, faltes, incapacitat, renúncia, pèrdua de la nacionalitat, condemna penal)."}]},{"text":"La imparcialitat es garanteix amb dos mecanismes que convé no confondre. En l''abstenció és el mateix òrgan judicial qui s''aparta de l''assumpte perquè hi concorre una causa legal; en la recusació són les parts del procés les que demanen que el jutge no conegui del cas.","refs":[{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"l’abstenció (els òrgans judicials s’han d’abstenir de conèixer dels assumptes quan incorrin en una de les causes previstes a la llei que podrien posar en perill la seva imparcialitat) i la recusació (les parts del procés poden demanar que el jutge i magistrat no conegui del cas si incorre en alguna de les causes esmentades)."}]},{"text":"Per la incompatibilitat, no poden exercir altres càrrecs públics ni pertànyer a partits polítics o sindicats, però sí que poden crear associacions professionals. Pel que fa a la responsabilitat, pot ser penal (per exemple, prevaricació), civil (dany causat amb actuació dolosa o culposa) i disciplinària (sancions que imposa el Consell General del Poder Judicial).","refs":[{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"Els jutges i magistrats no poden exercir altres càrrecs públics, ni pertànyer a partits polítics o sindicats, però poden crear associacions professionals."},{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"Aquesta responsabilitat pot ser penal (per exemple, delicte de prevaricació), civil (si es causa un dany o perjudici en l’exercici de les seves funcions, sempre que la seva actuació sigui dolosa o culposa) i disciplinària (imposició de sancions pel Consell General del Poder Judicial)."}]}]},{"n":"5","title":"Estructura del poder judicial","blocks":[{"text":"L''estructura es determina per dos criteris. Pel criteri material (especialització), hi ha quatre ordres: civil, penal, contenciós administratiu i social. La jurisdicció militar no s''integra en el poder judicial, excepte la Sala Cinquena del Tribunal Suprem, que és militar.","refs":[{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"Els òrgans judicials es divideixen, per raó de l’especialització material, en civil, penal, contenciós administratiu i social. Pel que fa a la jurisdicció militar, s’ha de dir que no s’integra en l’estructura del poder judicial, excepte pel que fa a la Sala Cinquena del Tribunal Suprem, que és militar."}]},{"text":"Pel criteri territorial, l''Estat es divideix en municipis, partits judicials, províncies, comunitats autònomes i tot l''Estat. El Tribunal Suprem i l''Audiència Nacional tenen seu a Madrid i jurisdicció a tot l''Estat; hi ha un tribunal superior de justícia per comunitat autònoma i una audiència provincial per província; els jutjats penals, socials, contenciosos administratius, de vigilància penitenciària i de menors, un o més per província; els de primera instància i instrucció, un o més per partit judicial; i els jutjats de pau, als municipis on no hi ha jutjat de primera instància i instrucció.","refs":[{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"L’Estat es divideix, a l’efecte de l’organització del poder judicial, en municipis, partits judicials, províncies, comunitats autònomes i tot l’Estat."},{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"a) Tribunal Suprem (seu a Madrid i jurisdicció a tot l’Estat). b) Audiència Nacional (seu a Madrid i jurisdicció a tot l’Estat). c) Tribunals superiors de justícia (un a cada comunitat autònoma). d) Audiències provincials (una a cada província)."},{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"e) Jutjats penals, socials, contenciosos administratius, de vigilància penitenciària i de menors (un o més a cada província). f) Jutjats de primera instància i instrucció (un o més a cada partit judicial). g) Jutjats de pau (en els municipis en què no hi hagi jutjats de primera instància i instrucció)."}]}]},{"n":"6","title":"El Tribunal Superior de Justícia de Catalunya","blocks":[{"text":"L''article 152 CE disposa que un tribunal superior de justícia culmina l''organització judicial a la comunitat autònoma i que les instàncies processals s''exhaureixen dins del seu territori, sens perjudici del Tribunal Suprem (art. 123 CE). Així, el TSJC és l''última instància de tots els processos iniciats a Catalunya, sens perjudici de la facultat del Tribunal Suprem per unificar doctrina. L''Estatut ho reprodueix a l''article 95.","refs":[{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"El Tribunal Superior de Justícia de Catalunya és l’última instància jurisdiccional de tots els processos judicials iniciats a Catalunya, sens perjudici de la facultat reconeguda al Tribunal Suprem per unificació de doctrina."},{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"Aquesta previsió ha estat reproduïda a l’article 95 de l’Estatut d’autonomia de Catalunya."}]},{"text":"Recorda que els tribunals superiors de justícia formen part del poder judicial i no són òrgans de la comunitat autònoma, tot i la seva incidència autonòmica. Al TSJC li correspon en exclusiva unificar la interpretació del dret de Catalunya, i el seu president o presidenta el nomena el rei a proposta del Consell General del Poder Judicial.","refs":[{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"encara que els tribunals superiors de justícia són òrgans integrats dins del poder judicial, i no són òrgans de la comunitat autònoma"},{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"Correspon en exclusiva al Tribunal Superior de Justícia de Catalunya la unificació de la interpretació del dret de Catalunya. El president o presidenta del Tribunal Superior de Justícia de Catalunya és nomenat pel rei a proposta del Consell General del Poder Judicial."}]}]},{"n":"7","title":"El Consell General del Poder Judicial: naturalesa","blocks":[{"text":"El Consell General del Poder Judicial (CGPJ) és l''òrgan de govern del poder judicial i té atribuïdes expressament les funcions de nomenaments, ascensos, inspecció i règim disciplinari de jutges i magistrats. El constituent el va crear per garantir la independència judicial.","refs":[{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"El Consell General del Poder Judicial (CGPJ) és l’òrgan de govern del poder judicial, i té atribuïdes expressament les funcions relatives a nomenaments, ascensos, inspecció i règim disciplinari dels jutges i magistrats."}]},{"text":"Sobre la seva naturalesa hi ha posicions doctrinals contradictòries, però el legislador el considera òrgan constitucional, perquè l''article 59.1.c) de la Llei orgànica del Tribunal Constitucional (LOTC) el legitima per plantejar conflictes d''atribucions. No és òrgan jurisdiccional ni d''autogovern, perquè no s''integra al poder judicial, i exerceix les competències a tot el territori.","refs":[{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"el legislador el considera un òrgan constitucional, atès que és, d’acord amb l’article 59.1.c) de la Llei orgànica del Tribunal Constitucional (LOTC), un dels òrgans legitimats per plantejar conflicte d’atribucions"},{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"el CGPJ no és un òrgan jurisdiccional, ni és un òrgan d’autogovern, perquè no es troba integrat dins el poder judicial."}]}]},{"n":"8","title":"Composició del CGPJ","blocks":[{"text":"La composició es regula a l''article 122.3 CE i als articles 566 a 571 de la Llei orgànica 4/2013, de 28 de juny. El CGPJ té un president i vint vocals, nomenats pel rei i escollits per les Corts Generals: 12 entre jutges i 8 entre juristes de reconeguda competència, per mèrit i capacitat.","refs":[{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"El CGPJ es compon d’un president i vint vocals nomenats pel rei i escollits per les Corts Generals entre jutges (12) i juristes (8) de reconeguda competència en virtut de criteris de mèrit i capacitat."}]},{"text":"El president l''elegeixen per majoria de 3/5 els vint vocals, i és alhora president del Tribunal Suprem. Ha de ser magistrat del Tribunal Suprem amb condicions per presidir-ne una sala, o bé jurista de reconeguda competència amb més de vint-i-cinc anys d''exercici.","refs":[{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"Aquest membre del CGPJ és elegit per majoria de 3/5 dels vint vocals del Consell, i és alhora el president o presidenta del Tribunal Suprem."},{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"un jurista de reconeguda competència amb més de vint-i-cinc anys d’antiguitat en l’exercici de la seva professió."}]},{"text":"Dels vint vocals, vuit són advocats i juristes amb més de quinze anys d''exercici: quatre a proposta de 3/5 del Congrés i quatre de 3/5 del Senat. Els altres dotze són jutges i magistrats de qualsevol categoria: sis a proposta del Congrés i sis del Senat, sempre per 3/5. Els jutges candidats necessiten l''aval de 25 membres de la carrera judicial en actiu o d''una associació judicial legalment constituïda.","refs":[{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"Vuit vocals han de ser advocats i altres juristes de reconeguda competència, amb més de quinze anys d’exercici de la seva professió. Quatre són elegits a proposta de 3/5 del Congrés, i quatre a proposta de 3/5 del Senat."},{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"Els jutges o magistrats que vulguin ser vocals hauran de comptar amb l’aval de 25 membres de la carrera judicial en servei actiu, o bé amb el d’una associació judicial legalment constituïda."}]}]},{"n":"9","title":"Funcions del CGPJ","blocks":[{"text":"L''article 560 de la Llei orgànica 4/2013 n''enumera les funcions. Les principals són: proposar el nomenament del president del Tribunal Suprem (que ho és també del CGPJ) i dels magistrats del Tribunal Suprem i del Tribunal Constitucional; ser escoltat pel Govern en el nomenament del Fiscal General de l''Estat; i les atribucions de selecció, nomenament, formació, destinacions, ascensos, situacions administratives i règim disciplinari dels jutges.","refs":[{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"a) Proposar el nomenament del president o presidenta del Tribunal Suprem, que ho és alhora del CGPJ, i dels jutges i magistrats del Tribunal Suprem i del Tribunal Constitucional. b) Ser escoltat pel Govern pel que fa al nomenament del Fiscal General de l’Estat."}]},{"text":"També exerceix l''alta inspecció de jutjats i tribunals; té funció consultiva (informes sobre avantprojectes de lleis i disposicions que afectin el poder judicial); potestat reglamentària sobre el seu personal, organització i funcionament i per aplicar la LOPJ; presenta cada any a les Corts una memòria sobre el seu estat i el dels tribunals; i informa els expedients de responsabilitat patrimonial de l''Administració de justícia.","refs":[{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"d) Exercir l’alta inspecció de jutjats i tribunals."},{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"g) Presentar anualment a les Corts Generals una memòria sobre l’estat, el funcionament i l’activitat del CGPJ i dels jutjats i tribunals de justícia. h) Emetre informes sobre expedients de responsabilitat patrimonial de l’Administració de justícia."}]}]},{"n":"10","title":"El Ministeri Fiscal","blocks":[{"text":"El Ministeri Fiscal no forma part del poder judicial, però les seves funcions hi estan directament relacionades. És un òrgan únic a tot l''Estat i actua amb òrgans propis segons els principis d''unitat d''actuació, dependència jeràrquica i subjecció a la legalitat i imparcialitat.","refs":[{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"El Ministeri Fiscal no forma part del poder judicial, però les seves funcions es troben directament relacionades amb la funció jurisdiccional. És un òrgan únic a tot l’Estat. Exerceix les seves funcions mitjançant òrgans propis d’acord amb els principis d’unitat d’actuació, dependència jeràrquica i subjecció a la legalitat i imparcialitat."}]},{"text":"Al capdavant hi ha el Fiscal General de l''Estat (art. 124 CE), a qui tots els fiscals estan jeràrquicament subordinats. El nomena el rei a proposta del Govern, després d''escoltar el CGPJ, entre juristes amb més de quinze anys d''exercici efectiu. El mandat és de quatre anys (art. 31 de l''Estatut orgànic del Ministeri Fiscal, Llei 50/1981, modificada per la Llei 24/2007).","refs":[{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"El Fiscal General de l’Estat és nomenat pel rei a proposta del Govern, després d’haver escoltat el CGPJ, entre juristes de reconeguda competència amb més de quinze anys d’exercici professional efectiu. El mandat del fiscal general té una durada de quatre anys"}]},{"text":"Com els jutges, els fiscals no poden exercir altres càrrecs públics ni pertànyer a partits o sindicats, però poden formar associacions professionals (art. 127.1 CE). La CE els encomana tres funcions: promoure l''acció de la justícia en defensa de la legalitat, dels drets de la ciutadania i de l''interès públic, d''ofici o a petició dels interessats; vetllar per la independència dels tribunals; i procurar davant dels tribunals la satisfacció de l''interès social.","refs":[{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"a) Promoure l’acció de la justícia en defensa de la legalitat, dels drets de la ciutadania i de l’interès públic tutelat per la llei, d’ofici o a petició dels interessats. b) Vetllar per la independència dels tribunals. c) Procurar davant dels tribunals la satisfacció de l’interès social."}]}]},{"n":"11","title":"El Tribunal Constitucional: naturalesa i composició","blocks":[{"text":"El Tribunal Constitucional (TC) vigila el respecte a la CE i depura l''ordenament de les lleis i normes amb rang de llei que la vulneren. És el garant de la supremacia de la CE i el seu intèrpret suprem, encara que no l''únic (art. 1.1 LOTC). És un òrgan constitucional jurisdiccional, però no forma part del poder judicial i només està sotmès a la CE i a la LOTC.","refs":[{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"El TC actua com a garant de la supremacia de la CE i és, d’acord amb el que disposa l’article 1.1 de la LOTC, l’intèrpret suprem (encara que no l’únic) de la CE."},{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"El TC és un òrgan constitucional de caràcter jurisdiccional, però no es troba integrat en el poder judicial"}]},{"text":"Segons l''article 159 CE, el formen dotze magistrats nomenats pel rei per nou anys, escollits entre magistrats, fiscals, professors d''universitat, funcionaris i advocats amb més de quinze anys d''exercici. La proposta es reparteix així: quatre el Congrés (3/5), quatre el Senat (3/5), dos el Govern i dos el CGPJ (3/5).","refs":[{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"El TC, d’acord amb el que disposa l’article 159 de la CE, es compon de dotze magistrats, nomenats pel rei per un període de nou anys."},{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"a) Quatre magistrats són nomenats a proposta del Congrés dels Diputats per majoria de 3/5. b) Quatre magistrats són nomenats a proposta del Senat per majoria de 3/5. c) Dels altres quatre magistrats, dos són nomenats a proposta del Govern i dos a proposta del CGPJ per majoria de 3/5."}]},{"text":"El president del TC l''elegeixen els seus membres cada tres anys, amb majoria absoluta en primera votació i simple en segona. Els magistrats són independents i inamovibles, i el càrrec és incompatible amb mandats representatius, càrrecs polítics o administratius, funcions directives en partits o sindicats, les carreres judicial i fiscal i qualsevol activitat professional o mercantil.","refs":[{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"El president o presidenta del TC és nomenat entre i pels seus membres cada tres anys. Es requereix majoria absoluta a la primera votació i simple a la segona. Els magistrats del TC són independents i inamovibles."}]}]},{"n":"12","title":"Competències del Tribunal Constitucional","blocks":[{"text":"El TC controla la constitucionalitat de les lleis i normes amb força de llei; si les declara inconstitucionals, queden expulsades de l''ordenament. Aquest control es fa per dues vies: el recurs d''inconstitucionalitat i la qüestió d''inconstitucionalitat. També fa el control previ de tractats internacionals: abans que l''Estat signi un tractat, es pronuncia sobre si conté estipulacions contràries a la CE.","refs":[{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"El control es pot exercir mitjançant dos procediments: el recurs d’inconstitucionalitat i la qüestió d’inconstitucionalitat."},{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"abans de la signatura d’un tractat internacional per l’Estat, es pronunciï sobre si el tractat conté estipulacions contràries a la CE."}]},{"text":"El recurs d''empara defensa els drets fonamentals dels articles 14 a 29 i 30.2 CE; és subsidiari, perquè primer cal esgotar la via judicial ordinària. A més, el TC resol conflictes de competència entre l''Estat i les comunitats autònomes (o entre comunitats), per determinar qui és titular de la competència; conflictes d''atribucions entre òrgans constitucionals, per garantir la divisió de poders; i conflictes en defensa de l''autonomia local, que permeten als ens locals defensar-se d''una llei estatal o autonòmica que la vulneri.","refs":[{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"El recurs d’empara: l’objecte d’aquest procediment és la defensa dels drets fonamentals reconeguts als articles 14 a 29 i 30.2 de la CE. És un procediment subsidiari perquè primer s’ha d’exhaurir la via jurisdiccional ordinària."},{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"Els conflictes en defensa de l’autonomia local: l’objecte d’aquest procediment és permetre que els ens locals puguin defensar l’autonomia local garantida a la CE"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Principis configuradors del poder judicial: exclusivitat i unitat jurisdiccional.","refs":[{"ref":"p. 157","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=157","quote":"Els principis que configuren el poder judicial són: l’exclusivitat i la unitat jurisdiccional."}]},{"text":"Recusació = la demanen les parts; abstenció = s''aparta el mateix jutge.","refs":[{"ref":"p. 152","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=152","quote":"les parts del procés poden demanar que el jutge i magistrat no conegui del cas"}]},{"text":"La Sala Cinquena del Tribunal Suprem és la militar.","refs":[{"ref":"p. 153","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=153","quote":"excepte pel que fa a la Sala Cinquena del Tribunal Suprem, que és militar."}]},{"text":"El TSJC és l''última instància a Catalunya i el màxim intèrpret del dret de Catalunya; el seu president el nomena el rei a proposta del CGPJ.","refs":[{"ref":"p. 157","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=157","quote":"És també el màxim intèrpret del dret de Catalunya."}]},{"text":"CGPJ: president + 20 vocals (12 jutges i 8 juristes); funcions de nomenaments, ascensos, inspecció i règim disciplinari.","refs":[{"ref":"p. 154","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=154","quote":"escollits per les Corts Generals entre jutges (12) i juristes (8)"}]},{"text":"Fiscal General de l''Estat: el nomena el rei a proposta del Govern, escoltat el CGPJ; mandat de quatre anys.","refs":[{"ref":"p. 155","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=155","quote":"El mandat del fiscal general té una durada de quatre anys"}]},{"text":"TC: 12 magistrats, nou anys; 4 Congrés, 4 Senat, 2 Govern, 2 CGPJ; president cada tres anys.","refs":[{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"El president o presidenta del TC és nomenat entre i pels seus membres cada tres anys."}]},{"text":"Recurs d''empara: drets dels articles 14 a 29 i 30.2 CE, subsidiari.","refs":[{"ref":"p. 156","law":"Guia d''estudi, tema B.6","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=156","quote":"És un procediment subsidiari perquè primer s’ha d’exhaurir la via jurisdiccional ordinària."}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=150'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=150', 150, 157, 157, null
