insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Els models d’organització territorial"},{"n":"1.1","title":"L’Estat unitari i l’Estat federal"},{"n":"1.2","title":"L’evolució dels models"},{"n":"2","title":"El model territorial a la Constitució espanyola de 1978"},{"n":"3","title":"Les comunitats autònomes"},{"n":"4","title":"Els municipis"},{"n":"5","title":"Les províncies"},{"n":"6","title":"Les comarques"},{"n":"7","title":"Les vegueries"}]'::jsonb, '["En funció de quina sigui la forma de distribuir el poder en un Estat a través del seu territori, podem trobar dos “models” d’Estat: l’unitari i el federal.","El model unitari es basa fonamentalment en l’existència d’un únic centre de decisió política (el govern) i un únic centre per dictar normes amb rang de llei (el parlament) per a tot el territori de l’Estat. Els principis en què es basa són: la unitat (un sol Estat), la uniformitat (la mateixa llei per a tot el territori) i la centralització (direcció política i direcció administrativa efectuada des del centre).","L’Estat federal és un “Estat d’estats”, on el poder polític s’exerceix des de dues instàncies, la central (que és la federació), que disposa d’uns òrgans propis (parlament, president i tribunals) i que exerceix les seves funcions sobre tot el territori federal d’acord amb el que preveu la constitució federal; i les diferents instàncies territorials (els estats membres), que disposen cadascuna d’elles d’una constitució pròpia, d’una organització política pròpia i d’uns poders propis que exerceixen només sobre el seu territori.","L’Estat federal, a diferència de l’unitari, es caracteritza per tenir una pluralitat de centres de poder, una diversitat de normes i orientacions polítiques i una descentralització o distribució territorial de la capacitat de decisió.","La CE estableix uns principis i uns procediments que, en cas que siguin activats, han de permetre transformar l’Estat unitari i centralista espanyol en un Estat descentralitzat políticament i que pot adoptar diverses formes.","Les comunitats autònomes són aquelles entitats polítiques que, en exercici del dret a l’autonomia reconegut a la CE, gaudeixen de personalitat jurídica, de potestat d’autogovern i d’autonomia legislativa pròpia dins el seu àmbit territorial.","El municipi és la unitat local bàsica de l’organització territorial. Els ajuntaments són definits com a òrgans de govern local per als municipis, que són entitats territorials de dret públic.","La província és una entitat local amb personalitat jurídica pròpia, determinada per l’agrupació de municipis limítrofes, que constitueix una divisió territorial per al compliment de les activitats de l’Estat.","La vegueria és la divisió territorial adoptada per la Generalitat per a la futura organització territorial dels seus serveis.","La CE no crea la institució comarcal, però preveu la possibilitat que es creïn agrupacions de municipis diferents de la província. A més, habilita els estatuts d’autonomia per establir circumscripcions territorials pròpies a través de l’agrupació de municipis limítrofes que gaudiran de personalitat jurídica."]'::jsonb, '["Antic règim","Autonomia legislativa","Consell comarcal","Conveni","Diputacions","Divisió horitzontal de poder","Divisió vertical de poder","Estat compost","Estat sobirà","Estructura territorial","Idees racionalistes","Institucions locals","Model d’Estat","Personalitat jurídica","Poder polític","Potencial","Potestat d’autogovern","Prestació de servei","Regidors","Tributs","Uniformització"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Estructura territorial i models d''Estat","blocks":[{"text":"El poder d''un Estat es reparteix segons la seva estructura territorial. Segons la guia, l''Estat espanyol s''estructura en comunitats autònomes, municipis i províncies, i també es poden crear agrupacions de municipis diferents de la província (com les comarques).","refs":[{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"L’Estat espanyol s’estructura en comunitats autònomes, municipis i províncies. Es poden crear agrupacions de municipis diferents de la província."}]},{"text":"Segons com es distribueix el poder pel territori, la guia distingeix dos grans models d''Estat: l''unitari i el federal. La resta de fórmules (regional, integral, autonòmic) s''expliquen com a evolucions d''aquests dos.","refs":[{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"En funció de quina sigui la manera de distribuir el poder en un Estat a través del seu territori podem trobar dos “models” d’Estat: l’unitari i el federal."}]}]},{"n":"2","title":"L''Estat unitari","blocks":[{"text":"L''Estat unitari neix a França amb la caiguda de l''antic règim, a partir de les idees racionalistes dels revolucionaris, i es porta a la pràctica amb la Constitució de 1791. Volia una organització uniforme i centralitzada que acabés amb la pluralitat d''ordenaments, jurisdiccions i administracions anterior.","refs":[{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"L’Estat unitari neix a França amb la caiguda de l’antic règim, a partir de les idees racionalistes dels revolucionaris i que foren portades a la pràctica amb la Constitució de 1791."}]},{"text":"Es basa en un únic centre de decisió política (el govern) i un únic centre que dicta normes amb rang de llei (el parlament) per a tot el territori. L''Administració en depèn jeràrquicament i executa les decisions de manera uniforme. El territori només es divideix en circumscripcions administratives (departaments i municipis) dirigides per una autoritat designada pel Govern (prefecte i alcalde).","refs":[{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"Aquest model es basa fonamentalment en l’existència d’un únic centre de decisió política (el govern) i un únic centre per dictar normes amb rang de llei (el parlament) per a tot el territori de l’Estat."},{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"es divideix únicament en unes circumscripcions merament administratives (els departaments i els municipis) al capdavant de les quals hi ha una única autoritat administrativa (el prefecte i l’alcalde), designada pel Govern"}]},{"text":"Els seus tres principis són la unitat (un sol Estat), la uniformitat (la mateixa llei per a tot el territori) i la centralització (direcció política i administrativa des del centre). Aquest model es va estendre per bona part de l''Europa continental, inclosa Espanya.","refs":[{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"Els principis en què es basa són, doncs, la unitat (un sol Estat), la uniformitat (la mateixa llei per a tot el territori) i la centralització (direcció política i direcció administrativa efectuada des del centre)."}]}]},{"n":"3","title":"L''Estat federal","blocks":[{"text":"L''Estat federal sorgeix amb la Constitució dels Estats Units de 1787, com a unió política de les antigues colònies britàniques ja independents. Neix d''un pacte entre estats sobirans que creen una nova entitat, la federació, a la qual deleguen expressament algunes funcions i en retenen la resta.","refs":[{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"L’Estat federal sorgeix amb la Constitució dels Estats Units d’Amèrica de 1787, com la fórmula d’unió política més perfecta entre les antigues colònies britàniques"}]},{"text":"És un «Estat d''estats»: el poder s''exerceix des de la federació (amb parlament, president i tribunals propis, sobre tot el territori) i des dels estats membres (cadascun amb constitució, organització i poders propis sobre el seu territori). A la divisió horitzontal de poders (executiu, legislatiu i judicial) hi afegeix una divisió vertical, que reparteix territorialment el poder ja dividit.","refs":[{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"en l’Estat federal no hi ha només el que se’n diu una divisió horitzontal de poders (executiu, legislatiu i judicial), sinó també una divisió vertical, que provoca que aquell poder ja dividit es trobi també repartit territorialment."}]},{"text":"Es caracteritza per la pluralitat de centres de poder, la diversitat de normes i orientacions polítiques i la descentralització. Però conserva elements d''unitat: és un únic poder cap a l''exterior i manté estructures unitàries a l''interior (exèrcit, moneda, sistema econòmic, duanes, comunicacions i símbols). El model l''han adoptat Alemanya, Suïssa, Mèxic, el Brasil, l''Argentina, el Canadà i Austràlia.","refs":[{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"manté unes estructures unitàries a l’interior (exèrcit, moneda, sistema econòmic, duanes, comunicacions i símbols)"},{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"fou adoptat posteriorment al continent europeu per Alemanya i Suïssa, per alguns països iberoamericans (Mèxic, el Brasil i l’Argentina) i per alguns estats històricament vinculats a la Gran Bretanya (el Canadà i Austràlia)."}]}]},{"n":"4","title":"L''evolució dels models","blocks":[{"text":"Els dos models s''han anat apropant: l''unitari ha introduït mecanismes de descentralització política, i el federal ha tendit a una major centralització i uniformització. L''Estat unitari centralitzat és el que ha entrat més en crisi, sobretot al segle XX, pel creixement de l''Estat, les demandes de participació i la complexitat social.","refs":[{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"l’Estat unitari ha anat introduint diversos mecanismes de descentralització política, mentre que l’Estat federal ha anat reclamant més competències en un procés constant de lluita amb els estats membres cap a una major centralització i uniformització."}]},{"text":"D''aquí en surten noves formes (Estat regional, Estat integral i Estat autonòmic) que s''agrupen sota el nom d''estats compostos. En aquests, es manté un únic Estat amb una única constitució, però la decisió política i la potestat legislativa es reparteixen entre els òrgans centrals i uns ens territorials amb autonomia política.","refs":[{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"(Estat regional, Estat integral i Estat autonòmic), que s’acostumen a agrupar sota la denominació d’estats compostos."}]}]},{"n":"5","title":"El model territorial a la Constitució de 1978","blocks":[{"text":"La CE no tanca el model: és només potencial. Fixa principis i procediments que, si s''activen, permeten transformar l''Estat unitari i centralista en un Estat políticament descentralitzat, i deixa la decisió final als estatuts d''autonomia. A partir del principi dispositiu, el règim autonòmic es generalitza amb la creació de les comunitats autònomes i l''Estat esdevé compost.","refs":[{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"D’acord amb la CE, el model d’organització territorial de l’Estat és només potencial i pot adoptar diverses variants."},{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"partint de l’anomenat principi dispositiu, la CE possibilita que el règim autonòmic es generalitzi a través de la creació de les comunitats autònomes"}]},{"text":"La fórmula constitucional té dos elements: un únic Estat, una única constitució, un únic ordenament i igualtat de drets i obligacions; i el reconeixement del dret a l''autonomia de les nacionalitats i regions (article 2 CE). Amb els primers estatuts, aprovats el 1979, neix un Estat compost que la CE no qualifica, però que la doctrina anomena Estat autonòmic o Estat de les autonomies.","refs":[{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"reconeix i garanteix el dret a l’autonomia de les nacionalitats i regions que integren l’Estat espanyol (article 2)"},{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"L’aprovació el 1979 dels primers estatuts d’autonomia va posar en funcionament un determinat tipus d’organització territorial de l’Estat"},{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"però que doctrinalment és conegut amb el nom d’Estat autonòmic o Estat de les autonomies."}]}]},{"n":"6","title":"Les comunitats autònomes: concepte i característiques","blocks":[{"text":"Les comunitats autònomes són entitats polítiques que, exercint el dret a l''autonomia, tenen personalitat jurídica, potestat d''autogovern i autonomia legislativa pròpia en el seu territori. La seva autonomia és qualitativament diferent de la dels municipis i les províncies, que només tenen autonomia administrativa.","refs":[{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"Les comunitats autònomes són aquelles entitats polítiques que, en exercici del dret a l’autonomia reconegut a la CE, gaudeixen de personalitat jurídica, de potestat d’autogovern i d’autonomia legislativa pròpia dins el seu àmbit territorial."},{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"els municipis i les províncies, a les quals només s’atorga autonomia administrativa."}]},{"text":"L''autonomia política es concreta en l''estatut d''autonomia, norma institucional bàsica que crea la comunitat i en fixa òrgans i competències, i en facultats de direcció política governamentals i legislatives. La seva organització segueix la divisió de poders i la responsabilitat del govern davant l''assemblea (article 152), i tenen autonomia financera.","refs":[{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"L’autonomia política es concreta normativament en l’estatut d’autonomia de cada comunitat autònoma, que és la seva norma institucional bàsica"},{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"e) Gaudeixen d’autonomia financera per exercir les seves competències."}]},{"text":"Les relacions amb l''Estat central no són de jerarquia sinó de competència. Participen en les instàncies centrals (iniciatives legislatives i designació directa de senadors pels parlaments autonòmics), i el dret estatal és supletori del dret autonòmic (article 149.3).","refs":[{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"f) Les relacions amb l’Estat central no són de jerarquia sinó de competència."},{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"h) El dret estatal és supletori del dret autonòmic (article 149.3)."}]}]},{"n":"7","title":"Tipus de comunitats autònomes i pactes autonòmics","blocks":[{"text":"La CE no dibuixa un mapa autonòmic, només procediments d''accés. El resultat són 17 comunitats autònomes i dues ciutats autònomes (Ceuta i Melilla), no originàriament iguals. Es classifiquen segons tres criteris: l''històric, el competencial i el del procediment d''accés.","refs":[{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"es va completar amb la creació de 17 comunitats autònomes i de dues ciutats autònomes (Ceuta i Melilla)."},{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"respon fonamentalment a un triple criteri: l’històric, el competencial i el del procediment d’accés a l’autonomia utilitzat."}]},{"text":"Primer grup: Catalunya, el País Basc i Galícia (i el territori foral de Navarra), que ja havien aprovat projectes d''estatut i tenien règims provisionals d''autogovern el 1978. Segon grup: les que poden arribar al mateix nivell per un procediment especial que exigeix una voluntat d''autogovern molt més àmplia (article 151.1). Tercer grup: les que segueixen el procediment general de l''article 143 i, segons l''article 148.2, poden ampliar competències passats cinc anys des de l''aprovació de l''estatut. Totes, excepte Catalunya, País Basc, Galícia, Andalusia i Navarra, van anar per l''article 143.","refs":[{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"En aquesta classificació cal incloure Catalunya, el País Basc i Galícia. En aquesta categoria també s’ha d’incloure el territori foral de Navarra."},{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"d’acord amb l’article 148.2, poden ampliar successivament les seves competències un cop hagin transcorregut cinc anys des de l’aprovació dels seus respectius estatuts d’autonomia."},{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"Excepte Catalunya, el País Basc, Galícia, Andalusia i Navarra, la resta de les comunitats autònomes que es crearen van accedir a l’autonomia a través del procediment general previst a l’article 143"}]},{"text":"Aquesta lògica va canviar amb el «pacte autonòmic» de 1981 entre el PSOE i la UCD, que va frenar el principi dispositiu i va intentar homogeneïtzar competències (en aquesta línia, la LOAPA). El 1992, el PSOE i el PP van fer un altre pacte per equiparar les comunitats de via lenta amb traspassos. Avui hi ha un anivellament competencial entre totes.","refs":[{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"“pacte autonòmic” signat el 1981 per les aleshores forces polítiques majoritàries a l’Estat espanyol, el PSOE i la UCD"},{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"fins a l’any 1992, en què el PSOE i el PP arriben a un altre gran pacte autonòmic per equiparar les competències de les comunitats autònomes de via lenta"}]}]},{"n":"8","title":"Els municipis","blocks":[{"text":"Les institucions locals tenen una llarga tradició, i per això la CE les regula breument (articles 140 a 142). El municipi és la unitat local bàsica de l''organització territorial, i l''ajuntament n''és l''òrgan de govern. Està representat per regidors elegits per sufragi universal i presidit per un alcalde elegit pels regidors (o directament pels ciutadans en els casos de la LOREG, articles 196 i següents, segons la població).","refs":[{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"El municipi és, doncs, la unitat local bàsica de l’organització territorial"},{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"Els municipis estan representats per regidors (elegits per sufragi universal) i presidits per un alcalde elegit directament pels regidors."}]},{"text":"Tenen potestat d''autoorganització, però com a mínim han de tenir alcalde, regidors, tinents d''alcalde, ple i comissió especial de comptes; els de més de cinc mil habitants, també una comissió de govern (és la denominació que fa servir la guia).","refs":[{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"com a mínim han de comptar amb un alcalde, regidors, tinents d’alcalde, el ple i la comissió especial de comptes."},{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"els municipis de més de cinc mil habitants han de tenir necessàriament una comissió de govern."}]},{"text":"La Llei 7/1985, de bases de règim local (LBRL), els reserva competències pròpies: urbanisme, trànsit urbà, mercats, cementiris, salubritat, assistència social, enllumenat i neteja, entre d''altres, i preveu figures associatives com mancomunitats i consorcis. Tenen potestats executives i normatives reglamentàries, i es financen amb tributs propis i amb participació en els ingressos de l''Estat i de la comunitat autònoma.","refs":[{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"La legislació de l’Estat, a través de la Llei 7/1985, de bases de règim local (LBRL), ha reservat una esfera pròpia de competències als ens locals"},{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"urbanisme, trànsit urbà, mercats, cementiris, salubritat, assistència social, enllumenat i neteja, entre d’altres."},{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"e) Tenen atribuïda també la capacitat de finançament a través de la creació de tributs propis i de la participació en els ingressos de l’Estat i de la comunitat autònoma de la qual formen part."}]}]},{"n":"9","title":"Les províncies","blocks":[{"text":"Segons l''article 141 CE, la província és una entitat local amb personalitat jurídica pròpia, formada per l''agrupació de municipis limítrofes, i divisió territorial per a les activitats de l''Estat. El seu govern correspon a les diputacions (o altres corporacions representatives), que coordinen i assisteixen els municipis.","refs":[{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"L’article 141 estableix que la província és una entitat local amb personalitat jurídica pròpia, determinada per l’agrupació de municipis limítrofes, que constitueix una divisió territorial per al compliment de les activitats de l’Estat."}]},{"text":"La LBRL atribueix a les diputacions la coordinació de serveis municipals, l''assistència jurídica, econòmica i tècnica als municipis, els serveis intermunicipals, el foment dels interessos provincials i el pla anual de cooperació a les obres i serveis municipals. La província té caràcter bifront: és divisió administrativa per a les finalitats de l''Estat i circumscripció electoral per al Congrés i el Senat.","refs":[{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"la coordinació de serveis municipals, l’assistència jurídica, econòmica i tècnica als municipis del seu territori, la prestació de serveis intermunicipals, el foment dels interessos de la província i l’adopció del pla anual de cooperació a les obres i serveis municipals."},{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"la província té un caràcter bifront, és a dir, d’una banda, gaudeix de la doble condició de divisió administrativa per al compliment de les finalitats de l’Estat, i de l’altra, és una circumscripció electoral"}]}]},{"n":"10","title":"Les comarques","blocks":[{"text":"La CE no crea la comarca, però l''article 141.3 permet agrupacions de municipis diferents de la província i habilita els estatuts per crear circumscripcions pròpies amb personalitat jurídica. A Catalunya, el règim general és al Decret legislatiu 2/2003, de 28 d''abril, text refós de la Llei municipal i de règim local de Catalunya.","refs":[{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"La CE no crea la institució comarcal, però a l’article 141.3 preveu la possibilitat que es creïn agrupacions de municipis diferents de la província."},{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"Decret legislatiu 2/2003, de 28 d’abril, pel qual s’aprova el text refós de la Llei municipal i de règim local de Catalunya."}]},{"text":"Les governa el consell comarcal, amb tres òrgans: el ple, el president i la comissió especial de comptes. Els consellers comarcals s''elegeixen de manera indirecta: cada formació rep consellers en proporció als vots i als regidors obtinguts a les eleccions municipals.","refs":[{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"El govern i l’administració de les comarques correspon al consell comarcal, que està constituït per tres òrgans: el ple, el president i la comissió especial de comptes."},{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"l’elecció dels quals és de caràcter indirecte"}]},{"text":"Les competències tenen dos orígens. Les municipals: serveis supramunicipals complementaris, obres d''infraestructura i les que els municipis deleguin per conveni. Les de la Generalitat: les lleis d''ordenació del territori i urbanisme, sanitat, serveis socials, cultura, esport, ensenyament, salubritat i medi ambient han de donar alguna competència a la comarca.","refs":[{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"Les competències de les comarques són de procedència municipal o de la Generalitat."},{"ref":"p. 164","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=164","quote":"(ordenació del territori i urbanisme, sanitat, serveis socials, cultura, esport, ensenyament, salubritat pública i medi ambient)"}]}]},{"n":"11","title":"Les vegueries","blocks":[{"text":"Segons l''article 90 de l''Estatut, la vegueria és l''àmbit territorial específic del govern intermunicipal de cooperació local i té personalitat jurídica pròpia. També és la divisió que adopta la Generalitat per organitzar territorialment els seus serveis, i com a govern local té autonomia per gestionar els seus interessos.","refs":[{"ref":"p. 164","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=164","quote":"Segons l’article 90 de l’Estatut d’autonomia, la vegueria és l’àmbit territorial específic per a l’exercici del govern intermunicipal de cooperació local, i té personalitat jurídica pròpia."}]},{"text":"L''article 91 encarrega el govern de la vegueria al Consell de Vegueria, format pel president i els consellers, que elegeixen el president entre ells. Els consells de vegueria han de substituir les diputacions. La creació, modificació, supressió i règim jurídic de les vegueries es regulen per llei del Parlament, i l''alteració de límits provincials s''ha de fer segons l''article 141.1 CE. Fixa-t''hi: la guia ho formula en futur («substituiran»).","refs":[{"ref":"p. 164","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=164","quote":"Segons l’article 91 de l’Estatut d’autonomia, el govern i l’administració autònoma de la vegueria correspondran al Consell de Vegueria, format pel president o presidenta i pels consellers de vegueria."},{"ref":"p. 164","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=164","quote":"Els consells de vegueria substituiran les diputacions."}]},{"text":"Segons les esmenes oficials de setembre de 2026, Catalunya té 8 vegueries (dada del tema A.5, útil també aquí).","refs":[{"ref":"","law":"Esmenes a la Guia d''estudi (setembre 2026)","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf","quote":"947 municipis i 8 vegueries"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Estat unitari: França, Constitució de 1791; principis d''unitat, uniformitat i centralització.","refs":[{"ref":"p. 159","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=159","quote":"foren portades a la pràctica amb la Constitució de 1791"}]},{"text":"Estat federal: EUA, 1787; «Estat d''estats» amb divisió vertical del poder.","refs":[{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"L’Estat federal és, doncs, un “Estat d’estats”"}]},{"text":"Principi dispositiu: base de la generalització del règim autonòmic; primers estatuts el 1979.","refs":[{"ref":"p. 160","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=160","quote":"l’anomenat principi dispositiu"}]},{"text":"17 comunitats autònomes i 2 ciutats autònomes; relacions amb l''Estat de competència, no de jerarquia.","refs":[{"ref":"p. 161","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=161","quote":"no són de jerarquia sinó de competència."}]},{"text":"Via de l''article 143: ampliació de competències passats cinc anys (art. 148.2).","refs":[{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"un cop hagin transcorregut cinc anys"}]},{"text":"Pactes autonòmics: 1981 (PSOE-UCD, LOAPA) i 1992 (PSOE-PP).","refs":[{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"Llei orgànica d’harmonització del procés autonòmic –LOAPA–"}]},{"text":"Municipi: unitat local bàsica; comissió de govern obligatòria a partir de cinc mil habitants; LBRL = Llei 7/1985.","refs":[{"ref":"p. 162","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=162","quote":"Els ajuntaments són definits com a òrgans de govern local per als municipis, que són entitats territorials de dret públic."}]},{"text":"Consell comarcal: ple, president i comissió especial de comptes; elecció indirecta.","refs":[{"ref":"p. 163","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=163","quote":"el ple, el president i la comissió especial de comptes."}]},{"text":"Vegueria: article 90 de l''Estatut (definició) i article 91 (Consell de Vegueria).","refs":[{"ref":"p. 164","law":"Guia d''estudi, tema B.7","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=164","quote":"La vegueria també és la divisió territorial adoptada per la Generalitat per a l’organització territorial dels seus serveis."}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=158'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=158', 158, 166, 165, null
