insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema B.8, pp. 167-176', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=167', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-b8-unio-europea', 'B.8 La Unió Europea') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('mossos-esquadra') and t.slug = 'mossos-b8-unio-europea' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Origen històric de la Unió Europea"},{"n":"2","title":"L’ordenament jurídic comunitari: dret comunitari originari i dret derivat"},{"n":"2.1","title":"El dret comunitari originari"},{"n":"2.2","title":"El dret comunitari derivat"},{"n":"2.3","title":"Relacions entre el dret comunitari i el dret dels estats membres"},{"n":"3","title":"Institucions comunitàries"},{"n":"3.1","title":"El Consell de la Unió Europea"},{"n":"3.2","title":"La Comissió Europea"},{"n":"3.3","title":"El Parlament Europeu"},{"n":"3.4","title":"El Tribunal de Justícia de la Unió Europea"},{"n":"3.5","title":"Altres institucions comunitàries rellevants"}]'::jsonb, '["La Unió Europea és una organització supraestatal, basada en la unitat política, econòmica i monetària, construïda mitjançant la signatura de diversos tractats internacionals entre els països que en formen part.","El projecte inicial de comunitats europees no es conformava exclusivament amb la creació d’un únic espai econòmic, ni tampoc amb la presència dels estats signataris del Tractat de Roma de 1957, sinó que preveia la seva expansió en un doble sentit: ampliar el seu marc geogràfic amb la integració de nous estats, i aprofundir en les relacions entre els socis comunitaris per assolir una veritable unitat política, econòmica i monetària.","Les fonts del dret comunitari europeu es divideixen entre dret originari (o primari), format pels tractats constitutius de la Unió, i dret derivat (o secundari), constituït per tots els actes normatius dictats pels òrgans comunitaris.","El Consell de la Unió Europea és l’òrgan intergovernamental, en què els membres representen els interessos del seu Estat dins l’àmbit de la Unió Europea. Està integrat per un representant de cadascun dels estats membres. Les decisions del Consell s’adopten preferentment d’acord amb el principi de majoria qualificada, i s’introdueix un criteri ponderat mitjançant el qual s’assigna a cada Estat membre un nombre determinat de vots.","La Comissió Europea és un òrgan independent dels estats membres, i la seva missió és protegir i vetllar pels interessos comunitaris. Està integrada per vint-i-set membres, elegits per raó de la seva competència general sempre que ofereixin garanties d’independència.","El Parlament és l’òrgan que representa els pobles dels estats membres. Els escons es distribueixen entre els estats membres d’acord amb criteris de proporcionalitat en funció de la població. L’elecció dels parlamentaris es fa per sufragi universal directe a cadascun dels estats membres.","El Tribunal de Justícia és l’òrgan que garanteix la interpretació i aplicació del dret comunitari, i té un paper essencial en el desenvolupament del seu ordenament, atès que gran part de l’evolució d’aquest troba el seu fonament en decisions del Tribunal de Justícia."]'::jsonb, '["Acte de cessió de sobirania","Ampliació de la Unió Europea","Dictamen","Drets de duanes","Eficàcia jurídica","Jurisconsults","Organització supraestatal","Política d’asil","Tractat internacional","Vetar","Zona de lliure comerç"]'::jsonb, '[{"text":"Esmena oficial (setembre 2026): el Parlament Europeu té 720 membres.","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf"}]'::jsonb, '[{"n":"1","title":"Concepte de Unió Europea","blocks":[{"text":"La guia defineix la Unió Europea (UE) com una organització supraestatal basada en la unitat política, econòmica i monetària, construïda amb diversos tractats internacionals signats pels seus membres. Aquests tractats creen institucions comunes (Consell, Comissió, Parlament i Tribunal de Justícia) en què els estats, per un acte de cessió de sobirania, deleguen competències normatives, de gestió i de control polític.","refs":[{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"La Unió Europea és una organització supraestatal, basada en la unitat política, econòmica i monetària, construïda mitjançant la signatura de diversos tractats internacionals entre els països que en formen part."},{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"en què els estats membres, mitjançant un acte de cessió de sobirania, deleguen a la Unió l’exercici de competències normatives, de gestió i de control polític"}]},{"text":"L''objectiu principal és el mercat únic, amb lliure circulació de mercaderies, capitals, serveis i ciutadans, però també la cooperació en política exterior i seguretat comuna i en justícia i interior. Amb la moneda comuna, la UE substitueix l''Estat en bona part de les seves competències tradicionals.","refs":[{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"principalment l’establiment d’un mercat únic en el qual mercaderies, capitals, serveis i ciutadans puguin circular lliurement; però també la cooperació en la política exterior i la seguretat comuna i en assumptes de justícia i interior."}]},{"text":"Sobre la reforma dels tractats, el Govern de la Generalitat, d''acord amb l''article 185 de l''Estatut, va adoptar les seves observacions el 24 de juliol de 2007 (la guia diu més endavant que es van lliurar al Govern espanyol el 25 de juliol). El 13 de desembre de 2007 els vint-i-set estats van signar el Tractat de Lisboa, en vigor des de l''1 de desembre de 2009. Els tractats constitutius passen a dir-se Tractat de funcionament de la UE (l''antic Tractat de la Comunitat Europea) i Tractat de la UE.","refs":[{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"D’acord amb l’article 185 de l’Estatut d’autonomia de Catalunya, el 24 de juliol de 2007 el Govern de la Generalitat de Catalunya va adoptar les seves observacions"},{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"El dia 13 de desembre de 2007 els caps d’Estat i de govern dels vint-i-set estats membres de la UE van signar el nou Tractat de reforma de la UE. El Tractat de Lisboa va entrar en vigor l’1 de desembre de 2009, un cop ratificat per tots els estats membres."},{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"– Tractat de funcionament de la Unió Europea (el Tractat de la Comunitat Europea modificat). – Tractat de la Unió Europea (el TUE modificat)."}]}]},{"n":"2","title":"Origen històric i adhesió d''Espanya","blocks":[{"text":"El procés d''integració comença el 1951 amb el Tractat de la Comunitat Europea del Carbó i l''Acer (CECA), signat a París el 18 d''abril. El segueixen els tractats de la Comunitat Econòmica Europea (CEE) i de l''Energia Atòmica (EURATOM), signats a Roma el 25 de març de 1957 pels sis estats fundadors: Bèlgica, els Països Baixos, Luxemburg, França, Itàlia i la República Federal d''Alemanya. El procés culmina amb el Tractat de Maastricht (7 de febrer de 1992).","refs":[{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"un procés d’integració política i econòmica que es va iniciar el 1951 amb la signatura del Tractat de la Comunitat Europea del Carbó i l’Acer (CECA), al qual van seguir els tractats de la Comunitat Econòmica Europea (CEE) i de l’Energia Atòmica (EURATOM), signats a Roma el 25 de març de 1957 per Bèlgica, els Països Baixos, Luxemburg, França, Itàlia i la República Federal d’Alemanya."}]},{"text":"Espanya s''hi incorpora amb el Tractat d''adhesió, autoritzat per la Llei orgànica 10/1985, de 2 d''agost. Des de l''1 de gener de 1986, tot el dret comunitari originari vigent i les normes posteriors s''integren com un tot a l''ordenament espanyol.","refs":[{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"Espanya s’incorpora a la Unió Europea mitjançant la signatura del Tractat d’adhesió, autoritzat per la Llei orgànica 10/1985, de 2 d’agost. D’acord amb el Tractat, a partir de l’1 de gener de 1986"}]},{"text":"La CEE buscava sobretot un mercat comú: la primera conseqüència va ser la supressió dels drets de duanes per crear una zona de lliure comerç de mercaderies, capital i treball. El projecte preveia una expansió en doble sentit: ampliar el marc geogràfic amb nous estats i aprofundir en les relacions entre socis fins a una veritable unitat política, econòmica i monetària.","refs":[{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"La primera conseqüència pràctica fou la supressió dels drets de duanes per generar una zona de lliure comerç de mercaderies, capital i treball entre els països membres."},{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"a) Ampliar el seu marc geogràfic amb la integració de nous estats."},{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"b) Aprofundir en les relacions entre els socis comunitaris per assolir una veritable unitat política, econòmica i monetària."}]}]},{"n":"3","title":"Brussel·les, Acta Única i Maastricht","blocks":[{"text":"El Tractat de Brussel·les (8 d''abril de 1965) va unificar institucions de les tres comunitats, com la Comissió i el Consell; els tribunals de justícia i les assemblees ja s''havien unificat per un conveni signat a Roma el mateix 25 de març de 1957. L''Acta Única Europea (AUE), signada a Luxemburg el 17 de febrer de 1986, va crear un mercat interior com a únic espai econòmic amb plena llibertat de circulació de persones, béns, serveis i capitals.","refs":[{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"Els tractats inicials foren seguits més endavant pel Tractat de Brussel·les, de 8 d’abril de 1965, pel qual es van unificar algunes de les institucions de les tres comunitats anteriors, que formalment eren independents les unes de les altres, com ara la Comissió i el Consell."},{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"l’Acta Única Europea (AUE), signada a Luxemburg el 17 de febrer de 1986, mitjançant la qual es creà un mercat interior com a únic espai econòmic entre els estats membres, amb plena llibertat de circulació de les persones, els béns, els serveis i els capitals."}]},{"text":"El Tractat de la Unió Europea (TUE), signat a Maastricht el 7 de febrer de 1992, va conciliar els estats que volien conservar sobirania en política exterior, seguretat i justícia amb els partidaris d''una integració federal. Va instituir la política exterior i seguretat comuna (PESC) i la cooperació en justícia i assumptes d''interior (CJAI).","refs":[{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"a través de la institució de la política exterior i seguretat comuna (PESC) i de la cooperació en els àmbits de la justícia i dels assumptes d’interior (CJAI)."}]},{"text":"Dins de la CJAI hi ha matèries d''interès policial: asil; pas de fronteres i política duanera; immigració de nacionals de tercers països; narcotràfic; prevenció policial i lluita contra el terrorisme; frau econòmic transnacional; i cooperació judicial civil i penal.","refs":[{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"la política d’asil; el creuament de persones per les fronteres i la política duanera; la política d’immigració de nacionals de tercers països; la lluita contra el narcotràfic; la prevenció policial i la lluita contra el terrorisme"}]}]},{"n":"4","title":"Amsterdam, Niça i la Constitució europea","blocks":[{"text":"El Tractat d''Amsterdam (2 d''octubre de 1997) va reformar sobretot l''àmbit institucional, però no va resoldre la composició de la Comissió ni la ponderació del vot al Consell. El Tractat de Niça (2001, signat el 26 de febrer) va adaptar les institucions a l''ampliació cap als països de l''est d''Europa.","refs":[{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"El Tractat d’Amsterdam, signat el 2 d’octubre de 1997, reforma els tractats de la Unió i de creació, especialment en l’àmbit institucional"},{"ref":"p. 169","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=169","quote":"el Tractat de Niça, de 2001, torna a modificar els tractats fundacionals i de la Unió per poder adaptar les institucions comunitàries en la perspectiva de l’ampliació de la Unió Europea als països de l’est d’Europa."}]},{"text":"El Consell Europeu de Laeken (desembre de 2001) va encarregar a la Convenció sobre el Futur d''Europa un projecte de constitució. El projecte fusionava els tractats, donava a la UE personalitat jurídica única, incorporava la Carta de drets fonamentals i convertia la codecisió en procediment legislatiu normal. El rebuig dels ciutadans de França i Holanda la va deixar en un escenari imprevisible.","refs":[{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"El Consell Europeu de Laeken, reunit el desembre de 2001, va dictaminar que la Convenció sobre el Futur d’Europa presentés un projecte de tractat pel qual s’instituís una constitució per a Europa."},{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"el rebuig a la Constitució europea que van expressar els ciutadans de França i Holanda va situar la viabilitat d’aquesta norma bàsica en un escenari imprevisible."}]}]},{"n":"5","title":"El Tractat de Lisboa: innovacions institucionals","blocks":[{"text":"El Tractat de Lisboa (2007, en vigor el 2009) manté la majoria dels avenços de la Constitució, però sense cap referència al caràcter constitucional de la UE. Innovacions: presidència estable del Consell Europeu de dos anys i mig, amb una reelecció possible; reducció dels membres de la Comissió a partir de 2014, i elecció del president de la Comissió vinculada a les eleccions europees.","refs":[{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"no recull cap referència al caràcter constitucional de la UE."},{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"Presidència estable del Consell Europeu: dos anys i mig de durada amb possibilitat d’una reelecció."}]},{"text":"També preveu noves funcions per a l''alt representant per a la Política Exterior i de Seguretat Comuna, que és alhora vicepresident de la Comissió i té el suport del Servei Europeu d''Acció Exterior; doble majoria per a la majoria qualificada al Consell des de novembre de 2014 (55% dels estats i 65% de la població); majoria qualificada en gairebé 50 àrees noves; la codecisió com a procediment legislatiu ordinari; i més pes pressupostari del Parlament.","refs":[{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"Nou sistema de doble majoria per a les votacions per majoria qualificada al Consell de la UE a partir de novembre de 2014: 55% dels estats membres i 65% de la població UE."},{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"Generalització del procediment de codecisió –és a dir, la necessitat d’acord entre el Consell i el Parlament– com a procediment legislatiu ordinari."}]},{"text":"La UE té personalitat jurídica pròpia, i la Carta dels drets fonamentals té valor jurídic vinculant, tot i que no s''integra al Tractat i no s''aplica al Regne Unit ni a Polònia. S''obre la iniciativa legislativa ciutadana i una participació més gran dels parlaments nacionals.","refs":[{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"Es reconeix el valor jurídic vinculant de la Carta dels drets fonamentals de la Unió Europea, tot i que no s’integrarà al Tractat i no serà aplicable al Regne Unit ni a Polònia."},{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"la possibilitat d’iniciativa legislativa ciutadana"}]}]},{"n":"6","title":"Lisboa: competències, espai de seguretat i regions","blocks":[{"text":"Lisboa classifica les competències en exclusives, compartides i d''acció de suport, coordinació o complement. Són exclusives: unió duanera, normes de competència, política monetària, conservació dels recursos biològics marins (política pesquera comuna) i política comercial comuna. A més, introdueix una clàusula de solidaritat en cas d''atac terrorista o desastre natural.","refs":[{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"Es clarifiquen les competències de la Unió i es classifiquen en exclusives (unió duanera, normes de competència, política monetària, conservació dels recursos biològics marins en el marc de la política pesquera comuna i política comercial comuna), compartides i accions de suport, coordinació o complement."},{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"Introducció d’una nova clàusula de solidaritat en cas d’atac terrorista o desastre natural."}]},{"text":"Per a la cooperació policial i judicial, que interessa especialment a un policia, la guia cita: l''Oficina Europea de Policia (Europol), que dona suport a les policies nacionals; la Xarxa Judicial Europea contra delictes greus com la corrupció o el tràfic de drogues; i l''ordre europea de detenció, que substitueix els llargs processos d''extradició. Eurojust existeix des de 2001 per millorar la coordinació contra la criminalitat organitzada transfronterera.","refs":[{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"existeix el reconeixement de l’Oficina Europea de Policia (Europol), que pot donar suport a l’acció de les policies nacionals"},{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"disposa també de l’ordre europea de detenció, que substitueix els llargs processos d’extradició."},{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"Des de l’any 2001 existeix Eurojust com a òrgan de la Unió Europea encarregat de millorar l’eficàcia de les autoritats competents dels estats membres en la lluita contra la criminalitat organitzada transfronterera"}]},{"text":"Des de l''1 de juny de 2021 és operativa la Fiscalia Europea, òrgan independent que investiga i porta a judici els delictes contra els interessos financers de la UE: frau, corrupció, blanqueig de diners i frau transfronterer en l''IVA. Pel que fa a les regions, Lisboa recull el que demanava el Govern català: respecte a la identitat nacional, inclosa l''autonomia regional i local, i reconeixement de la diversitat cultural i lingüística, amb possibilitat de traduir els tractats a les llengües cooficials.","refs":[{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"Des de l’1 de juny de 2021, és operativa la Fiscalia Europea, un òrgan independent de la Unió Europea encarregat d’investigar els delictes que atempten contra els interessos financers de la UE"},{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"– Respecte a la identitat nacional dels estats membres, inclosa l’autonomia regional i local."}]}]},{"n":"7","title":"Les fonts: el dret comunitari originari","blocks":[{"text":"Les fonts del dret comunitari es divideixen en dret originari o primari (els tractats constitutius) i dret derivat o secundari (els actes normatius dels òrgans comunitaris). El dret originari actua com una espècie de constitució europea: regula l''organització, el funcionament i les competències de la Unió i ocupa un lloc preeminent en la jerarquia de fonts.","refs":[{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"Les fonts del dret comunitari europeu es divideixen entre dret originari (o primari), format pels tractats constitutius de la Unió, i dret derivat (o secundari), constituït per tots els actes normatius dictats pels òrgans comunitaris."},{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"el dret comunitari originari ocupa un lloc preeminent en la jerarquia normativa de les fonts del dret comunitari"}]},{"text":"El formen, amb eficàcia directa: CECA (París, 18-4-1951), CEE i EURATOM (Roma, 25-3-1957), Tractat de Brussel·les (8-4-1965), AUE (Luxemburg, 17-2-1986), Maastricht (7-2-1992), Amsterdam (2-10-1997), Niça (26-2-2001) i Lisboa (13-12-2007).","refs":[{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"– El Tractat de Niça, signat el 26 de febrer de 2001. – El Tractat de Lisboa, signat el 13 de desembre de 2007."}]}]},{"n":"8","title":"El dret comunitari derivat","blocks":[{"text":"El dret derivat és el conjunt d''actes que adopten les institucions per complir els objectius dels tractats; és derivat perquè hi està subordinat. Els actes obligatoris són tres. El reglament té abast general, és obligatori i directament aplicable a cada Estat sense cap acte de recepció, des de la seva aprovació i publicació al Diari Oficial.","refs":[{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"El conjunt d’actes adoptats per les institucions comunitàries per complir els objectius dels tractats constitueix el dret comunitari derivat."},{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"Reglaments: són actes que tenen abast general, són obligatoris i directament aplicables a cada Estat membre."}]},{"text":"La directiva vincula el destinatari però no té eficàcia immediata: imposa una obligació de resultat i deixa a cada Estat la manera i els mitjans, dins d''un termini. La decisió és un acte particular, obligatori per als destinataris (estats o persones físiques o jurídiques), amb efectes des de la notificació.","refs":[{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"Mitjançant les directives s’imposa als estats destinataris una obligació de resultat (aquests han d’assolir un determinat objectiu) i deixen a la seva elecció la manera i els mitjans per complir el que disposa la directiva."},{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"Decisions: són actes particulars, obligatoris per als seus destinataris, que poden ser estats membres o persones físiques o jurídiques."}]},{"text":"Els actes no obligatoris són les recomanacions, que orienten un comportament sense vincular, i els dictàmens, que valoren l''actuació d''un o més estats, sense efectes vinculants.","refs":[{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"Recomanacions: tracten d’orientar i promoure un determinat comportament. No tenen caràcter vinculant per als seus destinataris."}]}]},{"n":"9","title":"Relacions entre el dret comunitari i el dret intern","blocks":[{"text":"Hi ha tres principis: autonomia institucional, efecte directe i primacia. Per l''autonomia institucional, l''execució del dret comunitari segueix les regles internes sobre òrgans i procediment; a Espanya, respecta el repartiment de competències entre l''Estat i les comunitats autònomes.","refs":[{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"Les relacions entre el dret comunitari i el dret dels estats membres es regeixen per tres principis: l’autonomia institucional, l’efecte directe i la primacia."},{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"l’execució del dret comunitari pels estats membres s’ha d’adequar a les regles de dret intern respecte als òrgans competents i el procediment a seguir per a l’execució."}]},{"text":"L''efecte directe, en sentit formal, vol dir que les normes comunitàries s''integren sense acte de recepció; en sentit material, que creen directament drets i obligacions que apliquen els tribunals nacionals. Per la primacia, si una norma comunitària i una d''interna es contradiuen, s''aplica la comunitària; la interna no desapareix de l''ordenament, simplement no s''aplica en aquell cas.","refs":[{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"En un sentit material, l’efecte directe implica que les normes comunitàries creen directament drets i obligacions, i són aplicables directament pels tribunals dels estats membres"},{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"Això no implica que la norma interna deixi de formar part de l’ordenament, sinó que no és aplicable en la resolució d’aquell supòsit."}]}]},{"n":"10","title":"El Consell de la UE i la Comissió Europea","blocks":[{"text":"El Consell és l''òrgan intergovernamental: un representant per Estat, que actua seguint les instruccions del seu govern. És un únic Consell amb diverses composicions (ministres d''Afers Exteriors per a matèries generals, o els ministres de cada matèria). La presidència és rotatòria per sis mesos, i decideix preferentment per majoria qualificada amb vot ponderat. Té competències legislatives, d''execució, de coordinació i de relacions exteriors (aquestes, amb la Comissió).","refs":[{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"El Consell és l’òrgan intergovernamental en què els membres representen els interessos del seu Estat dins l’àmbit de la Unió Europea. Està integrat per un representant de cadascun dels estats membres."},{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"La Presidència del Consell correspon rotativament, per un període de sis mesos, a cadascun dels estats membres."}]},{"text":"La Comissió és independent dels estats i vetlla pels interessos comunitaris. Té 27 membres, un per Estat, des de la sortida del Regne Unit el 31 de gener de 2020. Els nomenen els governs de comú acord, després que el Parlament aprovi la composició, i actua per col·legialitat. Competències: iniciativa (el Consell aprova a proposta seva), control de l''aplicació dels tractats i execució en alguns sectors.","refs":[{"ref":"p. 174","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=174","quote":"Està integrada per 27 membres, arran de la sortida del Regne Unit el 31 de gener de 2020."},{"ref":"p. 174","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=174","quote":"a) D’iniciativa: els actes que aprova el Consell són a proposta de la Comissió."}]}]},{"n":"11","title":"El Parlament Europeu","blocks":[{"text":"El Parlament és la branca legislativa i una de les set institucions de la UE. La guia (juny 2026) diu que té 705 membres i que a Espanya li corresponen 59 escons (abans del Brexit, 751 i 54). Atenció: l''esmena oficial de setembre de 2026 corregeix el total a 720 eurodiputats. L''esmena no esmenta el nombre d''escons d''Espanya.","refs":[{"ref":"p. 174","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=174","quote":"El Parlament es compon de 705 membres (eurodiputats) en representació de tots els països de la Unió Europea."},{"ref":"p. 174","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=174","quote":"Actualment, a l’Estat espanyol li corresponen 59 escons"},{"ref":"","law":"Esmenes a la Guia d''estudi (setembre 2026)","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf","quote":"el Parlament Europeu té 720 membres."}]},{"text":"Els escons es reparteixen en proporció a la població, i els diputats s''elegeixen per sufragi universal directe a cada Estat. S''agrupen per ideologia, no per nacionalitat, i decideixen, com a regla general, per majoria absoluta dels vots emesos. Té competències de control polític (sobre la Comissió, i també sobre el Consell), legislatives i pressupostàries.","refs":[{"ref":"p. 174","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=174","quote":"Els diputats del Parlament s’agrupen en grups polítics per ideologies polítiques, no per nacionalitats."}]},{"text":"La funció legislativa té tres procediments: consulta (el Consell ha de demanar dictamen al Parlament), codecisió (aprovació conjunta Parlament-Consell) i dictamen conforme (el Parlament pot vetar la decisió del Consell).","refs":[{"ref":"p. 175","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=175","quote":"– Procediment de dictamen conforme: permet que el Parlament pugui vetar la decisió del Consell d’aprovar algunes normes."}]}]},{"n":"12","title":"El Tribunal de Justícia i altres institucions","blocks":[{"text":"El Tribunal de Justícia de la UE garanteix la interpretació i aplicació del dret comunitari, i moltes de les seves decisions han fet evolucionar l''ordenament. Té dos òrgans: el Tribunal de Justícia, amb vint-i-set jutges (un per país) i onze advocats generals, designats de comú acord pels governs; i el Tribunal General, amb dos jutges per Estat.","refs":[{"ref":"p. 175","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=175","quote":"El Tribunal de Justícia es compon de vint-i-set jutges (un per cada país) i onze advocats generals designats de comú acord pels governs dels estats membres"},{"ref":"p. 175","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=175","quote":"El Tribunal General es compon de dos jutges per cada Estat membre."}]},{"text":"Competències del Tribunal de Justícia: controlar les violacions del dret comunitari pels estats i la legalitat de les institucions; la cassació contra decisions del Tribunal de Primera Instància (nom que encara fa servir la guia); dictàmens sobre acords internacionals; i la qüestió prejudicial, que planteja un òrgan judicial d''un Estat que ha d''aplicar el dret comunitari en un litigi.","refs":[{"ref":"p. 175","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=175","quote":"e) De la qüestió prejudicial, quan un òrgan judicial d’un Estat membre que ha d’aplicar el dret comunitari en un litigi sol·licita al Tribunal de Justícia que es pronunciï"}]},{"text":"Altres institucions: el Defensor del Poble europeu, el Banc Central Europeu (política monetària), el Comitè Econòmic i Social, el Comitè de les Regions i l''Institut Europeu de la Igualtat de Gènere.","refs":[{"ref":"p. 175","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=175","quote":"– Banc Central Europeu, responsable de la política monetària europea."},{"ref":"p. 175","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=175","quote":"– El Comitè de les Regions, que representa les autoritats regionals i locals."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"CECA el 1951 (París); CEE i EURATOM a Roma el 25 de març de 1957.","refs":[{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"El Tractat constitutiu de la Comunitat Econòmica del Carbó i l’Acer (CECA), signat a París el 18 d’abril de 1951."}]},{"text":"Espanya: dret comunitari incorporat des de l''1 de gener de 1986 (LO 10/1985).","refs":[{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"Llei orgànica 10/1985, de 2 d’agost"}]},{"text":"Lisboa: signat el 13-12-2007, en vigor l''1-12-2009; doble majoria 55% estats / 65% població.","refs":[{"ref":"p. 168","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=168","quote":"El Tractat de Lisboa va entrar en vigor l’1 de desembre de 2009"}]},{"text":"Fiscalia Europea operativa des de l''1 de juny de 2021; Eurojust des de 2001.","refs":[{"ref":"p. 171","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=171","quote":"Des de l’1 de juny de 2021, és operativa la Fiscalia Europea"}]},{"text":"Reglament: directament aplicable; directiva: obligació de resultat; decisió: efectes des de la notificació.","refs":[{"ref":"p. 172","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=172","quote":"Els seus efectes jurídics comencen a partir de la notificació als destinataris."}]},{"text":"Principis: autonomia institucional, efecte directe i primacia.","refs":[{"ref":"p. 173","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=173","quote":"l’autonomia institucional, l’efecte directe i la primacia."}]},{"text":"Presidència del Consell de la UE: rotatòria cada sis mesos; Consell Europeu: presidència estable de dos anys i mig.","refs":[{"ref":"p. 170","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=170","quote":"dos anys i mig de durada amb possibilitat d’una reelecció."}]},{"text":"Parlament Europeu: 720 membres segons l''esmena de setembre de 2026 (la guia deia 705).","refs":[{"ref":"","law":"Esmenes a la Guia d''estudi (setembre 2026)","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf","quote":"el Parlament Europeu té 720 membres."}]},{"text":"TJUE: 27 jutges i 11 advocats generals; Tribunal General, dos jutges per Estat.","refs":[{"ref":"p. 175","law":"Guia d''estudi, tema B.8","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=175","quote":"onze advocats generals"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=167'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=167', 167, 176, 176, null
  from public.topics t where t.slug = 'mossos-b8-unio-europea'
