insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema C.1, pp. 177-182', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=177', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-c1-competencies-seguretat', 'C.1 Competències de la Generalitat en seguretat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('mossos-esquadra') and t.slug = 'mossos-c1-competencies-seguretat' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Definició de competència"},{"n":"2","title":"La competència en matèria de seguretat"},{"n":"2.1","title":"Les competències en matèria d’emergència i protecció civil"},{"n":"2.2","title":"Les competències en matèria de joc i espectacles"},{"n":"2.3","title":"Les competències en matèria de seguretat privada"},{"n":"2.4","title":"Les competències en matèria de seguretat pública"},{"n":"2.5","title":"Matèria de trànsit, circulació de vehicles i seguretat viària"}]'::jsonb, '["L’Estatut d’autonomia atorga competència a la Generalitat de Catalunya per crear una policia autònoma dins el marc del seu territori i li atorga no sols el comandament suprem d’aquesta nova policia, sinó també la coordinació de l’actuació de les policies locals o municipals.","La Generalitat de Catalunya assumeix, entre d’altres, una competència a hores d’ara prou clarificada: la protecció de persones i béns i el manteniment de l’ordre públic. Aquesta atribució competencial implica potestat per actuar en diversos àmbits: – Protecció civil i emergències (incloent-hi la prevenció i extinció d’incendis), salvament marítim i seguretat nuclear d’acord amb el contingut del nou Estatut. – Joc i espectacles. – Seguretat privada. – Policia, amb comandament directe sobre la Policia de la Generalitat - Mossos d’Esquadra i la coordinació de les policies locals. – Seguretat ciutadana i prevenció i investigació de delictes. – Trànsit i seguretat viària.","La responsabilitat de la Generalitat en aquest àmbit és territorial, és a dir, s’estén a tot el territori de Catalunya, en el marc del qual s’ubiquen les seves potestats i s’apliquen les seves normes. En conseqüència, és l’Administració l’encarregada de mantenir la cohesió territorial en matèria de seguretat, equilibrant les demandes i les necessitats locals i regionals quan puguin entrar en conflicte. El seu objectiu ha de ser mantenir nivells i serveis de seguretat homogenis a tot el territori."]'::jsonb, '["Competència","Matèria joc i espectacles","Protecció civil","Salvament marítim","Seguretat privada","Seguretat pública","Vigilància del trànsit"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Definició de competència","blocks":[{"text":"El tema parteix d''un concepte bàsic del dret públic: la competència. Quan diem que una administració és «competent» en una matèria volem dir que l''ordenament jurídic li ha atribuït un conjunt de funcions en aquell àmbit. Per tant, la competència sempre té tres elements: unes funcions, un subjecte públic que les exerceix i una matèria concreta.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"En el camp del dret públic, s’utilitza l’expressió competència per designar una idea concreta: el conjunt de funcions que l’ordenament jurídic atribueix a un subjecte públic en una determinada matèria."}]},{"text":"Aquesta definició és la clau per entendre la resta del tema: no n''hi ha prou de dir que la Generalitat «s''ocupa» de la seguretat, sinó que cal saber quina funció concreta té en cada matèria (exclusiva, executiva, de participació…) i quina norma li l''atribueix.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"el conjunt de funcions que l’ordenament jurídic atribueix a un subjecte públic en una determinada matèria."}]}]},{"n":"2","title":"El repartiment de competències: Constitució i Estatut","blocks":[{"text":"La Constitució espanyola (CE) dedica el títol VIII a l''organització territorial de l''Estat, i és al capítol III d''aquest títol on es determinen les competències exclusives de l''Estat i les que poden assumir les comunitats autònomes.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"El títol VIII de la Constitució espanyola fa referència a l’organització territorial de l’Estat i en el capítol III es determinen aquelles competències que són exclusives de l’Estat i les que poden ser assumides per les comunitats autònomes."}]},{"text":"El sistema funciona així: la CE dona a l''Estat un llistat de competències (article 149.1 CE), mentre que la norma que atribueix competències a la Generalitat és l''Estatut d''autonomia. Excepcionalment, també ho podria fer una llei estatal, per la via de l''article 150.1 i 2 CE. Aquesta excepció és important en seguretat, com veurem en el trànsit.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"La Constitució atribueix a l’Estat un llistat de competències (art. 149.1 CE), mentre que la norma atributiva de competències a la Generalitat de Catalunya és l’Estatut d’autonomia, encara que excepcionalment podria ser una llei estatal (art. 150.1 i 2 CE)."}]}]},{"n":"3","title":"La seguretat pública a la CE i a la Llei orgànica 2/1986","blocks":[{"text":"L''article 149.1.29 CE diu que l''Estat té competència exclusiva sobre la seguretat pública, però sens perjudici que les comunitats autònomes puguin crear policies tal com estableixin els seus estatuts i dins del marc d''una llei orgànica. Aquesta és la base constitucional de l''existència dels Mossos d''Esquadra.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"L’article 149.1.29 de la CE diu que l’Estat té competència exclusiva sobre la seguretat pública, sens perjudici que les comunitats autònomes puguin crear policies en la forma que els respectius estatuts estableixin dins el marc del que disposi una llei orgànica."}]},{"text":"Aquesta llei orgànica és la Llei orgànica 2/1986, de forces i cossos de seguretat, que es refereix a la policia autònoma de Catalunya a la disposició final segona. Aquesta disposició es redacta per executar el mandat de l''article 150 CE, que permet transferir o delegar a les comunitats autònomes matèries de titularitat estatal. En seguretat pública, la disposició final segona delega en l''Estatut i en les normes que el despleguin la capacitat per regular aquest àmbit.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"Així mateix, la Llei orgànica 2/1986 fa referència a la policia autònoma de Catalunya a la disposició final segona, que es redacta en virtut de l’execució del mandat constitucional de l’article 150 de la CE pel que fa a la seguretat."},{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"Aquest precepte constitucional reconeix la transferència o delegació de matèries de titularitat estatal a les comunitats autònomes."}]},{"text":"A partir d''aquí, la guia repassa les matèries de seguretat que l''Estatut d''autonomia atribueix a la Generalitat: emergències i protecció civil, joc i espectacles, seguretat privada, seguretat pública i trànsit.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"D’entre les matèries de les competències de la Generalitat que es recullen a l’Estatut d’autonomia de Catalunya, cal destacar:"}]}]},{"n":"4","title":"Emergències i protecció civil","blocks":[{"text":"En protecció civil la Generalitat té competència exclusiva. Aquesta competència inclou, en tot cas, la regulació, la planificació i l''execució de mesures relatives a les emergències i la seguretat civil, i la direcció i coordinació dels serveis de protecció civil, entre els quals hi ha els de prevenció i extinció d''incendis.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"Correspon a la Generalitat la competència exclusiva en matèria de protecció civil, que inclou, en tot cas, la regulació, la planificació i l’execució de mesures relatives a les emergències i la seguretat civil, i també la direcció i la coordinació dels serveis de protecció civil, que inclouen els serveis de prevenció i extinció d’incendis"}]},{"text":"Que sigui exclusiva no vol dir que no tingui límits: s''exerceix sens perjudici de les facultats dels governs locals en la matèria i respectant el que estableixi l''Estat en exercici de les seves competències de seguretat pública.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"sens perjudici de les facultats dels governs locals en aquesta matèria, respectant el que estableixi l’Estat en exercici de les seves competències en matèria de seguretat pública."}]}]},{"n":"5","title":"Salvament marítim i seguretat nuclear","blocks":[{"text":"Cal distingir bé el grau de competència en cada matèria, perquè és pregunta habitual. En salvament marítim, la Generalitat té competència executiva, en els termes que determini la legislació de l''Estat: l''Estat legisla i la Generalitat executa.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"Correspon a la Generalitat la competència executiva en matèria de salvament marítim, en els termes que determini la legislació de l’Estat."}]},{"text":"En seguretat nuclear el grau és encara menor: la Generalitat només participa en l''execució, en els termes acordats en els convenis subscrits amb aquesta finalitat i, si escau, en les lleis.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"La Generalitat participa en l’execució en matèria de seguretat nuclear, en els termes que siguin acordats en els convenis subscrits a aquest efecte i, si s’escau, en les lleis."}]}]},{"n":"6","title":"Joc, apostes i casinos","blocks":[{"text":"La Generalitat té competència exclusiva en joc, apostes i casinos, però amb una condició: que l''activitat es faci exclusivament a Catalunya. Inclou, en tot cas, la creació, autorització i regulació del joc i les apostes i de les empreses que els gestionen, exploten o comercialitzen material de joc (també el joc per mitjans informàtics i telemàtics); la regulació i el control de locals, instal·lacions i equipaments; i el règim fiscal de l''activitat de joc de les empreses, dins de les seves competències.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"Correspon a la Generalitat la competència exclusiva en matèria de joc, apostes i casinos, si l’activitat s’acompleix exclusivament a Catalunya"},{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"incloent-hi les modalitats de joc per mitjans informàtics i telemàtics."},{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"b) La regulació i el control dels locals, les instal·lacions i els equipaments utilitzats per acomplir aquestes activitats."}]},{"text":"Quan el joc és d''àmbit estatal, la Generalitat no decideix sola, però tampoc no queda al marge: autoritzar noves modalitats de joc i apostes estatals, o modificar-ne les existents, requereix deliberació a la Comissió Bilateral Generalitat-Estat (prevista al títol V de l''Estatut) i l''informe previ determinant de la Generalitat.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"L’autorització de noves modalitats de joc i apostes d’àmbit estatal, o bé la modificació de les existents, requereix la deliberació a la Comissió Bilateral Generalitat-Estat que estableix el títol V i l’informe previ determinant de la Generalitat."}]}]},{"n":"7","title":"Espectacles i activitats recreatives","blocks":[{"text":"També és exclusiva la competència en espectacles i activitats recreatives. Inclou, en tot cas, tres aspectes: l''ordenació del sector, el règim d''intervenció administrativa i el control de tota mena d''espectacles en espais i locals públics.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"Correspon a la Generalitat la competència exclusiva en matèria d’espectacles i activitats recreatives, que inclou, en tot cas, l’ordenació del sector, el règim d’intervenció administrativa i el control de tota mena d’espectacles en espais i locals públics."}]}]},{"n":"8","title":"Seguretat privada","blocks":[{"text":"En seguretat privada la Generalitat no legisla: li correspon l''execució de la legislació de l''Estat. Aquesta execució comprèn quatre funcions: autoritzar les empreses de seguretat privada amb domicili social a Catalunya i àmbit d''actuació que no ultrapassi Catalunya (calen les dues condicions); inspeccionar i sancionar les activitats de seguretat privada que es fan a Catalunya; autoritzar els centres de formació del personal de seguretat privada; i coordinar els serveis de seguretat i investigació privades amb la Policia de la Generalitat i les policies locals.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"Correspon a la Generalitat l’execució de la legislació de l’Estat en les matèries següents: a) L’autorització de les empreses de seguretat privada que tenen llur domicili social a Catalunya i l’àmbit d’actuació de les quals no ultrapassa el territori de Catalunya."},{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"b) La inspecció i la sanció de les activitats de seguretat privada que s’acompleixen a Catalunya. c) L’autorització dels centres de formació del personal de seguretat privada. d) La coordinació dels serveis de seguretat i investigació privades amb la Policia de la Generalitat i les policies locals de Catalunya."}]}]},{"n":"9","title":"La seguretat pública: l''article 164 de l''Estatut","blocks":[{"text":"L''article 164 de l''Estatut regula la seguretat pública. D''acord amb la legislació estatal, correspon a la Generalitat: la planificació i regulació del sistema de seguretat pública de Catalunya i l''ordenació de les policies locals; la creació i organització de la Policia de la Generalitat - Mossos d''Esquadra; i el control i la vigilància del trànsit.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"L’article 164 de l’Estatut d’autonomia de Catalunya estableix que en matèria de seguretat pública, d’acord amb el que disposa la legislació estatal, correspon a la Generalitat: a) La planificació i la regulació del sistema de seguretat pública de Catalunya i l’ordenació de les policies locals. b) La creació i l’organització de la Policia de la Generalitat - Mossos d’Esquadra. c) El control i la vigilància del trànsit."}]},{"text":"A més, li correspon el comandament suprem dels Mossos d''Esquadra i la coordinació de les policies locals, i les facultats executives que li atribueixi l''Estat dins la legislació de seguretat. En tot cas, té les funcions governatives sobre els drets de reunió i manifestació i el compliment de les disposicions de conservació de la natura, el medi ambient i els recursos hidrològics.","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"correspon a la Generalitat el comandament suprem de la Policia de la Generalitat - Mossos d’Esquadra i la coordinació de l’actuació de les policies locals"},{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"a) Les funcions governatives sobre l’exercici dels drets de reunió i manifestació. b) El compliment de les disposicions per a la conservació de la natura, del medi ambient i dels recursos hidrològics."}]}]},{"n":"10","title":"Junta de seguretat i àmbits d''actuació dels Mossos","blocks":[{"text":"La coordinació amb l''Estat es fa a través d''una junta de seguretat de composició paritària entre la Generalitat i l''Estat, presidida pel president de la Generalitat. Hi participa en la coordinació de les polítiques de seguretat i dels cossos policials de l''Estat i de Catalunya, en el bescanvi d''informació internacional i en la col·laboració amb policies d''altres països. A més, d''acord amb l''Estat, la Generalitat ha de ser present als grups de treball amb policies estrangeres en què participi l''Estat.","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"La Generalitat participa, per mitjà d’una junta de seguretat de composició paritària entre la Generalitat i l’Estat i presidida pel president de la Generalitat, en la coordinació de les polítiques de seguretat i de l’activitat dels cossos policíacs de l’Estat i de Catalunya"},{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"La Generalitat, d’acord amb l’Estat, ha d’ésser present en els grups de treball de col·laboració amb les policies d’altres països en què participi l’Estat."}]},{"text":"La Policia de la Generalitat - Mossos d''Esquadra actua a tot el territori de Catalunya i exerceix totes les funcions pròpies d''un cos de policia en tres àmbits: la seguretat ciutadana i l''ordre públic; la policia administrativa, inclosa la que deriva de normativa estatal; i la policia judicial i la investigació criminal, incloses les diverses formes de crim organitzat i terrorisme.","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"La Policia de la Generalitat - Mossos d’Esquadra té com a àmbit d’actuació el conjunt del territori de Catalunya i exerceix totes les funcions pròpies d’un cos de policia, en els àmbits següents: a) La seguretat ciutadana i l’ordre públic. b) La policia administrativa, que inclou la que deriva de la normativa estatal. c) La policia judicial i la investigació criminal, que inclou la investigació de les diverses formes de crim organitzat i terrorisme."}]}]},{"n":"11","title":"Trànsit, circulació de vehicles i seguretat viària","blocks":[{"text":"El trànsit és un bon exemple de com ha evolucionat una competència. L''antecedent és l''article 12.1.sisè de la Llei 10/1994, d''11 de juliol, de la Policia de la Generalitat - Mossos d''Esquadra, que atribueix al cos les funcions transferides o delegades per l''article 150.2 CE. Per aquesta via, la Llei orgànica 6/1997, de 15 de desembre, va transferir a la Generalitat les competències executives en trànsit i circulació de vehicles de motor.","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"l’article 12.1.sisè de la Llei 10/1994, d’11 de juliol, de la Policia de la Generalitat - Mossos d’Esquadra, estableix que corresponen al cos de Mossos d’Esquadra les funcions que siguin transferides o delegades per la via de l’article 150.2 de la Constitució."},{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"mitjançant la Llei orgànica 6/1997, de 15 de desembre, l’Estat va transferir a la Generalitat les competències executives en matèria de trànsit i circulació de vehicles de motor"}]},{"text":"La transferència en va excloure tres matèries que l''Estat es reserva: els permisos i llicències per conduir, l''examen per obtenir el permís de conduir, i la matriculació i expedició de permisos o llicències de circulació.","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"llevat del que fa referència a permisos i llicències per conduir, examen per a l’obtenció del permís de conduir i matriculació i expedició de permisos o llicències de circulació."}]},{"text":"Per gestionar aquesta nova competència, la Llei 14/1997, de 24 de desembre, va crear l''organisme autònom Servei Català de Trànsit, dins de l''antic Departament de Governació. Amb l''Estatut actual, el control i la vigilància del trànsit han deixat de ser competències delegades i són competències pròpies de la Generalitat (article 164.1).","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"Mitjançant la Llei 14/1997, de 24 de desembre, es va crear un organisme autònom denominat Servei Català de Trànsit."},{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"l’actual Estatut d’autonomia de Catalunya disposa que el control i la vigilància del trànsit són competències pròpies de la Generalitat, i deixen de ser competències delegades, d’acord amb l’article 164.1."}]},{"text":"Segons les idees força, la responsabilitat de la Generalitat en seguretat és territorial: s''estén a tot Catalunya, i l''Administració ha de mantenir la cohesió territorial equilibrant demandes locals i regionals, amb l''objectiu de garantir nivells i serveis de seguretat homogenis a tot el territori.","refs":[{"ref":"p. 182","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=182","quote":"El seu objectiu ha de ser mantenir nivells i serveis de seguretat homogenis a tot el territori."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Competència = conjunt de funcions que l''ordenament atribueix a un subjecte públic en una matèria.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"s’utilitza l’expressió competència per designar una idea concreta"}]},{"text":"Les competències es reparteixen al capítol III del títol VIII CE; la norma atributiva per a la Generalitat és l''Estatut (excepcionalment, una llei estatal).","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"en el capítol III es determinen aquelles competències que són exclusives de l’Estat"}]},{"text":"Seguretat pública: article 149.1.29 CE (Estat) i article 164 de l''Estatut (Generalitat); la LO 2/1986 parla dels Mossos a la disposició final segona.","refs":[{"ref":"p. 179","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=179","quote":"la disposició final segona de la Llei orgànica 2/1986"}]},{"text":"Protecció civil i espectacles: competència exclusiva; salvament marítim: executiva; seguretat nuclear: participació en l''execució.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"Correspon a la Generalitat la competència executiva en matèria de salvament marítim"}]},{"text":"Joc: exclusiva si l''activitat es fa només a Catalunya; joc estatal nou: Comissió Bilateral i informe previ determinant.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"l’informe previ determinant de la Generalitat."}]},{"text":"Seguretat privada: execució de la legislació estatal; autoritza empreses amb domicili social i àmbit d''actuació a Catalunya.","refs":[{"ref":"p. 180","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=180","quote":"Correspon a la Generalitat l’execució de la legislació de l’Estat"}]},{"text":"La junta de seguretat és paritària i la presideix el president de la Generalitat.","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"presidida pel president de la Generalitat"}]},{"text":"Trànsit: LO 6/1997 (transferència), Llei 14/1997 (Servei Català de Trànsit); avui, competència pròpia per l''article 164.1.","refs":[{"ref":"p. 181","law":"Guia d''estudi, tema C.1","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=181","quote":"Llei 14/1997, de 24 de desembre"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=177'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=177', 177, 182, 182, null
