insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Funcions del Departament d’Interior i Seguretat Pública"},{"n":"2","title":"Estructura del Departament d’Interior i Seguretat Pública"},{"n":"3","title":"Funcions i estructura de la Direcció General de la Policia"},{"n":"4","title":"La Policia de la Generalitat - Mossos d’Esquadra"},{"n":"4.1","title":"Transformacions i evolució del cos de Mossos d’Esquadra"},{"n":"4.2","title":"Missió, visió i valors"},{"n":"4.3","title":"Compromisos amb la ciutadania"},{"n":"5","title":"L’Institut de Seguretat Pública de Catalunya"},{"n":"5.1","title":"Estructura de l’Institut de Seguretat Pública de Catalunya"},{"n":"5.2","title":"L’Escola de Policia de Catalunya"},{"n":"5.3","title":"L’Escola de Bombers, Protecció Civil i Agents Rurals de Catalunya"},{"n":"5.4","title":"La Subdirecció General d’Estudis Universitaris, Recerca i Desenvolupament"},{"n":"5.5","title":"La Subdirecció General d’Administració i Serveis"},{"n":"6","title":"El Servei Català de Trànsit"},{"n":"7","title":"Centre d’Atenció i Gestió de Trucades d’Urgència 112 Catalunya"}]'::jsonb, '["L’Institut de Seguretat Pública de Catalunya és l’encarregat d’estudiar la selecció i el procés formatiu exigible als cossos de policia i al personal de protecció del medi natural, de protecció civil i de prevenció i extinció d’incendis i de salvaments.","Depenen de l’Institut els òrgans següents: a) L’Escola de Policia de Catalunya. b) L’Escola de Bombers, Protecció Civil i Agents Rurals de Catalunya. c) La Subdirecció General d’Estudis Universitaris, Recerca i Desenvolupament. d) La Subdirecció General d’Administració i Serveis.","L’Escola de Policia de Catalunya dirigeix la detecció de les necessitats formatives, dissenya el contingut docent, i supervisa els processos d’avaluació dintre de l’àmbit de la seguretat.","L’Escola de Bombers, Protecció Civil i Agents Rurals de Catalunya dirigeix la detecció de les necessitats formatives, dissenya el contingut docent, i supervisa els processos d’avaluació dintre de l’àmbit de la prevenció, la protecció del medi natural i l’extinció d’incendis i de salvaments.","La Subdirecció General d’Administració i Serveis és responsable de la gestió integral dels recursos humans, econòmics, materials i jurídics de l’Institut, així com de la planificació pressupostària, la contractació i el manteniment de les infraestructures.","La Subdirecció General d’Estudis Universitaris, Recerca i Desenvolupament impulsa, coordina i gestiona la formació universitària, la recerca i la innovació en l’àmbit de la seguretat pública.","El Servei de Selecció i Avaluació és el responsable de planificar i d’executar l’avaluació del perfil de competències clau de l’alumnat dels cursos de formació bàsica de l’Institut.","La transferència de competències executives a la Generalitat en matèria de trànsit, circulació de vehicles i seguretat viària es va realitzar per la via de l’article 150.2 de la Constitució espanyola mitjançant la Llei orgànica de transferència de competències executives en matèria de trànsit i circulació de vehicles de motor a la Comunitat Autònoma de Catalunya.","El Servei Català de Trànsit és un organisme autònom de caràcter administratiu adscrit al Departament d’Interior i Seguretat Pública.","El Servei Català del Trànsit té adscrits l’Observatori de la Seguretat Viària, la Comissió Catalana de Trànsit i Seguretat Viària i la Comissió Inter departamental per a la millora de la Seguretat Viària.","El Centre d’Atenció i Gestió de Trucades d’Urgència 112 Catalunya és una entitat de dret públic dotada de personalitat jurídica pròpia i plena capacitat d’obrar per complir les seves funcions amb patrimoni i tresoreria propis i amb autonomia de gestió per assolir les seves finalitats, l’activitat del qual es regeix pel dret privat amb caràcter general.","El Centre d’Atenció i Gestió de Trucades d’Urgència 112 Catalunya s’adscriu al Departament d’Interior i Seguretat Pública, com a òrgan competent en matèria de seguretat pública."]'::jsonb, '["112","Adscripció","Assistència","Atenció","Avís","Centralització","Circulació de vehicles","Comandament operatiu","Competència","Consell de Direcció","Delinqüència ordinària, especialitzada i organitzada","Direcció General","Dret públic","Emergència","Extinció d’incendis","Gabinet del Conseller","Lliure exercici dels drets i llibertats","Mortalitat","Multa","Organisme autònom","Organisme","Organitzacions criminals","Percepció de seguretat","Pla estratègic","Protecció civil","Proximitat","Recursos humans","Recursos materials","Relacions amb la comunitat","Salvament","Sanció","Sancions disciplinàries","Secretaria General","Seguretat ciutadana","Seguretat pública","Seguretat viària","Serveis de gala i honors","Sub-direcció general","Telèfon únic","Transferència de competències executives","Trànsit","Trucada d’urgència","Urgència sanitària","Violència de gènere"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Funcions i estructura del Departament d''Interior i Seguretat Pública i de la Direcció General de la Policia","blocks":[{"text":"Les funcions genèriques del Departament d''Interior i Seguretat Pública són al Decret 133/2024, d''11 d''agost, de creació i determinació de l''àmbit dels departaments. Són set: seguretat ciutadana; trànsit; emergències i protecció civil; prevenció, extinció d''incendis i salvament; espectacles públics i activitats recreatives; vigilància i control del medi natural i protecció del medi ambient mitjançant el Cos d''Agents Rurals; i qualsevol altra que li atribueixin les lleis. Atenció: els Agents Rurals depenen d''Interior.","refs":[{"ref":"1. Funcions del Departament, p. 184","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=184","quote":"Les funcions genèriques del Departament d’Interior i Seguretat Pública de la Generalitat de Catalunya es recullen en el Decret 133/2024, d’11 d’agost"},{"ref":"1. Funcions del Departament, p. 184","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=184","quote":"– La vigilància, control i col·laboració en la gestió del medi natural, i la protecció i prevenció integrals del medi ambient, mitjançant el Cos d’Agents Rurals."}]},{"text":"L''estructura del Departament la fixa el Decret 12/2023, de 24 de gener: Secretaria General, Direcció de Serveis i, entre d''altres, les direccions generals de Prevenció, Extinció d''Incendis i Salvaments, de Protecció Civil, d''Administració de Seguretat, de Coordinació de les Policies Locals i dels Agents Rurals. La guia només remet als articles del decret i no en desenvolupa el contingut. La Direcció General de la Policia es regeix pel Decret 57/2023, de 21 de març, que inclou la Prefectura, les comissaries superiors i generals, les regions policials, les ABP i la Regió Policial Virtual.","refs":[{"ref":"2. Estructura del Departament, p. 184","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=184","quote":"Vegeu el Decret 12/2023, de 24 de gener, de reestructuració del Departament d’Interior i Seguretat Pública"},{"ref":"2. Estructura del Departament, p. 184","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=184","quote":"– 85. Direcció General de Protecció Civil"},{"ref":"3. Direcció General de la Policia, p. 185","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=185","quote":"El Decret 57/2023, de 21 de març, de reestructuració de la Direcció General de la Policia, en recull les funcions i l’estructura actuals."}]}]},{"n":"2","title":"Orígens dels Mossos d''Esquadra (1719-1836)","blocks":[{"text":"El nom de Mossos d''Esquadra neix el 1719 amb una força armada de civils i paisans, vestits de manera militar, per protegir rutes comercials, fires i mercats. Després de la caiguda de Barcelona (11 de setembre de 1714), el 21 d''abril de 1719 el capità general de Catalunya crea el cos per mantenir l''ordre públic, en substitució del sometent, i perseguir els darrers miquelets austriacistes. S''organitzava en esquadres de paisans; hi destaca Pere Anton Veciana, filipista, després comandant en cap.","refs":[{"ref":"4.1.1 Orígens, p. 186","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=186","quote":"el 21 d’abril de 1719, el capità general de Catalunya crea el cos de Mossos d’Esquadra, amb la finalitat de mantenir l’ordre públic, en substitució de la institució catalana del sometent"}]},{"text":"En els orígens era un institut armat de naturalesa civil amb doble dependència, civil i militar, i depenia de la Reial Audiència del Principat de Catalunya com a força de policia judicial. El juliol de 1721 es dissolen les esquadres excepte les de Cardona i Valls, reorganitzades el 24 de desembre de 1721 com a Escuadras de Paisanos Armados: per això és una de les policies més antigues d''Europa. El primer Reglament és del 8 de juny de 1719 i un de nou, del 27 de maig de 1817. El 1836 la família Veciana renuncia al comandament després de 115 anys ininterromputs.","refs":[{"ref":"4.1.1 Orígens, p. 186","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=186","quote":"Depèn de la Reial Audiència del Principat de Catalunya, com a força de policia judicial."},{"ref":"4.1.1 Orígens, p. 186","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=186","quote":"L’any 1836, la família Veciana renuncia al comandament dels Mossos d’Esquadra, després de 115 anys al capdavant del cos ininterrompudament."}]}]},{"n":"3","title":"De l''abolició de 1868 a la Llei 19/1983","blocks":[{"text":"El 1868, amb la Gloriosa, el general Prim va abolir el cos, que considerava d''adscripció monàrquica, i el va substituir per la Guàrdia Civil. El 1877 només es restableix a la Diputació de Barcelona. La Mancomunitat (1914) el manté. El 14 d''octubre de 1932 el president Francesc Macià signa el decret de desplegament a tot el territori català; els fets d''octubre de 1934 ho impedeixen. Durant la Guerra Civil és l''única força armada no destinada al front i passa d''uns 300 a un miler d''efectius; el 1939 s''exilia amb Companys i el cos és dissolt.","refs":[{"ref":"4.1.1 Orígens, p. 186","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=186","quote":"l’any 1868 va ser abolit per ordre del mateix general Prim"},{"ref":"4.1.1 Orígens, p. 187","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=187","quote":"El 14 d’octubre de 1932, el president de la Generalitat de Catalunya, Francesc Macià, va signar el decret de desplegament del cos de Mossos d’Esquadra a tot el territori català."}]},{"text":"El 21 de juliol de 1950 un decret autoritza la Diputació de Barcelona a organitzar una Sección de Mozos de Escuadra de 40 efectius, de caràcter militar, que comença a servir per Sant Jordi de 1952 (50 efectius el 1961). El Dia de les Esquadres era el 21 d''abril (primera celebració, 1976); el Decret 64/2005, de 19 d''abril, el fixa el 22 d''abril. L''Estatut de 1979 (article 13) preveu una Policia Autonòmica; el RD 2579/1980 transfereix la Secció a la Generalitat; el 1982 se''n fa el traspàs efectiu, i la Llei 19/1983, de 14 de juliol, crea la Policia Autonòmica, que n''adopta el nom i els efectius.","refs":[{"ref":"4.1.1 Orígens, p. 188","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=188","quote":"Aquesta estava constituïda per 40 efectius i va començar a prestar servei el dia de Sant Jordi de 1952"},{"ref":"4.1.1 Orígens, p. 188","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=188","quote":"mitjançant el Decret 64/2005, de 19 d’abril, en què s’estableix el dia 22 d’abril com el Dia de les Esquadres."},{"ref":"4.1.1 Orígens, p. 188","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=188","quote":"El 1983, amb la Llei 19/1983, de 14 de juliol, es crea la Policia Autonòmica de la Generalitat de Catalunya."}]}]},{"n":"4","title":"1983-1994: refundació i etapa moderna","blocks":[{"text":"El nou cos neix el 1983 amb 364 efectius i funcions específiques: protecció d''edificis i personalitats, joc, menors i patrimoni. El 1985 es convoca la segona promoció, amb accés de les dones per primer cop, es crea l''Escola de Policia de Catalunya a Mollet del Vallès i el Parlament aprova la Resolució 39/II, primera pedra del model policial català: totes les forces polítiques volen que la PG-ME substitueixi les FCSE. La LO 2/1986 i el bloqueig de promocions a la Junta de Seguretat obren una etapa d''estancament fins al 1989.","refs":[{"ref":"4.1.2 Refundació, p. 189","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=189","quote":"Es convoca la segona promoció dels Mossos d’Esquadra –és el primer cop que es permet l’accés al cos per a les dones–"},{"ref":"4.1.2 Refundació, p. 189","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=189","quote":"el Parlament de Catalunya aprova la Resolució 39/II, que posa la primera pedra del que després s’anomenarà el model policial català."}]},{"text":"El 1990 és un punt d''inflexió: es delimiten funcions i Mossos assumeix el trasllat de presos i el tractament policial dels menors (d''edat penal, 14-18 anys, i d''edat civil, 0-18). El 1992 funciona la central operativa del carrer de Bolívia. El 1993 s''obren comissaries a la Vall d''Aran, Osona i el Montsià i s''inicia la Llei 10/1994. Els acords de la Junta de Seguretat de 17 d''octubre de 1994 fixen el primer desplegament de substitució, el 4 de desembre a Osona, en forma de taca d''oli.","refs":[{"ref":"4.1.2 Refundació, p. 189","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=189","quote":"el trasllat de presos i el tractament policial dels menors d’edat penal (entre 14 i 18 anys)"},{"ref":"4.1.2 Refundació, p. 189","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=189","quote":"per al 4 de desembre a la comarca d’Osona"}]}]},{"n":"5","title":"1994-2008: de policia funcional a policia integral","blocks":[{"text":"El cos passa de policia funcional a integral, amb serveis territorials (proximitat, ABP i regions policials) i serveis centrals (especialitats i suport). Es creen divisions com la Central d''Investigació, Afers Interns o Trànsit, i el cos passa de Governació a la nova Conselleria d''Interior; el Decret 19/2002 crea la Sub-direcció General de la Policia. La primera fase del desplegament (1994-1998) cobreix les comarques gironines i de Ponent; la Junta de l''1 de juliol de 1999 el reorienta cap a l''entorn de Barcelona.","refs":[{"ref":"4.1.3 Policia integral, p. 190","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=190","quote":"passa d’un model de policia funcional a un de policia integral."}]},{"text":"El 27 de juny de 2004 la PG-ME patrulla per primer cop a Barcelona, dins del dispositiu Turisme amb el CNP i la Guàrdia Urbana; l''any següent s''hi inicia el desplegament (deu comissaries, una per districte). El Camp de Tarragona i les Terres de l''Ebre tanquen el desplegament el novembre de 2008. L''Estatut de 2006 dona com a funció pròpia la policia judicial i la investigació criminal. En trànsit, la LO 6/1997 transfereix la competència, la Llei 14/1997 crea el Servei Català de Trànsit i el RD 391/1998 tanca el traspàs; el primer relleu és a Figueres el 4 de maig de 1998 i el 2000 ja abasta tot Catalunya.","refs":[{"ref":"4.1.3 Policia integral, p. 190","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=190","quote":"El 27 de juny de 2004, agents de la Policia de la Generalitat - Mossos d’Esquadra comencen a patrullar per primera vegada a Barcelona, dins del dispositiu Turisme"},{"ref":"4.1.3 Policia integral, p. 190","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=190","quote":"Les comarques del Camp de Tarragona i de les Terres de l’Ebre conclouen el desplegament territorial el novembre de 2008."}]}]},{"n":"6","title":"2008-2030: consolidació i policia del futur","blocks":[{"text":"El model de seguretat de 2008-2017 té quatre punts: visió integral, seguretat objectiva i percebuda, preparació per prevenir, reaccionar i investigar, i corresponsabilització social. El Decret 415/2011 crea la Prefectura de la Policia (direcció estratègica i comandament operatiu). L''octubre de 2009 entra a ple rendiment el Complex Central, a Sabadell, nucli dels serveis especialitzats.","refs":[{"ref":"4.1.4 Consolidació, p. 192","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=192","quote":"Es crea la Prefectura de la Policia, a qui correspon la direcció estratègica i el comandament operatiu"},{"ref":"4.1.4 Consolidació, p. 192","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=192","quote":"És un conjunt d’edificis situat al municipi de Sabadell"}]},{"text":"El 2018 s''inicia un nou desplegament. La Junta de Seguretat acorda el 5 de novembre de 2021 ampliar el màxim d''efectius a 22.006; el 2022 arriba la jubilació anticipada i el Pla Mossos 2030 (proximitat, transformació digital, diversitat i feminització, intel·ligència, ciberdelinqüència i medi ambient, transparència). El 3 de febrer de 2023 canvia la uniformitat operativa, i el Decret 57/2023 reestructura la DGP.","refs":[{"ref":"4.1.5 Policia del futur, p. 193","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=193","quote":"la Junta de Seguretat de Catalunya acorda, el 5 de novembre de 2021, ampliar el nombre màxim d’efectius del cos de Mossos d’Esquadra a 22.006."}]}]},{"n":"7","title":"Missió, visió i valors","blocks":[{"text":"La missió és la raó de ser (qui som i què fem); la visió, què volem ser a mig termini; els valors, com som i els límits ètics. Es recullen a la Carta de Serveis. La missió de la PG-ME és fer de Catalunya un país segur, protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana, des de la proximitat. La visió, ser una policia de referència. Els valors: proximitat, compromís, integritat (no treure profit de la condició de policia), voluntat de servei i eficàcia.","refs":[{"ref":"4.2 Missió, visió i valors, p. 194","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=194","quote":"té com a missió fer de Catalunya un país segur, protegir el lliure exercici dels drets i les llibertats i garantir la seguretat ciutadana"},{"ref":"4.2 Missió, visió i valors, p. 194","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=194","quote":"Els seus valors estan basats en la proximitat, el compromís, la integritat, el servei i l’eficàcia"}]}]},{"n":"8","title":"Compromisos amb la ciutadania: Pla general, Carta de Serveis i SGQ","blocks":[{"text":"Els compromisos són tres: el Pla general de seguretat de Catalunya (quadriennal, amb la PG-ME com a actor clau), la Carta de Serveis (instrument de qualitat centrat en la satisfacció ciutadana) i el Sistema de gestió de la qualitat de la DGP. La Carta inclou compromisos com l''atenció ininterrompuda, la identificació dels agents, l''atenció en llengües estrangeres o la prioritat de les ordres de protecció per violència masclista.","refs":[{"ref":"4.3.1 Pla general de seguretat, p. 195","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=195","quote":"La seva periodicitat és quadriennal"}]},{"text":"L''SGQ té dos processos, per la vulnerabilitat de les persones afectades: la detenció, amb l''aplicació Sistema d''Imputació i Seguiment de Detencions (SISD) per seguir el procés integral de la detenció; i l''atenció a víctimes de violència masclista, domèstica i altres víctimes vulnerables, amb el Sistema Integral d''Atenció a les Víctimes (SIAV).","refs":[{"ref":"4.3.3.1 Procés de detenció, p. 196","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=196","quote":"Com a element de suport per al seguiment d’aquest procés integral de la detenció es disposa de l’aplicació informàtica Sistema d’Imputació i Seguiment de Detencions (SISD)."},{"ref":"4.3.3.2 Atenció a les víctimes, p. 197","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=197","quote":"l’aplicació informàtica Sistema Integral d’Atenció a les Víctimes (SIAV)."}]}]},{"n":"9","title":"L''Institut de Seguretat Pública de Catalunya: creació i estructura","blocks":[{"text":"La Llei 10/2007, de 30 de juliol, crea l''ISPC com a entitat autònoma de caràcter administratiu adscrita al departament de seguretat pública. Defineix els processos selectius i perfils professionals dels cossos de policia, del cos d''Agents Rurals i del personal de protecció civil i d''extinció d''incendis i salvaments, i programa la seva formació bàsica, de promoció, d''especialització i contínua. Segons el Decret 240/2024, de 4 de novembre, del director depenen l''Escola de Policia, l''Escola de Bombers, Protecció Civil i Agents Rurals, la Subdirecció General d''Estudis Universitaris, Recerca i Desenvolupament i la Subdirecció General d''Administració i Serveis.","refs":[{"ref":"5. L’ISPC, p. 197","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=197","quote":"Per la Llei 10/2007, de 30 de juliol, es va crear l’Institut de Seguretat Pública de Catalunya com a entitat autònoma de caràcter administratiu adscrita al departament competent en matèria de seguretat pública."},{"ref":"5. L’ISPC, p. 197","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=197","quote":"dels cossos de policia, del cos d’Agents Rurals i del personal de protecció civil i de prevenció i extinció d’incendis i salvaments"},{"ref":"5.1 Estructura de l’ISPC, p. 197","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=197","quote":"c) La Subdirecció General d’Estudis Universitaris, Recerca i Desenvolupament. d) La Subdirecció General d’Administració i Serveis."}]}]},{"n":"10","title":"Escoles i subdireccions de l''ISPC","blocks":[{"text":"L''Escola de Policia dirigeix la detecció de necessitats formatives en seguretat; en depenen l''Àrea d''Instructors de Policia, l''Àrea de Continguts de Formació Policial i el Servei de Formació Policial. L''Escola de Bombers, Protecció Civil i Agents Rurals fa el mateix en incendis, salvaments i medi natural; en depenen, entre d''altres, el Servei de Formació de Protecció Civil.","refs":[{"ref":"5.2 Escola de Policia, p. 198","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=198","quote":"a) L’Àrea d’Instructors de Policia."},{"ref":"5.3 Escola de Bombers, p. 198","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=198","quote":"b) El Servei de Formació de Protecció Civil."},{"ref":"Idees força C.2 (4), p. 203","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=203","quote":"L’Escola de Bombers, Protecció Civil i Agents Rurals de Catalunya dirigeix la detecció de les necessitats formatives"}]},{"text":"La Subdirecció General d''Estudis Universitaris, Recerca i Desenvolupament impulsa la formació universitària, la recerca i la innovació; en depèn el Servei de Selecció i Avaluació, que avalua les competències clau de l''alumnat i supervisa el suport tècnic per avaluar les condicions psicològiques per a l''ús d''armes de foc. La Subdirecció General d''Administració i Serveis gestiona els recursos humans, econòmics, materials i jurídics.","refs":[{"ref":"5.4 Subdirecció d’Estudis Universitaris, p. 198","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=198","quote":"planifica i supervisa el suport tècnic per a l’avaluació de les condicions psicològiques necessàries per a l’ús d’armes de foc dels cossos de policia de Catalunya."}]}]},{"n":"11","title":"El Servei Català de Trànsit","blocks":[{"text":"La transferència de competències executives de trànsit es va fer per la via de l''article 150.2 de la Constitució (LO 6/1997, de 15 de desembre). El Servei Català de Trànsit és un organisme autònom de caràcter administratiu adscrit a Interior, creat per la Llei 14/1997, de 24 de desembre. Impulsa cada tres anys el Pla de seguretat viària, amb tres línies: velocitat excessiva o inadequada, cooperació amb els ajuntaments i criteris mediambientals. El PSV 2021-2023 volia reduir un 15% les víctimes mortals, amb horitzó zero el 2050 (la guia no esmenta cap pla posterior).","refs":[{"ref":"6. El Servei Català de Trànsit, p. 199","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=199","quote":"per la via de l’article 150.2 de la Constitució espanyola"},{"ref":"6. El Servei Català de Trànsit, p. 199","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=199","quote":"El Servei Català de Trànsit és un organisme autònom de caràcter administratiu adscrit al Departament d’Interior i Seguretat Pública, creat a l’empara de la Llei 14/1997, de 24 de desembre."},{"ref":"6. El Servei Català de Trànsit, p. 199","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=199","quote":"impulsar l’elaboració, cada tres anys, del Pla de seguretat viària"},{"ref":"6. El Servei Català de Trànsit, p. 199","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=199","quote":"a) Lluita contra la velocitat excessiva o inadequada."}]},{"text":"Té tres subdireccions (Serveis, Gestió del Trànsit i Seguretat Viària) i quatre serveis territorials (Barcelona, Tarragona, Lleida i Girona), cadascun amb una Secció de Seguretat Viària i una de Procediment. Els delegats territorials del Govern imposen les sancions de trànsit. Té adscrits l''Observatori de la Seguretat Viària, la Comissió Catalana de Trànsit i Seguretat Viària (òrgan consultiu i de participació superior) i la Comissió Interdepartamental per a la Millora de la Seguretat Viària.","refs":[{"ref":"6. El Servei Català de Trànsit, p. 200","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=200","quote":"s’estructura en quatre serveis territorials de Trànsit (Barcelona, Tarragona, Lleida i Girona), que a la vegada s’estructuren cadascun d’ells en la Secció de Seguretat Viària i la Secció de Procediment."},{"ref":"6. El Servei Català de Trànsit, p. 200","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=200","quote":"Els delegats territorials del Govern de la Generalitat són competents, sens perjudici de les competències municipals, per imposar multes i sancions"},{"ref":"6. El Servei Català de Trànsit, p. 200","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=200","quote":"b) La Comissió Catalana de Trànsit i Seguretat Viària. És l’òrgan consultiu i de participació superior a Catalunya en matèria de trànsit, circulació i seguretat viària"}]}]},{"n":"12","title":"El Centre d''Atenció i Gestió de Trucades d''Urgència 112 Catalunya","blocks":[{"text":"La Decisió 91/396/CEE va imposar el 112 com a número europeu únic. A Catalunya el regula la Llei 9/2007, del 30 de juliol. El 085 (Bombers) i el 088 (Mossos) van deixar d''estar actius el 30 de setembre de 2012. El Centre és una entitat de dret públic amb personalitat jurídica pròpia, adscrita a Interior, l''activitat de la qual es regeix pel dret privat amb caràcter general. El servei és públic, gratuït, universal i permanent, amb centres a Reus i Barcelona.","refs":[{"ref":"7. Centre 112, p. 201","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=201","quote":"mitjançant la Llei 9/2007, del 30 de juliol, del Centre d’Atenció i Gestió de Trucades d’Urgència 112 Catalunya."},{"ref":"7. Centre 112, p. 201","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=201","quote":"van deixar d’estar actius a partir del 30 de setembre de 2012."},{"ref":"Idees força C.2 (11), p. 203","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=203","quote":"l’activitat del qual es regeix pel dret privat amb caràcter general."},{"ref":"7. Centre 112, p. 201","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=201","quote":"té centres actius a Reus i Barcelona."}]},{"text":"Els òrgans de govern són el president, el vicepresident, el Consell Rector i la Comissió Executiva. La Comissió Executiva la presideix el secretari competent en matèria de protecció civil, i el director del Servei Català de la Salut n''és el vicepresident.","refs":[{"ref":"7. Centre 112, p. 202","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=202","quote":"La Comissió Executiva està integrada pel secretari competent en matèria de protecció civil, que n’exerceix la presidència"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Funcions del Departament: Decret 133/2024; estructura: Decret 12/2023; DGP: Decret 57/2023, de 21 de març.","refs":[{"ref":"p. 185","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=185","quote":"Decret 57/2023, de 21 de març, de reestructuració de la Direcció General de la Policia"}]},{"text":"Creació del cos: 21 d''abril de 1719, pel capità general de Catalunya; abolit pel general Prim el 1868.","refs":[{"ref":"p. 186","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=186","quote":"el 21 d’abril de 1719, el capità general de Catalunya crea el cos de Mossos d’Esquadra"}]},{"text":"Dia de les Esquadres: 22 d''abril (Decret 64/2005).","refs":[{"ref":"p. 188","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=188","quote":"s’estableix el dia 22 d’abril com el Dia de les Esquadres."}]},{"text":"1985: segona promoció, primeres dones i Resolució 39/II del Parlament.","refs":[{"ref":"p. 189","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=189","quote":"aprova la Resolució 39/II"}]},{"text":"Primer desplegament de substitució: Osona (1994); final: Camp de Tarragona i Terres de l''Ebre (novembre de 2008).","refs":[{"ref":"p. 189","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=189","quote":"També s’acorda el primer desplegament de substitució de les forces i cossos de seguretat de l’Estat"},{"ref":"p. 190","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=190","quote":"Les comarques del Camp de Tarragona i de les Terres de l’Ebre conclouen el desplegament territorial el novembre de 2008."},{"ref":"p. 231","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=231","quote":"Des de l’any 1994, amb el desplegament de substitució de les FCSE a la comarca d’Osona"}]},{"text":"Complex Central a Sabadell; màxim d''efectius ampliat a 22.006 (5 de novembre de 2021).","refs":[{"ref":"p. 193","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=193","quote":"ampliar el nombre màxim d’efectius del cos de Mossos d’Esquadra a 22.006."}]},{"text":"ISPC: Llei 10/2007, de 30 de juliol, entitat autònoma de caràcter administratiu.","refs":[{"ref":"p. 197","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=197","quote":"com a entitat autònoma de caràcter administratiu"}]},{"text":"Servei Català de Trànsit: Llei 14/1997, organisme autònom; Pla de seguretat viària cada tres anys.","refs":[{"ref":"p. 199","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=199","quote":"creat a l’empara de la Llei 14/1997, de 24 de desembre."}]},{"text":"112: Llei 9/2007; 085 i 088 inactius des del 30 de setembre de 2012; centres a Reus i Barcelona.","refs":[{"ref":"p. 201","law":"Guia d''estudi, tema C.2","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=201","quote":"Els números de telèfon del cos de Bombers de la Generalitat (085) i de la Policia de la Generalitat - Mossos d’Esquadra (088) van deixar d’estar actius a partir del 30 de setembre de 2012."}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=183'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=183', 183, 204, 203, null
