insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"El concepte de coordinació policial"},{"n":"2","title":"La coordinació amb les forces i cossos de seguretat de l’Estat. La coordinació amb les policies locals de Catalunya"},{"n":"2.1","title":"La coordinació amb les forces i cossos de seguretat de l’Estat"},{"n":"2.2","title":"La coordinació amb les policies locals de Catalunya"},{"n":"3","title":"Els òrgans de coordinació establerts per la Llei 4/2003, de 7 d’abril, d’ordenació del sistema de seguretat pública de Catalunya"},{"n":"3.1","title":"Estructura del sistema de seguretat de Catalunya"},{"n":"4","title":"La cooperació policial internacional: Interpol i Europol"},{"n":"4.1","title":"La Interpol"},{"n":"4.2","title":"L’Europol"},{"n":"5","title":"Els acords internacionals en matèria de seguretat. El sistema d’informació Schengen (SIS)"},{"n":"5.1","title":"Objectius del SIS"},{"n":"5.2","title":"Estructura del SIS"},{"n":"5.3","title":"Funcionament del SIS"},{"n":"5.4","title":"El tractament de les dades informàtiques del SIS"},{"n":"5.5","title":"Competències de l’oficina SIRENE"}]'::jsonb, '["La seguretat es desenvolupa des dels diferents nivells de l’Administració pública: l’Estat, les comunitats autònomes i els ajuntaments. Aquesta competència compartida exigeix la coordinació entre els respectius cossos policials.","Un sistema de seguretat pública és el conjunt d’administracions, òrgans, autoritats i serveis que contribueixen a garantir la llibertat i la seguretat dels ciutadans i l’ordre públic.","L’article 164.2 de l’Estatut estableix que pertoca a la Generalitat el comandament suprem de la policia autònoma i la coordinació de l’actuació de les policies locals.","La coordinació en matèria policial entre la Policia de la Generalitat i les FCSE s’articula a través dels acords de la Junta de Seguretat de Catalunya.","Totes les funcions que l’ordenament jurídic atribueix al cos de Mossos d’Esquadra s’han de complir sota els principis de cooperació, coordinació i col·laboració mútua amb la resta de FCS.","En matèria de seguretat pública tenen competència l’Estat, les comunitats autònomes l’estatut d’autonomia de les quals ho preveu i que han exercit aquesta previsió, i les entitats locals. Atès que no es produeix una unificació de totes les competències en una sola entitat i, a més, no es dona exclusivitat a favor de cap administració, cal actuar d’acord amb els principis de cooperació, col·laboració i informació recíproca.","Coordinació entre la Generalitat i el Govern de l’Estat: Junta de Seguretat de Catalunya. La seva finalitat és coordinar les forces i cossos de seguretat de l’Estat i la Policia de la Generalitat - Mossos d’Esquadra.","Coordinació entre la Generalitat, el Govern de l’Estat i els ajuntaments: Junta Local de Seguretat. La coordinació de les policies locals correspon a la Generalitat, i és a les juntes locals de seguretat on s’adopten convenis de coordinació de la Policia de la Generalitat - Mossos d’Esquadra amb les entitats locals.","Coordinació entre la Generalitat i els ajuntaments: Comissió de Policia de Catalunya. És un òrgan consultiu que té com a funció elaborar informes dels projectes de coordinació que hagi d’aprovar el Govern de la Generalitat.","La Llei 4/2003, de 7 d’abril, posa les bases per dotar Catalunya d’un model de seguretat fonamentat en la prevenció, la participació i la implicació dels diferents serveis públics i privats, així com també de la societat civil.","El sistema de seguretat de Catalunya el constitueixen: les autoritats de seguretat, els cossos policials i els òrgans de coordinació i participació en matèria de seguretat.","La policia de les institucions pròpies de Catalunya està formada per les policies dels ajuntaments, ja siguin anomenades policia local, policia municipal, guàrdia urbana o d’altres maneres, i la Policia de la Generalitat - Mossos d’Esquadra.","La Llei crea i regula diferents òrgans de coordinació i participació: el Consell de Seguretat de Catalunya, la Comissió del Govern per a la Seguretat, la Comissió de Policia de Catalunya i les comissions regionals de seguretat. La Llei atorga una especial rellevància a les juntes locals de seguretat, que tenen caràcter obligatori en els municipis que disposin de policia local.","Coordinació entre la Generalitat i el Govern de l’Estat. Consell de Política de Seguretat: la seva finalitat és coordinar les polítiques de seguretat. Junta de Seguretat de Catalunya: la seva finalitat és coordinar les forces i cossos de seguretat de l’Estat i la Policia de la Generalitat - Mossos d’Esquadra.","Coordinació entre la Generalitat, el Govern de l’Estat i els ajuntaments: Junta Local de Seguretat. La coordinació de les policies locals correspon a la Generalitat i és a les juntes locals de seguretat on s’adopten convenis de coordinació i coordinació de la Policia de la Generalitat - Mossos d’Esquadra amb les entitats locals.","Coordinació entre la Generalitat i els ajuntaments: Comissió de Policia de Catalunya. És un òrgan consultiu que té com a funció elaborar informes dels projectes de coordinació que hagi d’aprovar el Govern de la Generalitat.","Un dels grans reptes als quals s’enfronta la societat actual és la globalització del crim organitzat. Aquesta nova forma de criminalitat implica que el comportament delictiu passi de ser una activitat local, patrimoni exclusiu d’uns quants, a ser-ho d’organitzacions delictives amb mitjans materials i tecnològics poderosos, sobretot amb la lliure circulació de persones i béns dins de l’àmbit comunitari.","La Interpol és una organització policial d’àmbit mundial que presta suport a les organitzacions, autoritats i serveis que tenen com a missió prevenir, detectar i combatre el delicte.","Els objectius generals de la Interpol són aconseguir i desenvolupar l’assistència recíproca entre les autoritats de policia criminal, i establir i desenvolupar tota una sèrie d’institucions.","A la Interpol, cada país membre disposa d’una oficina central nacional (OCN) que s’encarrega de mantenir l’enllaç amb els diversos serveis de policia de l’Estat respectiu, amb les oficines centrals nacionals dels altres països i amb la Secretaria General de l’organització. L’oficina central nacional (OCN) es compon de funcionaris de l’Estat, que actuen sempre dins del marc de la legislació nacional.","L’Europol neix amb la idea d’assolir una millora en la cooperació policial contra el terrorisme, el tràfic il·lícit de drogues i altres tipus de delinqüència internacional, mitjançant l’intercanvi d’informació permanent.","L’Europol té com a objectius millorar l’eficàcia i la cooperació entre les autoritats policials dels estats membres a fi i efecte de prevenir i lluitar contra el terrorisme, el tràfic il·lícit d’estupefaents, i de material radioactiu i nuclear, el tràfic d’éssers humans, el de vehicles, la immigració il·legal i el blanqueig de diners, sempre que hi hagi una estructura delictiva organitzada i que dos o més estats membres s’hi vegin afectats.","A l’Europol, cada Estat membre designa una unitat encarregada d’executar les funcions esmentades, que és l’únic òrgan d’enllaç entre l’Europol i els organismes i cossos policials dels estats membres.","L’objectiu de l’Acord de Schengen fou la creació d’una zona de lliure circulació, que implicava la supressió dels controls, tant de persones com de vehicles i mercaderies, a les fronteres comunes i l’establiment de tot un seguit de mecanismes i mesures de substitució per mantenir i incrementar els nivells de seguretat i control als països integrants.","El sistema integrat europeu d’informació d’interès policial té com a finalitat el manteniment d’un sistema europeu que permeti identificar persones, vehicles, armes de foc, documents i bitllets de banc, i proporcionar als agents que facin les identificacions les conductes que cal seguir en els supòsits d’una identificació positiva."]'::jsonb, '["Administració pública","Alcalde","Assistència mútua","Assistència recíproca","Àrea bàsica policial","Autoritats","Blanqueig de capital","Ciutadà extracomunitari","Col·laboració","Col·laboració mútua","Comissió de Policia de Catalunya","Comissió del Govern per a la Seguretat","Consell de Seguretat de Catalunya","Conveni de col·laboració","Cooperació","Cooperació recíproca","Coordinació","Crim organitzat","Criminalitat internacional","Delegats territorials del Govern","Delinqüència transnacional","Detenció preventiva","Extradició","Globalització","Globalització del crim","Informació recíproca","Intercanvi d’informació","Junta de Seguretat de Catalunya","Junta Local de Seguretat","Mesa de Coordinació Operativa","Oficina central nacional (OCN)","Òrgan executiu","Òrgans de coordinació i participació","Permisos de residència","Persona sospitosa","Pla general de seguretat de Catalunya","Pla local de seguretat","Policia judicial","Regió policial","Sala Interpolicial de Catalunya","Seguretat pública","Servei Nacional d’Intel·ligència Criminal - Europol (SNIC-Europol)","Sistema de seguretat pública","Substància estupefaent","Vigilància transfronterera","Visat"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El concepte de coordinació policial i de sistema de seguretat pública","blocks":[{"text":"La seguretat es gestiona des de tres nivells de l''Administració: l''Estat, les comunitats autònomes i els ajuntaments. Com que és una competència compartida, cal coordinar els cossos policials de cada nivell, i això pressuposa un sistema de seguretat pública. La guia el defineix així: el conjunt d''administracions, òrgans, autoritats i serveis que contribueixen a garantir la llibertat i la seguretat dels ciutadans i l''ordre públic. Aquest sistema reparteix obligacions, regula les relacions entre els agents i exigeix intercanvi d''informació i homogeneïtzació de mitjans.","refs":[{"ref":"1. El concepte de coordinació policial, p. 206","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=206","quote":"Un sistema de seguretat pública és el conjunt d’administracions, òrgans, autoritats i serveis que contribueixen a garantir la llibertat i la seguretat dels ciutadans i l’ordre públic."}]},{"text":"A Catalunya hi operen la PG-ME, les policies locals i les FCSE (Policia Nacional i Guàrdia Civil). La coordinació entre la PG-ME i les FCSE s''articula pels acords de la Junta de Seguretat de Catalunya, òrgan administratiu configurat per l''Estatut i integrat per igual nombre de representants del Govern central i de la Generalitat. Quant a les policies locals, l''article 164.2 de l''Estatut atribueix a la Generalitat el comandament suprem de la policia autònoma i la coordinació de l''actuació de les policies locals.","refs":[{"ref":"1. El concepte de coordinació policial, p. 206","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=206","quote":"La coordinació en matèria policial entre la Policia de la Generalitat i les FCSE s’articula a través dels acords de la Junta de Seguretat de Catalunya."},{"ref":"1. El concepte de coordinació policial, p. 206","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=206","quote":"l’article 164.2 de l’Estatut estableix que pertoca a la Generalitat el comandament suprem de la policia autònoma i la coordinació de l’actuació de les policies locals."}]}]},{"n":"2","title":"La coordinació en les lleis policials (LO 2/1986, Llei 10/1994 i Llei 16/1991)","blocks":[{"text":"La LO 2/1986 parteix del caràcter concurrent de la seguretat pública. El seu article 3 proclama el principi de cooperació recíproca i el de coordinació orgànica; l''article 12 obliga les FCSE a cooperar entre elles. L''article 38 enumera les funcions autonòmiques en col·laboració amb les FCSE; entre elles, vigilar espais públics, protegir manifestacions i mantenir l''ordre en grans concentracions correspon prioritàriament a les policies autonòmiques, sens perjudici de la intervenció de les FCSE.","refs":[{"ref":"1. El concepte de coordinació policial, p. 206","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=206","quote":"L’article 3 de la Llei orgànica 2/1986, de forces i cossos de seguretat, proclama el principi de cooperació recíproca i el de coordinació orgànica."},{"ref":"1. El concepte de coordinació policial, p. 207","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=207","quote":"L’exercici d’aquesta funció correspon prioritàriament a les policies autonòmiques, sense perjudici de la intervenció de les FCSE"}]},{"text":"L''article 53 regula la policia local, que en moltes funcions actua amb altres cossos: comunica a les FCSE els atestats de trànsit al nucli urbà i les diligències de prevenció, i en manifestacions i grans concentracions només intervé a requeriment previ i com a col·laboradora. La LO també preveu mecanismes d''auxili quan una comunitat no pot crear policia pròpia (ajuda de les FCSE o adscripció d''unitats de la PN). La Llei 10/1994 (article 12.2) imposa a Mossos la cooperació, coordinació i col·laboració mútua amb la resta de FCS; la Llei 16/1991 (article 12.2), la cooperació mútua i col·laboració recíproca en policia judicial.","refs":[{"ref":"1. El concepte de coordinació policial, p. 207","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=207","quote":"ho fa únicament a requeriment previ i a títol de col·laboradora amb les FCSE i amb les policies autonòmiques."},{"ref":"1. El concepte de coordinació policial, p. 207","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=207","quote":"A l’article 12.2 estableix que totes les funcions que l’ordenament jurídic atribueix al cos de Mossos d’Esquadra s’han de complir sota els principis de cooperació, coordinació i col·laboració mútua amb la resta de FCS."}]}]},{"n":"3","title":"Coordinació amb les FCSE (I): la Junta de Seguretat de Catalunya","blocks":[{"text":"La coordinació entre Mossos i FCSE té dos nivells: institucional i operatiu. En l''institucional hi ha la Junta de Seguretat (article 164.4 EAC), amb cinc representants del Govern central i cinc de la Generalitat. En el seu si es van adoptar els acords de 17 d''octubre de 1994, que van desbloquejar el pla de desplegament: aquell any Mossos va començar a substituir progressivament les FCSE. Segons l''article 50 de la LO 2/1986, la Junta resol les incidències en la col·laboració entre FCSE i Mossos, i rep informació periòdica del subdelegat del Govern i de les autoritats autonòmiques.","refs":[{"ref":"2.1 Coordinació amb les FCSE, p. 207","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=207","quote":"Dins la coordinació entre el cos de Mossos d’Esquadra i les FCSE (GC i PN) hi ha dos nivells: la coordinació institucional i l’operativa."},{"ref":"2.1.1 Àmbit institucional, p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"És precisament en el si de la Junta de Seguretat on es van adoptar els transcendents acords de 17 d’octubre de 1994."},{"ref":"2.1.1 Àmbit institucional, p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"L’article 50 de la Llei orgànica 2/1986 estableix que la Junta de Seguretat és l’òrgan competent per resoldre les incidències que es produeixin en la col·laboració entre els membres de les forces i cossos de seguretat de l’Estat i el cos de Mossos d’Esquadra."}]},{"text":"La Junta es regula per la Resolució de 28 de desembre de 1982, funciona com un òrgan col·legiat i pren els acords per unanimitat. Les seves funcions són: coordinar la PG-ME i les FCSE; determinar l''Estatut, el Reglament, les dotacions, la composició numèrica, l''estructura i el reclutament de la PG-ME; coordinar les FCSE amb les policies locals; i conèixer la delimitació de les funcions exclusives de cada cos a Catalunya. La presideix el president de la Generalitat; els representants de la Generalitat són els titulars del Departament d''Interior i Seguretat Pública, de la seva Secretaria General, de la Direcció General de la Policia i de l''Assessoria Jurídica del Departament.","refs":[{"ref":"2.1.1 Àmbit institucional, p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"Funciona com els òrgans col·legiats i pren els acords per unanimitat."},{"ref":"2.1.1 Àmbit institucional, p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"2. Determinar l’Estatut, el Reglament, les dotacions, la composició numèrica i l’estructura i el reclutament de la Policia de la Generalitat."},{"ref":"2.1.1 Àmbit institucional, p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"Està presidida pel president de la Generalitat de Catalunya"}]}]},{"n":"4","title":"Coordinació amb les FCSE (II): àmbit operatiu i policia judicial","blocks":[{"text":"En l''àmbit operatiu hi ha, entre d''altres, la Sala de Coordinació Interpolicial de Catalunya, creada per la Junta de Seguretat per intercanviar informació, col·laborar tècnicament i alimentar bases de dades, i comissions de coordinació territorials no permanents. En policia judicial, el Reial decret 769/1987, de 19 de juny (modificat pel RD 54/2002), va crear la Comissió Nacional i la Comissió Provincial de Coordinació de la Policia Judicial, per harmonitzar la direcció de les forces adscrites a la investigació criminal.","refs":[{"ref":"2.1.2 Àmbit operatiu, p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"La Junta de Seguretat de Catalunya va acordar crear la Sala Interpolicial de Catalunya, com a instrument d’intercanvi d’informació"},{"ref":"2.1.2 Àmbit operatiu, p. 209","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=209","quote":"a) Comissió Nacional de Coordinació de la Policia Judicial. b) Comissió Provincial de Coordinació de la Policia Judicial."}]}]},{"n":"5","title":"La coordinació amb les policies locals de Catalunya","blocks":[{"text":"La guia aporta dades de context: Catalunya té 32.107,98 km², 7,6 milions d''habitants, 25 milions de turistes l''any i 947 municipis, dels quals 213 tenen policia pròpia. Hi treballen uns 11.167 policies locals, 17.889 mossos i 6.535 agents estatals (3.388 PN i 3.147 GC): 4,5 policies per 1.000 habitants. Són xifres de la guia (edició de juny de 2026) que poden variar amb el temps. El sistema català es fonamenta en la cooperació, la col·laboració, la lleialtat institucional i l''auxili mutu, i la seva manifestació més elevada de coordinació i participació és el Consell de Seguretat de Catalunya.","refs":[{"ref":"2.2 Coordinació amb les policies locals, p. 209","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=209","quote":"Té un total de 947 municipis, dels quals 213 tenen cos de policia propi."},{"ref":"2.2 Coordinació amb les policies locals, p. 209","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=209","quote":"la manifestació més elevada dels quals la constitueix el Consell de Seguretat de Catalunya."}]},{"text":"La Generalitat exerceix la coordinació de les policies locals (article 164.2 EAC) mitjançant la Sub-direcció General de Coordinació de la Policia de Catalunya, dins la Direcció General d''Administració de Seguretat. Entre les seves funcions: planificar i assignar recursos, millorar la qualitat, atendre queixes ciutadanes, elaborar directrius i procediments comuns, supervisar convenis i donar suport als plans locals de seguretat. Els òrgans principals de coordinació amb les policies locals són la Comissió de Policia de Catalunya, les comissions regionals de seguretat, les juntes locals i les meses de coordinació operativa.","refs":[{"ref":"2.2 Coordinació amb les policies locals, p. 209","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=209","quote":"La Generalitat exerceix aquesta competència mitjançant la Sub-direcció General de Coordinació de la Policia de Catalunya"},{"ref":"2.2 Coordinació amb les policies locals, p. 210","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=210","quote":"són la Comissió de Policia de Catalunya, les comissions regionals de seguretat, les juntes locals de seguretat i les meses de coordinació operativa"}]}]},{"n":"6","title":"La Llei 4/2003, d''ordenació del sistema de seguretat pública de Catalunya","blocks":[{"text":"La Llei 4/2003, de 7 d''abril, aprovada per unanimitat pel Parlament, ordena les competències de seguretat de la Generalitat (sobretot policia) i les integra amb protecció civil, trànsit, joc i espectacles i seguretat privada en un sistema propi, coordinat i únic, que garanteix una prestació homogènia arreu de Catalunya. El model es fonamenta en la prevenció, la participació i la implicació de serveis públics, privats i de la societat civil. Els seus principis són: prevenció de riscos, adequació a la demanda social, proximitat i descentralització, eficàcia i eficiència, planificació i avaluació, proporcionalitat de la intervenció pública, corresponsabilitat, coordinació i cooperació, i transparència.","refs":[{"ref":"3. Llei 4/2003, p. 210","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=210","quote":"que va ser aprovada per unanimitat pel Parlament de Catalunya"},{"ref":"3. Llei 4/2003, p. 211","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=211","quote":"– La proporcionalitat de la intervenció pública."}]},{"text":"El sistema de seguretat de Catalunya el constitueixen tres elements: les autoritats de seguretat, els cossos policials (i altres serveis de seguretat) i els òrgans de coordinació i participació.","refs":[{"ref":"3. Llei 4/2003, p. 211","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=211","quote":"El sistema de seguretat de Catalunya el constitueixen: les autoritats de seguretat, els cossos policials i els òrgans de coordinació i participació en matèria de seguretat."}]}]},{"n":"7","title":"Autoritats de seguretat i cossos policials","blocks":[{"text":"El Govern és l''òrgan col·legiat superior en seguretat; el conseller competent dirigeix la política de seguretat de Catalunya. En l''àmbit local, l''alcalde és l''autoritat superior en seguretat pública. També són autoritats els delegats territorials del Govern i els titulars d''òrgans que exerceixin funcions per atribució legal o delegació. La policia de les institucions pròpies de Catalunya la formen les policies dels ajuntaments (policia local, municipal, guàrdia urbana…) i la PG-ME, que es relacionen per complementarietat, coordinació, col·laboració, cooperació i auxili mutu.","refs":[{"ref":"3.1.a Autoritats, p. 211","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=211","quote":"En l’àmbit local, els alcaldes són l’autoritat superior en matèria de seguretat pública, en el marc de les seves competències."},{"ref":"3.1.b Cossos policials, p. 211","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=211","quote":"La policia de les institucions pròpies de Catalunya està formada per les policies dels ajuntaments"}]}]},{"n":"8","title":"Òrgans de coordinació i participació de la Llei 4/2003","blocks":[{"text":"El Consell de Seguretat de Catalunya és l''òrgan consultiu i de participació superior: analitza la seguretat i emet un informe anual. La Comissió del Govern per a la Seguretat, presidida pel president de la Generalitat, coordina els departaments. La Comissió de Policia de Catalunya és l''òrgan col·legiat consultiu superior de coordinació entre la PG-ME i les policies locals, amb representants del Govern i dels ajuntaments, presidit pel conseller competent en seguretat pública; substitueix la Comissió de Coordinació de Policies Locals i elabora informes dels projectes de coordinació que ha d''aprovar el Govern.","refs":[{"ref":"3.1.c Òrgans, p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"es crea la Comissió del Govern per a la Seguretat, presidida pel president de la Generalitat"},{"ref":"3.1.c Òrgans, p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"presidit pel conseller o consellera del departament amb competències en matèria de seguretat pública."},{"ref":"Idees força C.3 (9), p. 220","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=220","quote":"És un òrgan consultiu que té com a funció elaborar informes dels projectes de coordinació que hagi d’aprovar el Govern de la Generalitat."}]},{"text":"En l''àmbit territorial, les comissions regionals de seguretat apleguen els municipis d''una regió policial per proposar plans supramunicipals. Les juntes locals de seguretat són obligatòries als municipis amb policia local, les presideix l''alcalde i coordinen tots els cossos del municipi; creen la Mesa de Coordinació Operativa, òrgan permanent.","refs":[{"ref":"3.1.c Òrgans, p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"es creen les comissions regionals de seguretat, que apleguen els municipis d’una mateixa regió policial"},{"ref":"3.1.c Òrgans, p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"La Llei atorga una rellevància especial a les juntes locals de seguretat, que tenen caràcter obligatori en els municipis que comptin amb policia local. Les juntes locals de seguretat, sota la presidència de l’alcalde o alcaldessa"}]}]},{"n":"9","title":"Pla general de seguretat i plans locals","blocks":[{"text":"El Pla general de seguretat de Catalunya és un instrument metodològic amb les previsions, actuacions i mitjans per a la convivència i la seguretat. És quadriennal, l''aprova el Govern després de presentar-lo a la Comissió del Govern per a la Seguretat i al Consell de Seguretat, i després es presenta al Parlament. Fixa els criteris dels plans locals i regionals; les juntes locals aproven el pla local de seguretat. La Llei preveu convenis entre Govern i ajuntaments, per exemple per a serveis unificats de recepció de denúncies.","refs":[{"ref":"3.1.c Òrgans, p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"El Pla, que té una periodicitat quadriennal, ha de ser aprovat pel Govern"},{"ref":"3.1.c Òrgans, p. 213","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=213","quote":"Les juntes locals de seguretat han d’aprovar un pla local de seguretat per al municipi respectiu"}]}]},{"n":"10","title":"La cooperació policial internacional: la Interpol","blocks":[{"text":"La globalització del crim organitzat obliga a cooperar internacionalment. La Interpol és una organització policial mundial: els seus orígens són a Mònaco (1914, 14 països); el 1923, a Viena, es crea la Comissió Internacional de Policia Criminal; el 1946 adopta el nom d''Interpol i el 1956 el definitiu d''OIPC-Interpol. Segons la guia, en formen part 195 països i és observadora a l''ONU. Els seus objectius (article 2 de l''Estatut) són l''assistència recíproca entre policies criminals i la prevenció i repressió de les infraccions de dret comú; l''article 3 li prohibeix intervenir en assumptes polítics, militars, religiosos o racials.","refs":[{"ref":"4.1 La Interpol, p. 214","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=214","quote":"Serà l’any 1946 quan s’adopti el nom d’Interpol, que posteriorment, l’any 1956, passa a anomenar-se definitivament Organització Internacional de Policia Criminal - Interpol (OIPC-Interpol). Actualment formen part de la Interpol 195 països"},{"ref":"4.1.1 Objectius, p. 214","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=214","quote":"L’article 3 de l’Estatut estableix que l’OIPC-Interpol no ha d’intervenir en assumptes de caràcter polític, militar, religiós o racial."}]},{"text":"L''estructura té l''Assemblea General (òrgan superior, majoria simple, un vot per Estat), el Comitè Executiu (13 personalitats) i la Secretaria General (òrgan executiu permanent). Cada país té una oficina central nacional (OCN) que fa d''enllaç amb les policies de l''Estat, les altres OCN i la Secretaria General; a Espanya funciona des de 1929.","refs":[{"ref":"4.1.2 Estructura, p. 214","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=214","quote":"Està format per 13 personalitats escollides per l’Assemblea General"},{"ref":"4.1.3 Funcionament, p. 214","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=214","quote":"Cada país membre disposa d’una oficina central nacional que s’encarrega de mantenir l’enllaç amb els diversos serveis de policia de l’Estat respectiu, amb les oficines centrals nacionals dels altres països i amb la Secretaria General de l’organització."},{"ref":"4.1.3 Funcionament, p. 215","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=215","quote":"A l’Estat espanyol, l’Oficina Central Nacional funciona des de l’any 1929."}]}]},{"n":"11","title":"L''Europol","blocks":[{"text":"L''Europol (Oficina Europea de Policia) neix arran del Tractat de Maastricht (7 de febrer de 1992). El 3 de gener de 1994 comença la Unitat de Drogues de l''Europol (EDU), amb seu a la Haia; el Conveni de l''Europol se signa l''1 d''octubre de 1998 i l''organització actua des de l''1 de juliol de 1999. Lluita contra el terrorisme, el tràfic de drogues, de material nuclear, d''éssers humans i de vehicles, la immigració il·legal i el blanqueig, sempre que hi hagi una estructura delictiva organitzada i dos o més estats afectats. Cada Estat designa una unitat, únic òrgan d''enllaç; a Espanya és al Cos Nacional de Policia.","refs":[{"ref":"4.2 L’Europol, p. 215","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=215","quote":"El 3 de gener de 1994 va iniciar la seva activitat la Unitat de Drogues de l’Europol (EDU), amb seu a la Haia (Països Baixos)."},{"ref":"4.2.1 Objectius, p. 215","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=215","quote":"sempre que hi hagi una estructura delictiva organitzada i que dos o més estats membres s’hi vegin afectats."}]}]},{"n":"12","title":"Schengen, el SIS i l''oficina SIRENE","blocks":[{"text":"L''Acord de Schengen es va signar el 14 de juny de 1985 per Bèlgica, Països Baixos, Luxemburg, França i Alemanya, per crear una zona de lliure circulació. El Conveni d''aplicació (CAAS) preveu: cooperació policial (article 39), vigilància transfronterera (article 40, continuar en un altre Estat una vigilància iniciada al propi), persecució transfronterera o «en calent» (article 41, delicte flagrant i frontera comuna), informació incondicionada (article 46), funcionaris d''enllaç (article 47, adscrits a policies d''altres estats) i lliurament vigilat d''estupefaents (article 73).","refs":[{"ref":"5. Schengen, p. 216","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=216","quote":"Vigilància transfronterera (article 40): un cos policial d’un Estat Schengen, dins del marc d’una investigació judicial, continua en el territori d’un altre Estat Schengen una operació de vigilància iniciada al seu país."},{"ref":"5. Schengen, p. 217","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=217","quote":"Persecució transfronterera (article 41): també anomenada “persecució en calent”"},{"ref":"5. Schengen, p. 217","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=217","quote":"Funcionaris d’enllaç (article 47): possibilitat que determinats funcionaris siguin adscrits als serveis de policia d’altres estats Schengen"}]},{"text":"El SIS permet identificar persones, vehicles, armes, documents i bitllets, només per a controls i visats, no per investigar. Té un ordinador central a Estrasburg (CSIS) i sistemes estatals (NSIS); l''Estat té, a més, la BDSN. Inclou detenció per extradició (article 95), estrangers no admissibles (96), desapareguts (97), testimonis (98) i vigilància discreta (99). L''oficina SIRENE, al Cos Nacional de Policia, canalitza totes les descripcions.","refs":[{"ref":"5.2 Estructura del SIS, p. 217","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=217","quote":"integrat perun ordinador central situat a Estrasburg (Central Schengen Information System, CSIS)"},{"ref":"5.5 SIRENE, p. 219","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=219","quote":"Totes les descripcions s’han de fer a través de l’organisme esmentat"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Junta de Seguretat de Catalunya: 5 representants estatals i 5 de la Generalitat, presidida pel president de la Generalitat, acords per unanimitat.","refs":[{"ref":"p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"La Junta de Seguretat de Catalunya està formada per 5 persones en representació del Govern central i 5 en representació de la Generalitat de Catalunya."}]},{"text":"Acords de la Junta que van desbloquejar el desplegament de Mossos: 17 d''octubre de 1994.","refs":[{"ref":"p. 208","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=208","quote":"acords de 17 d’octubre de 1994"}]},{"text":"Llei 4/2003: aprovada per unanimitat; el Pla general de seguretat és quadriennal.","refs":[{"ref":"p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"El Pla, que té una periodicitat quadriennal"}]},{"text":"Consell de Seguretat de Catalunya: màxim òrgan consultiu i de participació; emet un informe anual.","refs":[{"ref":"p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"emetre un informe anual sobre la seva evolució"}]},{"text":"Comissió de Policia de Catalunya: la presideix el conseller; juntes locals: obligatòries amb policia local i presidides per l''alcalde.","refs":[{"ref":"p. 212","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=212","quote":"presidit pel conseller o consellera del departament amb competències en matèria de seguretat pública."}]},{"text":"Interpol: nom definitiu OIPC-Interpol el 1956; OCN a Espanya des de 1929.","refs":[{"ref":"p. 214","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=214","quote":"l’any 1956, passa a anomenar-se definitivament"}]},{"text":"Europol: EDU a la Haia des del 3 de gener de 1994; actua si hi ha estructura organitzada i dos o més estats afectats.","refs":[{"ref":"p. 215","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=215","quote":"va iniciar la seva activitat la Unitat de Drogues de l’Europol (EDU), amb seu a la Haia"}]},{"text":"Schengen: article 40 vigilància transfronterera, article 41 persecució en calent, article 47 funcionaris d''enllaç; ordinador central del SIS a Estrasburg.","refs":[{"ref":"p. 216","law":"Guia d''estudi, tema C.3","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=216","quote":"Vigilància transfronterera (article 40)"}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=205'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=205', 205, 222, 220, null
