insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Llei orgànica 2/1986, de 13 de març, de forces i cossos de seguretat. Principis bàsics d’actuació"},{"n":"1.1","title":"Principis bàsics d’actuació de les forces i els cossos de seguretat"},{"n":"2","title":"Llei 10/1994, d’11 de juliol, de la Policia de la Generalitat - Mossos d’Esquadra. Funcions, àmbit territorial d’actuació i estructura"},{"n":"2.1","title":"Definició de les competències"},{"n":"2.2","title":"Àmbit territorial d’actuació"},{"n":"2.3","title":"Estructura de la Policia de la Generalitat - Mossos d’Esquadra"},{"n":"3","title":"La Llei 16/1991, de 10 de juliol, de les policies locals de Catalunya. Funcions"},{"n":"3.1","title":"Funcions de la policia local"}]'::jsonb, '["L’objectiu principal de la Llei orgànica 2/1986 és el disseny de les línies mestres del règim jurídic de les FCS en el seu conjunt, i establir els principis bàsics d’actuació comuns i els seus criteris estatutaris fonamentals.","La constitució confereix a l’Estat la competència exclusiva sobre seguretat pública, que és exercida a través de les FCS. Les comunitats autònomes poden crear cossos policials en la forma que els respectius estatuts estableixin, i d’acord amb el marc legal de la mateixa Llei orgànica 2/1986.","Els cossos policials autonòmics són instituts armats de naturalesa civil amb organització jerarquitzada. De manera genèrica, tots els cossos autonòmics poden desenvolupar, a l’àmbit territorial que els correspongui, les funcions d’acord amb el seu règim competencial.","Els cossos policials autonòmics poden exercir les funcions recollides a l’article 38 de la Llei orgànica 2/1986 i que es delimiten com a funcions pròpies, funcions amb caràcter compartit i indiferenciat amb les FCSE i funcions de col·laboració amb altres FCSE.","Els principis bàsics d’actuació es poden ordenar en sis eixos fonamentals: l’adequació a l’ordenament jurídic, les relacions amb la comunitat, el tractament de les persones detingudes, la dedicació professional, el secret professional i la responsabilitat dels membres de les FCS.","Els principis bàsic recollits a la Llei orgànica 2/1986 s’han d’aplicar directament a la Policia de la Generalitat, així com les disposicions estatutàries comunes que estableixen els articles 6, 7 i 8.","La Llei 10/1994 té per objecte establir els principis d’actuació, les funcions i el règim funcionarial i estatutari dels membres de la Policia de la Generalitat - Mossos d’Esquadra, i l’organització de la seguretat pública en tot el territori, i preveu la creació dels òrgans necessaris i la dotació dels mitjans imprescindibles per al compliment correcte de les funcions de seguretat que corresponen a la Generalitat.","La policia no està per damunt de la Llei i, per tant, ha d’adequar la seva conducta a l’ordenament jurídic. El respecte que la policia deu a la societat l’obliga a utilitzar els recursos coactius solament en situacions extremes i amb una aplicació escrupolosa dels principis d’oportunitat, proporcionalitat i congruència.","La Policia de la Generalitat - Mossos d’Esquadra, com qualsevol altre cos de policia, té com a missió i divisa principal la protecció de la llibertat i la seguretat de la ciutadania.","La Policia de la Generalitat opera, amb tots els altres cossos, segons els principis de cooperació, coordinació i col·laboració mútua.","La Policia de la Generalitat - Mossos d’Esquadra té com a àmbit d’actuació el conjunt del territori de Catalunya.","Per a la implantació de la PG-ME, la unitat territorial bàsica és l’àrea bàsica policial (ABP), que és aquell territori definit per criteris operatius policials i que té la seva seu en una comissaria, des de la qual es donen els serveis policials bàsics en seguretat ciutadana i investigació.","La regió policial (RP) es defineix com l’àmbit territorial format per un conjunt d’ABP, sobre les quals ha d’exercir funcions de coordinació jeràrquica, suport en recursos operatius, logístics i especialitats i planificació d’àmbit superior a l’ABP.","La Policia de la Generalitat - Mossos d’Esquadra, com a policia ordinària i integral, exerceix les funcions que l’ordenament jurídic atribueix a les forces i els cossos de seguretat, i, en concret, les funcions de policia de seguretat ciutadana, policia administrativa i policia judicial.","La Policia de la Generalitat - Mossos d’Esquadra s’estructura jeràrquicament en les escales de suport, bàsica, intermèdia, executiva i superior.","La policia local és un cos de seguretat amb dependència de les corporacions locals, que participa en el manteniment de la seguretat pública. És un institut armat de naturalesa civil amb estructura i organització jerarquitzada.","Tots els municipis amb una població superior als 10.000 habitants poden crear cossos de policia local.","L’àmbit territorial d’actuació de la policia local és el territori del seu municipi, i excepcionalment, per raons d’emergència i sempre que en doni compte al conseller o consellera del Departament amb competències en matèria de seguretat pública, pot actuar en els municipis limítrofes.","Les policies locals s’estructuren en les escales i les categories superior, que comprèn les categories de superintendent, d’intendent major i d’intendent; l’escala executiva, que comprèn la categoria d’inspector; l’escala intermèdia, que comprèn les categories de sotsinspector i de sergent, i l’escala bàsica, que comprèn les categories de caporal i d’agent.","La Llei 16/1991, de 10 de juliol, de les policies locals de Catalunya, incorpora altres figures en matèria de seguretat per a aquells municipis que no disposin de policia local, i que són guàrdies, vigilants, agents, algutzirs o similars, que exerceixin les funcions custodia i vigilància, ordenar i regular trànsit, participar en les tasques d’auxili al ciutadà i de protecció civil, així com vetllar pel compliment de la normativa municipal.","Les policies locals s’han de regir pels principis bàsics d’actuació i per les disposicions estatutàries comunes que recull la Llei 2/1986, del 13 de març, de forces i cossos de seguretat, amb l’adequació necessària a l’Administració local, per les disposicions dictades per les comunitats autònomes i pels reglaments específics de cada cos i altres normes dictades pels ajuntaments corresponents.","Entre les funcions que la Llei atorga a la policia local destaquen la de policia administrativa, en l’observació del compliment de les normes municipals; la de policia de trànsit, en el nucli urbà, i la de protecció de les autoritats i instal·lacions municipals.","Les funcions de vigilància dels espais públics, l’auxili a la ciutadania, la prevenció dels delictes i el manteniment de l’ordre s’exerceixen de forma compartida o en règim de col·laboració amb altres cossos de seguretat."]'::jsonb, '["Àrea bàsica policial (ABP)","Comandament directe","Comandament operatiu","Comissaries generals","Comissió de Policia de Catalunya","Competència exclusiva","Competències concurrents","Congruència, oportunitat, proporcionalitat","Criminalística","Disposicions estatutàries","Eficàcia","Espai jurídic","Estructura jeràrquica","Estructures organitzatives","Funcions","Junta de Seguretat de Catalunya","Lliure exercici de drets","Mandat constitucional","Model de proximitat","Model descentralitzat","Norma ordenadora","Norma reguladora","Ordenament jurídic","Ordre organitzatiu descendent","Planificació estratègica","Policia administrativa","Policia de seguretat ciutadana","Policia integral","Policia judicial","Policia ordinària i integral","Prevenció","Principis bàsics d’actuació","Recursos operatius","Regió policial (RP)"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La Llei orgànica 2/1986, de forces i cossos de seguretat: origen i objectiu","blocks":[{"text":"La Llei orgànica 2/1986, de 13 de març, de forces i cossos de seguretat (FCS), desplega l''article 104 de la Constitució. Aquest article encomana a les FCS la missió de protegir el lliure exercici dels drets i llibertats i garantir la seguretat ciutadana, i demana que una llei orgànica en determini les funcions, els principis bàsics d''actuació i els estatuts.","refs":[{"ref":"1. La LO 2/1986, p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"La Llei orgànica 2/1986 és una llei que desplega el mandat constitucional explícit a l’article 104, quan encomana a les FCS la missió de protegir el lliure exercici dels drets i de les llibertats i garantir la seguretat ciutadana, i afegeix la necessitat d’una llei orgànica que determini les funcions, els principis bàsics d’actuació i els estatuts."}]},{"text":"Els aspectes més importants de la Llei són tres: els principis bàsics d''actuació, les disposicions estatutàries (drets i deures) comunes a tots els cossos policials, i la disposició final segona, que és la base jurídica de la policia autònoma de Catalunya. El seu objectiu principal és dissenyar les línies mestres del règim jurídic de les FCS en conjunt i establir els principis bàsics d''actuació comuns i els criteris estatutaris fonamentals.","refs":[{"ref":"1. La LO 2/1986, p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"així com la disposició final segona, que ofereix la base jurídica de la policia autònoma de Catalunya."},{"ref":"1. La LO 2/1986, p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"L’objectiu principal de la Llei orgànica 2/1986 és el disseny de les línies mestres del règim jurídic de les FCS en el seu conjunt, i establir els principis bàsics d’actuació comuns i els seus criteris estatutaris fonamentals."}]}]},{"n":"2","title":"La seguretat pública: competència de l''Estat i competències concurrents","blocks":[{"text":"L''article 149.1.29 de la Constitució atribueix a l''Estat la competència exclusiva sobre seguretat pública, que exerceix a través de les FCS. Ara bé, això és sens perjudici que les comunitats autònomes puguin crear cossos policials en la forma que estableixin els seus estatuts i d''acord amb la LO 2/1986.","refs":[{"ref":"1. La LO 2/1986, p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"L’article 149.1.29 de la CE atribueix a l’Estat la competència exclusiva sobre seguretat pública. Aquesta competència exclusiva l’exerceix a través de les FCS, sens perjudici que les comunitats autònomes tinguin potestat per crear cossos policials en la forma que els respectius estatuts estableixin, i d’acord amb el marc legal de la mateixa Llei orgànica 2/1986."}]},{"text":"La seguretat pública és una matèria difícil de delimitar amb rigor i precisió. A més, el Tribunal Constitucional ha argumentat a favor d''un sistema de competències concurrents, exercides per totes les administracions d''acord amb els seus estatuts, que complementa la primera lectura de l''article 149.1.29.","refs":[{"ref":"1. La LO 2/1986, p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"Les sentències del Tribunal Constitucional argumenten l’afirmació en favor d’un sistema de competències concurrents (exercides per totes les administracions públiques d’acord amb els seus estatuts) que complementen la primera lectura de l’article 149.1.29."}]},{"text":"D''aquí en surt una definició clau: els cossos autonòmics de policia són instituts armats de naturalesa civil amb organització jerarquitzada. Tots poden exercir, en el seu àmbit territorial, les funcions que els corresponguin segons el seu règim competencial, que poden ser pròpies, compartides o de suport i col·laboració amb altres forces.","refs":[{"ref":"1. La LO 2/1986, p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"els cossos autonòmics de policia són instituts armats de naturalesa civil amb organització jerarquitzada."},{"ref":"1. La LO 2/1986, p. 225","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=225","quote":"Aquestes funcions poden basar-se en un àmbit competencial propi, o bé compartit, o bé de suport i col·laboració amb altres forces de seguretat."}]}]},{"n":"3","title":"Funcions de les policies autonòmiques (article 38 LO 2/1986) i qui són FCS","blocks":[{"text":"L''article 38 classifica les funcions de les policies autonòmiques en tres blocs. Les pròpies són: vigilar i protegir persones, òrgans, edificis i dependències de la comunitat; vetllar pel compliment de les seves disposicions i ordres; inspeccionar activitats de competència autonòmica i denunciar-ne les il·legals; i usar la coacció per a l''execució forçosa dels actes o disposicions de la comunitat autònoma.","refs":[{"ref":"1. La LO 2/1986, p. 225","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=225","quote":"d) L’ús de la coacció amb vista a l’execució forçosa dels actes o disposicions de la mateixa comunitat autònoma."}]},{"text":"Les funcions compartides i indiferenciades amb les FCSE són tres: cooperar en la resolució amistosa de conflictes privats, prestar auxili en accidents i catàstrofes, i vetllar per les disposicions de conservació de la natura i el medi ambient. Les de col·laboració amb les FCSE també són tres: vetllar per les disposicions de l''Estat i el funcionament dels serveis públics essencials, participar en funcions de policia judicial, i vigilar espais públics, protegir manifestacions i mantenir l''ordre en grans concentracions humanes.","refs":[{"ref":"1. La LO 2/1986, p. 225","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=225","quote":"Les funcions amb caràcter compartit i indiferenciat amb les FCSE: a) Cooperació en la resolució amistosa de conflictes privats. b) Prestació d’auxili en accidents i catàstrofes."},{"ref":"1. La LO 2/1986, p. 225","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=225","quote":"b) Participar en funcions de policia judicial. c) Vigilar espais públics, protegir les manifestacions i mantenir l’ordre en grans concentracions humanes."}]},{"text":"Segons la Llei, són FCS: les de l''Estat, dependents del Govern de la Nació; els cossos de policia de les comunitats autònomes; i els de les corporacions locals. Les funcions de la policia local són a l''article 53.","refs":[{"ref":"1. La LO 2/1986, p. 225","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=225","quote":"a) Les forces i cossos de seguretat de l’Estat dependents del Govern de la Nació. b) Els cossos de policia dependents de les comunitats autònomes. c) Els cossos de policia dependents de les corporacions locals."},{"ref":"1. La LO 2/1986, p. 225","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=225","quote":"l’article 53 d’aquesta llei orgànica regula les competències atribuïdes a la policia local."}]}]},{"n":"4","title":"Principis bàsics d''actuació (article 5): ordenament jurídic i relacions amb la comunitat","blocks":[{"text":"Els principis bàsics d''actuació són a l''article 5 de la LO 2/1986 i s''agrupen en sis eixos: adequació a l''ordenament jurídic, relacions amb la comunitat, tractament de detinguts, dedicació professional, secret professional i responsabilitat. El primer eix demana: respecte absolut a la Constitució i a l''ordenament; neutralitat política i imparcialitat, sense discriminació per raça, religió o opinió; integritat i dignitat, abstenint-se de tota corrupció; subjecció a jerarquia i subordinació; i col·laboració amb l''Administració de justícia.","refs":[{"ref":"1.1 Principis bàsics, p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"Segons l’article 5 de la Llei orgànica 2/1986, de 13 de març, de forces i cossos de seguretat, són principis bàsics d’actuació dels membres de les forces i cossos de seguretat els següents:"},{"ref":"Idees força C.4 (5), p. 235","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=235","quote":"Els principis bàsics d’actuació es poden ordenar en sis eixos fonamentals: l’adequació a l’ordenament jurídic, les relacions amb la comunitat, el tractament de les persones detingudes, la dedicació professional, el secret professional i la responsabilitat dels membres de les FCS."}]},{"text":"Sobre la jerarquia, retén el límit: en cap cas l''obediència deguda no pot emparar ordres que comportin actes manifestament delictius o contraris a la Constitució o a les lleis.","refs":[{"ref":"1.1 Principis bàsics, p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"En cap cas l’obediència deguda no pot emparar ordres que comportin l’execució d’actes que constitueixin manifestament un delicte o siguin contraris a la Constitució o a les lleis."}]},{"text":"En les relacions amb la comunitat, cal impedir qualsevol pràctica abusiva, arbitrària o discriminatòria que comporti violència física o moral; tractar els ciutadans de manera correcta i acurada, auxiliar-los i protegir-los, i informar-los àmpliament de les causes i la finalitat de les intervencions. Quan cal evitar un dany greu, immediat i irreparable, s''actua amb decisió i sense demora, regint-se per la congruència, l''oportunitat i la proporcionalitat. Les armes només es fan servir davant un risc racionalment greu per a la vida o la integritat pròpia o de tercers, o un risc greu per a la seguretat ciutadana.","refs":[{"ref":"1.1 Principis bàsics, p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"han d’actuar amb la decisió necessària, i sense demora quan en depengui evitar un dany greu, immediat i irreparable; i en fer-ho s’han de regir pels principis de congruència, oportunitat i proporcionalitat en la utilització dels mitjans al seu abast."},{"ref":"1.1 Principis bàsics, p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"Només han d’utilitzar les armes en les situacions en què hi hagi un risc racionalment greu per a la seva vida, la seva integritat física o les de terceres persones"}]}]},{"n":"5","title":"Principis bàsics d''actuació: detinguts, dedicació, secret i responsabilitat","blocks":[{"text":"En el tractament de detinguts, els agents s''han d''identificar degudament com a tals en el moment de la detenció; han de vetllar per la vida i la integritat física de les persones detingudes o sota custòdia, respectant-ne l''honor i la dignitat; i han de complir amb diligència els tràmits, terminis i requisits legals de la detenció.","refs":[{"ref":"1.1 Principis bàsics, p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"a) Els membres de les forces i cossos de seguretat s’han d’identificar degudament com a tals en el moment d’efectuar una detenció."}]},{"text":"La dedicació professional exigeix total dedicació i intervenir sempre, en qualsevol temps i lloc, tant de servei com fora de servei, en defensa de la llei i de la seguretat ciutadana. El secret professional obliga a guardar rigorós secret de les informacions conegudes per raó de les funcions; els agents no estan obligats a revelar les fonts d''informació, llevat que l''exercici de les funcions o la llei els imposin una altra cosa. I la responsabilitat és personal i directa pels actes que infringeixin normes legals, reglamentàries o aquests principis, sens perjudici de la responsabilitat patrimonial de l''Administració.","refs":[{"ref":"1.1 Principis bàsics, p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"han d’intervenir sempre, en qualsevol temps i lloc, tant si es troben de servei com si no, en defensa de la llei i de la seguretat ciutadana."},{"ref":"1.1 Principis bàsics, p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"No estan obligats a revelar les fonts d’informació, llevat que l’exercici de les seves funcions o les disposicions de la llei els imposin actuar d’una altra manera."},{"ref":"1.1 Principis bàsics, p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"Són responsables personalment i directament dels actes que portin a terme en la seva actuació professional"}]},{"text":"Aquests principis obliguen sense excepció tots els col·lectius policials. La disposició final segona estableix que s''apliquen directament a la Policia de la Generalitat els principis bàsics d''actuació i les disposicions estatutàries comunes dels articles 5, 6, 7 i 8. Compte: la idea força 6 de la guia esmenta només «els articles 6, 7 i 8» per a les disposicions estatutàries, però el text del tema i la resposta d''examen són 5, 6, 7 i 8 (l''article 5 conté els principis).","refs":[{"ref":"1.1 Principis bàsics, p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"que determina que s’han d’aplicar directament a la Policia de la Generalitat els principis bàsics d’actuació i les disposicions estatutàries comunes que estableixen els articles 5, 6, 7 i 8 de la Llei esmentada."},{"ref":"Idees força C.4 (6), p. 235","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=235","quote":"Els principis bàsic recollits a la Llei orgànica 2/1986 s’han d’aplicar directament a la Policia de la Generalitat, així com les disposicions estatutàries comunes que estableixen els articles 6, 7 i 8."}]}]},{"n":"6","title":"La Llei 10/1994, de la Policia de la Generalitat - Mossos d''Esquadra: antecedents i objecte","blocks":[{"text":"La Policia de la Generalitat va ser creada per la Llei 19/1983, de 14 de juliol, a partir del cos de Mossos d''Esquadra, que en conserva la denominació històrica. Així es manté la continuïtat amb un cos de principis del segle XVIII, primera força de policia professional a Catalunya i pionera a tot l''Estat. El precedent immediat són les competències de la Generalitat republicana: segons l''article 8 de l''Estatut de 1932, l''Estat només es reservava la seguretat pública extra i supracomunitària i deixava al Govern català totes les funcions de policia i ordre interiors, cosa que va ser decisiva per defensar la legalitat democràtica el juliol de 1936.","refs":[{"ref":"2. Llei 10/1994, p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"La Policia de la Generalitat fou creada per la Llei 19/1983, del 14 de juliol."},{"ref":"2. Llei 10/1994, p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"de conformitat amb l’article 8 de l’Estatut d’autonomia de Catalunya de 1932, segons les quals l’Estat només es reservava la seguretat pública de caràcter extra i supracomunitari, i deixava al Govern català totes les funcions de policia i ordre interiors."}]},{"text":"La Llei 10/1994, d''11 de juliol, té per objecte establir els principis d''actuació, les funcions i el règim funcionarial i estatutari dels membres del Cos de Mossos d''Esquadra, i l''organització de la seguretat pública a tot el territori, preveient els òrgans i mitjans necessaris. S''inspira en resolucions de l''Assemblea Parlamentària del Consell d''Europa (Declaració sobre la policia) i de l''Assemblea General de les Nacions Unides (Codi de conducta per a funcionaris encarregats de fer complir la llei).","refs":[{"ref":"2. Llei 10/1994, p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"la Llei present té per objecte establir els principis d’actuació, les funcions i el règim funcionarial i estatutari dels membres del Cos de Mossos d’Esquadra, i l’organització de la seguretat pública en tot el territori"},{"ref":"2. Llei 10/1994, p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"especialment en les relatives a la Declaració sobre la policia i al Codi de conducta per a funcionaris encarregats de fer complir la llei, respectivament."}]}]},{"n":"7","title":"Llei 10/1994: missió, policia judicial, coordinació i règim estatutari","blocks":[{"text":"La policia no està per damunt de la llei: ha d''adequar-se a l''ordenament, amb jerarquia i subordinació, i és col·laboradora indispensable de l''Administració de justícia. Només pot usar recursos coactius en situacions extremes i aplicant escrupolosament l''oportunitat, la proporcionalitat i la congruència. La seva missió i divisa principal és protegir la llibertat i la seguretat de la ciutadania.","refs":[{"ref":"2. Llei 10/1994, p. 228","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=228","quote":"té com a missió i divisa principal la protecció, d’acord amb l’ordenament jurídic, de la llibertat i la seguretat de la ciutadania."},{"ref":"2. Llei 10/1994, p. 228","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=228","quote":"l’obliga a utilitzar els recursos coactius solament en situacions extremes i amb una aplicació escrupolosa dels principis d’oportunitat, proporcionalitat i congruència."}]},{"text":"En policia judicial actua segons l''article 126 de la Constitució, el 164 de l''Estatut i els articles 547 i següents de la LOPJ; l''auxili a jutges, tribunals i fiscals és una activitat essencial, prioritària i permanent. Amb els altres cossos opera segons la cooperació, la coordinació i la col·laboració mútua; coordinar no vol dir sostreure competències, sinó informació recíproca i homogeneïtzació de mitjans. Amb les FCSE es coordina a la Junta de Seguretat de Catalunya i, amb les policies locals, a les juntes locals de seguretat, sens perjudici de la Comissió de Policia de Catalunya.","refs":[{"ref":"2. Llei 10/1994, p. 228","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=228","quote":"obliga la Policia de la Generalitat a operar, amb tots els altres cossos, segons els principis de cooperació, coordinació i col·laboració mútua."},{"ref":"2. Llei 10/1994, p. 228","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=228","quote":"la coordinació s’ha de produir mitjançant la Junta de Seguretat de Catalunya"}]},{"text":"En el règim de personal, l''accés i la promoció exigeixen superar els cursos de l''Institut de Seguretat Pública de Catalunya. La Llei facilita l''ingrés des de les policies locals, defineix drets i deures (inclosos els sindicals) i crea el Consell de la Policia, amb representació paritària de l''Administració de la Generalitat i dels membres del cos.","refs":[{"ref":"2. Llei 10/1994, p. 229","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=229","quote":"es crea el Consell de la Policia, amb representació paritària de l’Administració de la Generalitat i dels membres de la Policia de la Generalitat."},{"ref":"2. Llei 10/1994, p. 229","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=229","quote":"estableix com a requisit general la superació dels cursos de formació corresponents, impartits per l’Institut de Seguretat Pública de Catalunya"}]}]},{"n":"8","title":"Definició de les competències de la PG-ME","blocks":[{"text":"La PG-ME és una policia ordinària i integral: exerceix les funcions de policia de seguretat ciutadana, de policia administrativa i de policia judicial. Les de seguretat ciutadana inclouen protegir persones i béns, mantenir l''ordre públic, vigilar i protegir els edificis i dependències de la Generalitat, vigilar espais públics, protegir manifestacions, auxiliar en accidents i catàstrofes, ajudar en salvaments si hi és requerida, aplicar la LO 4/2015 de protecció de la seguretat ciutadana i prevenir actes delictius.","refs":[{"ref":"2.1 Definició de les competències, p. 229","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=229","quote":"La Policia de la Generalitat - Mossos d’Esquadra, com a policia ordinària i integral, exerceix les funcions que l’ordenament jurídic atribueix a les forces i els cossos de seguretat, i, en concret, les funcions de policia de seguretat ciutadana, policia administrativa i policia judicial."}]},{"text":"Com a policia administrativa, vetlla per les lleis del Parlament i les ordres de la Generalitat, inspecciona activitats, usa la coacció per a l''execució forçosa, vetlla per les normes estatals aplicables i els serveis públics essencials, pel medi ambient i la natura, i pel patrimoni cultural català (salvaguarda i protecció per evitar-ne l''espoli o la destrucció). També intercanvia informació policial amb altres cossos i controla les empreses de seguretat privada.","refs":[{"ref":"2.1 Definició de les competències, p. 230","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=230","quote":"f) Vetllar pel compliment de la normativa sobre el patrimoni cultural català, pel que fa a la salvaguarda i la protecció d’aquest i per evitar-ne l’espoli o la destrucció."},{"ref":"2.1 Definició de les competències, p. 230","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=230","quote":"h) Vigilar, inspeccionar i controlar les empreses de seguretat privada"}]},{"text":"A més, fa de policia judicial (pels serveis ordinaris o per unitats orgàniques), intervé en la resolució amistosa de conflictes privats si hi és requerida, i coopera amb els ens locals: dona suport tècnic i operatiu a les policies locals que no poden assumir un servei i, en els municipis sense policia local, n''exerceix les funcions pròpies, sempre mitjançant convenis de cooperació. També pot assumir funcions transferides o delegades per l''article 150.2 de la Constitució.","refs":[{"ref":"2.1 Definició de les competències, p. 230","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=230","quote":"b) Exercir, a més de les funcions assenyalades en aquest article, les pròpies de les policies locals en els municipis que no en disposin."},{"ref":"2.1 Definició de les competències, p. 230","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=230","quote":"la Generalitat i les corporacions locals han de subscriure els convenis de cooperació corresponents"}]}]},{"n":"9","title":"Àmbit territorial d''actuació: ABP i regió policial","blocks":[{"text":"L''àmbit d''actuació de la PG-ME és tot el territori de Catalunya, amb un model organitzatiu descentralitzat basat en l''Àrea Bàsica Policial (ABP), que és la unitat territorial bàsica. L''ABP es defineix per criteris operatius (població, vies de comunicació, planta judicial, índex de delictes, conflictivitat social) i té la seu en una comissaria que presta els serveis bàsics de seguretat ciutadana i investigació.","refs":[{"ref":"2.2 Àmbit territorial, p. 230","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=230","quote":"La Policia de la Generalitat - Mossos d’Esquadra té com a àmbit d’actuació el conjunt del territori de Catalunya."},{"ref":"2.2 Àmbit territorial, p. 231","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=231","quote":"i té la seva seu en una comissaria, des d’on es presten serveis policials bàsics en seguretat ciutadana i investigació."}]},{"text":"Una ABP pot abastar part d''una comarca, una comarca sencera o diverses comarques, però mai no es compon de parts de comarques diferents; a l''àmbit metropolità coincideix amb la divisió municipal. La regió policial (RP) agrupa un conjunt d''ABP i hi exerceix coordinació jeràrquica, suport en recursos i planificació superior.","refs":[{"ref":"2.2 Àmbit territorial, p. 231","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=231","quote":"Una ABP pot abastar part d’una comarca, una comarca sencera o un conjunt de comarques, però en cap cas es composa de parts de diferents comarques."},{"ref":"2.2 Àmbit territorial, p. 231","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=231","quote":"En l’àmbit metropolità, les ABP són coincidents amb la divisió municipal."}]}]},{"n":"10","title":"Estructura de la PG-ME: nivells organitzatius i escales","blocks":[{"text":"El desplegament va començar el 1994 a la comarca d''Osona. El Decret 57/2023, de 21 de març, estructura la PG-ME, per ordre de jerarquia, en: prefectura de la policia, comissaria superior, regió policial/comissaria general, divisió, àrea i unitat. Cal distingir aquesta estructura organitzativa de l''estructura jeràrquica, descrita als articles 18 i 19 de la Llei 10/1994.","refs":[{"ref":"2.3 Estructura, p. 231","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=231","quote":"Des de l’any 1994, amb el desplegament de substitució de les FCSE a la comarca d’Osona"},{"ref":"2.3 Estructura, p. 231","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=231","quote":"prefectura de la policia, comissaria superior, regió policial/comissaria general, divisió, àrea i unitat."}]},{"text":"Jeràrquicament hi ha cinc escales: bàsica (mosso i caporal: tasques executives i comandament dins la mateixa escala); intermèdia (sergent i sotsinspector: comandament operatiu i supervisió); executiva (inspector: gestió de les àrees i unitats i, si escau, comandament de l''activitat policial); superior (intendent, comissari i major: comandament, direcció, coordinació i inspecció en el nivell superior); i de suport (facultatiu i tècnic).","refs":[{"ref":"2.3 Estructura, p. 231","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=231","quote":"b) Escala intermèdia, que comprèn les categories de sergent i de sotsinspector."},{"ref":"2.3 Estructura, p. 232","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=232","quote":"c) Escala executiva, que comprèn la categoria d’inspector. La gestió de les diverses àrees i unitats dels Mossos d’Esquadra i, si s’escau, el comandament de l’activitat policial."},{"ref":"2.3 Estructura, p. 232","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=232","quote":"d) Escala superior, que comprèn les categories d’intendent, de comissari i de major."}]}]},{"n":"11","title":"La Llei 16/1991, de les policies locals de Catalunya","blocks":[{"text":"L''article 164.2 de l''Estatut atribueix a la Generalitat la coordinació de les policies locals, i la Llei 16/1991, de 10 de juliol, la desplega amb un règim homogeni que respecta l''autonomia municipal. La policia local depèn de les corporacions locals i és un institut armat de naturalesa civil amb estructura jerarquitzada. Els municipis de més de 10.000 habitants poden crear-ne (no és obligatori), i els més petits només per autorització excepcional del conseller. El comandament és de l''alcalde, i el comandament directe, del cap del cos.","refs":[{"ref":"3. Llei 16/1991, p. 232","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=232","quote":"tots els municipis amb una població superior als 10.000 habitants poden crear cossos de policia local."},{"ref":"3. Llei 16/1991, p. 232","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=232","quote":"El seu comandament serà exercit per l’alcalde, tot i que el comandament directe serà exercit pel cap del cos"}]},{"text":"L''article 24 fixa les escales de la policia local: superior (superintendent, intendent major i intendent), executiva (inspector), intermèdia (sotsinspector i sergent) i bàsica (caporal i agent). Només actua al seu municipi; excepcionalment, per emergència i donant-ne compte al conseller, pot actuar en municipis limítrofes. Els municipis sense policia local poden tenir guàrdies, vigilants, agents o algutzirs, sense arma. La Llei 4/2003, d''ordenació del sistema de seguretat pública, hi afegeix la cultura de la corresponsabilitat.","refs":[{"ref":"3. Llei 16/1991, p. 232","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=232","quote":"Escala superior, que comprèn les categories de superintendent, d’intendent major i d’intendent."},{"ref":"3. Llei 16/1991, p. 233","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=233","quote":"i excepcionalment, per raons d’emergència excepcional, i donant-ne compte al conseller o consellera del Departament amb competències en matèria de seguretat pública, pot actuar en els municipis limítrofes."},{"ref":"3. Llei 16/1991, p. 233","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=233","quote":"(cap d’aquestes figures estarà autoritzada per dur arma)"}]}]},{"n":"12","title":"Funcions de la policia local","blocks":[{"text":"Les policies locals es regeixen pels principis i disposicions estatutàries de la LO 2/1986, adaptats a l''Administració local. Les seves funcions pròpies destacades són la policia administrativa (normes municipals), la policia de trànsit al nucli urbà i la protecció d''autoritats i instal·lacions municipals; la vigilància d''espais públics, l''auxili, la prevenció de delictes i l''ordre es fan de forma compartida. Els municipis cap de partit judicial sense centre penitenciari poden assumir, per delegació, el dipòsit de detinguts.","refs":[{"ref":"3.1 Funcions de la policia local, p. 233","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=233","quote":"destaquen com a pròpies la de policia administrativa, en l’observació del compliment de les normes municipals; la de policia de trànsit, en el nucli urbà, i la de protecció de les autoritats i instal·lacions municipals."}]},{"text":"L''article 11 detalla les funcions: protegir les autoritats locals i custodiar-ne edificis i instal·lacions; ordenar el trànsit urbà; instruir atestats d''accidents al nucli urbà (comunicant-ho); policia administrativa i judicial; diligències de prevenció; col·laborar en manifestacions si són requerides; cooperar en conflictes privats; vigilar espais públics; auxili i protecció civil; medi ambient; i seguretat viària. En policia judicial actuen per cooperació mútua i col·laboració recíproca (article 12.2).","refs":[{"ref":"3.1 Funcions de la policia local, p. 234","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=234","quote":"a) Protegir les autoritats de les corporacions locals i vigilar i custodiar els edificis, les instal·lacions i les dependències d’aquestes corporacions."},{"ref":"3.1 Funcions de la policia local, p. 234","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=234","quote":"S’estableix a l’article 12.2 que les funcions de policia judicial s’han de complir d’acord amb els principis de cooperació mútua i de col·laboració recíproca amb la resta de FCS."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"La LO 2/1986 desplega l''article 104 de la Constitució; la seguretat pública és competència exclusiva de l''Estat (article 149.1.29).","refs":[{"ref":"p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"La Llei orgànica 2/1986 és una llei que desplega el mandat constitucional explícit a l’article 104"}]},{"text":"Els cossos autonòmics i les policies locals són instituts armats de naturalesa civil amb organització jerarquitzada.","refs":[{"ref":"p. 224","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=224","quote":"els cossos autonòmics de policia són instituts armats de naturalesa civil amb organització jerarquitzada."}]},{"text":"Principis bàsics d''actuació: article 5 de la LO 2/1986, en sis eixos; s''apliquen directament a la PG-ME (disposició final segona, articles 5 a 8).","refs":[{"ref":"p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"Segons l’article 5 de la Llei orgànica 2/1986"}]},{"text":"Ús de mitjans per evitar un dany greu, immediat i irreparable: congruència, oportunitat i proporcionalitat.","refs":[{"ref":"p. 226","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=226","quote":"principis de congruència, oportunitat i proporcionalitat en la utilització dels mitjans al seu abast."}]},{"text":"La Llei 19/1983 va crear la Policia de la Generalitat; la Llei 10/1994 crea el Consell de la Policia, paritari.","refs":[{"ref":"p. 227","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=227","quote":"La Policia de la Generalitat fou creada per la Llei 19/1983, del 14 de juliol."}]},{"text":"La PG-ME és policia ordinària i integral: seguretat ciutadana, administrativa i judicial.","refs":[{"ref":"p. 229","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=229","quote":"com a policia ordinària i integral"}]},{"text":"Unitat territorial bàsica: l''ABP, que mai no es compon de parts de comarques diferents; la RP n''agrupa diverses.","refs":[{"ref":"p. 235","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=235","quote":"Per a la implantació de la PG-ME, la unitat territorial bàsica és l’àrea bàsica policial (ABP)"}]},{"text":"Escales de la PG-ME: suport, bàsica, intermèdia, executiva i superior.","refs":[{"ref":"p. 236","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=236","quote":"s’estructura jeràrquicament en les escales de suport, bàsica, intermèdia, executiva i superior."}]},{"text":"Policia local: municipis de més de 10.000 habitants; escala superior amb superintendent, intendent major i intendent.","refs":[{"ref":"p. 236","law":"Guia d''estudi, tema C.4","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=236","quote":"Tots els municipis amb una població superior als 10.000 habitants poden crear cossos de policia local."}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=223'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=223', 223, 237, 235, null
