insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema C.5, pp. 238-242', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=238', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-c5-codi-deontologic', 'C.5 El Codi deontològic policial') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('mossos-esquadra') and t.slug = 'mossos-c5-codi-deontologic' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La deontologia policial"},{"n":"2","title":"El Codi europeu d’ètica de la policia"},{"n":"3","title":"Acord GOV/25/2015, de 24 de febrer, pel qual s’aprova el Codi d’ètica de la Policia de Catalunya"}]'::jsonb, '["En un sistema democràtic, l’Estat i la policia no només han de respectar els drets humans, sinó que n’han de ser els garants i protectors.","El Consell d’Europa, a la Recomanació REC(2001)10, aconsella als seus estats membres seguir el Codi europeu d’ètica de la policia. Aquest Codi promou la cooperació internacional sobre les qüestions referides a l’ètica policial i els aspectes relacionats amb els drets humans.","El Codi europeu d’ètica de la policia es basa en el principi de la protecció de l’Estat de dret com a base de qualsevol democràcia veritable, i en la consideració que la policia, juntament amb el sistema penal, tenen un paper determinant en aquesta protecció.","El Codi d’ètica de la Policia de Catalunya no entra a reglamentar pràctiques policials concretes, sinó que és una eina pedagògica i inspiradora dirigida als cossos de policia de les institucions pròpies de Catalunya, que identifica els seus mínims ètics comuns, el conjunt de principis, valors i competències que inspiren la funció policial."]'::jsonb, '["Codi","Convivència","Deontologia","Discriminació","Drets humans","Estat de dret","Garant","Norma ètica","Proximitat","Pedagogia"]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La deontologia professional: concepte i origen","blocks":[{"text":"El tema s''obre amb una definició que convé saber de memòria: la deontologia professional és el conjunt de principis i regles ètiques que regulen i guien una activitat professional. No parlem, doncs, de lleis penals ni de règim disciplinari, sinó de normes ètiques. La seva funció és fixar el mínim que es pot exigir a qualsevol professional: aquestes normes determinen els deures mínimament exigibles als professionals quan fan la seva feina. És una idea que l''examen pregunta directament («què determinen les normes deontològiques?»): els deures mínims, no els màxims ni les recompenses.","refs":[{"ref":"1. La deontologia policial, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"La deontologia professional és el conjunt de principis i regles ètiques que regulen i guien una activitat professional. Aquestes normes determinen els deures mínimament exigibles als professionals en l’acompliment de la seva activitat."}]},{"text":"D''on surten aquestes normes? La guia explica que, precisament perquè fixen els deures mínims de la professió, solen néixer del mateix col·lectiu professional. És el propi col·lectiu qui les posa per escrit i les recull en documents que anomenem codis deontològics. Per tant, l''origen típic no és una imposició externa del legislador, sinó l''autoregulació de la professió, que després es concreta en un codi escrit.","refs":[{"ref":"1. La deontologia policial, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"Per aquest motiu, solen sorgir del mateix col·lectiu professional, el qual s’encarrega de recollir-los per escrit en els codis deontològics."}]}]},{"n":"2","title":"El codi de deontologia policial: una doble garantia","blocks":[{"text":"Aplicat a la policia, un codi de deontologia policial és un enunciat de principis i ideals amb els quals els agents d''un servei de policia es comprometen. Fixa''t en el verb: els agents «es comprometen» amb aquests principis i ideals, és a dir, els assumeixen com a propis.","refs":[{"ref":"1. La deontologia policial, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"Un codi de deontologia policial és un enunciat de principis i ideals als quals els agents d’un servei de policia es comprometen."}]},{"text":"La guia subratlla que aquest codi és una garantia en dues direccions. D''una banda, ho és per al ciutadà, que sap quines regles ha de seguir la policia que l''atén. De l''altra, ho és també per al mateix agent de policia, perquè entén i accepta les regles amb què ha de treballar i les assimila com a pròpies. A l''examen, si et pregunten per a qui és una garantia el codi, la resposta completa és «per al ciutadà i també per a l''agent».","refs":[{"ref":"1. La deontologia policial, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"El Codi de deontologia policial és una garantia per al ciutadà, però també per al mateix agent de policia, que entén i accepta les regles amb les quals ha de treballar i les assimila com a pròpies."}]}]},{"n":"3","title":"La deontologia particular de la policia i els drets humans","blocks":[{"text":"La policia té una deontologia particular, diferent de la d''altres professions, perquè la seva feina toca directament els drets de les persones. En un estat democràtic, la policia ha de vetllar per la protecció dels drets humans de totes les persones. Per aconseguir-ho no n''hi ha prou amb complir i fer complir la llei: a més, ha de mostrar respecte cap als drets de les persones. Són dues exigències acumulades (legalitat i respecte), no alternatives.","refs":[{"ref":"1. La deontologia policial, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"La policia té una deontologia particular. En un estat democràtic, la policia ha de vetllar per la protecció dels drets humans de totes les persones. I perquè això sigui així, la policia no solament ha de complir i fer complir la llei, sinó que, a més, ha de mostrar respecte cap als drets de les persones."}]},{"text":"Els principals organismes internacionals coincideixen a entendre la deontologia policial d''acord amb les declaracions internacionals dels drets humans. La idea central, que és també la primera idea força del tema, és que en un sistema democràtic l''Estat i la policia no només han de respectar els drets humans, sinó que n''han de ser els garants i protectors. El paper, per tant, és actiu: no és només abstenir-se de vulnerar drets, sinó protegir-los.","refs":[{"ref":"1. La deontologia policial, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"Els principals organismes internacionals coincideixen a considerar la deontologia policial d’acord amb les declaracions internacionals dels drets humans i amb la convicció que, en un sistema democràtic, l’Estat i la policia no només han de respectar els drets humans, sinó que n’han de ser els garants i protectors."}]}]},{"n":"4","title":"El Codi europeu d''ètica de la policia: la Recomanació REC(2001)10","blocks":[{"text":"El segon apartat se centra en el text europeu de referència. El Codi europeu d''ètica de la policia es troba en la Recomanació REC(2001)10 del Comitè de Ministres del Consell d''Europa, adoptada el 19 de setembre de 2001. Memoritza les tres dades: òrgan (Comitè de Ministres del Consell d''Europa), nom de la norma (Recomanació REC(2001)10) i data d''adopció (19 de setembre de 2001). Atenció a no confondre el Consell d''Europa amb la Unió Europea: és el Consell d''Europa.","refs":[{"ref":"2. El Codi europeu d’ètica de la policia, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"El Comitè de Ministres del Consell d’Europa, en la Recomanació REC(2001)10, sobre el Codi europeu d’ètica de la policia, adoptada el 19 de setembre de 2001"}]},{"text":"Com que és una recomanació, el text no obliga directament: el que fa és recomanar que els governs dels estats membres basin en els principis del Codi la seva legislació, les seves pràctiques internes i els seus codis de conducta en matèria de policia. L''objectiu és que s''implanti de manera progressiva i que se''n faci la màxima difusió possible.","refs":[{"ref":"2. El Codi europeu d’ètica de la policia, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"recomana que els governs dels estats membres basin la seva legislació, les pràctiques internes i els seus codis de conducta en matèria de policia en els principis recollits en el Codi europeu d’ètica de la policia, amb vista a la seva implantació progressiva i a donar la màxima difusió possible a aquest text."}]}]},{"n":"5","title":"Finalitat, fonament i àmbit d''aplicació del Codi europeu","blocks":[{"text":"El Codi europeu promou la cooperació internacional en les qüestions d''ètica policial i en els aspectes relacionats amb els drets humans. La raó és que l''objectiu de la policia és la defensa dels drets i les llibertats fonamentals dels ciutadans, tal com recull la Convenció europea dels drets humans.","refs":[{"ref":"2. El Codi europeu d’ètica de la policia, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"Aquest Codi promou la cooperació internacional sobre les qüestions referides a l’ètica policial i els aspectes relacionats amb els drets humans, atès que l’objectiu de la policia és la defensa dels drets i les llibertats fonamentals dels ciutadans, com recull la Convenció europea dels drets humans."}]},{"text":"Pel que fa al seu fonament, el Codi es basa en el principi de la protecció de l''Estat de dret com a base de qualsevol democràcia veritable. A aquest principi s''hi afegeix una consideració: la policia, juntament amb el sistema penal, té un paper determinant en aquesta protecció de l''Estat de dret. Aquesta frase és literalment una idea força i ha sortit en preguntes de test.","refs":[{"ref":"2. El Codi europeu d’ètica de la policia, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"el Codi es basa en el principi de la protecció de l’Estat de dret com a base de qualsevol democràcia veritable, i en la consideració que la policia, juntament amb el sistema penal, tenen un paper determinant en aquesta protecció."}]},{"text":"L''àmbit d''aplicació és ampli. El Codi s''aplica a les forces públiques de seguretat tradicionals o serveis de policia, i també a altres òrgans autoritzats o controlats pels poders públics que compleixin dues condicions: que el seu primer objectiu sigui garantir el manteniment de l''ordre en la societat civil, i que l''Estat els autoritzi a utilitzar la força o poders especials per assolir-lo. Per tant, el criteri no és el nom del cos, sinó la funció (mantenir l''ordre) i l''autorització per usar la força.","refs":[{"ref":"2. El Codi europeu d’ètica de la policia, p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"Aquest Codi s’aplica a les forces públiques de seguretat tradicionals o serveis de policia, o a altres òrgans autoritzats i/o controlats pels poders públics el primer objectiu dels quals consisteix a garantir el manteniment de l’ordre en la societat civil, i que estan autoritzats per l’Estat a utilitzar la força i/o poders especials per assolir aquest objectiu."}]}]},{"n":"6","title":"La incorporació del Codi europeu a la PG-ME: Resolució INT/1828/2004","blocks":[{"text":"A Catalunya, el Codi europeu es va incorporar a l''actuació dels Mossos d''Esquadra mitjançant la Resolució INT/1828/2004, de 14 de juny. Aquesta resolució va aprovar la Instrucció per a la incorporació i l''aplicació del Codi europeu d''ètica de la policia en relació amb l''actuació i la intervenció de la Policia de la Generalitat - Mossos d''Esquadra. Dada d''examen: INT/1828/2004, de 14 de juny (no la confonguis amb l''Acord GOV/25/2015, que és el codi català propi).","refs":[{"ref":"2. El Codi europeu d’ètica de la policia, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Mitjançant la Resolució INT/1828/2004, de 14 de juny, es va aprovar la Instrucció per a la incorporació i l’aplicació del Codi europeu d’ètica de la policia en relació amb l’actuació i la intervenció de la Policia de la Generalitat - Mossos d’Esquadra"}]},{"text":"La finalitat de la Instrucció és que els membres del Cos de Mossos d''Esquadra procurin adequar la seva actuació i el compliment de les seves funcions als principis, les bases i els criteris del Codi ètic europeu, sempre d''acord amb les funcions que els atribueix l''ordenament jurídic.","refs":[{"ref":"2. El Codi europeu d’ètica de la policia, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"per tal que els membres del Cos de Mossos d’Esquadra procurin adequar-se en la seva actuació i en el compliment de les seves funcions als principis, les bases i els criteris establerts en el Codi ètic esmentat, d’acord amb les funcions que els atribueix l’ordenament jurídic."}]}]},{"n":"7","title":"El Comitè d''Ètica de la Policia de Catalunya i l''Acord GOV/25/2015","blocks":[{"text":"El tercer apartat explica el codi català. Les institucions catalanes competents en seguretat pública han de promoure les bones pràctiques policials i vetllar perquè encaixin en els marcs deontològics internacionals, especialment el Codi europeu d''ètica de la policia. Amb aquesta voluntat es va crear l''any 2007 el Comitè d''Ètica de la Policia de Catalunya, que va esdevenir una eina de recerca i de consulta en matèria de deontologia policial.","refs":[{"ref":"3. Acord GOV/25/2015, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Les institucions catalanes competents en matèria de seguretat pública han de vetllar per la promoció de les bones pràctiques en l’àmbit policial, i que aquestes encaixin en els marcs deontològics internacionals, especialment el Codi europeu d’ètica de la policia. Amb aquesta voluntat es va crear al 2007 el Comitè d’Ètica de la Policia de Catalunya, que va esdevenir una eina de recerca en matèria de deontologia policial i consulta."}]},{"text":"Va ser aquest Comitè d''Ètica qui va proposar el Codi d''ètica de la Policia de Catalunya, i el Govern el va aprovar per l''Acord GOV/25/2015, de 24 de febrer. Recorda la seqüència: Comitè creat el 2007, que proposa; Govern que aprova el 2015. Amb aquest Codi, Catalunya segueix la línia de la majoria de països de llarga tradició democràtica.","refs":[{"ref":"3. Acord GOV/25/2015, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Aquest Comitè va proposar el Codi d’ètica de la Policia de Catalunya, que va ser aprovat pel Govern a través de l’Acord GOV/25/2015, de 24 de febrer, pel qual s’aprova el Codi d’ètica de la Policia de Catalunya. Amb l’acceptació d’aquest Codi, Catalunya segueix la línia de la majoria de països de llarga tradició democràtica."}]},{"text":"El Codi no és un text tancat: ell mateix preveu que s''haurà de modificar per adaptar-se als canvis de la societat i de la funció policial. Aquesta previsió de revisió funciona com a mecanisme de garantia de la seva vigència efectiva i real.","refs":[{"ref":"3. Acord GOV/25/2015, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"El mateix Codi preveu la necessitat de ser modificat per adaptar-se als canvis que comporta l’evolució de la societat i de la funció policial, com a mecanisme de garantia de vigència efectiva i real."}]}]},{"n":"8","title":"Naturalesa, destinataris i contingut del Codi d''ètica de la Policia de Catalunya","blocks":[{"text":"Quina mena de text és el Codi català? No reglamenta pràctiques policials concretes, sinó que és una eina pedagògica i inspiradora. Va dirigit als cossos de policia de les institucions pròpies de Catalunya, i identifica els seus mínims ètics comuns: el conjunt de principis, valors i competències que inspiren la funció policial. A més, al preàmbul fa extensiva la seva funció de marc de referència als vigilants municipals. Distingeix bé: destinataris, els cossos de policia de les institucions pròpies de Catalunya; marc de referència estès, els vigilants municipals.","refs":[{"ref":"3. Acord GOV/25/2015, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Aquest Codi no entra a reglamentar pràctiques policials concretes, sinó que és una eina pedagògica i inspiradora dirigida als cossos de policia de les institucions pròpies de Catalunya, que identifica els seus mínims ètics comuns, el conjunt de principis, valors i competències que inspiren la funció policial. Al seu preàmbul, fa extensiva la seva funció com a marc de referència per als vigilants municipals."}]},{"text":"El Codi parteix d''una constatació realista: cap text normatiu no pot recollir tota la complexitat i diversitat de les situacions reals, i la naturalesa de la feina policial fa que sovint s''hagin de prendre decisions in extremis. Per això el Codi exposa drets, però també deures i compromisos de la policia davant la ciutadania, recordant sempre la seva autonomia d''actuació.","refs":[{"ref":"3. Acord GOV/25/2015, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"No és possible encabir en un text normatiu la complexitat i la diversitat de les situacions reals. La pròpia naturalesa de les actuacions policials comporta que la presa de decisions in extremis sigui habitual. Per això, el Codi exposa drets, i també deures i compromisos que ha d’assumir la policia davant la ciutadania, però recordant sempre la seva autonomia d’actuació."}]},{"text":"El contingut descriu allò que és exigible a la policia, amb una doble voluntat: garantir-ne la credibilitat i fomentar la confiança de la ciutadania en el cos. Per aconseguir-ho, demana actuar amb bones pràctiques, exercir les funcions de manera competent en pro del bé comú, actuar de forma no discriminatòria i respectar la dignitat i l''autonomia de les persones.","refs":[{"ref":"3. Acord GOV/25/2015, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"El seu contingut presenta un escenari on es descriu allò que és exigible a la policia, amb la voluntat de garantir-ne la credibilitat i fomentar la confiança de la ciutadania vers el cos policial. Per això, descriu la necessitat d’actuació a través de bones pràctiques, un exercici competent de les seves funcions en pro del bé comú, actuant de forma no discriminatòria i respectant la dignitat i l’autonomia de les persones."}]},{"text":"Finalment, el Codi destaca la cooperació policial, la col·laboració amb l''Administració de justícia i els poders públics, i la gestió responsable de la informació que deriva de les actuacions policials. I atribueix a la funció policial tres caràcters que cal recordar junts: proximitat i atenció a les persones, foment de la convivència i pràctica pedagògica.","refs":[{"ref":"3. Acord GOV/25/2015, p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Finalment, el Codi destaca la importància de la cooperació policial, la col·laboració amb l’Administració de justícia i els poders públics, així com de la gestió responsable de la informació que deriva de les seves actuacions. Atribueix a la funció policial el caràcter de proximitat i atenció a les persones, el foment de la convivència i la pràctica pedagògica."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Deontologia professional: conjunt de principis i regles ètiques que regulen i guien una activitat professional; fixa els deures mínimament exigibles i sol sorgir del mateix col·lectiu.","refs":[{"ref":"p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"Aquestes normes determinen els deures mínimament exigibles als professionals en l’acompliment de la seva activitat."}]},{"text":"El codi de deontologia policial és una garantia per al ciutadà i també per a l''agent.","refs":[{"ref":"p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"El Codi de deontologia policial és una garantia per al ciutadà, però també per al mateix agent de policia"}]},{"text":"En democràcia, l''Estat i la policia no només respecten els drets humans: en són els garants i protectors.","refs":[{"ref":"p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"en un sistema democràtic, l’Estat i la policia no només han de respectar els drets humans, sinó que n’han de ser els garants i protectors."}]},{"text":"Codi europeu d''ètica de la policia: Recomanació REC(2001)10 del Comitè de Ministres del Consell d''Europa, adoptada el 19 de setembre de 2001.","refs":[{"ref":"p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"El Comitè de Ministres del Consell d’Europa, en la Recomanació REC(2001)10, sobre el Codi europeu d’ètica de la policia, adoptada el 19 de setembre de 2001"}]},{"text":"Fonament del Codi europeu: la protecció de l''Estat de dret com a base de qualsevol democràcia veritable.","refs":[{"ref":"p. 239","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=239","quote":"el Codi es basa en el principi de la protecció de l’Estat de dret com a base de qualsevol democràcia veritable"}]},{"text":"Incorporació a la PG-ME: Resolució INT/1828/2004, de 14 de juny.","refs":[{"ref":"p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Mitjançant la Resolució INT/1828/2004, de 14 de juny, es va aprovar la Instrucció"}]},{"text":"Comitè d''Ètica de la Policia de Catalunya: creat el 2007; va proposar el Codi aprovat per l''Acord GOV/25/2015, de 24 de febrer.","refs":[{"ref":"p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"es va crear al 2007 el Comitè d’Ètica de la Policia de Catalunya"}]},{"text":"El Codi català va dirigit als cossos de policia de les institucions pròpies de Catalunya i, al preàmbul, és marc de referència per als vigilants municipals.","refs":[{"ref":"p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"dirigida als cossos de policia de les institucions pròpies de Catalunya"},{"ref":"p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Al seu preàmbul, fa extensiva la seva funció com a marc de referència per als vigilants municipals."}]},{"text":"Caràcter de la funció policial segons el Codi català: proximitat i atenció a les persones, foment de la convivència i pràctica pedagògica.","refs":[{"ref":"p. 240","law":"Guia d''estudi, tema C.5","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=240","quote":"Atribueix a la funció policial el caràcter de proximitat i atenció a les persones, el foment de la convivència i la pràctica pedagògica."}]}]}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=238'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=238', 238, 242, 241, null
  from public.topics t where t.slug = 'mossos-c5-codi-deontologic'
