select t.id, 'ca', '[{"n":"1","title":"Esport (Festa de l''Esport Català, Jocs de Milano Cortina 2026, campions del món)"},{"n":"2","title":"Premis i distincions (Medalla d''Or, Creu de Sant Jordi, Premi Internacional Catalunya, Premi Ramon Margalef)"},{"n":"3","title":"Cinema (Goya a Barcelona, Sirât als Oscars, Balandrau, Festival de Sitges)"},{"n":"4","title":"Grans esdeveniments (Tour de França, visita del papa Lleó XIV, eclipsi, MWC, Congrés UIA, Any Gaudí)"},{"n":"5","title":"Institucions, lleis i commemoracions (lleis del Parlament, commemoracions 2026 i 2027)"},{"n":"6","title":"Seguretat i emergències (INUNCAT, Agents Rurals)"}]'::jsonb, '["Les activistes palestina i israeliana que aquest dijous rebran el Premi Internacional Catalunya 2025, Reem Alhajajra i Yael Admi, han pogut conèixer durant tres dies el compromís amb la pau i els drets humans de la societat catalana (govern.cat, 15/01/2026)","Premi al millor esportista català: Kilian Jornet (ALPINISME) (govern.cat, 16/01/2026)","Premi a la millor esportista catalana: Iris Tió (NATACIÓ ARTÍSTICA) (govern.cat, 16/01/2026)","el cap de l’Executiu ha destacat que la celebració de la gala dels Premis Goya, demà a Barcelona per primera vegada en 25 anys, “posa de manifest la bona relació que hi ha entre les dues acadèmies”. (govern.cat, 27/02/2026)","El Departament de Cultura acompanyarà l’equip de la producció catalana Sirât a la gala d’entrega dels Premis Oscar que tindrà lloc a l’emblemàtic Dolby Theatre el pròxim 15 de març. (govern.cat, 12/03/2026)","El Govern, a proposta de la consellera de Cultura, ha acordat concedir la Creu de Sant Jordi de la Generalitat de Catalunya 2026 a 20 persones i 10 entitats (govern.cat, 14/04/2026)","El Parlament de Catalunya ha aprovat avui la primera Llei del Tercer Sector Social. (govern.cat, 20/05/2026)","El president de la Generalitat, Salvador Illa, ha destacat aquest matí que la visita del Papa Lleó XIV serà “un fet icònic per a Catalunya i Barcelona”, especialment per la seva coincidència amb la benedicció de la torre de Jesús de la Sagrada Família. (govern.cat, 09/06/2026)","La UIA ha presentat durant la cloenda la Declaració de Barcelona, un manifest articulat al voltant de sis compromisos: temps, matèria, vida, justícia, escala i significat (govern.cat, 02/07/2026)","El Grand Départ del Tour de França ha deixat petjada a Catalunya amb la celebració de tres etapes (govern.cat, 06/07/2026)","El Parlament de Catalunya ha aprovat avui el Projecte de llei de modificació del Codi civil de Catalunya en matèria de suports a l''exercici de la capacitat jurídica, una norma que culmina l''adaptació del dret civil català a la Convenció de les Nacions Unides sobre els drets de les persones amb discapacitat (govern.cat, 22/07/2026)","El Govern ha aprovat les 21 commemoracions oficials de la Generalitat per a l’any 2027 (govern.cat, 28/07/2026)","Catalunya va viure ahir amb èxit una jornada històrica amb motiu de l’eclipsi solar total, el primer que es podia observar des del territori català en més de 120 anys. (govern.cat, 13/08/2026)","El biòleg Josep Canadell i Gili ha estat distingit amb el Premi Ramon Margalef d’Ecologia 2026, que atorga anualment la Generalitat de Catalunya. (govern.cat, 25/08/2026)","El Consell Executiu ha aprovat atorgar la Medalla d’Or de la Generalitat de Catalunya al cuiner Ferran Adrià i a la física i directora del Sincrotró ALBA Caterina Biscari (govern.cat, 01/09/2026)","les commemoracions oficials de la Generalitat del 2026: el 150è aniversari dels naixements de Pau Casals i de Josep Irla i els 100 anys de la mort d’Antoni Gaudí. (govern.cat, 02/09/2026)","Protecció Civil de la Generalitat manté en fase d’Emergència el Pla especial d’emergències per inundacions de Catalunya (INUNCAT) i ha aixecat el confinament de la població del Baix Ebre i el Montsià. (govern.cat, 02/10/2026)","Els tres Campionats del Món d’aigües braves de Paddle Worldwide que Sort i la Seu d’Urgell acolliran l’any 2027 compartiran una mateixa identitat: Pirineus 27. (govern.cat, 05/10/2026)","Oriol Cardona: Campió olímpic d''esquí de muntanya als Jocs de Milano Cortina 2026, el primer or olímpic d''hivern de la història de l''esport català, i bronze en relleus mixtos. (govern.cat, 27/10/2026)","Pau Cubarsí: Amb 19 anys, campió del món amb la selecció espanyola i escollit Millor Jugador Jove del Mundial. (govern.cat, 27/10/2026)","Toni Bou: Campió del món de TrialGP i d''X-Trial per vintena vegada consecutiva. Amb 40 títols mundials, és el pilot més llorejat de la història del motociclisme. (govern.cat, 27/10/2026)","FC Barcelona Femení: Pòquer de títols, amb: Lliga F, UEFA Women''s Champions League, Copa de la Reina i Supercopa d''Espanya. (govern.cat, 27/10/2026)"]'::jsonb, '["Grand Départ","Festa de l''Esport Català","Medalla d''Or de la Generalitat","Creu de Sant Jordi","Premi Internacional Catalunya","INUNCAT","ES-Alert","Pirineus 27","UIA"]'::jsonb, '[{"text":"Font de cada fet: nota de premsa oficial (URL i data a la ''ref'' de cada pregunta). Fragments literals a fuentes-oficiales/contenido-mossos/web/actualitat-govern-2025-2026.txt.","url":"https://govern.cat/salapremsa/notes-premsa"}]'::jsonb, '[{"n":"1","title":"Esport: Festa de l''Esport Català, Jocs d''Hivern i campions del món","blocks":[{"text":"La Festa de l''Esport Català l''organitzen el Departament d''Esports, la Unió de Federacions Esportives de Catalunya (UFEC) i el diari Sport. A la 29a edició (nota del 16 de gener de 2026), els premis a la millor temporada del 2025 van ser per a l''alpinista Kilian Jornet (millor esportista català), per a la nedadora artística Iris Tió (millor esportista catalana) i per al futbolista Joan Garcia (esportista masculí amb més projecció).","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/783508/kilian-jornet-iris-tio-millors-esportistes-catalans-2025","quote":"La 29a edició de la Festa de l’Esport Català està organitzada pel Departament d’Esports, la Unió de Federacions Esportives de Catalunya (UFEC) i el diari Sport"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/783508/kilian-jornet-iris-tio-millors-esportistes-catalans-2025","quote":"Premi al millor esportista català: Kilian Jornet (ALPINISME) Premi a la millor esportista catalana: Iris Tió (NATACIÓ ARTÍSTICA) Premi a l’esportista amb més projecció masculí: Joan Garcia (FUTBOL)"}]},{"text":"Els finalistes de la 30a edició (nota del 27 d''octubre de 2026) resumeixen les grans fites individuals. Oriol Cardona va ser campió olímpic d''esquí de muntanya als Jocs de Milano Cortina 2026: el primer or olímpic d''hivern de la història de l''esport català (i bronze en relleus mixtos). Pau Cubarsí, amb 19 anys, va ser campió del món amb la selecció espanyola i Millor Jugador Jove del Mundial. Toni Bou va guanyar el TrialGP i l''X-Trial per vintena vegada consecutiva i, amb 40 títols mundials, és el pilot més llorejat de la història del motociclisme. Iris Tió va ser escollida per World Aquatics millor nedadora artística del món del 2025.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Oriol Cardona: Campió olímpic d''esquí de muntanya als Jocs de Milano Cortina 2026, el primer or olímpic d''hivern de la història de l''esport català, i bronze en relleus mixtos."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Pau Cubarsí: Amb 19 anys, campió del món amb la selecció espanyola i escollit Millor Jugador Jove del Mundial."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Toni Bou: Campió del món de TrialGP i d''X-Trial per vintena vegada consecutiva. Amb 40 títols mundials, és el pilot més llorejat de la història del motociclisme."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"World Aquatics la va escollir millor nedadora artística del món del 2025."}]},{"text":"Més campions del món: Ai Tsunoda, en judo (-70 kg), primer títol mundial del judo espanyol des del 1997; Guillem Farrés, campió del món de MX2, el primer títol mundial de motocròs de la història de Triumph; i Daniela Guillén, de 20 anys, campiona del món de motocròs femení (WMX), la primera pilot catalana i espanyola que ho aconsegueix.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Ai Tsunoda: Campiona del món absoluta de judo en la categoria de -70 kg, el primer títol mundial del judo espanyol des del 1997."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Guillem Farrés: Campió del món de MX2, el primer títol mundial de motocròs de la història de Triumph"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Daniela Guillén: Amb 20 anys, s''ha proclamat campiona del món de motocròs femení (WMX), la primera pilot catalana i espanyola que ho aconsegueix."}]},{"text":"Pel que fa als clubs: el CN Atlètic-Barceloneta va fer un sextet inèdit en el waterpolo estatal (Champions League, Supercopa d''Europa, Lliga, Copa del Rei, Copa Catalunya i Supercopa d''Espanya); el FC Barcelona Femení, un pòquer (Lliga F, UEFA Women''s Champions League, Copa de la Reina i Supercopa d''Espanya), i el FC Barcelona d''handbol, una temporada perfecta de set títols de set, amb l''EHF Champions League i la IHF Super Globe. Pere Romeu, entrenador del Barça Femení, va guanyar tots els títols i va ser reconegut com a millor entrenador a la gala de la Pilota d''Or.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"CN Atlètic-Barceloneta: Sextet inèdit en el waterpolo estatal, amb Champions League, Supercopa d''Europa, Lliga, Copa del Rei, Copa Catalunya i Supercopa d''Espanya."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"FC Barcelona Femení: Pòquer de títols, amb: Lliga F, UEFA Women''s Champions League, Copa de la Reina i Supercopa d''Espanya."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"FC Barcelona (handbol): Temporada perfecta amb set títols de set, inclosos l''EHF Champions League i la IHF Super Globe."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Reconegut com a millor entrenador a la gala de la Pilota d’Or."}]},{"text":"Esdeveniments esportius de futur: Sort i la Seu d''Urgell acolliran el 2027 tres Campionats del Món d''aigües braves de Paddle Worldwide (piragüisme), sota la marca comuna Pirineus 27 (nota del 5 d''octubre de 2026). I la Generalitat i Barcelona donen suport a la candidatura del Camp Nou per acollir la final de la Lliga de Campions de futbol masculina 2029, que presenten conjuntament la ciutat i el FC Barcelona (nota del 3 de febrer de 2026).","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/875860/presentada-pirineus-27-marca-unitaria-dels-tres-campionats-del-mon-daigues-braves-sort-durgell","quote":"Els tres Campionats del Món d’aigües braves de Paddle Worldwide que Sort i la Seu d’Urgell acolliran l’any 2027 compartiran una mateixa identitat: Pirineus 27."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/787440/catalunya-barcelona-donen-suport-candidatura-del-camp-nou-acollir-final-lliga-campions-futbol-masculina-2029","quote":"Catalunya i Barcelona donen suport a la candidatura del Camp Nou per acollir la final de la Lliga de Campions de futbol masculina 2029"}]}]},{"n":"2","title":"Premis i distincions","blocks":[{"text":"La Medalla d''Or és la màxima distinció de la Generalitat. L''1 de setembre de 2026 el Consell Executiu la va atorgar al cuiner Ferran Adrià i a la física Caterina Biscari, directora del Sincrotró ALBA. La Creu de Sant Jordi 2026 (nota del 14 d''abril) es va concedir, a proposta de la consellera de Cultura, a 20 persones i 10 entitats per serveis destacats en la defensa de la identitat de Catalunya o en el pla cívic i cultural.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/862672/govern-lliura-medalla-dor-generalitat-al-cuiner-ferran-adria-fisica-directora-del-sincrotro-alba-caterina-biscari","quote":"El Consell Executiu ha aprovat atorgar la Medalla d’Or de la Generalitat de Catalunya al cuiner Ferran Adrià i a la física i directora del Sincrotró ALBA Caterina Biscari"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/862672/govern-lliura-medalla-dor-generalitat-al-cuiner-ferran-adria-fisica-directora-del-sincrotro-alba-caterina-biscari","quote":"La Medalla d’Or és la màxima distinció que atorga la Generalitat de Catalunya."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/812364/govern-distingeix-creu-sant-jordi-20-persones-10-entitats","quote":"ha acordat concedir la Creu de Sant Jordi de la Generalitat de Catalunya 2026 a 20 persones i 10 entitats"}]},{"text":"El Premi Internacional Catalunya 2025 el van rebre (nota del 15 de gener de 2026) les activistes Reem Alhajajra, palestina, i Yael Admi, israeliana, pel seu compromís amb la pau. El Premi Ramon Margalef d''Ecologia 2026, que la Generalitat atorga cada any, va ser per al biòleg Josep Canadell i Gili pel seu treball pioner sobre la dinàmica dels embornals naturals de carboni.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/783348/guardonades-premi-internacional-catalunya-coneixen-compromis-pacifista-catala-patrimoni-del-pais","quote":"Les activistes palestina i israeliana que aquest dijous rebran el Premi Internacional Catalunya 2025, Reem Alhajajra i Yael Admi"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/861560/bioleg-josep-canadell-guanyador-del-22e-premi-ramon-margalef-decologia-2026","quote":"Canadell ha estat premiat pel seu treball pioner en la investigació sobre la dinàmica dels embornals naturals de carboni"}]}]},{"n":"3","title":"Cinema","blocks":[{"text":"La gala dels Premis Goya es va fer a Barcelona per primera vegada en 25 anys; el president Salvador Illa va oferir al Palau de la Generalitat una recepció pels Goya i els Gaudí i va dir que la gala mostra la bona relació entre les dues acadèmies (nota del 27 de febrer de 2026, que situa la gala l''endemà). El Departament de Cultura va acompanyar la producció catalana Sirât a la gala dels Oscars, al Dolby Theatre, el 15 de març de 2026. La nota recorda que el 2011 Pa negre, d''Agustí Villaronga, va representar Espanya als Oscars sense arribar a la nominació. La nota no diu el resultat de Sirât a la gala.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/795896/president-illa-la-celebracio-gala-dels-goya-barcelona-posa-manifest-bona-relacio-dues-academies-del-cinema","quote":"la celebració de la gala dels Premis Goya, demà a Barcelona per primera vegada en 25 anys, “posa de manifest la bona relació que hi ha entre les dues acadèmies”."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/800624/departament-cultura-acompanya-produccio-catalana-sirat-als-oscars-2026","quote":"El Departament de Cultura acompanyarà l’equip de la producció catalana Sirât a la gala d’entrega dels Premis Oscar que tindrà lloc a l’emblemàtic Dolby Theatre el pròxim 15 de març."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/800624/departament-cultura-acompanya-produccio-catalana-sirat-als-oscars-2026","quote":"Anteriorment, el 2011, Pa Negre d’Agustí Villaronga va ser la pel·lícula escollida per representar Espanya als Oscars"}]},{"text":"La pel·lícula Balandrau, vent salvatge es va estrenar en versió original en català amb el suport de l''Institut Català de les Empreses Culturals (ICEC). Recrea el 30 de desembre del 2000, quan un grup d''amics va fer el cim del Balandrau, entre les valls de Ribes i de Camprodon, i els va sorprendre el torb, una ventada que aixeca la neu i anul·la la visibilitat. El Sitges - Festival Internacional de Cinema Fantàstic de Catalunya va celebrar la 59a edició l''octubre de 2026; el Jurat Carnet Jove va premiar Ghost in the Cell, de Joko Anwar.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/793216/balandrau-vent-salvatge-sestrena-versio-original-cinquantena-sales","quote":"El 30 de desembre del 2000, un grup d’amics es disposa a fer el cim del Balandrau, entre les valls de Ribes i de Camprodon."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/793216/balandrau-vent-salvatge-sestrena-versio-original-cinquantena-sales","quote":"és el torb"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/881916/jurat-del-carnet-jove-del-festival-internacional-sitges-premia-ghost-in-the-cell-joko-anwar","quote":"la cerimònia de cloenda de la 59a edició del Sitges - Festival Internacional de Cinema Fantàstic de Catalunya"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/881916/jurat-del-carnet-jove-del-festival-internacional-sitges-premia-ghost-in-the-cell-joko-anwar","quote":"El film Ghost in the Cell, de Joko Anwar, ha estat guardonat pel Jurat Carnet Jove"}]}]},{"n":"4","title":"Grans esdeveniments","blocks":[{"text":"El Grand Départ del Tour de França va portar a Catalunya tres etapes, amb pas per Barcelona, Tarragona i Granollers; la tercera va sortir de Granollers i va acabar a Les Angles (França). El conseller d''Esports, Berni Álvarez, en va fer un balanç molt positiu (nota del 6 de juliol de 2026).","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/844960/govern-celebra-lexit-del-grand-depart-del-tour-catalunya-balanc-positiu","quote":"El Grand Départ del Tour de França ha deixat petjada a Catalunya amb la celebració de tres etapes"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/844960/govern-celebra-lexit-del-grand-depart-del-tour-catalunya-balanc-positiu","quote":"assegura el conseller d’Esports, Berni Álvarez, un cop la caravana del Tour abandonava territori català per finalitzar la tercera etapa a Les Angles (França)."}]},{"text":"El president Illa va qualificar la visita del papa Lleó XIV de «fet icònic per a Catalunya i Barcelona», per la coincidència amb la benedicció de la torre de Jesús de la Sagrada Família (nota del 9 de juny de 2026). L''eclipsi solar total de l''agost de 2026 va ser el primer observable des de Catalunya en més de 120 anys; la Generalitat en va destacar la coordinació institucional i la iniciativa «Catalunya mira al cel» (nota del 13 d''agost, que el situa el dia abans).","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/833640/president-illa-la-visita-del-papa-lleo-xiv-fet-iconic-catalunya-barcelona","quote":"la visita del Papa Lleó XIV serà “un fet icònic per a Catalunya i Barcelona”, especialment per la seva coincidència amb la benedicció de la torre de Jesús de la Sagrada Família."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/860012/catalunya-viu-exit-jornada-historica-dobservacio-leclipsi-solar-total","quote":"el primer que es podia observar des del territori català en més de 120 anys"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/860012/catalunya-viu-exit-jornada-historica-dobservacio-leclipsi-solar-total","quote":"La Generalitat destaca la coordinació institucional, la participació ciutadana i el llegat científic de la iniciativa «Catalunya mira al cel»"}]},{"text":"Al Mobile World Congress 2026, Illa es va reunir amb el director general de la GSMA, John Hoffman, i va dir que el congrés és «una finestra cap al futur». El Congrés Mundial d''Arquitectes UIA 2026 Barcelona va reunir més de 10.000 participants i va presentar la Declaració de Barcelona, amb sis compromisos: temps, matèria, vida, justícia, escala i significat. En el centenari de la mort de Gaudí, el Gaudí International Congress 2026 (22-25 d''octubre) va ser el primer congrés científic disciplinar sobre l''arquitecte a nivell mundial.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/797092/president-illa-el-mobile-world-congress-finestra-cap-al-futur","quote":"el director general de la GSMA, John Hoffman. En el transcurs de l’acte, el cap de l’Executiu ha celebrat que \"el Mobile World Congress és una finestra cap al futur\"."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/843520/congres-mundial-darquitectes-uia-2026-barcelona-clausura-despres-superar-expectatives-reunir-mes-10000-participants","quote":"La UIA ha presentat durant la cloenda la Declaració de Barcelona, un manifest articulat al voltant de sis compromisos: temps, matèria, vida, justícia, escala i significat"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/884128/barcelona-acull-congres-internacional-gaudi-lany-commemoracio-del-centenari-larquitecte","quote":"el Gaudí International Congress 2026, el primer congrés científic disciplinar sobre l''arquitecte a nivell mundial"}]}]},{"n":"5","title":"Institucions, lleis i commemoracions","blocks":[{"text":"El Parlament va aprovar el 20 de maig de 2026 la primera Llei del Tercer Sector Social, que reconeix institucionalment la tasca de les entitats socials. El 22 de juliol va aprovar la modificació del Codi civil de Catalunya en matèria de suports a l''exercici de la capacitat jurídica, que culmina l''adaptació del dret civil català a la Convenció de les Nacions Unides sobre els drets de les persones amb discapacitat.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/825636/parlament-aprova-primera-llei-del-tercer-sector-social-catalunya","quote":"El Parlament de Catalunya ha aprovat avui la primera Llei del Tercer Sector Social. La nova norma reconeix institucionalment la tasca de les entitats socials"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/852512/parlament-aprova-llei-suports-que-reforca-dret-persones-discapacitat-decidir-mateixes","quote":"una norma que culmina l''adaptació del dret civil català a la Convenció de les Nacions Unides sobre els drets de les persones amb discapacitat"}]},{"text":"Les commemoracions oficials del 2026 inclouen el 150è aniversari del naixement de Pau Casals i de Josep Irla i els 100 anys de la mort d''Antoni Gaudí; per la Diada, les delegacions del Govern a l''exterior la van commemorar a 20 països d''Europa, Àfrica, Amèrica i Àsia, amb Pau Casals com a principal homenatjat. Per al 2027 el Govern ha aprovat 21 commemoracions, i en destaca el 50è aniversari del retorn de l''exili del president Josep Tarradellas i de la recuperació de les institucions d''autogovern.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/862872/govern-commemora-diada-20-paisos-darreu-del-mon-pau-casals-principal-homenatjat","quote":"Les delegacions del Govern a l’exterior commemoren la Diada Nacional de Catalunya a 20 països d’Europa, Àfrica, Amèrica i Àsia"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/862872/govern-commemora-diada-20-paisos-darreu-del-mon-pau-casals-principal-homenatjat","quote":"el 150è aniversari dels naixements de Pau Casals i de Josep Irla i els 100 anys de la mort d’Antoni Gaudí"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/855536/govern-aprova-commemoracions-generalitat-lany-2027","quote":"El Govern ha aprovat les 21 commemoracions oficials de la Generalitat per a l’any 2027"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/855536/govern-aprova-commemoracions-generalitat-lany-2027","quote":"destaca especialment el 50è aniversari del retorn de l’exili del president Josep Tarradellas"}]}]},{"n":"6","title":"Seguretat i emergències","blocks":[{"text":"El 2 d''octubre de 2026 Protecció Civil mantenia en fase d''Emergència el Pla especial d''emergències per inundacions de Catalunya (INUNCAT), i va aixecar el confinament de la població del Baix Ebre i el Montsià. Més de 100 agents rurals van participar a les Jornades eduCAR 2026, a Montserrat, sobre educació i sensibilització ambiental, centrades en ApropaNatura, el vessant social del programa adreçat als col·lectius més vulnerables.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/874652/proteccio-civil-mante-emergencia-pla-inuncat-aixeca-confinament-al-baix-ebre-montsia","quote":"Protecció Civil de la Generalitat manté en fase d’Emergència el Pla especial d’emergències per inundacions de Catalunya (INUNCAT) i ha aixecat el confinament de la població del Baix Ebre i el Montsià."},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/880680/consellera-parlon-reivindica-paper-clau-dels-agents-rurals-leducacio-ambiental-inclusio-social-jornades-educar-2026","quote":"Més de 100 agents rurals participen i es formen en les Jornades eduCAR 2026 a Montserrat"},{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/880680/consellera-parlon-reivindica-paper-clau-dels-agents-rurals-leducacio-ambiental-inclusio-social-jornades-educar-2026","quote":"Enguany, les jornades se centren en ApropaNatura, el vessant social del programa EduCAR, dirigit als col·lectius més vulnerables"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Primer or olímpic d''hivern de l''esport català: Oriol Cardona (esquí de muntanya, Milano Cortina 2026).","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"el primer or olímpic d''hivern de la història de l''esport català"}]},{"text":"Millors esportistes del 2025: Kilian Jornet i Iris Tió; Toni Bou suma 40 títols mundials.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/885692/festa-lesport-catala-arriba-30a-edicio-mes-100-candidatures-ja-finalistes","quote":"Amb 40 títols mundials"}]},{"text":"Medalla d''Or 2026: Ferran Adrià i Caterina Biscari. Creu de Sant Jordi 2026: 20 persones i 10 entitats.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/812364/govern-distingeix-creu-sant-jordi-20-persones-10-entitats","quote":"a 20 persones i 10 entitats"}]},{"text":"Tour de França: tres etapes a Catalunya. Papa Lleó XIV: benedicció de la torre de Jesús.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/833640/president-illa-la-visita-del-papa-lleo-xiv-fet-iconic-catalunya-barcelona","quote":"la benedicció de la torre de Jesús de la Sagrada Família"}]},{"text":"Eclipsi total: el primer en més de 120 anys. Declaració de Barcelona (UIA): sis compromisos.","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/860012/catalunya-viu-exit-jornada-historica-dobservacio-leclipsi-solar-total","quote":"en més de 120 anys"}]},{"text":"Commemoracions: 2026, Casals i Irla (150 anys) i Gaudí (centenari de la mort); 2027, 21 commemoracions i el retorn de Tarradellas (50 anys).","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/855536/govern-aprova-commemoracions-generalitat-lany-2027","quote":"les 21 commemoracions oficials de la Generalitat per a l’any 2027"}]},{"text":"Emergència per inundacions: pla INUNCAT (Baix Ebre i Montsià, octubre de 2026).","refs":[{"ref":"","law":"Sala de premsa del Govern","url":"https://govern.cat/salapremsa/notes-premsa/874652/proteccio-civil-mante-emergencia-pla-inuncat-aixeca-confinament-al-baix-ebre-montsia","quote":"Pla especial d’emergències per inundacions de Catalunya (INUNCAT)"}]}]}]'::jsonb, (select id from public.sources where url = 'https://govern.cat/salapremsa/notes-premsa'), 'https://govern.cat/salapremsa/notes-premsa', null, null, null, 'Tema d''actualitat: caduca. Revisar cada trimestre i retirar els fets de més de 12 mesos abans de cada convocatòria.'
  from public.topics t where t.slug = 'mossos-d-actualitat'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);

do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where t.slug like 'mossos-%' and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'mossos-esquadra',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el hilo del proyecto (10/11/2026: apuntes completos por tema)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Mossos d''Esquadra: % fichas con apuntes publicadas', v_n;
end $$;

commit;
